\begin{remark}\label{rem: basis of measure}
    An explicit base for $\mathfrak{M}(\Xi_{\bf v})$ is given by the set of  measures $\{\mu_I\}_{I\in \mathtt{P}(\{1,\dots,d\})}$ with normalization chosen so that if $\X_{{\bf v}_I}$ is discrete then
$$\mu_I(A)\;:=\;{{\rm Vol}\big(\R^{I}/\tilde{\X}_{{\bf v}_I}\big)}\nu_I(\Gamma(A))$$
with $A\subset \mathcal{C}_{{\bf v}_I}$ and $\nu_I$ the counting measure on $\Z^{I}_+$. If  $\X_{{\bf v}_I}=\R^{I}_+$ then $\Gamma_*(\mu_I)=\nu_I$ with  $\nu_I$ the normalized Lebesgue measure on $\R^{I}_+$.
\hfill $\blacktriangleleft$
\end{remark}
\begin{remark}\label{rem: basis of measure zd}
    Let $\mathfrak{M}(\tilde{\Xi}_{\bf v})$ be the vector space of those $\Z^D$-invariant Borel measures on $\tilde{\Xi}_{\bf v}$ which are trivial extensions of Radon measures on some $\tilde{\Xi}_r\setminus \tilde{\Xi}_{r-1}$. Under the same assumptions as Theorem~\ref{teo measures} this space also has dimension $2^d$ and  a basis is provided by the set $\{ \tilde{\mu}_I\}_{I\in \mathtt{P}(\{1,\dots,d\})}$ where each $\tilde{\mu}_I$ is uniquely determined by the relation $\tilde{\mu}_I|_{\Xi_{\bf v}}=\mu_I.$
\hfill $\blacktriangleleft$
\end{remark}


\section{Chern numbers in the cone geometry} \label{Sec: chern}
This section is devoted to the proof of Theorem \ref{Theorem 2}. Here, we shall construct the correct nontrivial Chern cocycle on the boundary algebras $\mathfrak{I}_r$, defined by the trace per unit hypersurface induced by the measures computed in the previous section.

\medskip


Consider the \emph{cone} semigroup $C^*$-algebra $\A_{\bf v}:=C^*_r(\LL_{\bf v})$ with $\bf v$ displaying the RCI property. This admits the cofiltration
\begin{equation}
    \A_{\bf v}\;=\;\A_{d}\stackrel{\psi_d}\to \A_{d-1}\stackrel{\psi_{d-1}}\to \cdots \to \A_1\stackrel{\psi_1}\to \A_0\;=\;C^*_r(\Z^D)
\end{equation}
induced by the filtration \eqref{eq: filtration 1} of $\Xi_{\bf v}$. Here $\A_{r}:=C^*_r(\LL_{\bf v}|_{\Xi_r})$ and $\psi_r$ is the surjective $*$-homomorphism given by the restriction from $\Xi_r$ to $\Xi_{r-1}$.  The codimension-$r$ boundary algebra is then defined as $  \mathfrak{I}_r={\rm Ker}(\psi_r)$ and $\mathfrak{I}_r \simeq C^*_r(\LL_{\bf v}|_{\Xi_r\setminus\Xi_{r-1}})$, according to \ref{Prop:ES}. From the construction, we have the following short exact sequences
\begin{equation}\label{eq: seq 2}
0\to \mathfrak{I}_r\to \A_r\to \A_{r-1}\to 0
\end{equation}
Observe that $\mathfrak{I}_r$ can be decomposed in direct sum as
\begin{equation}\label{eq: edge algebra}
  \mathfrak{I}_r\;=\;\bigoplus_{|I|=r} \mathfrak{I}_I  
\end{equation}
where $\mathfrak{I}_I:=C^*_r(\LL_{\bf v}|_{\mathcal{C}_{{\bf v}_I}})$ is a closed ideal of $\A_r$ by Proposition \ref{prop: general case}.  Define the linear functional on $\mathfrak{I}_I$ given by 
\begin{equation}
    \Tt_I(f)\;:=\;\int_{\mathcal{C}_{{\bf v}_I}}E(f)(x){\rm d}\mu_I(x),\qquad f\in \mathfrak{I}_I
\end{equation}
where $\mu_I$ is the unique invariant Radon measure on $\mathcal{C}_{{\bf v}_I}$ defined in Remark \ref{rem: basis of measure}. As a consequence of the properties of $\mu_I$, this functional satisfies:
\begin{proposition}\label{prop: traces}
 $\Tt_I$ is a densely defined trace on $\mathfrak{I}_I$ which is faithful and lower semicontinuous.
\end{proposition}
 The real-space representation of $\Tt_I$  and its interpretation as a trace-per-surface-area will be discussed in Section \ref{sec: trace}.
\medskip

We are now in place to define the Chern cocycles on $\mathfrak{I}_r$. Consider  a tuple of normalized vectors ${\bf w}=( w_1,w_2,\dots,w_m)$ in $\R^D$ and define the $(m+1)$-linear functional
\begin{equation}
    {\rm Ch}_{I,{\bf w}}(f_0,f_1,\dots, f_m)\;:=\;\sum_{\rho\in S_m}(-1)^\rho\Tt_I\big(f_0\nabla_{w_{\rho(1)}}f_1\cdots \nabla_{w_{\rho(m)}}f_m\big)
\end{equation}
which is well-defined for any $(m+1)$-tuple of elements $f_k$ in a suitable dense subalgebra of $\mathfrak{I}_I$ consisting of elements in the domain of both $\nabla$ and $\Tt_I$. Here, $S_m$ is the symmetric group of $m$ elements, $(-1)^\rho$ stands for the sign of $\rho$ and the directional derivatives are defined according to
\begin{equation}\label{eq: deriva}
    \nabla_vf\;:=\; v\cdot \nabla f\;=\;\sum_{i=1}^Dv_i\nabla_if
\end{equation}
with $\nabla_if=\ii[\mathfrak{n}_i,f]$ and $\mathfrak{n}_i$ the position operator in the direction $i$ on $\ell^2(\LL_{\bf v})$. Thanks to the properties of the trace $\Tt_I$, it follows that ${\rm Ch}_{I,{\bf w}}$ defines a cyclic $m$-cocyle on $\mathfrak{I}_I$ \cite{Con}. For even $m$, this Chern cocycle pairs with the group $K_0(\mathfrak{I}_I)$ via
$$\langle [p]_0, [{\rm Ch}_{I, {\bf w}}]\rangle \;=\;\frac{1}{(m/2)!(-2\pi \imath)^{m/2}}\;{\rm Ch}_{I, {\bf w}}(p,\dots,p)$$
and for odd $m$ with $K_1(\mathfrak{I}_I)$ via 
$$\langle [u]_1, [{\rm Ch}_{I, {\bf w}}]\rangle \;=\;\frac{\imath^{(m+1)/2}}{m!!(-2)^m\pi^{(m+1)/2}}\,{\rm Ch}_{I, {\bf w}}(u^{-1}-1, u-1,u^{-1}-1,\dots,u-1).$$

These pairings are group homomorphisms with respect to $K_*(\mathfrak{I}_I)$ and depend only on the cohomology class of the $m$-cycle ${\rm Ch}_{I,{\bf w}}$ \cite{Con}.
%\begin{remark}\label{rem: crossed cone algebra}

\medskip
   Define the \emph{extended} cone algebra as the crossed product $\tilde{\A}_{\bf v}:=C_0(\tilde{\Xi}_{\bf v})\rtimes\Z^D$ where $\tilde{\Xi}_{\bf v}$ is provided in Corollary \ref{coro: zd hull}.  This algebra also admits a cofiltration
   \begin{equation}\label{eq: extended cofiltrarion}
    \tilde{\A}_{\bf v}=\tilde{\A}_{d}\stackrel{\tilde{\psi}_d}\to \tilde{\A}_{d-1}\stackrel{\tilde{\psi}_{d-1}}\to \cdots \to \tilde{\A}_1\stackrel{\tilde{\psi}_1}\to \tilde{\A}_0=C^*_r(\Z^D)
\end{equation}
with $\tilde{\A}_r=C_0(\tilde{\Xi}_r)\rtimes \Z^D$ and ideals $\tilde{\mathfrak{I}}_r:={\rm Ker}(\tilde{\psi}_r).$ Similarly, one has the decomposition $\tilde{\mathfrak{I}}_r=\bigoplus_{|I|=r}\tilde{\mathfrak{I}}_I$, where $\tilde{\mathfrak{I}}_I:=C_0(\tilde{\mathcal{C}}_{{\bf v}_I})\rtimes \Z^D$ are closed ideals of $\tilde{\A}_r$ with a unique tracial weight defined via
\begin{equation}
    \tilde{\Tt}_I(f)\;:=\;\int_{\tilde{\mathcal{C}}_{{\bf v}_I}}E(f)(x){\rm d}\tilde{\mu}_I(x),\qquad f\in \tilde{\mathfrak{I}}_I\,.
\end{equation}
Here $\tilde{\mu}_I$ is the measure in Remark \ref{rem: basis of measure zd}. Thus, the natural Chern cocycle on $\tilde{\mathfrak{I}}_I$ is
\begin{equation}
    \tilde{\rm Ch}_{I,{\bf w}}(f_0,f_1,\dots, f_m)\;:=\;\sum_{\rho\in S_m}(-1)^\rho\tilde{\Tt}_I\big(f_0\nabla_{w_{\rho(1)}}f_1\cdots \nabla_{w_{\rho(m)}}f_m\big)
\end{equation}
% Recall that by Theorem \ref{Teo morita}, the $C^*$-algebras $\A_{\bf v}$ and $\tilde{\A}_{\bf v}$ are Morita equivalent. Consequently, the $K$-theory and their lattice of ideals are isomorphic.
%   $\hfill\blacktriangleleft$
%\end{remark}


The next Proposition will complete the Proof of Theorem \ref{Theorem 2}:
\begin{proposition}\label{prop: numerical invariants}
 For any linearly independent tuple $(w_1,...,w_m)$ of vectors orthogonal to ${\bf v}_I$ there is an elements$ [\zeta]_i\in K_i(\mathfrak{I}_I)$, $i= m\, \mathrm { mod }\,2$, such that the pairing $\langle [\zeta]_i,[{\rm Ch}_{I,{\bf w}}]\rangle$ does not vanish.
\end{proposition}
Before we can prove this Proposition, we first need to introduce another variant of the transversal hull, which will define a \emph{smooth} cone algebra $\mathcal{A}_{\bf v}$. Consider the locally compact space
\begin{equation}\label{eq: Omega}
  \Omega_{\bf v}\;=\;\overline{\big\{ \R_+^d-x\;|\;x\in \R^d\big\}}\setminus \emptyset  
\end{equation}
where the closure is taken with respect to the Fell topology on $\mathscr{C}(\R^d).$ 
Translations in $\Z^D$ act via
$$(\Ss,n)\;\mapsto\; \beta_n(\Ss)\;=\;\Ss - A_{{\bf v}}n,\qquad \forall \, \Ss\in \Omega_{\bf v},n \in \Z^D.$$
In \cite[Proposition 3.2]{DET2} it is shown that $\Omega_{\bf v}$ has a decomposition as a CW-complex with cell decomposition
$$\Omega_{\bf v}\;\simeq\;\bigsqcup_{I\in \mathtt{P}(1,\dots,d)} \R^{I}$$
where $\R^{\emptyset}=\{*\}$ is a single point. This is only a bijection, not a homeomorphism, since the cells are glued non-trivially. Precisely, any element of $\Omega_{\bf v}$ can be written uniquely in the form $\Ss=(x+ \R_+^I)\times \R^{I^c}$ for some $I\subset \{1,...,d\}$ and $x\in \R^I$. Under the bijection the $\Z^D$-action $\beta$ turns into the \emph{affine} transformations
$$(x,n)\;\mapsto\; \beta_n(x)\;=\;x+A_{{\bf v}_I}n,\qquad \forall \,x\in \R^{I},n \in \Z^D.$$
The \emph{smooth} cone algebra $\mathcal{A}_{\bf v}$ shall be the crossed product algebra under this action, \ie
$$\mathcal{A}_{\bf v}\;:=\;C_0(\Omega_{\bf v})\rtimes_\beta\Z^D.$$
This algebra compares to $C_0(\tilde{\Xi}_{\bf v})\rtimes \Z^D$ in a similar way that the so-called smooth Toeplitz algebra \cite{JI} relates to the usual Toeplitz algebra.

The crossed product algebra $\mathcal{A}_{\bf v}$ can be described as the universal $C^*$-algebra generated by formal Fourier series
$$a \;=\; \sum_{n\in \Z^D} a_n u^n$$
with commuting unitaries $u^n=u_1^{n_1}\cdots u_D^{n_D}$ representing the generators of the $\Z^D$-action and coefficients $f_n\in C_0(\Omega_{\bf v})$ satisfying the commutation relation $u^nf_m u^{-n}=\beta_n(f_m)$. Moreover, one obtains a strongly continuous family of $*$-representations $\{\pi_\omega\}_{\omega\in\Omega_{\bf v}}$ of $\mathcal{A}_{\bf v}$ on $\ell^2(\Z^D)$ determined by the relation
$$\langle n|\pi_\omega(a)|m\rangle\;=\;a_{n-m}\big(\beta_{n-m}(\omega)\big).$$

Similarly to the unit-space $\tilde{\Xi}_{\bf v}$ the space $\Omega_{\bf v}$ also has a similar filtration by closed $\Z^D$-invariant subsets
\begin{equation}\label{eq: filtration smooth 2}
    \{ *\}=\Omega_0\subset \Omega_1\subset\dots \subset \Omega_{d-1}\subset \Omega_d =\Omega_{\bf v}
\end{equation}
where $\Omega_r:=\Omega_d\setminus \bigsqcup_{|I|>r}\R^{I}$. This in turn a cofiltration of $\mathcal{A}_{\bf v}$ 
\begin{equation}\label{eq: cofiltration smooth}
    \mathcal{A}_{\bf v}\;=\;\mathcal{A}_{d}\stackrel{\phi_d}\to \mathcal{A}_{d-1}\stackrel{\phi_{d-1}}\to \cdots \to \mathcal{A}_1\stackrel{\phi_1}\to \mathcal{A}_0\;\simeq\; C(\T^D)
\end{equation}
with $\phi_r$ surjective $*$-homomorphism and $\mathcal{A}_r=C_0(\Omega_r)\rtimes_{\beta}\Z^D$. The smooth boundary ideals here are
$\mathcal{I}_r:={\rm Ker}(\phi_r)$. It turns out that the following decomposition in direct sum
\begin{equation}\label{eq: smooth edge algebra}
\mathcal{I}_r\;=\;\bigoplus_{|I|=r}\mathcal{I}_I
\end{equation}
where each $\mathcal{I}_I\;:=\;C_0(\R^{I})\rtimes_{\beta}\Z^D$ is an ideal of $\mathcal{A}_r$. The canonical trace on $\mathcal{I}_I$ is given by 
\begin{equation}
        \mathcal{T}_I(f)\;:=\;\int_{\R^{I}}E(f)(x)\,{\rm d}\nu_I(x)
\end{equation}
where $\nu_I$ is the normalized Lebesgue measure on $\R^{I}$ and $E\colon \mathcal{A}_{\bf v}\to C_0(\Omega_{\bf v})$ is the conditional expectation map. As a consequence,  $\mathcal{T}_I$ is a densely defined, faithful, and lower semicontinuous trace on $\mathcal{I}_I$. Thanks to all these properties, one can define for a tuple ${\bf w}=(w_1,\dots,w_m)$ of  vectors in $\R^D$ the \emph{smooth} Chern cocycle

\begin{equation}
       {\rm Ch}^s_{I,{\bf w}}(f_0,f_{1},\dots, f_m)\;=\;\sum_{\rho\in S_m}(-1)^\rho \mathcal{T}_I\big(f_0\nabla _{w_{\rho(1)}}f_{1}\cdots \nabla _{w_{\rho(m)}}f_m\big)
    \end{equation}
for $(m+1)$-tuple of elements of suitable element $f_j\in\mathcal{I}_I$. Here, the directional derivative is given in terms of the formal Fourier series
$$\nabla_v f\;=\;\sum_{n\in \Z^D} v\cdot \nabla(f_nu^n)\;=\;- {\rm i}\sum_{i=1}^D\sum_{n\in \Z^D} v_in_if_n u^n$$
\begin{proposition}\label{prop: num}
 For any linearly independent tuple $(w_1,...,w_m)$ of vectors orthogonal to $v_I$ there is an elements$ [\zeta]_i\in K_i(\mathcal{I}_I)$, $i= m\, \mathrm { mod }\,2$, such that the pairing $\langle [\zeta]_i,[{\rm Ch}_{I,{\bf w}}]\rangle$ does not vanish.
\end{proposition}
\begin{proof}
From \cite[Proposition 4.1]{DET2} one gets $\mathcal{I}_I\simeq C(\T^D)\rtimes \R^{I}.$ Thus,  the Connes-Thom isomorphism  and \cite[Theorem 5.3]{DET2} completes the proof.
\end{proof}

\medskip
\noindent
{\bf Proof of Proposition \ref{prop: numerical invariants}.}
\begin{proof}
The idea of the proof is to construct a homomorphism $\iota_*\colon  K_*(\mathcal{I}_I)\to K_*(\mathfrak{I}_I)$ such that 
\begin{equation}\label{eq: equality chern}
     \big \langle [\zeta]_i, [{\rm Ch}^s_{I,{\bf w}}
      ]\big\rangle \;=\;\big\langle \iota_*[\zeta]_i, [{\rm Ch}_{I,{\bf w}}]\big\rangle, \qquad [\zeta]_i\in K_i(\mathcal{I}_I)
  \end{equation}  
  Hence, by combining this equality with Proposition \ref{prop: num}, the non-triviality is established.
    Let us start with the case for which ${\bf v}$ is CI.  Observe that the map $\Gamma $ provided in Lemma \ref{coro: surjective} induces a continuous surjective $\Z^D$-equivariant map $\tilde{\Gamma}_I\colon \tilde{\mathcal{C}}_{{\bf v}_I}\to \R^{I}$. By functoriality of the crossed product, there is an injective $*$-homomorphism   $\iota'\colon \mathcal{I}_I\to \tilde{\mathfrak{I}}_I$. From Remarks \ref{rem: basis of measure} and \ref{rem: basis of measure zd}, the Lebesgue measure $\nu_I$ on $\R^{I}$ is the pushforward measure of $\tilde{\mu}_I$. As a consequence,  $\mathcal{T}_I(f)\;=\;\tilde{\Tt}_I\big(\iota'(f)\big)$ for any $f\in \mathcal{I}_I.$ This implies the equality in Chern numbers
\begin{equation*}
     \big \langle [\zeta]_i, [{\rm Ch}^s_{I,{\bf w}}
      ]\big\rangle \;=\;\big\langle \iota'_*[\zeta]_i, [\tilde{\rm Ch}_{I,{\bf w}}]\big\rangle, \qquad [\zeta]_i\in K_i(\mathcal{I}_I)
  \end{equation*}
  Letting $\iota_*$ as the composition of the arrows $K_*(\mathcal{I}_I)\stackrel{\iota'_*}\to K_*(\tilde{\mathfrak{I}}_I)\simeq K_*(\mathfrak{I}_I)$ one lands in \eqref{eq: equality chern}, where the last isomorphism follows from the fact that  $\mathfrak{I}_I$ and $\tilde{\mathfrak{I}}_I$ are Morita equivalent by Theorem \ref{Teo morita}.\\
If  $\X_{{\bf v}_I}$ is discrete then $\tilde{\Gamma}_I$ provides an equivariant homeomorphism of $\tilde{\mathcal{C}}_{{\bf v}_I}$ onto the $\Z^D$-orbit in $\R^{I}$ of an single element $\omega\in \R^{I}$. With the corresponding surjective $*$-homomorphism $\iota_\omega\colon \mathcal{I}_I\to \tilde{\mathfrak{I}}_I$ one has by \cite[Proposition 5.5]{DET2}
 \begin{equation*}
     \big \langle [\zeta]_i, [{\rm Ch}^s_{I,{\bf w}}
      ]\big\rangle \;=\;\big\langle (\iota_\omega)_*[\zeta]_i, [\tilde{\rm Ch}_{I,{\bf w}}]\big\rangle, \qquad \forall [\zeta]_i\in K_i(\mathcal{I}_I)
  \end{equation*}
Thus, as in the previous case, $\iota_*$ is the composition of $(\iota_\omega)_*$ with $ K_*(\tilde{\mathfrak{I}}_I)\simeq K_*(\mathfrak{I}_I)$.
\end{proof}


\medskip 
Let us finish this section with a discussion about the consequences of Theorem \ref{Theorem 2} in the \emph{bulk-edge} correspondence for two-dimensional lattice models in the irrational case. Consider in $\R^2$ the half-plane geometry defined by the semigroup $\LL_{v}$ for a single vector $v\in \R^2$ with components rational independent over $\Q$. According to Proposition \ref{prop: containing 2}, the transversal hull is
\begin{align*}
\Xi_{v}\;&=\; \big\{ \LL^\emptyset_{v,x}\big\}_{x\in \R_+}\cup  \big\{ \LL^{\{1\}}_{v,x}\big\}_{x\in \mathtt{X}^{\{1\}}_{{\bf v}}} \cup \{ \Z^2\}\\
\;&=\; \big\{ \LL^\emptyset_{v,x}\big\}_{x\in \R_+}\cup \big\{\LL_{v,0}^{\{1\}}-n\;:\;n\in \LL_{v},\;n\neq 0\big\}\cup \{ \Z^2\}\\
\;&=\; \big\{ \LL^\emptyset_{v,x}\big\}_{x\in \R_+}\cup \mathscr{O}(\LL_{v,0}^{\{1\}})\cup \{ \Z^2\},
\end{align*}
since in this case $\mathtt{X}^{\{1\}}_{\bf v} = v\cdot (\LL_v \setminus \{0\})$. The canonical filtration $\{\Z^2\}=\Xi_0\subset \Xi_1=\Xi_v$ has length two.  The cofiltration of $\A_v$ reduces to the short  exact sequence
\begin{equation}\label{eq: seq bulk-boundary}
    0\to\mathfrak{I}_1\to \A_v\to \A_0\to 0
\end{equation}
where  $\mathfrak{I}_1= C^*_r(\LL_{v}|_{\mathcal{C}_v})$ and $\A_0\simeq C(\T^2)$ is the bulk algebra. This sequence is the core of the bulk-edge correspondence  \cite{PRO}.

\medskip

 Recall that  $\mathcal{I}_1=C_0(\R)\rtimes_{\beta} \Z^2\simeq C(\T^2)\rtimes \R$ is the smooth boundary algebra. Here the homomorphism $\iota_*\colon K_*(\mathcal{I}_1)\to K_*(\mathfrak{I}_1)$ provided in the proof Proposition  \ref{prop: numerical invariants} is surjective. The latter is a consequence of \cite[Corollary 2.8]{RX}, where it is shown that the map $\iota'_*\colon K_*(\mathcal{I}_1)\to K_*(\tilde{\mathfrak{I}}_1)$ is surjective, where $\tilde{\mathfrak{I}}_1$ is the extended boundary algebra. Thus, $\iota_*$ is also surjective. In particular, one has the relations
$$K_0(\mathfrak{I}_1)\;\simeq\;K_0(\mathcal{I}_1)\;=\;\Z^2,\qquad  K_1(\mathfrak{I}_1)\;\simeq\; K_0(\mathcal{I}_1)/\Z\;=\;\Z.$$ 
The isomorphism $K_1(\mathfrak{I}_1)\simeq \Z$ is given by a suitable normalization of the pairing with the Chern cocycle ${\rm Ch}_{\{1\},\{w\}}$ for $w$ orthogonal to $v$. Moreover, this pairing is completely determined by an input coming from the Chern cocycle on the bulk algebra $\A_0$:
\begin{proposition}\label{prop: duality}
  Let $\partial_1\colon K_i(\A_0)\to K_{i-1}(\mathfrak{I}_1)$ be  the connecting map  related to the sequence \eqref{eq: seq bulk-boundary}. One has the duality
   $$\langle [\zeta]_i,[{\rm Ch}_{\emptyset, \{w, v\}}]\rangle\;=\;\langle \partial_1([\zeta]_i),[{\rm Ch}_{\{1\},\{w\}}]\rangle \qquad \forall[\zeta]_i\in K_i(\A_0)$$
   where $w$ is any vector in $\R^2$ linearly independent to $v$.
\end{proposition}
\begin{proof}
Since $\A_0\simeq C(\T^2)$ and $\mathcal{J}_1\simeq C(\T^2)\rtimes\R$, one gets by \cite[Theorem 5.3]{DET2} the duality
 $$\langle [\zeta]_i,[{\rm Ch}_{\emptyset, \{w, v\}}]\rangle\;=\;\langle \partial_1^s([\zeta]_i),[{\rm Ch}^s_{\{1\},\{w\}}]\rangle \qquad [\zeta]_i\in K_i(\A_0)$$
 where $\partial_1^s\colon K_i(\A_0)\to K_{i-1}(\mathcal{I}_1)$  is the connecting map of \eqref{eq: cofiltration smooth}. Moreover, the above with \eqref{eq: equality chern} yield
  $$\langle [\zeta]_i,[{\rm Ch}_{\emptyset, \{w, v\}}]\rangle\;=\;\langle \iota_*\circ\partial_1^s([\zeta]_i),[{\rm Ch}_{\{1\},\{w\}}]\rangle $$
  To conclude the proof is enough to recall the definition of $\iota_*$ and to note that the following diagram is commutative
  $$ \xymatrix{0\ar[r]^{} & \mathcal{I}_{1} \ar[r]^{i}\ar[d]^{\iota'}& \mathcal{A}_1\ar[r]^{\phi_1}\ar[d]^{\iota'} &C(\T^2)\ar[r]^{}\ar[d]^{\iota'}&0\\
0\ar[r]^{} & \tilde{\mathfrak{I}}_1 \ar[r]^{i}& \tilde{\A}_1\ar[r]^{\tilde{\psi}_1} &C(\T^2)\ar[r]^{}&0 }$$
which implies $\partial_1=(\iota')_* \circ \partial^s_1=\iota_* \circ \partial^s_1$ due to naturalness of the connecting maps.
\end{proof}

We can now discuss the consequences of Proposition \ref{prop: duality} for lattice Hamiltonians. Let  $H=H^*\in M_N(\A_1)$ be a Hamiltonian with a bulk spectral gap at $0$, \ie  $0$ lies in a compact interval $\Delta$ contained in a spectral gap of the bulk Hamiltonian $H_B:=\psi_1(H)\in M_N(\A_0)\simeq M_N(C(\T^2)).$ One associates to $H$ the bulk invariant
$$[P_f]\;:=\;[\chi_{(-\infty,0)}(H_B)]_0\in K_0(\A_0)$$
defined by the \emph{Fermi projection}, and the edge invariant by the \emph{edge unitary}
$$[U_f]\;=\;[e^{i\pi f(H)}]_1 \in K_1\big(\mathfrak{I}_1\big)$$
where $f$ is any smooth function that takes the constant values $-1$ below $\Delta$ and $1$ above $\Delta$. It is not difficult to see that these invariants satisfy the correspondence $\partial_1([P_f])=[U_f]$. 
Therefore, Proposition \ref{prop: duality} leads to the bulk-edge correspondence 

$$\langle [P_f],[{\rm Ch}_{\emptyset, \{w, v\}}]\rangle\;=\;\langle [U_f],[{\rm Ch}_{\{1\},\{w\}}]\rangle$$
The numerical invariant on the right-hand side has a concrete physical interpretation in terms of quantized edge currents \cite{PRO}.

\section{On a real-space expression for the trace}\label{sec: trace}

Having seen that the trace $\Tt$ on each ideal $\mathfrak{I}=C_r^*(\LL_{\bf v}\rvert_{\mathcal{C}_{\bf v}})$ is essentially unique it is interesting to derive an explicit expression for it which can be computed from matrix elements in the canonical Hilbert space representation on $\ell^2(\LL_{\bf v})$. Such an expression is known in the case $d=1$ as the trace-per-surface-area, for reasons that will become clear. 

\begin{definition}
Denote the span of the linearly independent vectors ${\bf v} =\{v_1,\dots,v_d\}$ in $\R^D$ by $E_{\triangleleft}$ and its orthogonal complement by $E_{\triangledown}$. For the linear map $A_{\bf v}\colon \R^D \to \R^d$ consider the slab $$V_L\; =\; A_{\bf v}^{-1}([0,L]^d)\;\subset\; \R^D$$ and the as well as the window
$$W_t \;=\; \big\{n \in \R^D: \; \lVert n_{\triangledown}\rVert \leq t\big\}$$
where $n_{\triangledown}\in E_{\triangledown}$ is the orthogonal projection of $n$ and we used the Euclidean norm.  Define on $\ell^2(\LL_{\bf v})$ the projection operators $P_{L,t}$ on $\ell^2(\LL_{\bf v})$ restricting to all lattice points in the finite-volume slab
$$\Lambda_{L,t}\;=\; V_L \cap W_t.$$
For any $a\in C^*_r(\LL_{\bf v})$ that is trace-class w.r.t. $\Tt$ define
\begin{equation}\label{eq: limit1}
\begin{split}
   \hat{\Tt}(a)&\;=\;\lim_{L\to \infty} \lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \Tr(P_{L,t} a P_{L,t})
\\
&\;=\;\lim_{L\to \infty} \lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in \Lambda_{L,t}\cap \LL_{\bf v}} \langle n| a|n \rangle. 
\end{split}
\end{equation}
with $\Tr$ the usual Hilbert-space trace on $\mathcal{B}(\ell^2(\LL_{\bf v}))$ and $\mathrm{Vol}(B_{D-d})$ the volume of the $(D-d)$-dimensional unit ball.
\end{definition}

\begin{remark}
As will become clear, the normalization is chosen such that the trace of the indicator function for the slab $V_L$ is approximately $$\hat{\Tt}(\chi_{V_L})\;\sim\; L^{D-d}\,\mathrm{Vol}(E_\triangleleft/ \langle v_1,\dots,v_d\rangle)$$
for large $L$ with the covolume of the rank $d$ lattice spanned by $v_1,\dots,v_d$. This corresponds exactly to the $d$-dimensional volume of $V_L$ projected to $E_{\triangleleft}$. For example, if $d=1$ then the ergodic average represents a trace per $(D-1)$-dimensional surface area (see Figure~\ref{fig:picture} for $D=2$). $\hfill \blacktriangleleft$
\end{remark}


