We will now prove that the limit \eqref{eq: limit1} exists for almost all choices of $\bf v$ and is proportional to the trace $\Tt$, thereby giving it a concrete interpretation. 

\medskip

Recall that there is a conditional expectation $E\colon \mathfrak{I} \to C_0(\mathcal{C}_{\bf v})$, where we consider $C_0(\mathcal{C}_{\bf v})$ as a commutative sub-algebra of $\mathfrak{I}$. The trace factors through this map $\Tt=\Tt \circ E$. In the groupoid picture the representation of any function $f\in C_c(\G_{\LL_{\bf v}})$ on $\ell^2(\LL_{\bf v})$ is given by the matrix elements
$$\langle n| \pi(f)|m \rangle\; =\; f(\LL_{{\bf v}}-n,m-n), \qquad n,m\in \LL_{\bf v},$$
in particular, all off-diagonal elements vanish in the case where $f\in C_0(\mathcal{C}_{\bf v})$ is an element of the commutative sub-algebra. In that case, the diagonal elements
$$\langle n| \pi(f)|n \rangle \;=\; f(\LL_{{\bf v}}-n), \qquad a\in C_0(\mathcal{C}_{\bf v}),n\in \LL_{\bf v}$$
sample a dense subset of the domain $\mathcal{C}_{\bf v}$.  In this representation, the conditional expectation $E$ acts by truncating the off-diagonal matrix elements
$$\langle n| \pi(E(f))|m \rangle\;=\;\langle n| \pi(f)|m \rangle\, \delta_{n,m}.$$

Thus we see that both $\Tt=\Tt\circ E$ and $\hat{\Tt}=\hat{\Tt}\circ E$ factor through the conditional expectation. It is therefore enough to prove that $\Tt$ and $\hat{\Tt}$ coincide on the commutative algebra $C_0(\mathcal{C}_{\bf v})\cap L^1(\mathcal{C}_{\bf v})$. Let us prepare the completely irrational case first. 
\begin{lemma}
\label{lemma:almost sure continuity}
Assume that $\X_{\bf v}= \R^d_+$. Define for $f\in C_0(\mathcal{C}_{\bf v})$ the function $\tilde{f}\colon \R^d_+\to \C$ via
$$\tilde{f}(x) := f(\LL_{{\bf v},x}^\emptyset).$$
Then $\tilde{f}$ is continuous outside a set of Lebesgue measure $0$.
\end{lemma}
\begin{proof}
We already saw that $N:=\bigcup_{J\neq \emptyset} \mathtt{X}^J_{\bf v}$ has measure $0$ and it is a consequence of Lemma~\ref{Lemma J} that $\lim_{y\to x}\LL_{{\bf v},y}^\emptyset=\LL_{{\bf v},x}^\emptyset$ if $x\notin N$, hence $\tilde{f}$ is continuous outside $N$.
\end{proof}

To relate the average with the integral we need a precise estimate for the number of lattice points inside a slab like $\Lambda_{L,t}$. We obtain it by specializing a recent result from \cite{KoivusaloLagace}:
\begin{theorem}
\label{th:lattice point count}
Let $\R^D=E_{\triangleleft}\oplus E_{\triangledown}$ be an orthogonal decomposition which is irrational w.r.t. $\Z^D$. Assume that $\Z^D$ is $\psi$-repellent w.r.t. that decomposition for a function $\psi:\R_+\to \R_+$ with $\psi(t)=O(t^\mu)$. For any set with finite perimeter $\Omega_{\triangleleft}\subset E_{\triangleleft}$ and $\delta>0$ there exists a constant $C$ such that
$$\lVert \#(\Z^D \cap (\Omega_{\triangleleft} \oplus E_{\triangledown}) \cap W_t) - \mathrm{Vol}(\Omega_{\triangleleft})\mathrm{Vol}(B_{D-d}) t^{D-d}\rVert\; \leq \;C t^{D-d - \frac{D-d}{D + \mu^{-1}}+\delta}$$
for all large enough $t$.
\end{theorem}

Accordingly, the number of lattice points in any slab windowed by $W_t$ behaves asymptotically in $t$ like its Euclidean volume. If one naturally parametrizes the possible decompositions by $(n\times d)$ matrices, then the assumption of $\psi$-repellence w.r.t. a suitable function are satisfied for a set whose complement has zero Lebesgue-measure \cite[Lemma 5.8]{BjorklundHartnick}, hence for almost all ${\bf v}$.


\begin{proposition}
\label{prop:riemann}
Assume that $\bf v$ is completely irrational $\X_{\bf v}=\R^d_+$ and that the technical assumption of Theorem~\ref{th:lattice point count} is satisfied.
For any $f\in C_0(\mathcal{C}_{\bf v})$ one has
$$\lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in \Lambda_{L,t}\cap \LL_{\bf v}} \langle n| \pi(a)|n \rangle\;  =\; \frac{1}{\mathrm{Vol}(E_\triangleleft / \langle v_1,...,v_d\rangle)}\; \int_{[0,L]^d} \tilde{f}(x) d\nu(x)$$
with $\tilde{f}$ as in Lemma~\ref{lemma:almost sure continuity} and the normalized Lebesgue integral.
\end{proposition}

\begin{proof}
Recall that a function like $\tilde{f}$ which is continuous outside a set of measure $0$ is Riemann-integrable and its Riemann integral coincides with its Lebesgue integral. We will therefore, relate the sum to a Riemann integral for $\tilde{f}$. This requires us to subdivide $\Lambda_{L,t}$ into smaller slabs. For integer $M>0$ and $m\in [0,M)^d\cap \Z^d$ define 
$$\Lambda_{m,M,L,t}\;=\;A^{-1}_{\bf v}(R_{m,M,L})\cap W_t$$
with the boxes of sides $LM^{-1}$ given by $$R_{m,M,L}\;=\; \bigtimes_{i=1}^d[m_i,m_i+LM^{-1}]\;\subset \;\R^d.$$
We can bound for any $M$
\begin{align}
\label{eq:upper_riemann1}
&\frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in \Lambda_{L,t}\cap \LL_{\bf v}} \langle n| \pi(a)|n \rangle \\ = &\frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{m\in [0,M)\cap \Z^d} \sum_{n\in \Lambda_{m,M,L,t}\cap \LL_{\bf v}} \langle n| \pi(a)|n \rangle \nonumber \\
\label{eq:upper_riemann2}
\leq &\sum_{m\in [0,M)\cap \Z^d}\frac{\#(\Lambda_{m,M,L,t}\cap \Z^D) }{t^{D-d} \mathrm{Vol}(B_{D-d})} \sup_{x\in R_{m,M,L}} \tilde{f}(x)
\end{align}
with $\#(\Lambda_{m,M,L,t} \Z^D)= \#(\Lambda_{m,M,L,t} \LL_{\bf v})$ counting the number of lattice points.

By Theorem~\ref{th:lattice point count} one has for fixed $M$ 
\begin{align*}
\lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \#(\Lambda_{m,M,L,t}\cap \Z^D) &= \lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \#(\Lambda_{m,M,L,t}\cap \Z^D)\\
&= \mathrm{Vol}_d(A^{-1}_{\bf v}(R_{m,M,L})\cap E_\triangleleft)\\
&= (L M^{-1})^{d}\mathrm{Vol}( A^{-1}_{\bf v}([0,1]^d)\cap E_\triangleleft)
\end{align*}
with the $d$-dimensional volume of $A^{-1}_{\bf v}(R_{m,M,L})\cap E_\triangleleft$ which can be computed as
$$\mathrm{Vol}_d(A^{-1}_{\bf v}([0,1]^d)\cap E_\triangleleft)=\lvert\det(A_{\bf v}\rvert_{E_\triangleleft})^{-1}\rvert=\frac{1}{\sqrt{\det(A_{\bf v}A_{\bf v}^t)}}= \frac{1}{\mathrm{Vol}(E_\triangleleft/\langle v_1,...,v_d\rangle)}$$
where we used that the Gram determinant computes the covolume of the lattice spanned by $v_1,...,v_d$. In conclusion, the right-hand side of \eqref{eq:upper_riemann2} converges for $t\to \infty$ to an upper Riemann sum for an equidistant partition of the square $[0,L]^d$.

Likewise we can bound \eqref{eq:upper_riemann1} from below by replacing the supremum in  \eqref{eq:upper_riemann2} by an infimum, hence
\begin{align*}
\sum_{m\in [0,M)\cap \Z^d} (LM^{-1})^{d} \inf_{x\in R_{m,M,L}}\tilde{f}(x) &\leq \lim_{t\to \infty} \frac{\mathrm{Vol}(E_\triangleleft/\langle v_1,...,v_d\rangle)}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in \Lambda_{L,t}\cap \LL_{\bf v}} \langle n| \pi(a)|n \rangle\\
&\leq \sum_{m\in [0,M)\cap \Z^d} (LM^{-1})^{d} \sup_{x\in R_{m,M,L}} \tilde{f}(x). \end{align*}
For $M\to \infty$ both the upper and lower bound converge to the Riemann integral of $\tilde{f}$.
\end{proof}


\begin{corollary}
Assume the conditions of Proposition~\ref{prop:riemann} or that $\X_{\bf v}$ is discrete. Then there exists a constant $C$ such that
$$\Tt(a)\;=\; C \hat{\Tt}(a)$$
for all $a\in \mathfrak{I}$ which are $\Tt$-traceclass.
\end{corollary}
\begin{proof}
It only remains to consider the rational case since the other one is an obvious consequence of Proposition~\ref{prop:riemann}. In the rational case, $\Tt$ is induced by the counting measure on the discrete topological space $\mathcal{C}_{\bf v}$, \ie, concretely
$$\Tt(f)= {{\rm Vol}\big(\R^{d}/\tilde{\X}_{{\bf v}}\big)}\sum_{x\in \X_{\bf v}} f(\LL_{{\bf v},x}^\emptyset), \qquad \forall f\in C_c(\mathcal{C}_{\bf v})$$
with the normalization constant as in Remark~\ref{rem: basis of measure}.
Note that $V_{L}\cap \Z^D$ decomposes into a disjoint union over the fibers $$V_{x}:=A_{\bf v}^{-1}(\{x\})\cap \Z^D,$$ which are $(D-d)$-dimensional sublattices of $\Z^D$ (the lattices are translates of the kernel of the homomorphism $A_{\bf v}\rvert_{\Z^D}$ into a group isomorphic to $\Z^d$, hence it is a subgroup of $\Z^D$ of rank $D-d$).

Since any function $C_0(\mathcal{C}_{\bf v})$ decomposes into a sum of functions supported in a single $\LL_{{\bf v},x}^\emptyset$ we can reduce the computation of $\hat{\Tt}$ to the limit
$$\lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in V_x\cap W_t} \langle n| \pi(f)|n \rangle=\lim_{t\to \infty} \frac{1}{t^{D-d} \mathrm{Vol}(B_{D-d})} \sum_{n\in V_x\cap W_t}  f(\LL_{{\bf v},x}^\emptyset)$$
where we used that $A_{\bf v}n = x$ for all $n$ in the sum.

Clearly,
$$\sum_{n\in V_x\cap W_t} f(\LL_{{\bf v},x}^\emptyset)= (\#V_x\cap W_t) f(\LL_{{\bf v},x}^\emptyset)$$
and we merely need to count those lattice points.  It is not difficult to show that the limit
$$\lim_{t\to \infty} \frac{1}{t^{D-d}}(\#V_x\cap W_t) =\frac{\mathrm{Vol}(B_{D-d})}{\mathrm{Vol}(E_{\triangledown}/V_x)}$$
exists and is equal to volume of the $(D-d)$-dimensional unit ball divided by the covolume of the lattice $V_x$. Note that this constant does not depend on $x$ since any two lattices $V_x$ and $V_{x'}$ are translates of each other and therefore have the same covolume. We conclude
$$
\hat{\Tt}(\pi(f))=\sum_{x\in \X_{\bf v}} \frac{1}{\mathrm{Vol}(E_{\triangledown}/V_x)} f(\LL_{{\bf v},x}^\emptyset) =  \frac{1}{\mathrm{Vol}\big(\R^{d}/\tilde{\X}_{{\bf v}}\big)\mathrm{Vol}(E_{\triangledown}/V_0)} \Tt(f).
$$
%To finish the proof we need to demonstrate that
%$$\mathrm{Vol}\big(\R^{d}/\tilde{\X}_{{\bf v}}\big)\mathrm{Vol}(E_{\triangledown}/V_0)= \mathrm{Vol}(E_{\triangleleft}/\langle v_1,...,v_d\rangle).$$
%By scaling we can reduce to the case where $v_1,...,v_d$ have integer entries.
\end{proof}

