% $$0\to \mathfrak{I}_I\to \A_I\to \A_{I-1}\to 0$$

% where $\A_I=C^*_r(\LL_{\bf v}|_{\Xi_{{\bf v}_I}})\simeq C^*_r(\LL_{{\bf v}_I})$ and $\A_{I-1}=C^*_r(\LL_{\bf v}|_{\Xi_{{\bf v}_I}\cap \Xi_{r-1}})$

