\section{}
In this appendix, we summarize the main consequences of the RCI property on ${\bf v}$ that we use in this work. Accordingly, throughout this section, we assume that ${\bf v}$ satisfies the RCI property.  We start with the following convergence criterion.

\begin{lemma}\label{Lemma J}
    Assume the RCI property on ${\bf v}$. Let $\overline{\R}:=\R\cup\{+\infty\}$ and $\{x(j)\}_{j\in \N}$ a sequence in $\X_{\bf v}$ with that converges to $x\in \overline{\R}^d.$ Denote by 
    \begin{enumerate}
    \item[(i)] $J_+\subset \{1,\dots,d\}$ the set of $k$ for which $\{x_k(n)\}_{n\in \N}$ is non-increasing and converges to a finite value,
    \item[(ii)] $J_-\subset \{1,\dots,d\}$ the set of $k$ such that $\{x_k(j)\}_{j\in \N}$ is strictly increasing and converges to a finite value,
    \item[(iii)] $J_\infty\subset \{1,\dots,d\}$ the set of $k$ such that $\{x_k(j)\}_{j\in \N}$ converges to $+\infty$.
    \end{enumerate} 
    If $J_+\cup J_-\cup J_\infty = \{1,\dots,d\}$ then $\LL_{{\bf v},x(j)}^\emptyset\to \LL_{{\bf v},x}^{J_+,J_-}$ in the Fell topology, where $ \LL_{{\bf v},x}^{J_+,J_-}$ is the semigroup
    consisting of all points $n\in\mathbb{Z}^D$ such that
\begin{align*}
v_k \cdot n + x_k &\;\geq\; 0, \qquad \forall k \in J_+,\\
v_k \cdot n + x_k &\;> \;0, \qquad \forall k \in J_-.
\end{align*}
\end{lemma}

\begin{proof}
Recall that $\LL_{{\bf v},x
(j)}^\emptyset$ is the subset of all $n\in \Z^D$ defined by the inequalities
$$v_k \cdot n + x_k(j) \geq 0, \qquad k=1,\dots,d.$$
 Since $J_+\cup J_-\cup J_\infty = \{1,\dots,d\}$ and the real numbers $x_k$ are approximated from below, respectively from above, the sets defined by the given inequalities clearly converge in the Fell topology.
\end{proof}

Now, let us assume that $D=d$ and ${\bf v}$ is not rational. This means that $\X_{{\bf v}_I}=\R^{d-|I|}_+$ for any properly contained subset $I$ of $\{1,\dots ,d\}$ while $\X_{\bf v}$ remains discrete. As a consequence, all the vectors ${\bf v}=\{ v_1,\dots,v_d\}$ have components linearly independents over $\Q.$ For any fixed $i\in \{1,\dots,d\}$, and $M,\epsilon>0$ define the set
$$\Lambda_{M,\epsilon,i}\;=\;\big\{n\in \Z^D: \epsilon> v_k\cdot n> 0, k\neq i \;\; \wedge \;\;  v_i\cdot n > M\big\}$$
An important property is that this set is non-empty:
\begin{proposition}\label{lemma_special_CI_case}
    Under the above assumption, the set $\Lambda_{M,\epsilon ,i}$ is non-empty for all $i\in \{1,\dots,d\}$ and $M,\epsilon >0.$
\end{proposition}
\begin{proof}
Due to $\X_{{\bf v}\setminus i}=\R^{d-1}_+$, each of the boxes $$B_{M,\epsilon}\;=\;\big\{n\in \Z^D\,|\,  \epsilon> v_k\cdot n> 0, k\neq i \;\; \wedge \;\; \lvert v_i\cdot n\rvert \leq M\big\},$$
and the slabs
$$S_{\epsilon}\;=\;\big\{n\in \Z^D:  \epsilon> v_k\cdot n> 0, k\neq i\big\}$$ contains infinitely many points. Choose some $m\in S_\epsilon$ and let $R>0$ be such that $m\in B_{R,\epsilon}$, e.g. $R=\lvert v_i\cdot n\rvert$. We set $$\tilde{\epsilon}\;=\;\frac{1}{2}\min_{k\neq i} (v_k\cdot m)\;>\;0.$$
Let $\tilde{R}>0$ be so large that $\tilde{R}-R > M$. There exists an element $\tilde{m} \in S_{\tilde{\epsilon}}\setminus B_{\tilde{R},\tilde{\epsilon}}$ since $S_{\tilde{\epsilon}}$ is infinite but $B_{\tilde{R},\tilde{\epsilon}}$ finite. 

There are now two possible cases: In the first case, $v_i\cdot \tilde{m}$ is positive, which means $v_i \cdot \tilde{m}>\tilde{R}>M$ and thus $\tilde{m} \in \Lambda_{M,\epsilon,i}$, showing that the set is non-empty.  In the second case, $v_i\cdot \tilde{m}< -\tilde{R}$ is negative. Consider instead $n=m-\tilde{m}$. One has $$0\;<\;\tilde{\epsilon} - \frac{1}{2}\tilde{\epsilon}\;<\;v_k\cdot n \;<\; \epsilon$$ for each $k\neq i$ as well as
$$v_i \cdot n \;= \;v_i \cdot m - v_i \cdot\tilde{m} \;>\; -R + \tilde{R} > M,$$
showing that $n\in \Lambda_{M,\epsilon,i}$. 
\end{proof}
\begin{lemma}\label{lemma convergence}
   Let the RCI property be valid for ${\bf v}.$  For any $I\subset \{1,\dots,d\}$ and $x\in \X_{{\bf v}_I}$ there exists a sequence $\{n(j)\}_{j\in \N}$ in $\LL_{\bf v}$ such that $A_{{\bf v}_I}n(j)\to x$, $j\mapsto v_k\cdot n(j)$ is non-increasing for $k\in I$ and $v_k\cdot n(j)\to +\infty$ for all $k\notin I.$
\end{lemma}
\begin{proof}
It is enough to prove existence of a sequence $\{n(j)\}_{j\in \N}$ in $\LL_{\bf v}$ such that $A_{{\bf v}_I}n(j)\to 0$ in $\R^{I}$, $j\mapsto v_k\cdot n(j)$ is non-increasing for $k\in I$ and $v_k\cdot n(j)\to +\infty$ for all $k\notin I.$ For general $x$ one can then add to $n(j)$ a suitable sequence $n'(j)$ such that $A_{{\bf v}_I}n'(j)\to x$ and $j\mapsto v_k\cdot n'(j)$ is non-increasing for $k\in I$ (and such a sequence $n'(j)$ always exists under RCI). It further suffices to prove the result for sets $I = \{1,\dots,d\}\setminus \{i\}$ for each $i \in \{1, \dots, d\}$, since the general case then follows by considering the sum of sequences associated to each $i\in \{1,...,d\}\setminus I$. 

If ${\bf v}$ is CI the result follows directly from the density of $A_{\bf v}(\LL_{\bf v})$ in $\mathcal{X}_{\bf v}$. If  $d=D$ and ${\bf v}$ is not rational, the existence follows by Proposition ~\ref{lemma_special_CI_case}.

The remaining case is the rational case, where we notice that ${\rm dim}_{\Z}({\rm Ker} A_{{\bf v} \setminus i}|_{\Z^D}) = \dim_{\Z}({\rm Ker}A_{{\bf v}}|_{\Z^D}) + 1$ since those are lattices of maximal rank. Therefore, there exists a non-zero vector $n \in \Z^D$ such that $A_{{\bf v} \setminus i} n = 0$ and $v_i\cdot n> 0$. Thus, the sequence $n(j) := jn$ for $j \in \N$ satisfies the required properties. %The general case $x\neq 0$ and arbitrary $I$, it is obtained by taking $m\in \LL_{{\bf v}_I}$  such that $A_{{\bf v}_I} m =x$ and the sequence $n(j)=m+n'(j)$ where $n'(j)$ is the sequence of the previous part of the proof.

%If the sequences $v_i \cdot n'(j)$ are bounded from below, we can define $n(j) := n'(j) + n''(j)$, and the result follows. Otherwise, %define
%\[
%n(j) := n'(j) + n''(g(j)),
%\]
%where $g \colon \N \to \N$ is any increasing function such that
%\[
%\lim_{j\to +\infty}\frac{v_i \cdot n'(j)}{v_i\cdot n''\big(g(j)\big)} \;=\;0,\qquad  \forall i\notin I.
%\]
%This ensures that $v_i \cdot n(j) \to +\infty$, while still having $A_{{\bf v}_I} n(j) \to x$.

\end{proof}
