The Cartesian spatial derivatives required by the momentum~\eqref{eq:Navier-Stokes-Eq-B} and continuity \eqref{eq:Conti-Eq-B} equations (INSE) are expressed in the reference coordinate system $(\xi, \eta)$ by applying the chain rule, e.g.,~$
\partial_x = \partial_x\xi \, \partial_\xi + \partial_x\eta \,   \partial_\eta$, and using a coordinate transformation, i.e.,~$\partial_x \xi=\partial_\eta z/J$, $\partial_x\eta=-\partial_\xi z/J$, $\partial_y \xi=-\partial_\eta x/J$ and $\partial_y \eta=\partial_\xi x/J$, viz.
\begin{align}
\label{eq:curviliner-deriavtive}
    (\partial_x, \partial_z) = \frac{1}{J}
    \begin{pmatrix}
        \partial_\eta z & -\partial_\xi z \\
        -\partial_\eta x & \partial_\xi x
    \end{pmatrix}
    (\partial_\xi,  \partial_\eta)^\intercal\, ,
\end{align}
for first spatial derivatives and 
\begin{align}
    \Delta =  \frac{1}{J}(\partial_\xi, \partial_\eta)
     \frac{1}{J} \begin{pmatrix}
         g_{22} &  -g_{12} \\
         -g_{21}  & g_{11}
    \end{pmatrix}  (\partial_\xi,  \partial_\eta)^\intercal\, ,
\end{align}
for the Laplace operator. Here, $J$ denotes the Jacobian determinant and $g$ the metric tensor. They are given by the following expressions
\begin{equation}
    \begin{split}
        J = (\partial_\xi x)(\partial_\eta z) - (\partial_\eta x)(\partial_\xi z) 
    = \det \begin{pmatrix}
    \partial_\xi x & \partial_\eta x \\
    \partial_\xi z & \partial_\eta z
    \end{pmatrix} \ &,  \\
    g_{11} = (\partial_\xi x)^2 + (\partial_\xi z)^2 \ ,\quad   
    g_{22} = (\partial_\eta x)^2 + (\partial_\eta z)^2 \ , \quad 
    g_{12} = (\partial_\xi x)(\partial_\eta x) + (\partial_\xi z)(\partial_\eta z)\ & .
    \end{split}
\end{equation}
Writing out the Laplacian operator one obtains a sum of seven operator terms
\begin{equation}
    \Delta = \frac{1}{J} \Bigg\{
\partial_\xi\left( \frac{g_{22}}{J} \right) \partial_\xi 
+ \frac{g_{22}}{J} \, \partial_{\xi\xi} 
- \partial_\xi\left( \frac{g_{12}}{J} \right) \partial_\eta 
- \partial_\eta\left( \frac{g_{12}}{J} \right) \partial_\xi 
- 2 \frac{g_{12}}{J} \, \partial_{\xi\eta} 
+ \partial_\eta\left( \frac{g_{11}}{J} \right) \partial_\eta 
+ \frac{g_{11}}{J} \, \partial_{\eta\eta}
\Bigg\} \, .
\end{equation}
The derivatives w.r.t. $\xi$ and $\eta$ are approximated with second-order central difference methods. The first  derivatives of a generic scalar field \( \phi \) read 
\begin{equation}
    \begin{split}
       \partial_\xi \phi\Big|_{ij}  = \frac{\phi_{i,j+1}-\phi_{i,j-1}}{2\delta \xi} + \mathcal{O}(\delta \xi^2)\,, \quad
        \partial_\eta \phi\Big|_{ij}  = \frac{\phi_{i+1,j}-\phi_{i-1,j}}{2\delta \eta} + \mathcal{O}(\delta \eta^2)\,.
    \end{split}
\end{equation}
Similarly, the corresponding second derivatives read
\begin{equation}
\begin{split}
     \partial_{\xi\xi} \phi \Big|_{ij} = \frac{\phi_{i,j+1}-2\phi_{i,j}+\phi_{i,j-1}}{\delta \xi^2}  + \mathcal{O}(\delta \xi^2)\ , \quad
      \partial_{\eta\eta}\phi \Big|_{ij} = \frac{\phi_{i+1,j}-2\phi_{i,j}+\phi_{i-1,j}}{\delta \eta^2}  + \mathcal{O}(\delta \eta^2)\ .
\end{split}
\end{equation}
and finally mixed derivatives are approximated by 
\begin{equation}
\left.\partial_{\xi\eta} \phi \right|_{i,j}
= \frac{ \phi_{i+1,j+1} - \phi_{i+1,j-1} - \phi_{i-1,j+1} + \phi_{i-1,j-1} }{4 \delta \xi \delta \eta} + \mathcal{O}(\delta \xi^2 + \delta \eta^2)\,.
\end{equation}


