	Let ${\rm Sq}(G)$ and ${\rm Nsq}(G)$ be the sets of all square and non-square elements of $G$, respectively. For a subgroup $K$ of $G$, denote $\mathcal{L}(K)=\min\{|{\rm Nsq}(G)\cap Kx|: x\in G\setminus K\}$.

	\begin{lemma}\label{lem3}
		Let $K$ be a subgroup of $G$ and $S$ be a normal and square-free subset of $G$. The following hold:
		\begin{enumerate}
			\item\label{lem3-1} The subgroup $K$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$ if and only if $\alpha=|S\cap K|$ and $\beta=|S\cap Kx|$ for each $x\in G\setminus K$;

			\item\label{lem3-2} If $K$ is an $(\alpha,\beta)$-regular set of ${\rm CayS}(G,S)$, then $\alpha\leq|{\rm Nsq}(G)\cap K|$ and $\beta\leq \mathcal{L}(K)$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		\ref{lem3-1} The necessity is immediate from \cite[Lemma 2.4 and Corollary 2.5]{FS24}. Next we prove the sufficiency. Since $\alpha=|S\cap K|$ and $\beta=|S\cap Kx|$ for each $x\in G\setminus K$, $S$ contains exactly $\alpha$ elements of $K$ and $\beta$ elements of $Kx$ for each $x\in G\setminus K$. Let $a\in G\setminus K$. Without loss of generality, we may assume $S\cap K=\{k_1,k_2,\ldots,k_{\alpha}\}$ and $S\cap Ka=\{a_1a,a_2a,\ldots,a_{\beta}a\}$ with $a_j\in K$ for $1\leq j\leq \beta$. For each $k\in K$, there are exactly $\alpha$ elements $k^{-1}k_1,k^{-1}k_2,\ldots,k^{-1}k_{\alpha}\in K$ such that $kk^{-1}k_{i}=k_i\in S$ for $1\leq i\leq \alpha$. For $a\in G\setminus K$, there are exactly $\beta$ elements $a_1,a_2,\ldots,a_{\beta}\in K$ such that $a_ja\in S$ for $1\leq j\leq\beta$. Since $a\in G\setminus K$ was arbitrary, every element of $K$ is adjacent to exactly $\alpha$ elements of $K$ in ${\rm CayS}(G,S)$, every element of $G\setminus K$ is adjacent to exactly $\beta$ elements of $K$ in ${\rm CayS}(G,S)$. Since $S$ is a normal and square-free subset of $G$, $K$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$.

		\ref{lem3-2} This is immediate from \cite[Theorem 2.9]{FS24}.
	\end{proof}
