	Let $C$ be a subset of $A$. Denote $a_C=e$ if $C=\emptyset$, and $a_C=\prod_{a\in C}a$ if $C\neq\emptyset$. Let $T$ be the set consisting of $a_i$ with $\varphi_i(H)\neq\langle a_i\rangle$ for $1\leq i\leq \lambda$. Throughout the paper, $\sqcup$ denotes the disjoint union. Then $L\sqcup T=\{a_1,\ldots,a_{\lambda}\}$.

	\begin{lemma}\label{ff3}
		If $L'\subseteq L$ and $T'\subseteq T$, then $|Ba_{L'}a_{T'}b\cap Ha_{T'}b|=|H|/2^{|L|}$.
	\end{lemma}
	\begin{proof}
		Since $a_{L'}\in H$, we have $|Ba_{L'}a_{T'}b\cap Ha_{T'}b|=|Ba_{L'}\cap H|=|B\cap H|$. This together with Lemma \ref{fact2} \ref{fact2-1} leads to $|Ba_{L'}a_{T'}b\cap Ha_{T'}b|=|H|/2^{|L|}$.
	\end{proof}


	\begin{lemma}\label{ff2}
		There are $2^{|L|}$ distinct $a_{L'}$ for $L'\subseteq L$ and $2^{\lambda-|L|}$ distinct $a_{T'}$ for $T'\subseteq T$.
	\end{lemma}
	\begin{proof}
		Let $L'\subseteq L$ and $T'\subseteq T$. For each element $a_i\in L$ and each symbol $K\in\{L',T'\}$, if $a_i\in K$, then $\varphi_i(a_{K})=a_i$; if $a_i\notin K$, then $\varphi_i(a_{K})=e$. It follows that $\varphi_i(a_{L'})\in\{a_i,e\}$ for each $a_i\in L$ and $\varphi_i(a_{T'})\in\{a_i,e\}$ for each $a_i\in T$. Note that $|T|=\lambda-|L|$. Since $L'\subseteq L$ and $T'\subseteq T$ were arbitrary, there are exactly  $2^{|L|}$ distinct $a_{L'}$ for $L'\subseteq L$ and $2^{\lambda-|L|}$ distinct $a_{T'}$ for $T'\subseteq T$.
	\end{proof}

	\begin{lemma}\label{f2}
		We have $\sqcup_{L'\subseteq L,T'\subseteq T}Ba_{L'}a_{T'}=A$ and $H=\sqcup_{L'\subseteq L}(H\cap B)a_{L'}$.
	\end{lemma}
	\begin{proof}
		In view of Lemma \ref{ff2}, there are $2^{|L|}$ distinct $a_{L'}$ for $L'\subseteq L$ and $2^{\lambda-|L|}$ distinct $a_{T'}$ for $T'\subseteq T$. By \eqref{A'B}, $Ba_K$ and $Ba_{K'}$ are pairwise disjoint for distinct subsets $K$ and $K'$ of $\{a_1,\ldots,a_{\lambda}\}$. In view of \eqref{A'B}, we get $|A:B|=2^{\lambda}$. The fact $L\sqcup T=\{a_1,\ldots,a_{\lambda}\}$ implies $\sqcup_{L'\subseteq L,T'\subseteq T}Ba_{L'}a_{T'}=A$. Since $L\subseteq H$, from Lemma \ref{fact2} \ref{fact2-1}, we get $H=\sqcup_{L'\subseteq L}(H\cap B)a_{L'}$.	\end{proof}



	\begin{lemma}\label{f1}
		Let $a\in A\setminus H$ and $m=|L|$. If $Ha=Ha^{-1}$, then there exists $h\in H$ such that $a^2=h^2$.
	\end{lemma}
	\begin{proof}
		Since $m=|L|$, we may assume
		\begin{align}
			H=\langle a_{i_1}\rangle\times\cdots\times\langle a_{i_{|L|}}\rangle\times\langle a_{\lambda+1}'\rangle\times\cdots\times\langle a_{\lambda+\mu}'\rangle\nonumber,
		\end{align}
		where $1\leq i_1<i_2<\cdots<i_{{|L|}}\leq\lambda$ and $a'_{j}\in\langle a_j\rangle$ with $\lambda+1\leq j\leq \lambda+\mu$. Since $Ha=Ha^{-1}$, we have $a^2\in H$. Since $a\in A$, from \eqref{A'B} and Fact \ref{jb2}, we obtain $a^2\in B$, and so $a^2\in H\cap B=\langle a_{i_1}^2\rangle\times\cdots\times\langle a_{i_{|L|}}^2\rangle\times\langle a_{\lambda+1}'\rangle\times\cdots\times\langle a_{\lambda+\mu}'\rangle$. It follows that there exists $h\in H$ such that $a^2=h^2$.
	\end{proof}


	\begin{lemma}\label{fact1}
		Let $a\in A\setminus H$. If $m=|L|$, then $Ha=Ha^{-1}$ if and only if $Ha\cap A'\neq\emptyset$.
	\end{lemma}
	\begin{proof}
		We first prove the necessity. Assume $Ha=Ha^{-1}$. In view of Lemma \ref{f1}, we have $a^2=h^2$ for some $h\in H$. It follows that $(h^{-1}a)^2=e$. By Fact \ref{jb3}, we get $h^{-1}a\in Ha\cap A'$, which implies $Ha\cap A'\neq\emptyset$.

		We next prove the sufficiency. Let $a'\in Ha\cap A'$. Then there exists $h\in H$ such that $a'=ha$. It follows that $a=h^{-1}a'$. Since $a'\in A'$, from Fact \ref{jb3}, one gets $a^2=(h^{-1}a')^2=h^{-2}a'^2=h^{-2}\in H$. Then $Ha=Ha^{-1}$.
	\end{proof}




	\begin{lemma}\label{fact3}
		Let $a\in A\setminus H$. Suppose $Ha=Ha^{-1}$. If $Ha\cap A'\neq\emptyset$ and $Ha\cap {\rm Sq}(G)\neq\emptyset$, then $Ha\cap A'\cap {\rm Sq}(G)\neq\emptyset$.
	\end{lemma}
	\begin{proof}
		In view of Fact \ref{jb2}, we obtain ${\rm Sq}(G)=B\cup\{b^2\}$, and so $Ha\cap {\rm Sq}(G)=Ha\cap (B\cup\{b^2\})\neq\emptyset$. If $b^2\in Ha$, then $Hb^2=Ha$, which implies $b^2\in Ha\cap A'\cap{\rm Sq}(G)$ from Fact \ref{jb3}.

		Now we only need to consider the case $b^2\notin Ha$. It follows that $Ha\cap B\neq\emptyset$. Since $a\notin H$, there exists $c\in B\setminus H$ such that $Hc=Ha$. Since $Ha=Ha^{-1}$, one gets $(Hc)^2=(Ha)^2=H$, which implies $Hc=Hc^{-1}$. Since $Ha=Hc$, we have $Hc\cap A'\neq\emptyset$, and so $(hc)^2=e$ for some $h\in H$ from Fact \ref{jb3}. It follows that $h^{2}=c^{-2}$. Since $h\in H$, from Lemma \ref{f2}, we have $h=c'a_{L'}$ for some $c'\in H\cap B$ and $L'\subseteq L$. It follows that $h^2={c'}^2a_{L'}^2=c^{-2}$, and so $(c'c)^2=a_{L'}^{-2}$. Since $c\in B\setminus H$ and $c'\in H\cap B$, we get $c'c\in B\setminus H$. It follows from Fact \ref{jb2} that $c'c\in Hc\cap {\rm Sq}(G)$. Since $Hc=Ha$, we obtain $c'c\in Ha\cap {\rm Sq}(G)$.

		By Fact \ref{jb3}, it suffices to show that $(c'c)^{2}=a_{L'}^{-2}=e$. The case $a_{L'}=e$ is trivial. Now suppose $a_{L'}\neq e$. Since $c'c\in (B\setminus H)\cap {\rm Sq}(G)$, from \eqref{A'B}, there exists $a'\in A\setminus H$ such that $c'c={a'}^2$. Pick $a_i\in L'$. Let $\varphi_i(a')=a_i^{t_i}$. Since $a'^4=(c'c)^2=a_{L'}^{-2}$ and $\varphi_i(a_{L'})=a_i$, we have ${a_i}^{4t_i}={a_i}^{-2}$, and so $4t_i\equiv-2~\pmod{2^{e_{i}}}$ with $e_i\geq 1$, which imply $2^{e_i-1}\mid 2t_i+1$. It follows that $e_i=1$, and so $a_i$ is an involution. Since $a_i\in L'$ was arbitrary, one gets $(c'c)^{2}=a_{L'}^{-2}=e$.
	\end{proof}


	\section{$(0,\beta)$-regular set}
	In this section, we give some results concerning $(0,\beta)$-regular sets in Cayley sum graphs on generalized dicyclic groups.
	\begin{lemma}\label{f3}
		Let $a\in A$ and $S$ be a normal and square-free subset of $G$. Suppose $a\in Ba_{L'}a_{T'}$ for some $L'\subseteq L$ and $T'\subseteq T$. If $S$ contains exactly $t$ sets of type $Ba_{L''}a_{T'}b$ with $L''\subseteq L$, then $|S\cap Hab|=t|H|/2^{|L|}$.
	\end{lemma}
	\begin{proof}
		Let $\mathscr{A}$ be the set consisting of $(L'',T'')$ such that $L''\subseteq L$, $T''\subseteq T$ and $S\cap Ba_{L''}a_{T''}b\neq\emptyset$. In view of Lemma \ref{lem2}, $Ba_{L''}a_{T''}b$ is normal for $(L'',T'')\in\mathscr{A}$. Since $S$ is normal, $(L'',T'')\in\mathscr{A}$ if and only if $Ba_{L''}a_{T''}b\subseteq S$ for $L''\subseteq L$ and $T''\subseteq T$. By Lemma \ref{f2}, we have $\cup_{(L'',T'')\in\mathscr{A}}Ba_{L''}a_{T''}b=S\cap Ab$.

		Since $a\in Ba_{L'}a_{T'}$, there exists $c\in B$ such that $a=ca_{L'}a_{T'}$. Since $a_{L'}\in H$ and $c\in B$, we get
		\begin{align}\label{SHab}
			|S\cap Hab|&=|S\cap Ab\cap Hca_{L'}a_{T'}b|\nonumber\\
			&=|S\cap Ab\cap Hca_{T'}b|\nonumber\\
			&=|(\cup_{(L'',T'')\in\mathscr{A}}Ba_{L''}a_{T''}b)\cap Hca_{T'}b|\nonumber\\
			&=|(\cup_{(L'',T'')\in\mathscr{A}}Ba_{L''}a_{T''}b)\cap Ha_{T'}b|.
		\end{align}
		By Lemma \ref{f2}, we get $H=\sqcup_{L''\subseteq L}(H\cap B)a_{L''}\subseteq \sqcup_{L''\subseteq L}Ba_{L''}$, and so $Ha_{T'}b\subseteq \sqcup_{L''\subseteq L}Ba_{L''}a_{T'}b$. In view of \eqref{A'B}, $Ba_K$ and $Ba_{K'}$ are pairwise disjoint for distinct subsets $K$ and $K'$ of $\{a_1,\ldots,a_{\lambda}\}$, which implies
		$(\cup_{(L'',T'')\in\mathscr{A}}Ba_{L''}a_{T''}b)\cap Ha_{T'}b=(\cup_{(L'',T')\in\mathscr{A}}Ba_{L''}a_{T'}b)\cap Ha_{T'}b$.

		By \eqref{SHab}, we obtain $|S\cap Hab|=|(\cup_{(L'',T')\in\mathscr{A}}Ba_{L''}a_{T'}b)\cap Ha_{T'}b|$. Since $(L'',T')\in\mathscr{A}$ if and only if $Ba_{L''}a_{T'}b\subseteq S$ for $L''\subseteq L$, from Lemmas \ref{ff3} and \ref{f2}, we get $|S\cap Hab|=t|H|/2^{|L|}$, where $S$ contains exactly $t$ sets of type $Ba_{L''}a_{T'}b$ with $L''\subseteq L$.
	\end{proof}

	In this section, let $J$ be the union of $Ha$ for $a\in A\setminus H$ satisfying $Ha=Ha^{-1}$ and $Ha\cap A'=\emptyset$.

	\begin{lemma}\label{f6}
		If $m>|L|$, then $J\neq\emptyset$.
	\end{lemma}
	\begin{proof}
		Since $m>|L|$, we may assume
		\begin{align}
			H=\langle a_{i_1}\rangle\times\cdots\times\langle a_{i_{|L|}}\rangle\times \langle a'_{i_{|L|+1}}\rangle\times\cdots\times\langle a'_{i_m}\rangle\times\langle a'_{\lambda+1}\rangle\times\cdots\times\langle a'_{\lambda+\mu}\rangle,\nonumber
		\end{align}
		where $1\leq i_1<i_2<\cdots<i_m\leq\lambda$, $\{e\}\neq\langle a'_{h}\rangle\subsetneq\langle a_{h}\rangle$ with $i_{|L|+1}\leq h\leq i_m$ and $a'_{j}\in\langle a_{j}\rangle$ with $\lambda+1\leq j\leq\lambda+\mu$. Let $l$ be the minimal positive integer such that $a_{i_{m}}^{l}\in H$. Since $o(a_{i_m})=2^{e_{i_m}}$ and $\{e\}\neq \langle a'_{i_m}\rangle\subsetneq\langle a_{i_m}\rangle$, one gets $l=2^{e'_{i_m}}$ with $1\leq e'_{i_m}< e_{i_m}$. It follows that $2\leq l<2^{e_{i_m}}$ and $a_{i_{m}}^{l/2}\in A\setminus H$. Then $Ha_{i_m}^{l/2}=Ha_{i_m}^{-l/2}$.

		It suffices to show that $Ha_{i_m}^{l/2}\cap A'=\emptyset$. Since $Ha_{i_m}^{l/2}\cap H=\emptyset$ and $\varphi_{i}(Ha_{i_m}^{-l/2})=\varphi_{i}(H)$ for $1\leq i\leq \lambda+\mu$ with $i\neq i_{m}$, we have $\varphi_{i_m}(Ha_{i_m}^{l/2})\cap \varphi_{i_m}(H)=\varphi_{i_m}(Ha_{i_m}^{l/2})\cap \langle a'_{i_m}\rangle=\emptyset$. By the minimality of $l$, one gets $\langle a_{i_m}^{2^{e_{i_m}-1}}\rangle\leqslant \langle a'_{i_m}\rangle=\langle a_{i_m}^{l}\rangle$, and so $\varphi_{i_m}(Ha_{i_m}^{l/2})\cap \langle a_{i_m}^{2^{e_{i_m}-1}}\rangle=\emptyset$, which imply $\varphi_{i_m}(Ha_{i_m}^{l/2})\cap A'=\emptyset$ from \eqref{A'}. Then $Ha_{i_m}^{l/2}\cap A'=\emptyset$.% Assume the contrary, namely, $J=\emptyset$. Then $Ha_{i_m}^{l/2}\cap A'\neq\emptyset$, and so $\varphi_{i_m}(Ha_{i_m}^{l/2})\cap \varphi_{i_m}(A')\neq\emptyset$. By \eqref{A'}, we get $\varphi_{i_m}(A')=\langle a_{i_m}^{2^{e_{i_m}-1}}\rangle$, which implies $\varphi_{i_m}(Ha_{i_m}^{l/2})\cap \langle a_{i_m}^{2^{e_{i_m}-1}}\rangle$
	\end{proof}

	A {\em right transversal} (resp. {\em left transversal}) of $H$ in $A$ is defined as a subset of $A$ which contains exactly one element in each right coset (resp. left coset) of $H$ in $A$. Since $A$ is abelian, every right coset of any subgroup is also a left coset of the subgroup, for the sake of simplicity, we use the term ``transversal'' to substitute for ``right transversal'' or ``left transversal''.

	\begin{lemma}\label{fact4}
		There exists a transversal $I$ of $H$ in $A$ containing $e$ such that $I\setminus J$ is inverse-closed and $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$.
	\end{lemma}
	\begin{proof}
		Let $I$ be a transversal of $H$ in $A$ containing $e$ such that $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$. Note that $Ha\neq Ha^{-1}$, $Ha=Ha^{-1}$ and $Ha\cap A'\neq\emptyset$, or $Ha=Ha^{-1}$ and $Ha\cap A'=\emptyset$ for each $Ha\in A/H\setminus\{H\}$. For each $Ha\in A/H\setminus\{H\}$ satisfying $Ha\neq Ha^{-1}$, let $ha\in Ha$ and $h^{-1}a^{-1}\in Ha^{-1}$ belong to $I$ for some $h\in H$. For each $Ha\in A/H\setminus\{H\}$ satisfying $Ha=Ha^{-1}$ and $Ha\cap A'\neq\emptyset$, if $Ha\cap {\rm Sq}(G)=\emptyset$, then let $ha\in Ha\cap A'$ belong to $I$ for some $h\in H$; if $Ha\cap {\rm Sq}(G)\neq\emptyset$, from Lemma \ref{fact3}, then let $ha\in Ha\cap A'\cap {\rm Sq}(G)$ belong to $I$ for some $h\in H$. Since $J$ is the union of $Ha$ for $a\in A\setminus H$ satisfying $Ha=Ha^{-1}$ and $Ha\cap A'=\emptyset$, from Fact \ref{jb3}, $I\setminus J$ is inverse-closed.
	\end{proof}



	\subsection{$H$ is a $(0,\beta)$-regular set of $G$}

	In this subsection, by giving an appropriate connection set $S$, we determine each possibility for $\beta$ such that $H$ is a $(0,\beta)$-regular set of $G$.





	\begin{lemma}\label{lem7}
		The following hold:
		\begin{enumerate}
			\item\label{lem7-1} If $B\cup\{b^2\}\subseteq H$, then $\mathcal{L}(H)=|H|$;

			\item\label{lem7-4} If $B\leqslant H$ and $b^2\notin H$, then $\mathcal{L}(H)=|H|-1$;

			\item\label{lem7-3} If $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}-1$;

			\item\label{lem7-2} If $B\nleqslant H$, and $b^2\in H\cup B$ or $Hb^2\cap B=\emptyset$, then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}$.

		\end{enumerate}
	\end{lemma}
	\begin{proof}
		By Fact \ref{jb2}, one gets ${\rm Sq}(G)=B\cup\{b^2\}$. It follows that $Hx\subseteq {\rm Nsq}(G)$ for each $Hx\in G/H\setminus\{H\}$ with $Hx\cap(B\cup\{b^2\})=\emptyset$. For each $Hx\in G/H\setminus\{H\}$ with $Hx\cap B\neq\emptyset$ and $b^2\notin Hx$, there exists $c\in B$ such that $Hx=Hc$, which implies $|{\rm Nsq}(G)\cap Hx|=|{\rm Nsq}(G)\cap Hc|=|Hc\setminus (H\cap B)c|=(2^{|L|}-1)|H|/2^{|L|}$ from Lemma \ref{fact2} \ref{fact2-1}. To determine $\mathcal{L}(H)$, it suffices to consider the coset $Hb^2$.

		\ref{lem7-1} Since $B\cup\{b^2\}\subseteq H$, one gets $Hx\subseteq {\rm Nsq}(G)$ for each $x\in G\setminus H$, and so $\mathcal{L}(H)=|H|$.

		\ref{lem7-4} Since $B\leqslant H$, we have $Hx\cap B=\emptyset$ for each $Hx\in G/H\setminus\{H\}$. Since $B\leqslant H$ and $b^2\notin H$, one obtains ${\rm Nsq}(G)\cap Hb^2=Hb^2\setminus \{b^2\}$, and so $\mathcal{L}(H)=|H|-1$.

		\ref{lem7-3} Since $Hb^2\cap B\neq\emptyset$, one gets $Hb^2=Ha$ for some $a\in B$. Since $b^2\notin H\cup B$ and $Ba=B$, from Lemma \ref{fact2} \ref{fact2-1}, one gets $|{\rm Nsq}(G)\cap Hb^2|=|Ha\setminus(Ba\cup\{b^2\})|=|Ha\setminus (Ha\cap Ba)|-1=(2^{|L|}-1)|H|/2^{|L|}-1$. Then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}-1$.

		\ref{lem7-2} If $b^2\in H$, then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}$, and so \ref{lem7-2} is valid. Now suppose $b^2\notin H$. If $b^2\in B$, from Lemma \ref{fact2} \ref{fact2-1}, then $|{\rm Nsq}(G)\cap Hb^2|=|Hb^2\setminus B|=|Hb^2\setminus(H\cap B)b^2|=(2^{|L|}-1)|H|/2^{|L|}$, which implies that \ref{lem7-2} holds. If $b^2\notin B$, then $Hb^2\cap B=\emptyset$, and so $|{\rm Nsq}(G)\cap Hb^2|=|Hb^2\setminus \{b^2\}|=|H|-1$. Thus, \ref{lem7-2} holds.
	\end{proof}

	\begin{lemma}\label{lem13}
		Suppose that $I$ is a transversal of $H$ in $A$ containing $e$ such that $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$. The following hold:
		\begin{enumerate}
			\item\label{lem13-1} If $B\cup\{b^2\}\subseteq H$, then $(I\setminus\{e\})x$ is square-free for each $x\in H$;

			\item\label{lem13-2} If $B\leqslant H$ and $b^2\notin H$, then $(I\setminus\{e\})x$ is square-free for each $x\in H\setminus B$;

			\item\label{lem13-3} If $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, then $(I\setminus\{e\})x$ is square-free for each $x\in H\setminus (B\cup Bb^2)$;

			\item\label{lem13-4} If $B\nleqslant H$, and $b^2\in H\cup B$ or $Hb^2\cap B=\emptyset$, then $(I\setminus\{e\})x$ is square-free for each $x\in H\setminus B$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		Note that $I\setminus\{e\}=((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))\cup (I\setminus(\cup_{a\in B\cup \{b^2\}}Ha))$. By Fact \ref{jb2}, one gets ${\rm Sq}(G)=B\cup \{b^2\}\subseteq \cup_{a\in B\cup \{b^2\}}Ha$. Since $Hah=Ha$ for each $h\in H$ with $a\in A$, one gets $(I\setminus(\cup_{a\in B\cup \{b^2\}}Ha))h\subseteq A\setminus(B\cup\{b^2\})$, which implies that $(I\setminus(\cup_{a\in B\cup \{b^2\}}Ha))h$ is square-free. It suffices to show that $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free for each case.

		\ref{lem13-1} Since $B\cup\{b^2\}\subseteq H$, we get $\cup_{a\in B\cup \{b^2\}}Ha=H$, and so $(I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha)=(I\setminus\{e\})\cap H=\emptyset$, which imply $(I\setminus\{e\})x=(I\setminus(\cup_{a\in B\cup \{b^2\}}Ha))x$ for each $x\in H$. Thus, \ref{lem13-1} is valid.

		\ref{lem13-2} Since $b^2\notin H$, one gets $Hb^2\cap H=\emptyset$. Since $B\leqslant H$, we have $Hb^2\cap B=\emptyset$ and $\cup_{a\in B\cup \{b^2\}}Ha=H\cup Hb^2$. Since $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$ and $Hb^2\cap B=\emptyset$, from Fact \ref{jb2}, we have $b^2\in I$, which implies $(I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha)=(I\setminus\{e\})\cap (H\cup Hb^2)=(I\setminus\{e\})\cap Hb^2=\{b^2\}$. Then $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x=\{b^2x\}\subseteq Hb^2\setminus (B\cup Bb^2)\subseteq A\setminus (B\cup Bb^2)$ for each $x\in H\setminus B$, and so $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free. Thus, \ref{lem13-2} holds.

		\ref{lem13-3} Note that $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$. Since $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, from Fact \ref{jb2}, one obtains $(I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha)\subseteq B\cup \{b^2\}\subseteq B\cup Bb^2$, which implies $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x\subseteq (B\cup Bb^2)x\subseteq A\setminus (B\cup Bb^2)$ for each $x\in H\setminus (B\cup Bb^2)$. Then $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free for each $x\in H\setminus (B\cup Bb^2)$. Thus, \ref{lem13-3} is valid.

		\ref{lem13-4} Note that $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$. If $b^2\in H$, from Fact \ref{jb2}, then $(I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha)=(I\setminus\{e\})\cap (\cup_{a\in B}Ha)\subseteq B\setminus\{e\}$, and so $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x\subseteq A\setminus (H\cup B)$ for each $x\in H\setminus B$, which imply that $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free. If $b^2\in B$, then $B\cup\{b^2\}=B$, and so $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x\subseteq Bx\subseteq A\setminus B$ for each $x\in H\setminus B$ from Fact \ref{jb2}, which imply that $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free.

		Now suppose $b^2\notin H\cup B$. It follows that $Hb^2\cap B=\emptyset$. Since $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$, one has $I\cap Hb^2=\{b^2\}$. For each $x\in H\setminus B$, since $Hb^2\cap B=\emptyset$, we obtain $(I\cap Hb^2)x=\{b^2x\}\subseteq Hb^2\setminus Bb^2\subseteq A\setminus (B\cup \{b^2\})$ and $((I\setminus\{e\})\cap (\cup_{a\in B}Ha))x\subseteq Bx\subseteq A\setminus (B\cup Bb^2)$, which imply that $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x\subseteq A\setminus (B\cup \{b^2\})$. Then $((I\setminus\{e\})\cap (\cup_{a\in B\cup \{b^2\}}Ha))x$ is square-free for each $x\in H\setminus B$. Thus, \ref{lem13-4} is valid.
	\end{proof}



	\begin{lemma}\label{lem8}	
		The subgroup $H$ is a $(0,\beta)$-regular set in ${\rm CayS}(G,S)$ if and only if $\beta=t|H|/2^{|L|}$ and one of the following holds:
		\begin{enumerate}
			\item\label{lem8-1} $0\leq t\leq 2^{|L|}$, $B\cup\{b^2\}\subseteq H$;

			\item\label{lem8-2} $0\leq t\leq 2^{|L|}-1$, $B\leqslant H$ and $b^2\notin H$;

			\item\label{lem8-4} $0\leq t\leq 2^{|L|}-2$, $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$;

			\item\label{lem8-3} $0\leq t\leq 2^{|L|}-1$, $B\nleqslant H$, and $b^2\in H\cup B$ or $Hb^2\cap B=\emptyset$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}

		We first prove the necessity. Pick an element $a\in A$. In view of Lemma \ref{f2}, one gets $a\in Ba_{L'}a_{T'}$ for some $L'\subseteq L$ and $T'\subseteq T$. Since $S$ is normal, from Lemma \ref{lem2}, we may assume that $S$ contains exactly $t$ sets of type $Ba_{L''}a_{T'}b$ with $L''\subseteq L$. In view of Lemmas \ref{lem3} and \ref{f3}, we get $\beta=|S\cap Hab|=t|H|/2^{|L|}$ with $0\leq t\leq \frac{\mathcal{L}(H)\cdot2^{|L|}}{|H|}$.

		If $B\cup\{b^2\}\subseteq H$, from Lemma \ref{lem7} \ref{lem7-1}, then $\mathcal{L}(H)=|H|$, and so $0\leq t\leq 2^{|L|}$, which imply that \ref{lem8-1} is valid. If $B\leqslant H$ and $b^2\notin H$, from Lemma \ref{lem7} \ref{lem7-4}, one gets $\mathcal{L}(H)=|H|-1$, and so $0\leq t\leq 2^{|L|}-1$, which imply that \ref{lem8-2} holds. If $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, from Lemma \ref{lem7} \ref{lem7-3}, then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}-1$, and so $0\leq t\leq 2^{|L|}-2$, which imply that \ref{lem8-4} is valid. If $B\nleqslant H$, and $b^2\in H\cup B$ or $Hb^2\cap B\neq\emptyset$, from Lemma \ref{lem7} \ref{lem7-2}, then $\mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}$, and so $0\leq t\leq 2^{|L|}-1$, which imply that \ref{lem8-3} holds.


		Next we prove the sufficiency. If $t=2^{|L|}$, then $\beta=|H|$, and so $S=G\setminus H$. Now we consider $0\leq t\leq 2^{|L|}-1$. By Lemma \ref{fact4}, let $I$ be a transversal of $H$ in $A$ containing $e$ such that $I\setminus J$ is inverse-closed and $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$.

		In view of Lemma \ref{ff2}, there are $2^{|L|}-1$ distinct $a_{L'}$ for $\emptyset\neq L'\subseteq L\subseteq H$. By \eqref{A'B}, $Ba_K$ and $Ba_{K'}$ are pairwise disjoint for distinct subsets $K$ and $K'$ of $\{a_1,\ldots,a_{\lambda}\}$. If $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, then $H\cap Bb^2\neq\emptyset$, and there are $2^{|L|}-2$ distinct $a_{L'}$ for $\emptyset\neq L'\subseteq L$ and $a_{L'}\notin Bb^2$ from Lemma \ref{f2}. Since $0\leq t|H|/2^{|L|}\leq \mathcal{L}(H)$ from Lemma \ref{lem7}, each coset $Hx$ with $x\in G\setminus H$ has at least $t|H|/2^{|L|}$ non-square elements. Since $a_{L'}\in H$ with $L'\subseteq L$, from Lemma \ref{fact2} \ref{fact2-1}, one has $|H\cap Ba_{L'}|=|H|/2^{|L|}$.

		If $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, then let $S$ be a union of $t|H|/2^{|L|+1}$ sets of type $\{ha',h^{-1}a'^{-1}\}$ with $ha'\in{\rm Nsq}(G)$ and $h\in H$ for each $Ha'\subseteq J$, $t$ sets of type $\cup_{x\in H\cap Ba_{L'}}(I\setminus (J\cup\{e\}))x$ and $t$ sets of type $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$ and $a_{L'}\notin Bb^2$. If $B\leqslant H$, or $b^2\in H\cup B$, or $Hb^2\cap B=\emptyset$, then let $S$ be a union of $t|H|/2^{|L|+1}$ sets of type $\{ha',h^{-1}a'^{-1}\}$ with $ha'\in{\rm Nsq}(G)$ and $h\in H$ for each $Ha'\subseteq J$, $t$ sets of type $\cup_{x\in H\cap Ba_{L'}}(I\setminus (J\cup\{e\}))x$ and $t$ sets of type $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$.

		%If $m=|L|$, then let $S$ be a union of $t$ sets of type $\cup_{x\in H\cap Ba_{L'}}(I\setminus \{e\})x$ and $t$ sets of type $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$ (For $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, $\emptyset\neq L'\subseteq L$ and $Ba_{L'}\cap Bb^2\neq\emptyset$). If $m>|L|$, then let $S$ be a union of $t$ sets of type $\cup_{x\in H\cap Ba_{L'}}(I\setminus (J\cup\{e\}))x$, $t|H|/2^{|L|+1}$ sets of type $\{ha',h^{-1}a'^{-1}\}$ with $h\in H$ and $ha'\in{\rm Nsq}(G)$ for each $Ha'\subseteq J$, and $t$ sets of type $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$ (For $B\nleqslant H$, $b^2\notin H\cup B$ and $Hb^2\cap B\neq\emptyset$, $\emptyset\neq L'\subseteq L$ and $Ba_{L'}\cap Bb^2\neq\emptyset$).

		We now claim that $H$ is a $(0,t|H|/2^{|L|})$-regular set in ${\rm CayS}(G,S)$. The proof proceeds in the following steps.
		\begin{step}\label{step-1}
			$S$ is normal and square-free.
		\end{step}
		In view of Fact \ref{jb2} and Lemma \ref{lem2}, $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$ is normal and square-free. By Lemma \ref{lem13}, $S$ is square-free.

		Let $L'$ be a nonempty subset of $L$ and $d\in H\cap Ba_{L'}$. Since $d\in Ba_{L'}$, there exists $c\in B$ such that $d=ca_{L'}$. By \eqref{A'B}, we have $a_{L'}^2\in B$, and so $d^{-1}=c^{-1}a_{L'}^{-1}\in H\cap Ba_{L'}^{-1}=H\cap Ba_{L'}$. Since $L'$ and $d$ were arbitrary, $H\cap Ba_{L'}$ is inverse-closed for each nonempty subset of $L$.

		%If $m=|L|$, by Lemma \ref{fact1}, then $J=\emptyset$, and so $\cup_{x\in H\cap Ba_{L'}}(I\setminus\{e\})x$ with $\emptyset\neq L'\subseteq L$ is normal from Corollary \ref{cor1}, which imply that $S$ is normal.

		%If $m>|L|$, from Lemma \ref{f6}, then $J\neq\emptyset$, and so $\cup_{x\in H\cap Ba_{L'}}(I\setminus (J\cup\{e\}))x$ with $\emptyset\neq L'\subseteq L$, and $\{ha',h^{-1}a'^{-1}\}$ with $h\in H$ and $ha'\in{\rm Nsq}(G)$ for $Ha'\subseteq J$ are normal by Corollary \ref{cor1}, which imply that $S$ is normal.

		Since $I\setminus (J\cup\{e\})$ is inverse-closed, $\cup_{x\in H\cap Ba_{L'}}(I\setminus (J\cup\{e\}))x$ for each nonempty subset $L'$ of $L$, and $\{ha',h^{-1}a'^{-1}\}$ with $ha'\in{\rm Nsq}(G)$ and $h\in H$ for each $Ha'\subseteq J$ are normal by Corollary \ref{cor1}, which imply that $S$ is normal.


		Thus, Step \ref{step-1} holds.
		\begin{step}\label{step-2}
			%By Fact \ref{jb2}, we have ${\rm Sq}(G)=B\cup\{b^2\}\subseteq \cup_{a\in B\cup\{b^2\}}Ha$. Since $Hax=Ha$ for each $x\in H\cap Ba_{L'}$ with $a\in A$, we have $\cup_{x\in H\cap Ba_{L'}}(I\setminus (\cup_{a\in B\cup\{b^2\}}Ha))x\subseteq A\setminus(B\cup\{b^2\})$, which implies $\cup_{x\in H\cap Ba_{L'}}(I\setminus (\cup_{a\in B\cup\{b^2\}}Ha))x$ is square-free.

			%Since $I$ contains a square element in each coset of $H$ having intersection with ${\rm Sq}(G)$, one gets $I\cap (\cup_{a\in B\cup\{b^2\}}Ha)\subseteq {\rm Sq}(G)=B\cup\{b^2\}$.  %It follows that $(I\setminus\{e\})\cap (\cup_{a\in B}Ha)\subseteq B\setminus\{e\}$. Note that $Hax=Ha$ for each $x\in H\cap Ba_{L'}$ with $a\in A$. Since $H\cap Ba_{L'}\subseteq H\setminus B$ with $\emptyset\neq L'\subseteq L$, one gets $\cup_{x\in H\cap Ba_{L'}}((I\setminus\{e\})\cap (\cup_{a\in B}Ha))x$ is square-free. If $b^2\in \cup_{a\in B}Ha$, then $\cup_{a\in B\cup\{b^2\}}Ha=\cup_{a\in B}Ha$, and so $\cup_{x\in H\cap Ba_{L'}}((I\setminus\{e\})\cap (\cup_{a\in B\cup\{b^2\}}Ha))x$ is square-free with $\emptyset\neq L'\subseteq L$. If $b^2\notin \cup_{a\in B}Ha$, then $Hb^2\cap B=\emptyset$ and $I\cap Hb^2=b^2$, and so $\cup_{x\in H\cap Ba_{L'}}((I\setminus\{e\})\cap Hb^2)x$ is square-free with $\emptyset\neq L'\subseteq L$, which imply $\cup_{x\in H\cap Ba_{L'}}((I\setminus\{e\})\cap (\cup_{a\in B\cup\{b^2\}}Ha))x$ is square-free.

			%Since
			%\begin{align}
			%I\setminus\{e\}=((I\setminus\{e\})\cap (\cup_{a\in B\cup\{b^2\}}Ha))\cup(I\setminus (\cup_{a\in B\cup\{b^2\}}Ha)),\nonumber
			%\end{align} one has $\cup_{x\in H\cap Ba_{L'}}(I\setminus\{e\})x$ is square-free with $\emptyset\neq L'\subseteq L$. In view of Fact \ref{jb2}, $\cup_{T'\subseteq T}Ba_{L'}a_{T'}b$ is square-free with $\emptyset\neq L'\subseteq L$. Then $S$ is square-free.
			$|S\cap Hab|=t|H|/2^{|L|}$ for each $a\in A$.
		\end{step}
		Note that $S$ contains $t$ sets of type $Ba_{L'}a_{T'}b$ with $\emptyset\neq L'\subseteq L$ for each $T'\subseteq T$. For each $a\in A$, from Lemma \ref{f2}, one gets $a\in Ba_{L''}a_{T''}$ for some $L''\subseteq L$ and $T''\subseteq T$. By Lemma \ref{f3}, we get $|S\cap Hab|=t|H|/2^{|L|}$ for each $a\in A$.

		Thus, Step \ref{step-2} is valid.
		\begin{step}\label{step-3}
			$|S\cap Ha|=t|H|/2^{|L|}$ for each $a\in A\setminus H$.
		\end{step}
