	\subsection{$\langle H,zb\rangle$ is a $(0,\beta)$-regular set of $G$}
	In this subsection, we always assume that $\langle H,zb\rangle$ is a subgroup of $G$ such that $H$ has index $2$ of $\langle H,zb\rangle$.

	In the following lemma, by giving an appropriate connection set $S$ with $S\cap A=\emptyset$, we determine each possibility for $(\alpha,\beta)$ such that $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set of $G$.

	\begin{lemma}\label{lem9}
		Let $S$ be a normal and square-free subset of $G$ with $S\cap A=\emptyset$. Then $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$ if and only if one of the following holds:
		\begin{enumerate}
			\item\label{lem9-1} $B\leqslant H$, $\alpha=t'|H|/2^{|L|}$ and $\beta=t|H|/2^{|L|}$;

			\item\label{lem9-2} $B\nleqslant H$ and $\alpha=\beta=t|H|/2^{|L|}$.
		\end{enumerate}
		Here, $0\leq t,t'\leq 2^{|L|}$.
	\end{lemma}
	\begin{proof}
		Since $H$ has index $2$ of $\langle H,zb\rangle$, we have $\langle H,zb\rangle=H\cup Hzb$. Since $S\cap A=\emptyset$, we have
		\begin{align}\label{beta}
			|S\cap \langle H,zb\rangle a|=|S\cap (H\cup Hzb)a|=|S\cap Hzba|=|S\cap Hza^{-1}b|
		\end{align}
		for each $a\in A$. Since $z\in A$, from Lemma \ref{f2}, one gets $z\in Ba_{L'}a_{T'}$ for some $L'\subseteq L$ and $T'\subseteq T$.

		We first prove the necessity. Let $a\in A\setminus H$. Since $H$ has index $2$ of $\langle H,zb\rangle$, we have $\langle H,zb\rangle a\neq \langle H,zb\rangle$. In view of Lemma \ref{f2}, one gets $za^{-1}\in Ba_{L''}a_{T''}$ for some $L''\subseteq L$ and $T''\subseteq T$. Since $S$ is normal, from Lemma \ref{lem2}, we may assume that $S$ contains exactly $t$ sets of type $Ba_{L_0}a_{T''}b$ with $L_0\subseteq L$. By Lemma \ref{lem3} \ref{lem3-1}, Lemma \ref{f3} and \eqref{beta}, one has $\beta=|S\cap \langle H,zb\rangle a|= |S\cap Hza^{-1}b|=t|H|/2^{|L|}$ with $0\leq t\leq 2^{|L|}$.


		Suppose $B\leqslant H$. Note that $z\in Ba_{L'}a_{T'}$. Since $S$ is normal, from Lemma \ref{lem2}, we may assume that $S$ contains exactly $t'$ sets of type $Ba_{L''}a_{T'}b$ with $L''\subseteq L$. By Lemma \ref{lem3} \ref{lem3-1}, Lemma \ref{f3} and \eqref{beta}, we get $\alpha=|S\cap \langle H,zb\rangle|= |S\cap Hzb|=t'|H|/2^{|L|}$ with $0\leq t'\leq 2^{|L|}$. Thus, \ref{lem9-1} is valid.


		Suppose $B\nleqslant H$. It follows that $B\setminus H\neq\emptyset$. Since $z\in Ba_{L'}a_{T'}$, we have $zc^{-1}\in Ba_{L'}a_{T'}$ with $c\in B\setminus H$. By Lemma \ref{f3}, we have $|S\cap Hzb|=|S\cap Hzc^{-1}b|$. In view of Lemma \ref{lem3} \ref{lem3-1} and \eqref{beta}, one gets $\alpha=|S\cap \langle H,zb\rangle|=|S\cap Hzb|=|S\cap Hzc^{-1}b|=|S\cap \langle H,zb\rangle c|=\beta$. Thus, \ref{lem9-2} holds.

		We next prove the sufficiency. In view of Fact \ref{jb2} and Lemma \ref{lem2}, $Ba_{L''}a_{T''}b$ is normal and square-free for each $L''\subseteq L$ and $T''\subseteq T$.

		Suppose $B\leqslant H$. It follows from Lemma \ref{f2} that $H=\sqcup_{L''\subseteq L}Ba_{L''}$. Since $z\in Ba_{L'}a_{T'}\subseteq Ha_{L'}a_{T'}=Ha_{T'}$, one gets $Hz=Ha_{T'}=\cup_{L''\subseteq L}Ba_{L''}a_{T'}$, which implies $(\cup_{L''\subseteq L}Ba_{L''}a_{T'})\cap (A\setminus Hz)=\emptyset$. Let $S$ be a union of $t'$ sets of type $Ba_{L''}a_{T'}b$ with $L''\subseteq L$, and $t$ sets of type $Ba_{L''}a_{T''}b$ with $L''\subseteq L$ for each $T''\subseteq T$ with $(\cup_{L''\subseteq L}Ba_{L''}a_{T''})\cap (A\setminus Hz)\neq\emptyset$. Since $z\in Ba_{L'}a_{T'}$, from \eqref{beta} and Lemma \ref{f3}, we obtain $|S\cap \langle H,zb\rangle|=|S\cap Hzb|=t'|H|/2^{|L|}$. For each $x\in A\setminus H$, since $zx^{-1}\in A$, from Lemma \ref{f2}, one gets $zx^{-1}\in Ba_{L''}a_{T''}$ for some $L''\subseteq L$ and $T''\subseteq T$, which implies $zx^{-1}\in Ba_{L''}a_{T''}\cap (A\setminus Hz)$. In view of \eqref{beta} and Lemma \ref{f3}, one gets $|S\cap \langle H,zb\rangle x|=|S\cap Hzx^{-1}b|=t|H|/2^{|L|}$ for each $x\in A\setminus H$. By Lemma \ref{lem3} \ref{lem3-1}, $\langle H,zb\rangle$ is a $(t'|H|/2^{|L|},t|H|/2^{|L|})$-regular set in ${\rm CayS}(G,S)$ with $0\leq t,t'\leq 2^{|L|}$.


		Suppose $B\nleqslant H$. Let $S$ be a union of $t$ sets of type $\cup_{T''\subseteq T}Ba_{L''}a_{T''}b$ with $L''\subseteq L$. For each $za^{-1}\in A$, from Lemma \ref{f2}, one gets $za^{-1}\in Ba_{L''}a_{T''}$ for some $L''\subseteq L$ and $T''\subseteq T$. By \eqref{beta} and Lemma \ref{f3}, one gets $|S\cap \langle H,zb\rangle a|=|S\cap Hza^{-1}b|=t|H|/2^{|L|}$ for each $a\in A$. In view of Lemma \ref{lem3} \ref{lem3-1}, $\langle H,zb\rangle$ is a $(t|H|/2^{|L|},t|H|/2^{|L|})$-regular set in ${\rm CayS}(G,S)$ with $0\leq t\leq 2^{|L|}$.
	\end{proof}



