	\begin{lemma}\label{lem18}
		Let $S$ be a normal and square-free subset of $G$ with $S\subseteq A$. Then $\langle H,zb\rangle$ is a $(0,\beta)$-regular set in ${\rm CayS}(G,S)$ if and only if one of the following holds:
		\begin{enumerate}
			\item\label{lem18-1} $B\leqslant H$ and $0\leq\beta\leq |H|$;

			\item\label{lem18-2} $B\nleqslant H$ and $0\leq\beta\leq (2^{|L|}-1)|H|/2^{|L|}$.
		\end{enumerate}
		Moreover, if $m>|L|$, then $2\mid\beta$.
	\end{lemma}

	\begin{proof}
		Since $H$ has index $2$ of $\langle H,zb\rangle$ and $S\subseteq A$, one gets
		\begin{align}\label{Aemptyset}
			S\cap \langle H,zb\rangle x=S\cap (H\cup Hzb)x=S\cap Hx
		\end{align}
		for each $x\in A\setminus H$.

		We first prove the necessity. Since $|G:A|=2$, one has $G=A\cup Ab$. By Fact \ref{jb2}, we have $|{\rm Nsq}(G)\cap Hab|=|H|$ for each $a\in A$. It follows that $\mathcal{L}(H)=\min\{|{\rm Nsq}(G)\cap Hx|:x\in G\setminus H\}=\min\{|{\rm Nsq}(G)\cap Hx|:x\in A\setminus H\}$. Let $\mathcal{L}(H)=|{\rm Nsq}(G)\cap Hx_0|$ with $x_0\in A\setminus H$. Since $S$ is square-free, one gets $S\cap Hx_0\subseteq {\rm Nsq}(G)\cap Hx_0$. By Lemma \ref{lem3} \ref{lem3-1} and \eqref{Aemptyset}, one obtains $\beta=|S\cap \langle H,zb\rangle x|=|S\cap Hx|$ for all $x\in A\setminus H$. It follows that $\beta=|S\cap Hx_0|\leq |{\rm Nsq}(G)\cap Hx_0|=\mathcal{L}(H)$.

		Suppose $B\leqslant H$. Since $b^2\in H$, from Lemma \ref{lem7} \ref{lem7-1}, we have $\beta\leq \mathcal{L}(H)=|H|$ for each $x\in A\setminus H$. Thus, \ref{lem18-1} is valid.

		Suppose $B\nleqslant H$. Since $b^2\in H$, from Lemma \ref{lem7} \ref{lem7-2}, one gets $\beta\leq \mathcal{L}(H)=(2^{|L|}-1)|H|/2^{|L|}$ for each $x\in A\setminus H$. Thus, \ref{lem18-2} holds.


		Now suppose $m>|L|$. In view of Lemma \ref{f6}, one has $J\neq\emptyset$. By Lemma \ref{lem3} \ref{lem3-1} and \eqref{Aemptyset}, we get $\beta=|S\cap Ha|$ for $Ha\subseteq J$. For each $ha\in S\cap Ha$ with $Ha\subseteq J$ and $h\in H$, since $S$ is normal and $Ha\cap A'=\emptyset$, we have $h^{-1}a^{-1}\in S\cap Ha^{-1}=S\cap Ha$ from Lemma \ref{lem2}. Since $Ha\cap A'=\emptyset$, from Fact \ref{jb3}, one obtains $2\mid|S\cap Ha|$, and so $2\mid\beta$. The second statement follows.

		Next we prove the sufficiency. By Lemma \ref{fact4}, let $I$ be a transversal of $H$ in $A$ containing $e$ such that $I\setminus J$ is inverse-closed and $I$ contains a square element in each coset of $H$ having nonempty intersection with ${\rm Sq}(G)$.

		By Lemma \ref{fact2} \ref{fact2-1}, we have $|H\setminus B|=(2^{|L|}-1)|H|/2^{|L|}$, $|H\cap A'|=2^m$ and $|(H\cap A')\setminus B|=2^m-2^{m-r}$. Note that $b^2\in H$. It follows that $\langle b^2\rangle\leqslant H$, and so $|H\cap A'|=2^m\geq2$, which imply $m\geq 1$. By Lemma \ref{lem7} \ref{lem7-1} and \ref{lem7-2}, we have $\beta\leq \mathcal{L}(H)$, which implies that each coset $\langle H,zb\rangle x$ with $x\in A\setminus H$ has at least $\beta$ non-square elements in $A$ by \eqref{Aemptyset}. Let $\sigma(n)=\frac{1-(-1)^{n}}{2}$ for an integer $n$. Now we give an appropriate connection set $S$ for each case respectively.
		\begin{itemize}[leftmargin=*]
			\item Suppose $B\leqslant H$, $m=|L|$ and $\beta\leq 2^m$. Let $S$ be a union of $\beta$ sets of type $(I\setminus\{e\})a'$ with $a'\in H\cap A'$.

			\item Suppose $B\leqslant H$, $m=|L|$ and $\beta> 2^m$. Let $S$ be a union of $2^m-\sigma(\beta)$ sets of type $(I\setminus\{e\})a'$ with $a'\in H\cap A'$ and $\frac{\beta-(2^m-\sigma(\beta))}{2}$ sets of type $(I\setminus\{e\})a\cup(I\setminus\{e\})a^{-1}$ with $a\in H\setminus A'$.

			\item Suppose $B\nleqslant H$, $m=|L|$ and $\beta\leq 2^m-2^{m-r}$. Let $S$ be a union of $\beta$ sets of type $(I\setminus \{e\})c'$ with $c'\in (H\cap A')\setminus B$.

			\item Suppose $B\nleqslant H$, $m=|L|$ and $\beta>2^m-2^{m-r}$. Let $S$ be a union of $2^m-2^{m-r}-\sigma(\beta)+(-1)^{\beta+1}\cdot\delta_{m,r}$ sets of type $(I\setminus \{e\})c'$ with $c'\in (H\cap A')\setminus B$ and $\frac{\beta-(2^m-2^{m-r}-\sigma(\beta)+(-1)^{\beta+1}\cdot\delta_{m,r})}{2}$ sets of type $(I\setminus\{e\})c\cup(I\setminus\{e\})c^{-1}$ with $c\in H\setminus(A'\cup B)$, where $\delta$ is the Kronecker's delta.

			\item Suppose $B\leqslant H$, $m>|L|$ and $\beta\leq 2^m$. Let $S$ be a union of $\beta$ sets of type $(I\setminus(J\cup\{e\}))a'$ with $a'\in H\cap A'$ and $\beta/2$ sets of type $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$.

			\item Suppose $B\leqslant H$, $m>|L|$ and $\beta>2^m$. Let $S$ be a union of $2^m$ sets of type $(I\setminus(J\cup\{e\}))a'$ with $a'\in H\cap A'$, $\frac{\beta-2^m}{2}$ sets of type $(I\setminus(J\cup\{e\}))a\cup(I\setminus(J\cup\{e\}))a^{-1}$ with $a\in H\setminus A'$, and $\beta/2$ sets of type $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$.

			\item Suppose $B\nleqslant H$ and $m>|L|$ and $\beta\leq 2^m-2^{m-r}$. Let $S$ be a union of $\beta$ sets of type $(I\setminus(J\cup\{e\}))c'$ with $c'\in (H\cap A')\setminus B$ and $\beta/2$ sets of type $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$.

			\item Suppose $B\nleqslant H$ and $m>|L|$ and $\beta> 2^m-2^{m-r}$. Let $S$ be a union of $2^m-2^{m-r}$ sets of type $(I\setminus(J\cup\{e\}))c'$ with $c'\in (H\cap A')\setminus B$, $\frac{\beta-(2^m-2^{m-r})}{2}$ sets of type $(I\setminus(J\cup\{e\}))c\cup(I\setminus(J\cup\{e\}))c^{-1}$ with $c\in H\setminus(A'\cup B)$, and $\beta/2$ sets of type $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$.
		\end{itemize}

		We now claim that $H$ is a $(0,\beta)$-regular set in ${\rm CayS}(G,S)$. The proof proceeds in the following steps.

		\begin{stepp}\label{stepp-1}
			$S$ is normal.
		\end{stepp}
		Suppose $m=|L|$. By Lemma \ref{fact1}, we get $J=\emptyset$, and so $I\setminus\{e\}$ is inverse-closed, which imply that $S$ is normal from Corollary \ref{cor1}.

		Suppose $m>|L|$. In view of Lemma \ref{f6}, one obtains $J\neq\emptyset$. Since $I\setminus(J\cup\{e\})$ and $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$ are inverse-closed, from Corollary \ref{cor1}, $S$ is normal.

		\begin{stepp}\label{stepp-2}
			$S$ is square-free.
		\end{stepp}
		%Note that $\{ha'',h^{-1}a''^{-1}\}$ is square-free with $h\in H$ and $ha''\in {\rm Nsq}(G)$ for each $Ha''\subseteq J$.
		If $B\leqslant H$, from Lemma \ref{lem13} \ref{lem13-1}, then $S$ is square-free; if $B\nleqslant H$, from Lemma \ref{lem13} \ref{lem13-4}, then $S$ is square-free.

		\begin{stepp}\label{stepp-3}
			$|S\cap \langle H,zb\rangle x|=\beta$ for each $x\in A\setminus H$.
		\end{stepp}
		By \eqref{Aemptyset}, one gets $S\cap \langle H,zb\rangle x=S\cap Hx$ for each $x\in A\setminus H$. We only need to prove $|S\cap Hx|=\beta$ for each $x\in A\setminus H$.

		Suppose $m=|L|$. Note that $J=\emptyset$. Since $|(I\setminus\{e\})\cap Hx|=1$ for each $x\in A\setminus H$, we have $|S\cap Hx|=\beta$.

		Suppose $m>|L|$. By Lemma \ref{f6}, one has $J\neq\emptyset$. Since $|(I\setminus(J\cup\{e\}))\cap Hd|=1$ for each $Hd$ satisfying $Hd\cap J\cap H=\emptyset$, we have $|S\cap Hd|=\beta$. Since $S$ contains $\beta/2$ sets of type $\{ha'',h^{-1}a''^{-1}\}$ with $ha''\in {\rm Nsq}(G)$ and $h\in H$ for each $Ha''\subseteq J$, we have $|S\cap Ha''|=\beta$.

		In view of Steps \ref{step-1}--\ref{step-3} and Lemma \ref{lem3} \ref{lem3-1}, our claim is valid.
	\end{proof}



