			\end{enumerate}
		\end{lemma}
		\begin{proof}
			We first prove the necessity. In view of Lemma \ref{lem3}, we get $S=S\cap H$. Now we divide the proof into the following two cases.

			\textbf{Case 1.} $b^2\in H\setminus B$.

			By Fact \ref{jb2}, one gets ${\rm Nsq}(G)\cap H=H\setminus((H\cap B)\cup\{b^2\})$. If $|L|=0$, from Lemma \ref{fact2} \ref{fact2-1}, then $|H\cap B|=|H|$, and so $H\leqslant B$, contrary to $b^2\in H\setminus B$. Then $|L|\geq 1$. In view of Lemma \ref{lem3} and Lemma \ref{fact2} \ref{fact2-1}, we have $0\leq\alpha=|S\cap H|\leq |H\setminus((H\cap B)\cup\{b^2\})|=(2^{|L|}-1)|H|/2^{|L|}-1$.

			Suppose $m=1$. It follows that $m=|L|=1$. By Lemma \ref{fact2} \ref{fact2-1}, we have $|H\cap A'|=2$. Since $\langle b^2\rangle\leqslant H\cap A'$, we get $H\cap A'=\langle b^2\rangle$, and so $H\cap A'\subseteq {\rm Sq}(G)$ from Fact \ref{jb2}. Since $S$ is square-free and $S=S\cap H$, we have $S\subseteq {\rm Nsq}(G)\cap H=H\setminus{\rm Sq}(G)$. Since $H\cap A'\subseteq {\rm Sq}(G)$, from Fact \ref{jb3}, $S$ has no involution. If $a\in S\cap H$, from Lemma \ref{lem2}, then $a^{-1}\in S\cap H$ since $S$ is normal. It follows that $2\mid |S\cap H|$. By Lemma \ref{lem3}, $\alpha$ is even. Thus, \ref{lem20-1} holds.

			Suppose $m\neq 1$. Then $m\geq|L|\geq 1$ and $m\neq 1$. Note that $0\leq\alpha\leq (2^{|L|}-1)|H|/2^{|L|}-1$. Thus, \ref{lem20-2} is valid.

			\textbf{Case 2.} $b^2\notin H\setminus B$.

			Since $b^2\notin H\setminus B$, from Fact \ref{jb2}, we have ${\rm Nsq}(G)\cap H=H\setminus(H\cap B)$. It follows from Lemma \ref{lem3} and Lemma \ref{fact2} \ref{fact2-1} that $0\leq\alpha\leq |H\setminus(H\cap B)|=(2^{|L|}-1)|H|/2^{|L|}$.

			Suppose $r=0$. By Lemma \ref{fact2} \ref{fact2-1}, one has $|H\cap A'|=|H\cap A'\cap B|=2^m$, and so $H\cap A'\subseteq B$. Since $S$ is square-free and $S=S\cap H$, we have $S\subseteq {\rm Nsq}(G)\cap H=H\setminus(H\cap B)$. Since $H\cap A'\subseteq B$, $S$ has no involution from Fact \ref{jb3}. If $a\in S\cap H$, from Lemma \ref{lem2}, then $a^{-1}\in S\cap H$ since $S$ is normal. Then $2\mid |S\cap H|$. It follows from Lemma \ref{lem3} that $\alpha$ is even. Thus, \ref{lem20-3} holds.

			Suppose $r>0$. Note that $0\leq\alpha\leq(2^{|L|}-1)|H|/2^{|L|}$. Thus, \ref{lem20-4} is valid.

			Next we prove the sufficiency. If $b^2\in H\setminus B$, from Lemma \ref{fact2} \ref{fact2-1}, then $|(H\cap A')\setminus (B\cup\{b^2\})|=2^m-2^{m-r}-1$. If $b^2\notin H\setminus B$, then $(H\cap A')\setminus (B\cup\{b^2\})=(H\cap A')\setminus B$, and so $|(H\cap A')\setminus B|=2^m-2^{m-r}$ from Lemma \ref{fact2} \ref{fact2-1}. Let $\sigma(n)=\frac{1-(-1)^{n}}{2}$ for an integer $n$. Now we give a normal square-free subset $S$ of $G$ such that $H$ is an $(\alpha,0)$-regular set in ${\rm CayS}(G,S)$ for each case respectively.

			Suppose $b^2\in H\setminus B$. If $m=|L|=1$, then let $S$ be a union of $\alpha/2$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus((H\cap B)\cup\{b^2\})$. We only need to consider $m\geq|L|\geq 1$ and $m\neq1$. If $\alpha\leq 2^m-2^{m-r}-1$, then let $S$ be a union of $\alpha$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus (B\cup\{b^2\})$; if $\alpha>2^m-2^{m-r}-1$, then let $S$ be a union of $2^m-2^{m-r}-2+\sigma(\alpha)+(-1)^{\alpha}\cdot\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus (B\cup\{b^2\})$ and $\frac{\alpha-(2^m-2^{m-r}-2+\sigma(\alpha)+(-1)^{\alpha}\cdot\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$.

			Suppose $b^2\notin H\setminus B$. If $r=0$, then let $S$ be a union of $\alpha/2$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (H\cap B)$. We only need to consider $r>0$. If $\alpha \leq 2^m-2^{m-r}$, then let $S$ be a union of $\alpha$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus B$; if $\alpha>2^m-2^{m-r}$, then let $S$ be a union of $2^m-2^{m-r}-\sigma(\alpha)+(-1)^{\alpha+1}\cdot\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus B$ and $\frac{\alpha-(2^m-2^{m-r}-\sigma(\alpha)+(-1)^{\alpha+1}\cdot\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$.

			In view of Fact \ref{jb2} and Lemma \ref{lem2}, $S$ is normal and square-free. Since $S=S\cap H$ and $|S\cap H|=\alpha$, from Lemma \ref{lem3}, $H$ is an $(\alpha,0)$-regular set in ${\rm CayS}(G,S)$.
		\end{proof}
	\end{comment}


	\begin{lemma}\label{lem20}
		The subgroup $H$ is an $(\alpha,0)$-regular set of $G$ if and only if one of the following occurs:
		\begin{enumerate}
			\item\label{lem20-1} $0\leq\alpha\leq |H|/2-1$ and $\alpha$ is even, when $m=|L|=1$ and $b^2\in H\setminus B$;

			\item\label{lem20-2} $0\leq\alpha\leq (2^{|L|}-1)|H|/2^{|L|}-1$, when $m\geq|L|\geq 1$, $m\neq 1$ and $b^2\in H\setminus B$;

			\item\label{lem20-3} $0\leq\alpha\leq (2^{|L|}-1)|H|/2^{|L|}$ and $\alpha$ is even, when $r=0$ and $b^2\notin H\setminus B$;

			\item\label{lem20-4} $0\leq\alpha\leq (2^{|L|}-1)|H|/2^{|L|}$, when $r>0$ and $b^2\notin H\setminus B$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		Let $H$ be an $(\alpha,0)$-regular set in ${\rm CayS}(G,S)$ for some subset $S$ of $G$. By Lemma \ref{lem3} \ref{lem3-1}, one obtains $S=S\cap H$. Since $b^2\in A'$ from Fact \ref{jb2}, we get
		\begin{align}\label{Salpha0}
			S=S\cap H &\subseteq {\rm Nsq}(G)\cap H\nonumber\\
			&=({\rm Nsq}(G)\cap (H\cap A'))\cup ({\rm Nsq}(G)\cap (H\setminus A'))\nonumber\\
			&=((H\cap A')\setminus (B\cup\{b^2\}))\cup (H\setminus (A'\cup B)).
		\end{align}

		We divide the proof into the following two cases.

		\textbf{Case 1.} $b^2\in H\setminus B$.

		By Fact \ref{jb2}, one gets ${\rm Nsq}(G)\cap H=H\setminus((H\cap B)\cup\{b^2\})$. If $|L|=0$, from Lemma \ref{fact2} \ref{fact2-1}, then $|H\cap B|=|H|$, and so $H\leqslant B$, contrary to $b^2\in H\setminus B$. Then $|L|\geq 1$. In view of Lemma \ref{lem3} \ref{lem3-2} and Lemma \ref{fact2} \ref{fact2-1}, we have $0\leq\alpha\leq |H\setminus((H\cap B)\cup\{b^2\})|=(2^{|L|}-1)|H|/2^{|L|}-1$.

		Suppose $m=1$. It follows that $m=|L|=1$. By Lemma \ref{fact2} \ref{fact2-1}, we have $|H\cap A'|=2$. Since $\langle b^2\rangle\leqslant H\cap A'$, we get $H\cap A'=\langle b^2\rangle$, and so $H\cap A'\subseteq {\rm Sq}(G)$ from Fact \ref{jb2}. Since $S$ is square-free and $S=S\cap H$, we have $S\subseteq {\rm Nsq}(G)\cap H=H\setminus{\rm Sq}(G)$. Since $H\cap A'\subseteq {\rm Sq}(G)$, from Fact \ref{jb3}, $S$ has no involution. Since $S$ is normal, from Lemma \ref{lem2}, $S$ is a union of $\alpha/2$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus((H\cap B)\cup\{b^2\})$. It follows that $\alpha$ is even. Thus, \ref{lem20-1} holds.

		Suppose $m\neq 1$. Then $m\geq|L|\geq 1$ and $m\neq 1$. By Lemma \ref{fact2} \ref{fact2-1}, we have $|(H\cap A')\setminus B|=2^m-2^{m-r}$. Since $b^2\in H\setminus B$ and $b^2\in A'$, from Fact \ref{jb3}, one gets $|(H\cap A')\setminus (B\cup\{b^2\})|=2^m-2^{m-r}-1$, which implies that $S$ has at most $2^m-2^{m-r}-1$ involutions from \eqref{Salpha0}. If $\alpha\leq 2^m-2^{m-r}-1$, from Lemma \ref{lem2} and \eqref{Salpha0}, then $S$ can be a union of $\alpha$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus (B\cup\{b^2\})$ since $S$ is normal.

		We only need to consider the case $\alpha>2^m-2^{m-r}-1$. Note that $S$ is normal. If $\alpha$ is even, from Lemma \ref{lem2} and \eqref{Salpha0}, then $S$ can be a union of $2^m-2^{m-r}-2+\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus (B\cup\{b^2\})$ and $\frac{\alpha-(2^m-2^{m-r}-2+\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$. If $\alpha$ is odd, from Lemma \ref{lem2} and \eqref{Salpha0} again, then $S$ can be a union of $2^m-2^{m-r}-1-\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus (B\cup\{b^2\})$ and $\frac{\alpha-(2^m-2^{m-r}-1-\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$. Thus, \ref{lem20-2} is valid.

		\textbf{Case 2.} $b^2\notin H\setminus B$.

		%Note that $b^2\notin H\setminus B$. If $b^2\notin H$, then $b^2\in A\setminus H$; if $b^2\in H$, then $b^2\in B$, and so $b^2\in H\cap B$. Then $b^2\in A\setminus H$ or $b^2\in H\cap B$.
		Since $b^2\notin H\setminus B$, from Fact \ref{jb2}, we have ${\rm Nsq}(G)\cap H=H\setminus(H\cap B)$. It follows from Lemma \ref{lem3} \ref{lem3-2} and Lemma \ref{fact2} \ref{fact2-1} that $0\leq\alpha\leq |H\setminus(H\cap B)|=(2^{|L|}-1)|H|/2^{|L|}$.

		Suppose $r=0$. By Lemma \ref{fact2} \ref{fact2-1}, one has $|H\cap A'|=|H\cap A'\cap B|=2^m$, and so $H\cap A'\subseteq B$. Since $S$ is square-free and $S=S\cap H$, we have $S\subseteq {\rm Nsq}(G)\cap H=H\setminus(H\cap B)$. Since $H\cap A'\subseteq B$, from Fact \ref{jb3}, $S$ has no involution. Since $S$ is normal, from Lemma \ref{lem2}, $S$ is a union of $\alpha/2$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (H\cap B)$. It follows that $\alpha$ is even. Thus, \ref{lem20-3} holds.

		Suppose $r>0$. Since $b^2\notin H\setminus B$, we get $(H\cap A')\setminus (B\cup\{b^2\})=(H\cap A')\setminus B$. By Lemma \ref{fact2} \ref{fact2-1}, we get $|(H\cap A')\setminus B|=2^m-2^{m-r}$. By \eqref{Salpha0} and Fact \ref{jb3}, $S$ has at most $2^m-2^{m-r}$ involutions. If $\alpha \leq 2^m-2^{m-r}$, from Lemma \ref{lem2} and \eqref{Salpha0}, then $S$ can be a union of $\alpha$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus B$ since $S$ is normal.

		We only need to consider the case $\alpha>2^m-2^{m-r}$. Note that $S$ is normal. If $\alpha$ is even, from Lemma \ref{lem2} and \eqref{Salpha0}, then $S$ can be a union of $2^m-2^{m-r}-\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus B$ and $\frac{\alpha-(2^m-2^{m-r}-\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$. If $\alpha$ is odd, from Lemma \ref{lem2} and \eqref{Salpha0} again, then $S$ can be a union of $2^m-2^{m-r}-1+\delta_{m,r}$ sets of type $\{a'\}$ with $a'\in (H\cap A')\setminus B$ and $\frac{\alpha-(2^m-2^{m-r}-1+\delta_{m,r})}{2}$ sets of type $\{a,a^{-1}\}$ with $a\in H\setminus (A'\cup B)$. Thus, \ref{lem20-4} is valid.
	\end{proof}


	\begin{lemma}\label{lem16} The subgroup $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set of $G$ if and only if there exists a normal and square-free subset $S$ of $G$ such that $\langle H,zb\rangle$ is an $(\eta,\zeta)$-regular set in ${\rm CayS}(G,S\cap A)$ and an $(\alpha-\eta,\beta-\zeta)$-regular set in ${\rm CayS}(G,S\cap Ab)$ for some $\eta\in\{0,1,\ldots,\alpha\}$ and $\zeta\in\{0,1,\ldots,\beta\}$.
	\end{lemma}
	\begin{proof}
		We first prove the necessity. Suppose that $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$.  By Lemma \ref{lem3} \ref{lem3-1}, one gets $|S\cap \langle H,zb\rangle|=\alpha$ and $|S\cap \langle H,zb\rangle x|=\beta$ for each $x\in A\setminus H$, which imply that $S$ is the union of $S\cap \langle H,zb\rangle$, and $\beta$ pairwise disjoint subsets $T_j$ of ${\rm Nsq}(G)$, $1\leq j\leq\beta$, such that for each $j$, $T_{j}\cup\{e\}$ is a right transversal of $\langle H,zb\rangle$ in $G$. Without loss of generality, we may assume that $|S\cap H|=\eta$, $\cup_{h=1}^{\zeta}T_h\subseteq A$ and $\cup_{h=\zeta+1}^{\beta}T_h\subseteq Ab$ for some $\eta\in\{0,1,\ldots,\alpha\}$ and $\zeta\in\{0,1,\ldots,\beta\}$. Since $H$ has index $2$ of $\langle H,zb\rangle$, we have $|S\cap Hzb|=\alpha-\eta$. Then $|S\cap A\cap \langle H,zb\rangle|=\eta$, $|S\cap A\cap \langle H,zb \rangle x|=\zeta$ for each $x\in A\setminus H$ and $|S\cap Ab\cap \langle H,zb\rangle|=\alpha-\eta$,  $|S\cap Ab\cap \langle H,zb \rangle x|=\beta-\zeta$ for each $x\in A\setminus H$. Note that $S=(S\cap A)\cup(S\cap Ab)$. Since $S$ is a normal and square-free subset of $G$, $S\cap A$ and $S\cap Ab$ are both normal and square-free. By Lemma \ref{lem3} \ref{lem3-1}, $\langle H,zb\rangle$ is an $(\eta,\zeta)$-regular set in ${\rm CayS}(G,S\cap A)$ and an $(\alpha-\eta,\beta-\zeta)$-regular set in ${\rm CayS}(G,S\cap Ab)$.

		Next we prove the sufficiency. Suppose that $\langle H,zb\rangle$ is an $(\eta,\zeta)$-regular set in ${\rm CayS}(G,S\cap A)$ and an $(\alpha-\eta,\beta-\zeta)$-regular set in ${\rm CayS}(G,S\cap Ab)$. By Lemma \ref{lem3} \ref{lem3-1}, $S\cap A$ contains exactly $\eta$ elements of $\langle H,zb\rangle$ and $\zeta$ elements of $\langle H,zb\rangle x$ for each $x\in A\setminus H$, and $S\cap Ab$ contains exactly $\alpha-\eta$ elements of $\langle H,zb\rangle$ and $\beta-\zeta$ elements of $\langle H,zb\rangle x$ for each $x\in A\setminus H$.
		Since $G=A\cup Ab$, one gets $S=(S\cap A)\cup (S\cap Ab)$, which implies that $S$ contains exactly $\alpha$ elements of $\langle H,zb\rangle$ and $\beta$ elements of $\langle H,zb\rangle x$ for each $x\in A\setminus H$. Since $S\cap A$ and $S\cap Ab$ are both normal and square-free, from Lemma \ref{lem3} \ref{lem3-1}, $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$.
	\end{proof}

	\begin{lemma}\label{lem5}
		Let $S$ be a normal and square-free subset of $G$ with $S\subseteq A$. Then $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$ if and only if $H$ is an $(\alpha,0)$-regular set in ${\rm CayS}(G,S\cap H)$ and $\langle H,zb\rangle$ is a $(0,\beta)$-regular set of ${\rm CayS}(G,S\setminus H)$.
	\end{lemma}
	\begin{proof}
		Since $S\subseteq A$ and $H$ has index $2$ of $\langle H,zb\rangle$, we have $S\cap \langle H,zb\rangle=S\cap H$ and $S\cap (G\setminus \langle H,zb\rangle)=S\cap (A\setminus H)$.

		We first prove the necessity. Since $S$ is normal, square-free and $H$ is a normal subgroup of $G$, $S\cap H$ is normal and square-free, which implies that $S\setminus H$ are normal and square-free. Since $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$, from Lemma \ref{lem3} \ref{lem3-1}, one has $|S\cap H|=|S\cap \langle H,zb\rangle|=\alpha$ and $|(S\setminus H)\cap \langle H,zb\rangle x|=|S\cap \langle H,zb\rangle x|=\beta$ for each $x\in A\setminus H$. Since $S\cap Hb=\emptyset$, from Lemma \ref{lem3} \ref{lem3-1} again, $H$ is an $(\alpha,0)$-regular set in ${\rm CayS}(G,S\cap H)$ and $\langle H,zb\rangle$ is a $(0,\beta)$-regular set in ${\rm CayS}(G,S\setminus H)$.

		We next prove the sufficiency. Since $H$ is an $(\alpha,0)$-regular set in ${\rm CayS}(G,S\cap H)$ and $\langle H,zb\rangle$ is a $(0,\beta)$-regular set in ${\rm CayS}(G,S\setminus H)$, from Lemma \ref{lem3} \ref{lem3-1}, one gets $|S\cap \langle H,zb\rangle|=|S\cap H|=\alpha$ and $|S\cap \langle H,zb\rangle x|=|(S\setminus H)\cap \langle H,zb\rangle x|=\beta$ for each $x\in A\setminus H$. Since $S=(S\cap H)\cup (S\setminus H)$, from Lemma \ref{lem3} \ref{lem3-1}, $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set in ${\rm CayS}(G,S)$.
	\end{proof}

	Now we are ready to give a proof of Theorem \ref{thm1}.

	\begin{proof}[Proof of Theorem \ref{thm1}] By Lemma \ref{lem4}, $H$ is an $(\alpha,\beta)$-regular set of $G$ if and only if $H$ is an $(\alpha,0)$-regular set of $G$ and a $(0,\beta)$-regular set of $G$. The desired result is valid from Lemmas \ref{lem8} and \ref{lem20}.
	\end{proof}

	Next, we give a proof of Theorem \ref{thm2}.

	\begin{proof}[Proof of Theorem \ref{thm2}] %By Lemmas \ref{lem16}, \ref{lem9}, \ref{lem5}, \ref{lem18} and \ref{lem20}, the sufficiency is valid.

		By Lemma \ref{lem16}, $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set of $G$ if and only if $\langle H,zb\rangle$ is an $(\eta,\zeta)$-regular set in ${\rm CayS}(G,S\cap A)$ and an $(\alpha-\eta,\beta-\zeta)$-regular set in ${\rm CayS}(G,S\cap Ab)$ for some $\eta\in\{0,1,\ldots,\alpha\}$, $\zeta\in\{0,1,\ldots,\beta\}$, and normal, square-free subset $S$. In view of Lemma \ref{lem5}, $\langle H,zb\rangle$ is an $(\alpha,\beta)$-regular set of $G$ if and only if $H$ is an $(\eta,0)$-regular set in ${\rm CayS}(G,S\cap H)$, $\langle H,zb\rangle$ is an $(0,\zeta)$-regular set in ${\rm CayS}(G,(S\cap A)\setminus H)$ and an $(\alpha-\eta,\beta-\zeta)$-regular set in ${\rm CayS}(G,S\cap Ab)$ for some $\eta\in\{0,1,\ldots,\alpha\}$, $\zeta\in\{0,1,\ldots,\beta\}$, and normal, square-free subset $S$. The desired result follows from Lemma \ref{fact2} \ref{fact2-2} and Lemmas \ref{lem9}, \ref{lem18} and \ref{lem20}.
	\end{proof}

