\section{Measures of matrix ensembles \label{Ensembles}}

\paragraph{Unitary matrices.}
The Haar measure on $\mathbb{U}_N$ in its explicit form is written as
\be\label{Haar}
d_*U=\frac{d\Omega}{(2\pi)^N}\prod_{ 1\le i<k\le N} |e^{\sqrt{-1}\theta_i}-e^{\sqrt{-1}\theta_k}|^2 \prod_{i=1}^N d\theta_i,\quad
-\pi < \theta_1 < \cdots <\theta_N \le \pi\,.
\ee
where $e^{\sqrt{-1}\theta}$ are eigenvalues of $U\in\mathbb{U}_N$, and $d\Omega$ is the measure of the angular part (which is inessential in the case of dealing only with averages of invariant quantities), see \cite{Mehta}.

\paragraph{Hermitian matrices.}

It is natural \cite{Mehta} to take the following measure on the space $\mathfrak{H}_N$ of Hermitian $N\times N$ matrices:
\be\label{HermitianM}
 dM=C_N\prod_{i\le j\le N}e^{-w\left(\Re M_{i,j}\right)^2 }d\Re M_{i,j}
 \prod_{i < j\le N} e^{-w\left(\Im M_{i,j}\right)^2 } d\Im M_{i,j}
\ee
$$
 = c_N \prod_{ 1\le i<k\le N}\left(x_i-x_j\right)^2  \prod_{i=1}^N e^{-w x^2_i}dx_i d_*U\,,
$$
where $w>0$ is a parameter, and $x_i$ are eigenvalues of the matrix $M$, while $U$ describes its angular part, $U\in \mathbb{U}_N$.

\br
In many applied problems that use random matrices, it is very convenient to propose
that the parameter $w$ is proportional to the size $N$ of the matrices \cite{BIPZ,ZinZub,Zuber}.
\er


\section{Bilinear equations for UC hierarchy}

The pair of bilinear equations for the UC hierarchy is
\be
\sum_{k-l+m=-1} s_{k}(-2u)s_{l}(\tilde D_p)s_{m}(\tilde D_{p^*})
 \cdot\tau^{UC}(\pb+u,\pb^*+v)\tau^{UC}(\pb-u,\pb^*-v)=0,
\ee
\be
\sum_{k-l+m=-1} s_{k}(-2v)s_{l}(\tilde D_{p^*})s_{m}(\tilde D_{p})
 \cdot\tau^{UC}(\pb+u,\pb^*+v)\tau^{UC}(\pb-u,\pb^*-v)=0
\ee
where $u=(u_1,u_2,\dots)$ are arbitrary parameters, and $\tilde D_{p}=(D_1,D_2,\dots)$ are Hirota derivatives \cite{JM}.

For instance, the term $u^0v^0$ gives
$$
\sum_{m\ge 0} s_{m+1}(\tilde D_p)s_{m}(\tilde D_{p^*})\tau^{UC}(\pb,\pb^*)\tau^{UC}(\pb,\pb^*) =0
$$

If $\tau^{UC}(\pb,\pb^*)$ does not depend on $\pb^*$, one reproduces the KP Hirota bilinear equation
$$
\sum_{k\ge 0} s_{k}(-2u)s_{k+1}(\tilde D_p)
 \tau^{UC}(\pb+u)\tau^{UC}(\pb-u)=0\,.
$$

