\section{Complex linear algebra and complex Cartan calculus}\label{apcxcartan}
\subsection{Complex linear spaces}
We recall some well-known facts of complex linear algebra. Let $V$ be a real vector space, we have the maps 
\begin{align*}
    \re:\{\text{complex subspaces of $V_{\C}$}\}&\to \{\text{real subspaces of $V$}\}\\
    S\subseteq V_{\C}&\mapsto \re S=S\cap V
\end{align*}
\begin{align*}
    \cdot_{\C}:\{\text{real subspaces of $V$}\}&\to \{\text{complex subspaces of $V_{\C}$}\}\\
    W&\mapsto W_{\C}
\end{align*}
These maps are not inverse one of the other. 

Let $U$ be a complex vector space, denote by $U_{\R}$ to its realification (restriction of scalar to $\R$). We will denote by $U^*$ its complex dual and by $(U_{\R})^*$ its real dual.

Let $\xi: U\to \C$, $\C$-linear, $\xi(u)=\eta_1(u)+i\eta_2(u)$, using that $\xi(iu)=i\xi(u)$ we get $\eta_1 \circ j=-\eta_2$, where $j:U\to U$, $j(u)=iu$.
Hence, we obtain the following map
\begin{equation*}
\eta\in (U_{\R})^*\to \eta-i\eta\circ j\in (U^*)_{\R},    
\end{equation*}
that is in fact a $\R$-isomorphism.
So we have:
\begin{proposition}
    $(U_{\R})^*\cong (U^*)_{\R}$
\end{proposition}
Consider the following map:
\begin{align*}
    \widehat{}\:\::(V^*)_{\C}\to (V_{\C})^*,\:\:\:\:\:\:\:
    \xi=\xi_1+i\xi_2&\mapsto \widehat{\xi},
\end{align*}
where $\widehat{\xi}$ is given by:
\begin{equation*}
    \widehat{\xi}(X+iY)=\xi_1(X)-\xi_2(Y)+i(\xi_2(X)+\xi_1(Y)).
\end{equation*}
Note that for pure real and pure imaginary elements we have the following: 
\begin{equation*}
    \widehat{\xi_1}=(\xi_1)_{\C}\:\:\text{and}\:\:\widehat{(i\xi_2)}=i(\xi_2)_{\C}.
\end{equation*}

\begin{proposition}\label{multicxisom}
    The map $\:\:\widehat{}\:\:$ is an isomorphism and it extends to an isomorphism from $(\wedge^k V)_{\C}$ to $\wedge^k V_{\C}$.
\end{proposition}

Let $V$ and $W$ be two real vector spaces, and $\Phi: V_{\C}\to W_{\C}$ a $\C$-linear map. Consider $S$ and $S'$, real vector subspaces of $V$ and $W$, respectively. If $\Phi(S)=S'$, then $\Phi(S_{\C})=S'_{\C}$. However, the converse is not true, if $\Phi(S_{\C})=S'_{\C}$, then we do not necessarily have that $\Phi(S)=S'$. 
\subsection{Complex bilinear operators}
Let $S$ be a complex vector space, $W$ a real vector space and $B\in Mult_k(S, W_{\C})$ a $k$-multilinear operator. We have the following decomposition
\begin{equation}\label{decom1}
B(w_1,\ldots,w_k)=\widetilde{B}_1(w_1,\ldots,w_k)+i\widetilde{B}_2(w_1,\ldots,w_k).\end{equation}
However, note that $\widetilde{B}_1,\widetilde{B}_2$ are not $\C$-linear, in fact $\widetilde{B}_1,\widetilde{B}_2\in Mult_k(S_{\R},W)$ and satisfy the following property:
\begin{equation*}
\widetilde{B}_1(w_1,\ldots,iw_j, \ldots ,w_k)=-\widetilde{B}_2(w_1,\ldots,w_j, \ldots ,w_k).
\end{equation*}
\begin{lemma}\label{bivdecom}
 Let $V$ and $W$ be real vector spaces and $B:V_{\C}\times V_{\C}\to W_{\C}$ any $\C$-bilinear map and the decomposition of \eqref{decom1} $B=\widetilde{B}_1+i\widetilde{B}_2$. Consider $B_1=\widetilde{B}_1|_{V\times V}$ and $B_2=\widetilde{B}_2|_{V\times V}$. Then
 \begin{align*}
     B(X_1+iX_2, Y_1+iY_2)&= B_1(X_1,Y_1)-B_1(X_2,Y_2)-B_2(X_2,Y_1)-B_2(X_1,Y_2)\\
 &+i(B_2(X_1,Y_1)-B_2(X_2,Y_2)+B_1(X_2,Y_1)+B_1(X_1,Y_2)).
 \end{align*}
 In particular, for $X,Y\in V$, $B(X,Y)=B_1(X,Y)+iB_2(X,Y)$.
\end{lemma}
As an immediate consequence we obtain a characterization of complexification:
\begin{corollary}\label{realoperator}
Let $B:\underbracket{V_{\C}\times\ldots\times V_{\C}}_{k-times}\to W_{\C}$ be a $\C$-multilinear map. Then $B$ is a complexification if and only if $B_2=0$. 
\end{corollary}

\subsection{Complex Cartan calculus}
The complex Schouten bracket is defined in the usual way:
\begin{equation*}
    [\cdot,\cdot]_{Sch}:\Gamma(\wedge^p \TCM)\times\Gamma(\wedge^q \TCM)\to \Gamma(\wedge^{p+q-1}\TCM)
\end{equation*}
\begin{equation*}
    [X_1\wedge\ldots\wedge X_p, Y_1\wedge\ldots\wedge Y_q]=\sum_{i,j}(-1)^{i+j}[X_i,Y_j]\wedge X_1\wedge\ldots \widehat{X_i}\wedge\ldots\wedge X_p\wedge Y_1\wedge \ldots \widehat{Y_j}\ldots \wedge Y_q
\end{equation*}
and then we extend it by $\C$-linearity.
Note that, by Corollary \ref{realoperator}, it is the complexification of the real Schouten bracket and satisfies the same properties that the real Schouten bracket. 

We have two complex of complex differential forms:

The complex $(\Gamma(\wedge^{\bullet} T^*_{\C}M), \widetilde{d})$: for a complex differential form $\alpha\in \Gamma(\wedge^{k} T^*_{\C}M)$, we have the operator 
\begin{align*}
\widetilde{d}\alpha(Z_0,\ldots, Z_k)&=\sum_j (-1)^{j+1}Z_j(\alpha(Z_0, \ldots, \widehat{Z_j}, \ldots Z_k))\\
&+\sum_{i,j}(-1)^{i+j+1}\alpha([Z_i,Z_j], Z_0, \ldots, \widehat{Z_i},\ldots, \widehat{Z_j},\ldots, Z_k),
\end{align*}
where $Z_0,\ldots, Z_k\in  \Gamma(\TCM)$.


The complex $(\Gamma(\wedge^{\bullet} T^*M)_{\C}, d_{\C})$:
for a complex differential form $\alpha=\alpha_1+i\alpha_2\in \Gamma(\wedge^k T^*M)_{\C}$, we define the differential $d_{\C}$ as 
\begin{equation*}
d_{\C}\alpha=d\alpha_1+i d\alpha_2.
\end{equation*}


By Lemma \ref{multicxisom}, we have that the map 
\begin{equation*}
\hat{}:\Gamma(\wedge^k T^*_{\C}M)\to \Gamma(\wedge^k T^*M)_{\C}
\end{equation*}is an isomorphism. 
\begin{proposition}
The operators $\widetilde{d}$ and $d_{\C}$ are equivalent in the following sense:
\begin{equation*}
\begin{tikzcd}
\Gamma(\wedge^k T^*_{\C}M)\arrow[d, "\widetilde{d}"] \arrow[r, "\widehat{}"]
& \Gamma(\wedge^k T^*M)_{\C}\arrow[d,  "d_{\C}"] \\
\Gamma(\wedge^{k+1} T^*_{\C}M)\arrow[r, "\widehat{}"]
& \Gamma(\wedge^{k+1} T^*M)_{\C}.
\end{tikzcd}
\end{equation*}

\end{proposition}

Also consider the Lie derivative as 
\begin{equation*}
    L_{X+iY}(\beta_1+i\beta_2)=L_{X}\beta_1 -L_{Y}\beta_2 + i(L_{X}\beta_2 + L_{Y}\beta_1).
\end{equation*}

An straightforward computation proves the following:
\begin{proposition}[Complex Cartan magic formula]
Let $X+iY\in \Gamma(\TCM)$. Then, 
    \begin{equation*}
        L_{X+iY}=\iota_{X+iY}d_{\C}+d_{\C}\iota_{X+iY}
    \end{equation*}
\end{proposition}
\section{Dirac geometry}\label{apcxdirac}
Given a manifold $M$ we consider its  {\em generalized tangent bundle} $\T M:=TM\oplus T^*M$ with the canonical nondegenerate symmetric pairing
\begin{equation*}
\langle X+\xi, Y+\eta\rangle=\frac{1}{2}(\eta(X)+\xi(Y)),
\end{equation*}
 and the Courant-Dorfman bracket \cite{dorfman1987dirac} on $\Gamma(\T M)$
\begin{equation*}
[ X+\xi, Y+\eta]=[X,Y]+\lie_{X}\eta-\imath_{Y}d\xi,\:\:{\rm for}\:\:X+\xi,\:\: Y+\eta \in \Gamma (\T M).
\end{equation*}

Using extension of scalars, we extend the canonical pairing $\la\cdot,\cdot\ra$ and the Courant-Dorfmann bracket $[\cdot,\cdot]$ to $\TTCM$ and $\Gamma(\TTCM)$, respectively. Along this article we focus on structures defined on $\TTCM$. 
\begin{definition}
A {\em lagrangian family} is a correspondence $p\in M\mapsto L_p\subseteq \TTCM$, where $L_p$ is a lagrangian subspace of $\TCM|_p$ (we can define also lagrangian families on $\T M$ in the obvious way, and we still refer to them as lagrangian families). We say that the lagrangian is {\em smooth} if it defines a subbundle of $\TCM$ or $\T M$, in that case the lagrangian family is called {\em lagrangian subbundle}.
A {\em (complex) Dirac structure} is a lagrangian subbundle that is involutive with respect to the Courant-Dorfman bracket (that is, $[\Gamma(L),\Gamma(L)]\subseteq \Gamma(L)$).
\end{definition}

The {\em range distribution} $E$ of a lagrangian subbundle $L$ is 
\begin{equation*}
 E:=\pr_{TM}L\:\text{ or }\:E:=\pr_{\TCM}L,  
\end{equation*}
 which is smooth but not necessarily regular. There exists a  skew-symmetric bilinear map $\varepsilon_L:E\times E\to \K$ such that 
\begin{equation*}
    L=L(E,\varepsilon_L):=\{X+\xi\:|\: X\in E,\:\:\xi_{|E}=\imath_{X}\varepsilon_L\},
\end{equation*}
 where $\K=\R$ or $\C$. While the range distribution of a Dirac structure is always integrable to a possibly singular foliation, the range distribution of a complex Dirac structure is involutive but not integrable (until this moment we have not found a sense of the integration of an involutive regular complex distribution). Furthermore, in the case of Dirac structures $\varepsilon_L$ restricts to a presymplectic form on each leaf.
\begin{examples}
\begin{enumerate}\normalfont
    \item Let $\pi$ be a real or complex Poisson bivector. Then, the graph of $\pi$ is a Dirac or complex Dirac structure, respectively.
    \item Let $\F$ be a regular foliation where each leaf $S$ is equipped with a presymplectic two-form $\omega_S$, and this family of presymplectic forms is calibrated, i.e. there exists a closed two-form $\omega\in \Omega^2(M)$ such that $\iota^*_S\omega=\omega_S$. Then, $R=L(T\F,\omega)$ is a Dirac structure and $L=L((T\F)_{\C},i\omega_{\C})$ is a complex Dirac structure.

\end{enumerate}
\end{examples} 
$B$-fields and $\beta$-transformations
Two-forms act on the space of lagrangian families, in the following way: given $B\in \Omega^{2}(M)$ or in $\Omega_{\C}^{2}(M)$ and $L$ a real or complex lagrangian family, repectively
\begin{equation*}
    e^BL=\{X+\xi+\imath_{X}B\st X+\xi\in L\}
\end{equation*}
is the {\em $B$-transformation} of $L$ by $B$. When $B$ is closed and $L$ is real or complex Dirac, $e^{B}L$ is real or complex Dirac, respectively.

A {\em $\beta$-transformation} is an action of a bivector $\beta\in \Gamma(\wedge^2 TM)$ or in $\Gamma(\wedge^2 \TCM)$ over a real or complex lagrangian family, respectively, given by:
\begin{equation*}
    e^{\beta}L=\{X+\imath_{\xi}\beta+\xi\st X+\xi\in L\}.
\end{equation*}
\begin{definition}\label{ri_order}
The {\em real index} of a \underline{complex} lagrangian family $L$ is the $\mathbb{N}$-valued function
\begin{equation*}
    p\in M\mapsto \text{real-index}|_p L=L|_p \cap \T_p M. 
\end{equation*}
Additional to its range, a complex Dirac structure $L$ has associated the real distributions:
\begin{equation*}
    \Delta_L=\pr_{\TCM} L \cap TM \subseteq TM\text{ and } D_L=\pr_{TM} L \subseteq TM. 
\end{equation*}
We say that a complex Dirac structure has {\em constant order} whenever $D_L$ is a vector bundle.
\end{definition}
Moreover, any complex Dirac structure $L$ has associated the real distribution 
\begin{equation*}
L^{\rea}=L\cap(TM\oplus\CCM).
\end{equation*} 
\begin{proposition}[\cite{aguero2024complexliealgebroidsconstant}]\label{lreisalgebroid}
If $ \pr_{TM}L$ is a subbundle of $TM$, then $L^{\rea}$ is a Lie algebroid.
\end{proposition}

In the same way as with Dirac structures, complex Dirac structures have a tangent product: Let $L_1$ and $L_2$ be two lagrangian families, consider the space:
\begin{equation*}
    L_1 \star L_2=\{X+\eta_1+\eta_2\st X+\eta_1\in L_1\:\:\text{and}\:\: X+\eta_2\in L_2 \}.
\end{equation*}
Note that $L_1*L_2$ is not necessarily smooth but it is a lagrangian family. However, if $L_1$ and $L_2$ are complex Dirac structures and the smoothness condition is satisfied, then $L_1 * L_2$ is a complex Dirac structure.

There is an action of $\C$ on the space of lagrangian families, given by the following formula:
\begin{equation*}
    z\cdot L=\{X+z\xi\st X+\xi\in L\},
\end{equation*}
where $z\in \C$ and $L$ is a lagrangian family. Observe that this action satisfies the following properties:
\begin{align}\label{prop_cx_action}
    \overline{z\cdot L}&=\overline{z}\cdot\cL\\
    z\cdot(L_1\star L_2)&=(z\cdot L_1)\star(z\cdot L_2),
\end{align}
for $z\in \C$ and $L, L_1,L_2$ lagrangian families. Using the versatility of complex Dirac structures we can define other actions on the space of lagrangian families.

Any complex Dirac structure $L$ has associated a real lagrangian family that we denote by $\widehat{L}$. On way to obtain it is by the identity, \cite{frejlich2024dirac}
\begin{equation*}
    L\star(-1)\cdot\overline{L}=2i\cdot \widehat{L}_{\C}.
\end{equation*}

It is known the following identification:
\begin{equation}\label{lhatid}
\widehat{L}=\{ X+\xi\st \exists\eta\in T^*M \:\:\text{such that}\:\: X+i\xi+\eta\in L\}.
\end{equation}

Let $K=L\cap \T M$ be the space of real elements of $L$ and denote by $K^{\perp}$ to the orthogonal of $K$ with respect to the canonical pairing $\la\cdot,\cdot\ra$. Then, we have the following:

\begin{lemma}\label{proj_K}\cite[Lemma 4.8]{aguero2022complex}
For the distributions $K$ and $K^\perp$ we have
\begin{align*}
    \pr_{TM} K^\perp &= D\:\text{ and}\\ \pr_{TM} K &= \ker\varepsilon_{\widehat{L}}.
\end{align*}
\end{lemma}
Let $\varphi:M\to N$ be a smooth map and $L_M$ and $L_N$ complex Dirac structures on $M$ and $N$, respectively. The {\em backward image of $L_N$ under $\varphi$} is the lagrangian family:
\begin{equation*}
    (\varphi^! L_N)|_m=\{X+\varphi^* \xi\st T\varphi (X)+\xi\in L_N|_{\varphi(m)}\}\subseteq \TCM
\end{equation*}
and the {\em forward image of $L_M$ under $\varphi$}
\begin{equation*}
    (\varphi_! L_M)|_m=\{T\varphi (X)+\xi\st X+\varphi^*\xi\in L_M|_m\}\subseteq\varphi^*\TCN.
\end{equation*}
Note that the forward image is not a subbundle of $\TCN$. We say that $L_M$ is {\em $\varphi$-invariant} if for $m, m'\in M$ in the same $\varphi$-fiber, we have that $(\varphi_! L_M)|_m=(\varphi_! L_M)|_{m'}$. If $L_M$ is $\varphi$-invariant, the forward image $\varphi_! L_M$ defines a lagrangian family on $N$, that we shall call forward image and denote by $\varphi_! L_M$, if it is clear from the context. 


As with real Dirac structures, under certain clean intersection conditions, we can prove the smoothness of the backward and forward image, see for example \cite{bursztyn2013brief}.

In the same way as in Example 5.10 of \cite{bursztyn2013brief}, we have the following result: 
\begin{lemma}\label{quotientdirac}
    If $\ker Tp\subseteq L\cap TM=\re\ker L$, then $L$ is $p$-invariant.
\end{lemma}

\section{Euler-like vector fields and Normal forms}\label{apnormal}
 The {\em Euler vector field} associated to a vector bundle $E\to M$, usually denoted by $\mathcal{E}\in \mathfrak{X}(E)$, is the vector field generated by the one-parameter group $s\mapsto \kappa_{e^{-s}}$, where the maps $\kappa_{t}:E\to E$ are given by $\kappa_{t}e=t\cdot e$, $t\in \R$ (in case $t=0$, $\kappa_0$ is the projection to the zero section).


Given a submanifold $N\xhookrightarrow{}M$, {\em the normal bundle of $N$} is the bundle 
\begin{equation*}
\nu_N=TM|_{N}/TN,
\end{equation*} with projection map by $p:\nu_N\to N$.

Any map of pairs $\varphi:(M',N')\to (M,N)$  has an associated map $\nu(\varphi):\nu_{N'}\to \nu_N.$
The following lemma is a known fact. 
Consider a vector field $X\in \mathfrak{X}(M)$ tangent to $N$, that is $X:(M,N)\to (TM,TN)$. Using the fact that $T\nu_N=\nu_{TN}$ (see \cite[Appendix A]{bursztyn2019splitting}) we have that $\nu(X)$ is a vector field on~$\nu_N$.

Let $p:E\to M$ be a vector bundle and $s\in \Gamma(E)$ such that $s|_N=0$. Then, we have a map of pairs $s:(M,N)\to (E,M)$. The {\em normal derivative of $s$} is the map
\begin{equation*}
    d^N s:\nu_N\to E|_N,
\end{equation*}
given by $d^N s=\nu(s)$, here we are using the identification $\nu_M=TE|_M/TM=E|_M$. Note that any bundle map from $\nu_N$ to $E|_N$ is the normal derivative of a certain section $s\in \Gamma(E)$ satisfying that $s|_N=0$.
\begin{definition}\label{defTN-EL}
Let $N$ be an embedded submanifold of $M$. A {\em tubular neighborhood embedding} is an embedding 
$\psi:\nu_N\to M$ that takes $N$ as the zero section of $\nu_N$ to $N\subseteq M$ and $\nu(\psi)=Id$, where $\nu(\psi)$ is induced by $\psi:(\nu_N,N)\to (M,N)$ (here we are using the identification $\nu(\nu_N,N)=\nu_N$).
A vector field $X\in\mathfrak{X}(M)$ is called {\em Euler-like} (along $N$) if it is complete, $X|_{N}=0$ and $\nu(X)$ is the Euler vector field of $\nu(M,N)$.
\end{definition}
Given a submanifold $N$ of $M$, there is a one-to-one correspondence between Euler-like vector and tubular neighborhood embedding, see for example \cite{bursztyn2019splitting}. 
\begin{lemma}\cite[Lemma 3.9]{bursztyn2019splitting}\label{existence_esp_section}
Let $(A, \rho)$ be RAVB over $M$, and $N\subseteq M$ a submanifolds transversal to $\rho$.
Then there exists a section $\epsilon\in \Gamma(A)$ with $\epsilon|_N = 0$, such that $X = \rho(\epsilon)$ is Euler-like along~$N$.
\end{lemma}

The way to construct $\epsilon$ is the following. Consider, the exact sequence
\begin{equation*}
\xymatrix{
0\ar[r]&\iota^! A\ar[r]& A|_N\ar[r]&\nu_N\ar[r]&0},
\end{equation*}
where the map $A_|N\to \nu_N$ is given by the anchor map composed with the quotient map. Any section $\nu_N\to A|_N$ of the exact sequence comes from the normal derivative of a section $\epsilon\in \Gamma(E)$ such that $\epsilon|_N=0$. It is proved that $X=\rho(\epsilon)$ is Euler-like.
