               \textcolor{black} 
		{\textbf{CE $e$ in DIMM $d$: }
		{[{'CpuId': 0, 'ChannelId': 1, 'DimmId': 0, 'RankId': 1, 'ChipId': 1, 'BankId': 2, 'RowId': 67745, 'ColumnId': 0,  'MemoryType': 'DDR4', 'Manufacturer': 'A', 'Region': 'E', 'Capacity': 16, 'ProcessorArchitecture': 'X86 Intel Purley', 'MaxSpeedMHz': 4000, 'FrequencyMHz': 2600, 'LogTime': 1711522709, 'beats': {'0': [], '1': [], '2': [], '3': [], '4': [], '5': [], '6': [57], '7': []}}]}}
\end{tcolorbox}
