\section{Implementation Details}
\label{sec:appendix-imple}

\subsection{Time-point Methods}

\subsubsection{Naive Method}
Each CE is represented by a DQ-Beat Matrix $B(e) \in \{0,1\}^{8 \times 4}$, where rows are beats and columns are DQs. Let $n_{+}(B(e))$ and $n_{-}(B(e))$ count occurrences in positive and negative samples. 

A CE is flagged as faulty if:
\[ n_{+}(B(e)) > n_{-}(B(e)). \]

\subsubsection{Risky CE Rule}
This rule examines bit-level errors in $B(e)$ across DQ signals $\text{DQ}_0$ to $\text{DQ}_3$. 

A CE is faulty if:
\[ (e(\text{DQ}_0) + e(\text{DQ}_1) \geq 1) \land (e(\text{DQ}_2) + e(\text{DQ}_3) \geq 1). \]

\subsubsection{DQ Beat Predictor}
Counts errors in DQs and Beats:
\[ N_{\text{DQ}} = \text{DQs with errors}, \quad N_{\text{Beat}} = \text{Beats with errors}. \]
A CE is faulty if:
\[ N_{\text{DQ}} > 1 \land N_{\text{Beat}} > 1. \]

\subsubsection{CNN-based Method (Time-point)}
In this approach, the input is the binary DQ-Beat Matrix
\[
\mathbf{X} \in \{0,1\}^{8 \times 4},
\]
representing the CE's bit-level feature (equals to B(e)). This method adopts a hybrid CNN-MLP architecture similar to that used in the time-patch methods. Specifically, the model processes inputs via parallel pathways:
\begin{align}
    \mathbf{H}_{\text{CNN}} &= \sigma\Big(\mathbf{W}_{\text{conv}} \ast \mathbf{X} + \mathbf{b}_{\text{conv}}\Big), \\
    \mathbf{H}_{\text{MLP}} &= \sigma\Big(\mathbf{W}_2 \cdot \sigma\big(\mathbf{W}_1 \mathbf{x} + \mathbf{b}_1\big) + \mathbf{b}_2\Big), \\
    \mathbf{y} &= \text{Softmax}\Big(\mathbf{W}_c \Big[\mathbf{H}_{\text{CNN}} \oplus \mathbf{H}_{\text{MLP}}\Big] + \mathbf{b}_c\Big),
\end{align}
where \(\ast\) denotes the convolution operation, \(\oplus\) denotes concatenation, and \(\sigma\) is the ReLU activation function. Here, \(\mathbf{x} \in \mathbb{R}^{8}\) represents the DIMM-level CE statistical features.

\subsection{Time-patch Methods}

\subsubsection{CNN-based Method}
The model combines a CNN for image processing and an MLP for statistical features:

\begin{itemize}[leftmargin=*]
    \item \textbf{CNN Branch:}  
    - Input: 8×4 DQ-Beat Matrix  
    - Layers: 3×3 conv (32 filters, padding 1) → 2×2 max pool → flatten → FC(128)  
    - Regularization: Dropout (p=0.1) after FC layer

    \item \textbf{MLP Branch:}  
    - Input: 8-dim CE features  
    - Layers: FC(8→64) → Dropout (0.1) → FC(64→128)
\end{itemize}

The combined feature $\mathbf{h}_{\text{combined}} \in \mathbb{R}^{256}$ is classified via:
\[ \mathbf{y} = \mathbf{W}_{\text{combined}}\mathbf{h}_{\text{combined}}, \quad \mathbf{W} \in \mathbb{R}^{2 \times 256} \]

\subsubsection{1D CNN-based Method}
Dual 1D convolutional pathways:

\begin{itemize}[leftmargin=*]
    \item \textbf{Row Pathway:}  
    (1,4) conv → (8,1) max pool (stride 8,1) → additional convs → 32 features

    \item \textbf{Column Pathway:}  
    (8,1) conv → (1,4) max pool (stride 1,4) → additional convs → 32 features
\end{itemize}

Features are concatenated (128D) → FC(128) → dropout (0.1). Combined with MLP branch (same as above) for final classification.

\subsubsection{ViT-based Method}
Processes image patches ($p \times p$) via transformer:

\begin{itemize}[leftmargin=*]
    \item Patch embedding: 1×1 patches ($p=1$) → 128D embedding
    \item Class token + learned positional embeddings
    \item Transformer: 3 layers, 4 heads, 256-dim MLP
    \item Final classification uses class token representation
\end{itemize}

MLP branch processes 8-dim features separately. Combined features classified via linear layer.

\subsubsection{1D ViT-based Method}
Dual-branch 1D ViT:

\begin{itemize}[leftmargin=*]
    \item \textbf{Branch 1:} 8-length patches (N=4), 2 layers
    \item \textbf{Branch 2:} 4-length patches (N=8), 2 layers 
    \item Both use 4 attention heads, d=128
    \item Combines with MLP branch (d=128)
\end{itemize}

Final classification on $\mathbb{R}^{384}$ combined features.

