\includegraphics[width=0.49\textwidth]{Figures/hubbleSketch.pdf}
\includegraphics[width=0.49\textwidth]{Figures/angleSketch.pdf}
%
\caption{\justifying\textbf{Left:} Sketch of the avoided crossing that underlies the phenomenology in this paper. The axion fields start oscillating when $m_{H,L}\sim H$. This results in different scenarios depending on whether the onset of oscillations take place before or after the crossing. The physical mass eigenvalues $m_H$ and $m_L$ are indicated by colored lines. Several potential scenarios for the Hubble parameter $H$ are shown and colored 
to match the different regimes in Fig. \ref{fig:comparison}. The masses of the flavor states $m_a(T)$ and $m_S$, using the conventions of Eq.\,\eqref{eq:VTAK}, are represented by the gray dashed lines. 
\textbf{Right:} Sketch of the evolution of the mixing parameter $\sin^2 2\xi$ from which we define the width of the resonance, $\delta t_{\rm res}$. Note that the right sketch shows a much shorter time interval than the left sketch so that both can highlight the relevant features.} 
\label{fig:masscross}
\end{figure}
%%%%%
The behavior of this system of coupled differential equations is governed by the hierarchy between the variation of the mixing angle $\dot \xi$ and the oscillation rates of each individual axion, $m_{H,L}$, and the oscillation rate \textit{between} axions, $m_H - m_L$, the non-relativistic analog of a neutrino oscillation rate. Depending on this interplay, two distinct regimes emerge: the adiabatic and non-adiabatic limits, corresponding to whether $\dot{\xi}$ can be neglected or not, which is tied to the existence of a resonance.



\paragraph*{\textbf{Adiabatic case.}}

When the mixing angle changes slowly enough in time that the $\dot \xi$ and $\ddot \xi$ terms in Eq. \eqref{eq:AxionAlpEOMMassBasisSimplified} can be neglected,  the equation of motion for the comoving mass eigenstates $\tilde{a}_H$ and $\tilde{a}_L$ is nearly diagonal,
\begin{equation}
    \partial_t^2 \,
    \begin{pmatrix}
        \tilde{a}_H
        \\
        \tilde{a}_L
    \end{pmatrix}
    \simeq 
    \begin{pmatrix}
        -\frac{3}{4}H^2-m_H^2
        && 0
        \\[2pt]
        0 && 
        -\frac{3}{4}H^2-m_L^2
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_H
        \\
        \tilde{a}_L
    \end{pmatrix}\, .
    \label{eq:AxionAlpEOMMassBasisAdiabatic}
\end{equation}
In this regime, the \textit{adiabatic theorem} implies that this slow-acting perturbation in the axion Hamiltonian does not affect the energy level populations. As a consequence, states initially occupying an energy eigenstate will remain within that energy eigenstate, as they evolve continuously in flavor space. More concretely, after the fields start to oscillate at time $t_{{\rm osc},H,L}$ when $m_{H,L} > H$, one can solve the independent evolution of the two mass eigenstates $a_H$ and $a_L$ under the WKB approximation,
\begin{align}
    & a_H(t) = a_{H,\text{osc}}\sqrt{\frac{{R_{\text{osc}}^3 m_{H,\text{osc}}}}{{R^3 m_H}}}  \cos\left(\int^t_{t_{\text{osc,}H}} m_H(\tau) \mathrm{d}\tau\right) \, ,
    & a_L(t) = a_{L,\text{osc}}\sqrt\frac{{R_{\text{osc}}^3 m_{L,\text{osc}}}}{R^3 m_L}  \cos\left(\int^t_{t_{\text{osc,}L}} m_L(\tau) \mathrm{d}\tau\right) \, ,
    \label{Eq:WKBexactsolmain}
\end{align}
where  the `\rm{osc}' subscript indicates that the associated quantity is evaluated at the $t = t_{{\rm osc},H}$ for the heavy field and $t_{{\rm osc},L}$ for the light field.
The WKB approximation is equivalent to the assumption that the mass eigenvalues 
change slowly,
$\dot\omega_i/\omega_i^2\ll1$ where $\omega_i^2=3/4H^2+m_i^2$ for $i = \{H,L\}$, implying $H\ll m_i$ and $\dot m_i/m_i^2\ll1$ . 
Thus, even if the mass eigenstates change in time, there exists two independent  adiabatic invariants i.e. comoving number of axions, $n_H^{\rm WKB}$ and $n_L^{\rm WKB}$, which remain constant in the evolution,
\begin{align}
    &n_H^{\rm WKB}(T) = \frac{\rho_H(T) R^3}{m_H(T)} \simeq \text{constant} \, ,
    &n_L^{\rm WKB}(T) = \frac{\rho_L(T)R^3}{m_L(T)} \simeq \text{constant} \label{eq:numberdensitiesWKB} \, ,
\end{align}
where $\rho_{H,L}\equiv \dot a^2_{H,L}/2+ m_{H,L}^2 a^2_{H,L}/2 $ are the corresponding energy densities of the two mass eigenstates.
% 
It is important to stress that in terms of any static basis, e.g. the flavor basis $a$ and $a_S$, the adiabatic evolution of the fields is  coupled and it is only in the instantaneous eigenstate basis that the two evolutions decouple.
Note that the WKB results, \cref{Eq:WKBexactsolmain,eq:numberdensitiesWKB}, apply even when the axion fields experience a resonance (see Fig.\,\ref{fig:masscross} and resonance condition\, \eqref{eq:tCross}), as long as the evolution remains adiabatic ($\dot\xi\ll\Delta m$, see \cref{eq:gamma}), analogously to the Mikheyev–Smirnov–Wolfenstein (MSW) effect in solar neutrinos \cite{Mikheyev:1985zog,Wolfenstein:1977ue}.
We now quantify the condition for non-adiabatic evolution and show how such evolution is captured with the LZ formalism.
\paragraph*{\textbf{Non-adiabatic case.}}
What happens when $\dot{\xi}$ is large so that the off-diagonal elements of \eqref{eq:AxionAlpEOMMassBasisSimplified} become important in the evolution of $(a_H, a_L)$? In this \textit{non-adiabatic} regime, the population of the mass eigenstates $a_H$ and $a_L$ can convert between themselves. To understand any non-adiabatic evolution, it is useful to linearize Eq.\,\eqref{eq:AxionAlpEOMMassBasisSimplified} to a two-state Schrödinger equation, which we derive for the axion system in Appendix \ref{app:FeshbachVillars}. The resulting equations of motions, written in terms of positive and negative frequency modes of the axion field, are 


\begin{align}
    \label{eq:schrodingerEOM}
    i \partial_t
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix}
    &= 
    \pm
    \begin{pmatrix}
        \frac{m_H + m_L}{2} && 0
        \\
        0 &&  \frac{m_H + m_L}{2}
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix}
    +
    \begin{pmatrix}
        \pm\frac{m_H - m_L}{2} - \frac{i}{2}\frac{\dot{m_H}}{m_H}  &&  i \dot{\xi}
        \\
        -i \dot{\xi} &&  \mp\frac{m_H - m_L}{2}  - \frac{i}{2}\frac{\dot{m_L}}{m_L} 
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix} \, ,
\end{align} 
%%
%% 
where $\tilde{a}_{H} \equiv \tilde{a}_{H+} +  \tilde{a}_{H-}$ and  $\tilde{a}_{L} \equiv \tilde{a}_{L+} +  \tilde{a}_{L-}$. The derivation of Eq.\,\eqref{eq:schrodingerEOM} assumes the axion fields have negligible momenta so that any spatial gradients are small and that $m_{H,L} > H$, which allows the axion fields to oscillate. 

Since the term proportional to the identity matrix gives rise to an unimportant phase, Eq.~\ref{eq:schrodingerEOM} makes manifest that non-adiabatic evolution occurs when $\dot{\xi} \gg \omega_{\rm osc}$,
where
%%
\begin{align}
    \omega_{\rm osc} = E_H - E_L = \Delta m = \frac{m_H^2 - m_L^2}{m_H + m_L}
    \label{eq:OscFrequencyDifference}
\end{align}
%%
is the oscillation rate \textit{between} the two axion flavor states, analogous to the oscillation rate between neutrino flavors. The larger $\dot{\xi}$ is relative to $\omega_{\rm osc}$, the greater the probability of conversion between $\tilde{a}_H$  and $\tilde{a}_L$ since $\dot{\xi}$ connects $\tilde{a}_H$ and $\tilde{a}_L$ states in the Hamiltonian of Eq.\,\eqref{eq:schrodingerEOM}. In terms of the rate of change of the matrix elements of $\mathbf{M}^2$, $\dot{\xi}$ can be found by taking the time derivative of Eq. \eqref{eq:tan2xi},
%%
\begin{align}
\begin{split}
      \dot \xi &= \frac{1}{4 m_{as}^2}\left[ 2\sin 2\xi \cos 2 \xi  \frac{d m_{as}^2}{dt} - \sin^2 2\xi \left(\frac{d m_{ss}^2}{dt} - \frac{d m_{aa}^2}{dt} \right)\right] \, .
\end{split}
\label{eq:2xiDot}
\end{align}
%%
Eq.\,\eqref{eq:2xiDot} demonstrates that the rapid changes in the mixing angle $\xi$ occur prominently at $t_{\rm \times}$  when $\sin^2 2\xi$ briefly equals unity.
%%
The duration of this resonance, $\delta t_{\rm res}$, is set by the width of the $\sin^2 2\xi$ peak as shown in the right panel of Fig.\,\ref{fig:masscross}. It is convenient to define $\delta t_{\rm res}$  by the condition that if $\sin^2 2\xi(t_\times) = 1$, then $\sin^2 2\xi(t_{\times} + \delta t_{\rm res}) = 1/2$ \cite{kuo1989nonadiabatic}. From Eq.\,\eqref{eq:tan2xi}, this gives 
%%
%%
\begin{align}
\label{eq:tres}
    \delta t_{\rm res} = 2\left|\frac{ m_{as}^2}{\frac{d m_{ss}^2}{dt} - \frac{d m_{aa}^2}{dt}}\right|_{t = t_\times} = \frac{1}{2|\dot{\xi}(t_\times)|}\,.
\end{align}
%%
Thus, the degree of non-adiabaticity is tied to the existence of a resonance.  

The evolution of the $(\tilde{a}_H, \tilde{a}_L)$ system for all time, including the brief non-adiabatic behavior around $t_{\times}$, can be analytically determined by solving Eq.~\ref{eq:schrodingerEOM} along a world-line that is $\textit{always}$ adiabatic, where the evolution of the $(\tilde{a}_H, \tilde{a}_L)$ states are known and is simply the WKB evolution. This method, due to Landau \cite{Landau:1932vnv,landau1977quantum}, is achived by analytically continuing the worldline into the complex plane around $t_{\times}$ such that non-adiabatic evolution is avoided as shown in App~\ref{app:Landau_Approach}. Alternatively, Eq.\eqref{eq:schrodingerEOM} can be solved directly in terms of parabolic Cylindrical functions, which is the method of Zener \cite{zener1932non}.
%%
\footnote{
Interestingly, in addition to the derivations by Landau and Zener, analogous results were obtained in the same year (1932) by Majorana~\cite{Majorana:1932ga} and St\"uckelberg~\cite{stueckelberg1932}, in the contexts of oriented atoms in a varying magnetic field and inelastic atomic collisions, respectively.}
%%
We confirm both methods give the same result in Appendix \ref{app:Zener_Approach}.

The key result is that, up to a phase, 
each axion field after $t_\times$ becomes a linear combination of $\tilde{a}_H$ and $\tilde{a}_L$ given by the solution \eqref{eq:adiabaticSolution}, %
%%
\begin{align}
    {a}_H(t_\times^+) = C_1 \,{a}_H(t_\times^-) + C_2 {a}_L(t_\times^-) \, ,
\end{align}
with the LZ probability of conversion, $P_{\rm LZ}$, given by
%%
\begin{align}
    \label{eq:LZProbability}
   |C_2|^2 = P_{\rm LZ}(\tilde{a}_H \leftrightarrow \tilde{a}_L) = \exp(- \pi \gamma/2)\,\quad \text{and}\quad |C_1|^2 = 1 - |C_2|^2\, ,
\end{align}
%%
where the \textit{adiabatic parameter} $\gamma$ given by
%%
\begin{align}
    \gamma  = \left\vert \frac{4(m_{as}^2)^2}{\frac{d \, m_{aa}^2}{dt} - \frac{d\, m_{ss}^2}{dt}}\frac{1}{m_H + m_L}  \right\vert _{t=t_{\times}}  = \Big|\frac{\omega_{\rm osc}}{2\dot\xi}\Big|_{t=t_\times}= \delta t_{\rm res}\omega_{\rm osc}(t_\times) \, .
    \label{eq:gamma}
\end{align}
In the second equality, we have made use of the fact that $m_H^2 - m_L^2 = 2 |m_{as}^2|$  at $t_{\times}$ (see Eq.\,\eqref{eq:tan2xi}), to write $\gamma$ in terms of $\omega_{\rm osc}(t_\times)$ and $\delta t_{\rm res}$.~We point out that, while the parametric dependence of $\gamma$ on the oscillation rate between the two axions has been suggested in previous studies~\cite{Ho:2018qur, Murai:2024nsp}, the analytical expression in Eq.~\ref{eq:LZProbability} is derived for the first time in this work.

Whenever $\gamma \gg 1$, the evolution is adiabatic through crossing, which corresponds to $P_{\rm LZ} \to 0$, and the result reduces to~\cref{Eq:WKBexactsolmain}. In the opposite limit, $\gamma \ll 1$, the crossing becomes highly non-adiabatic, and the LZ probability captures the likelihood of conversion between mass eigenstates, with $P_{\rm LZ} \to 1 - \pi\gamma/2\sim 1$. In this regime, the populations of the mass eigenstates efficiently exchange.

Two important assumptions underline the LZ treatment:
during the level crossing, \textit{(1)} the difference between the 
diagonal elements in $\mathbf M^2$ evolves linearly with time and \textit{(2)} the variation of the off-diagonal element is sufficiently small in comparison to the latter, so that it can be neglected. As we show in App~\ref{app:LZValidity}, \textit{such conditions are only violated if the resonance width is larger than the age of the Universe}, which does not occur unless the two derivatives, $dm_{aa}^2/dt$ and $dm_{ss}^2/dt$ in the expression above are tuned to cancel each other at $t_{\times}$. We can therefore employ the LZ method in the entire non-adiabatic regions for most axion two-state systems. 

In the following sections, we study two different axion potentials and discuss the mixing in different regimes. We will analytically determine the relic abundance of the two mass eigenstates today, $\Omega_{a_L}$ and $\Omega_{a_H}$, in the adiabatic regime and the non-adiabatic regime. Furthermore, we will also solve the coupled equations of motion numerically to confirm the analytic results.



\subsection{Application I}\label{sec:PotentialI}
%
Let us start by considering the following interaction potential~\cite{Murai:2023xjn}: 
\begin{equation}
V(a,\,a_S)  =  m_a^2(T) f_a^2 \left[1-\cos\left(\frac{a}{f_a}\right)\right]  +m_S^2f_S^2\left[1-\cos\left(\frac{a_S}{f_S}+\frac{a}{f_a}\right)\right]\,,
\label{eq:VTAK}
\end{equation}
where the first term stems from the interaction with gluons, $\frac{\alpha_s}{8\pi} \frac{a}{f_a} G \widetilde G$, being the overall amplitude the QCD  topological susceptibility, $ \chi (T) = m_a^2(T) f_a^2  $.

By expanding the potential to second order in the scalar fields, one identifies the mass matrix:
%
\begin{equation}
V (a,\,a_s)  \approx
\begin{pmatrix} 
a_S & a 
\end{pmatrix} 
\left(\begin{array}{cc}
m_S^2 & m_S^2 R_f \\
m_S^2 R_f & m_a^2(T)+ m_S^2 R_f^2
\end{array}\right) \begin{pmatrix} a_S \\  a \end{pmatrix} \equiv A^T \mathbf{M}^2 A\,,
\label{eq:massMatrix}
\end{equation}
where $R_f \equiv f_S/f_a$ and $R_m \equiv m_S/m_{a,0}$. 
The temperature dependence of the QCD topological susceptibility follows a power-law at high temperatures and remains constant below $T_{\rm QCD}$,
\begin{equation}
m_a^2 (T) = m_{a,0}^2 \text{max} \left\{1, \left(\frac{T}{T_{\rm QCD}}\right)^{-2n}\right\}\,, \label{eq:maofT}
\end{equation}
with $m_{a,0}^2 \equiv m_a^2(T=0)= \frac{m_\pi^2 f_\pi^2}{f_a^2} \frac{{m_u\,m_d}}{(m_u+m_d)^2}$, $T_{\rm QCD} \approx 100$ MeV and $n\approx { 3.34}$\,\footnote{ Note that there are several estimates for $n$. While the power-law behaviour predicted by the DIGA for QCD, $n\sim 4$, agrees with some lattice simulations \cite{Borsanyi:2016ksw}, alternative approximations like the interacting instanton liquid model (IILM) suggest $n \sim 3.3$ and other lattice computations result in smaller values, $n \sim 3.8-4.2$ \cite{Trunin:2015yda} for QCD.}.



In this scenario, the eigenvalues read
%
\begin{equation}
    m_{H,L}^2=\frac{1}{2} m_a^2 + m_s^ 2 \left(1+R_f^2\right) \pm \sqrt{m_a^2 - 2 m_a^2 m_s^ 2 (1-R_f^2) + m_s^4 (1+ R_f^2)^2}\,,
\end{equation}
%
whereas the mixing angle is given by
%
\begin{equation}
\tan 2\xi = \frac{2 R_f}{1-R_f^2 - (1/R_m^2) (m_a^2/m_{a,0}^2)}\,.
\label{eq:angle_pot1}
\end{equation}
%

Focusing on the high temperature limit of Eq.\,\eqref{eq:VTAK}, one can also obtain the initial field values of the two mass eigenstates as a function of the initial misalignment angles $\theta_{a}\equiv a/f_a$ %\big|_{ini.}
 and $\theta_{s}\equiv a_s/f_s$:
\begin{align}
   & a_{H} (T)= \frac{R_f f_a}{\sqrt{1+R_f^2}}(\theta_{a}+\theta_{s})\,,\quad 
    &a_{L} (T)= \frac{R_f f_a}{\sqrt{1+R_f^2}}\Big(\frac{1}{R_f}\theta_{a}-R_f\theta_{s}\Big)\,.
    \label{Eq:InitialFieldValues}
\end{align}
These expressions will be relevant to the discussion that follows.

As argued in the last section, the temperature at which level crossing takes place, $T_\times$, can be found by exploring the resonant behavior of the mixing angle, defined when $|\tan 2 \xi(T_\times)| \rightarrow \infty$\,: 
\begin{align}
 \frac{m_a^2 (T_{\times})}{m_{a,0}^2} = R_m^2 (1-R_f^2)\,
\Leftrightarrow T_{\times} = \left({\sqrt{1-R_f^2} R_m}\right)^{-1/n} T_{\rm QCD}\,.
\label{eq:Tcross}
\end{align}
%
The first equation above has solutions whenever $R_f < 1$ and  $R_m^2 (1-R_f^2)<1$, 
therefore level crossing is forbidden in the blue regions represented in Fig.~\ref{fig:regionLC}. These regions have been previously identified in Ref.~\cite{Ho:2018qur}.


%%%%%%%%%%%%%%%%%%%%

With these results, it is now straightforward to obtain the LZ probability in terms of the adiabatic parameter defined in Eq.~\ref{eq:gamma}, which in this model reads
\begin{align}
\gamma 
&  = \frac{m_S}{H(T_\times) n} R_f^2 + \mathcal{O}(R_f^4)\,.
\label{eq:gammaTAK}
\end{align}
%
In Fig.~\ref{fig:regionLC}, we represent the parameter space where $\gamma < 1$ enclosed by a dashed red line, assuming that $f_a = 10^{13}$\,GeV. By employing the LZ conversion probability, we will show that the evolution of the two fields can be studied analytically in this entire region, as long as the fields start oscillating~{before} $T_\times$.

