\newcommand\SmallMatrix[1]{{%
  \arraycolsep=0.35\arraycolsep\ensuremath{\begin{pmatrix}#1\end{pmatrix}}}}
% \begin{widetext}
\begin{align}
    \label{eq:FVHamiltonian}
    i\partial_t
     \SmallMatrix{
        \tilde{a}_{H_+}
        \\
        \tilde{a}_{L_+}
        \\
        \tilde{a}_{H_-}
        \\
