    }
    % \nonumber 
    % \\
    &=
    % \begin{pmatrix}
    \SmallMatrix{
        m_H + \frac{\mathbf{p}^2}{2m_H} - \frac{i}{2} \frac{\dot{m_H}}{m_H} 
        && 
        i \dot{\xi} - \frac{i(m_H-m_L)\dot{\xi}}{2m_H}
        && 
        \frac{\mathbf{p}^2}{2m_H} + \frac{i}{2} \frac{\dot{m_H}}{m_H}
        &&
        \frac{i(m_H-m_L)\dot{\xi}}{2m_H}
        \\
        -i \dot{\xi} - \frac{i(m_H-m_L)\dot{\xi}}{2m_L}
        &&
         m_L + \frac{\mathbf{p}^2}{2m_L} - \frac{i}{2} \frac{\dot{m_L}}{m_L} 
        &&
        \frac{i(m_H-m_L)\dot{\xi}}{2m_L}
        &&
        \frac{\mathbf{p}^2}{2m_L} + \frac{i}{2} \frac{\dot{m_L}}{m_L}
        \\
        -\frac{\mathbf{p}^2}{2m_H} + \frac{i}{2} \frac{\dot{m_H}}{m_H} 
        &&
        \frac{i(m_H-m_L)\dot{\xi}}{2m_H}
        &&
        -m_H - \frac{\mathbf{p}^2}{2m_H} - \frac{i}{2} \frac{\dot{m_H}}{m_H} 
        &&
        i \dot{\xi} - \frac{i(m_H-m_L)\dot{\xi}}{2m_H}
        \\
        \frac{i(m_H-m_L)\dot{\xi}}{2m_L}
        &&
        -\frac{\mathbf{p}^2}{2m_L} + \frac{i}{2} \frac{\dot{m_L}}{m_L}
        &&
        -i \dot{\xi} - \frac{i(m_H-m_L)\dot{\xi}}{2m_L}
        &&
        -m_L - \frac{\mathbf{p}^2}{2m_L} - \frac{i}{2} \frac{\dot{m_L}}{m_L} 
    % \end{pmatrix}
   }
    \SmallMatrix{
        \tilde{a}_{H_+}
        \\
        \tilde{a}_{L_+}
        \\
        \tilde{a}_{H_-}
        \\
        \tilde{a}_{L_-}
    }
    \, .
\end{align}
% \end{widetext}
%%
%%
In the extreme adiabatic limit where the terms $\dot{m}_H/m_H, \dot{m}_L/m_L$, and $\dot{\xi}$ are much smaller than $m_H$ and $m_L$ the four eigenvalues of Eq.\,\eqref{eq:FVHamiltonian} yield the standard relativistic dispersion relations,
%%
\begin{align}
    E = \{\pm \sqrt{\mathbf{p}^2 + m_H^2}, \pm \sqrt{\mathbf{p}^2 + m_L^2}\}  \qquad (\text{Extreme adiabatic eigenvalues})\, ,
\end{align}
with $\pm$ corresponding to the positive/negative frequency modes, respectively.

In general, however, the terms $\dot{m}_H/m_H, \dot{m}_L/m_L$, and $\dot{\xi}$ cannot be neglected, especially in the extreme non-adiabatic regime where $\dot{\xi}$ can be much greater than $m_H$ and $m_L$. When keeping only the leading order non-adiabatic  ($\dot{m}_H/m_H, \dot{m}_L/m_L$) and kinetic ($\mathbf{p}^2$) corrections to adiabatic propagation and  mass-eigenstate mixing ($i\dot{\xi})$
%%
\footnote{The off-diagonal term $i\dot{\xi}(m_H-m_L)/m_{H,L}$ can be neglected since it is always smaller than $i \dot{\xi}$ when mass-eigenstate mixing becomes important near the resonance point when $\sin^2 2\xi(t_\times) = 1$ and $\dot{\xi} \gg m_{H} \simeq m_L$. This follows from Eq.\,\eqref{eq:tan2xi} which indicates that on resonance, $\dot{\xi}(m_H-m_L) \lesssim m_{H,L}^2$.}
%%
, the full $4\times4$ Hamiltonian becomes block-diagonal, splitting into the following two $2\times2$ Hamiltonians,
%%

\renewcommand{\arraystretch}{2.0}
% \begin{widetext}
\begin{alignat}{3}
    \label{eq:FVHamiltonianApproxPlus}
    i\partial_t
     \SmallMatrix{
        \tilde{a}_{H_+}
        \\
        \tilde{a}_{L_+}
    }
    % \nonumber 
    % \\
    &\simeq
    % \begin{pmatrix}
    \SmallMatrix{
        m_H + \frac{\mathbf{p}^2}{2m_H} - \frac{i}{2} \frac{\dot{m_H}}{m_H} 
        && 
        i \dot{\xi} 
        \\
        -i \dot{\xi}
        &&
         m_L + \frac{\mathbf{p}^2}{2m_L} - \frac{i}{2} \frac{\dot{m_L}}{m_L} 
    % \end{pmatrix}
   }
    \SmallMatrix{
        \tilde{a}_{H_+}
        \\
        \tilde{a}_{L_+}
    }
    \quad&\equiv & \quad \mathcal{H}_+ \Psi_{D+}
    \\
    \label{eq:FVHamiltonianApproxMinus}
    i\partial_t
     \SmallMatrix{
        \tilde{a}_{H_-}
        \\
        \tilde{a}_{L_-}
    }
    % \nonumber 
    % \\
    &\simeq
    % \begin{pmatrix}
    \SmallMatrix{
        -m_H - \frac{\mathbf{p}^2}{2m_H} - \frac{i}{2} \frac{\dot{m_H}}{m_H} 
        && 
        i \dot{\xi}
        \\
        -i \dot{\xi}
        &&
         -m_L - \frac{\mathbf{p}^2}{2m_L} - \frac{i}{2} \frac{\dot{m_L}}{m_L} 
    % \end{pmatrix}
   }
    \SmallMatrix{
        \tilde{a}_{H_-}
        \\
        \tilde{a}_{L_-}
    }
   \quad&\equiv & \quad \mathcal{H}_- \Psi_{D-}
    \, .
\end{alignat}
%%
In the non-relativistic and adiabatic limit, the solutions of Eq.\,\eqref{eq:FVHamiltonianApproxPlus} and \eqref{eq:FVHamiltonianApproxMinus} become
%%
\begin{alignat}{3}
    \label{eq:aHAdiabaticSolution}
    \tilde{a}_{H \pm} &= \exp\left[\mp i \int_{t_{\rm osc}}^t m_H(\tau) d\tau  - \frac{1}{2} \int_{t_{\rm osc}}^t \frac{d \ln m_H}{d\tau}d\tau \right] \quad &=\quad &\tilde{a}_{H\pm}(t_{\rm osc}) \sqrt{\frac{m_H(t_{\rm osc})} {m_H(t)}} \exp[\mp i \int_{t_{\rm osc}}^t m_H(\tau) d\tau] \, ,
    \\
    \label{eq:aLAdiabaticSolution}
    \tilde{a}_{L \pm} &= \exp\left[\mp i \int_{t_{\rm osc}}^t m_L(\tau) d\tau  - \frac{1}{2} \int_{t_{\rm osc}}^t \frac{d \ln m_L}{d\tau}d\tau \right] &=\quad &\tilde{a}_{L\pm}(t_{\rm osc}) \sqrt{\frac{m_L(t_{\rm osc})}{m_L(t)}} \exp[\mp i \int_{t_{\rm osc}}^t m_L(\tau) d\tau] \, .
\end{alignat}
%%
Since $\Psi = \Psi_{+} + \Psi_-$, the full solution is
%%
\begin{alignat}{3}
    &\tilde{a}_H(t) = \tilde{a}_{H+}(t) + \tilde{a}_{H-}(t) \quad &=\quad & \tilde{a}_H(t_{\rm osc})\sqrt{\frac{{m_{H,\text{osc}}}}{{m_H}}}  \cos\left(\int^t_{t_\text{osc}} m_H(\tau) \mathrm{d}\tau\right) \, ,
    \\
    &\tilde{a}_L(t) = \tilde{a}_{L+}(t) + \tilde{a}_{L-}(t) \quad &=\quad & \tilde{a}_L(t_{\rm osc})\sqrt{\frac{{m_{L,\text{osc}}}}{{m_L}}}  \cos\left(\int^t_{t_\text{osc}} m_L(\tau) \mathrm{d}\tau\right) \, .
\end{alignat}
%%
which, after recalling $\tilde{a}(t) \equiv a(t)R(t)^{3/2}$ is the comoving axion field, reduces to the standard WKB solution of the Klein-Gordan equation of Eq.\,\eqref{Eq:WKBexactsolmain}. Above, the coefficients $\tilde{a}_{H+}(t_{\rm osc}) = \tilde{a}_{H-}(t_{\rm osc})^*= \tilde{a}_H(t_{\rm osc})/2$.

As demonstrated by Eqns.\,\eqref{eq:aHAdiabaticSolution} and \eqref{eq:aLAdiabaticSolution}, the four separate quantities $|m_H\tilde{a}_{H\pm}^2|$ and $|m_L\tilde{a}_{L\pm}^2|$ are conserved in  adiabatic evolution, corresponding to the comoving number densities of each axion mode. Even in non-adiabatic evolution, however, there remain conserved quantities: Noting that $ \partial_t(\Psi_{D\pm}^\dagger\Psi_{D\pm}) = -i \Psi_{D\pm}^\dagger(\mathcal{H}_{\pm} - \mathcal{H}_{\pm}^\dagger)\Psi_{D\pm} $ where $\mathcal{H}_{\pm}$ is the $2\times2$ Hamiltonian of Eqns.\,\eqref{eq:FVHamiltonianApproxPlus} and \eqref{eq:FVHamiltonianApproxMinus}, implies that for all time,
%%
\begin{align}
    \label{eq:probabilityConservation}
    \partial_t|\tilde{a}_{H\pm}|^2 + \partial_t|\tilde{a}_{L\pm}|^2 + |\tilde{a}_{H\pm}|^2\partial_t \ln m_H + |\tilde{a}_{L\pm}|^2\partial_t \ln m_L
 = 0\,.\end{align}
%%
For any brief period of time, such as near a non-adiabatic resonance, the last two terms of Eq.\,\eqref{eq:probabilityConservation} can be neglected since the timescale of the resonance, $\delta t_{\rm res}$ is much shorter than the timescale for which the masses vary, which is $\mathcal{O}(H(t_\times))$, and since the field values themselves, $\tilde{a}_{H,L}$, change rapidly. In this regime, Eq.\,\eqref{eq:probabilityConservation} can be interpreted as a conservation of probability: $ \partial_t|\tilde{a}_{H\pm}|^2 + \partial_t|\tilde{a}_{L\pm}|^2 \simeq 0$. From here on, when quantitatively analyzing the behavior of the axion fields around the resonance time $t_{\times}$, we will drop the logarithmic correction to the masses $\dot{m}_{H,L}/m_{H,L}$. 

In the following two sections, we show two different ways of determining the evolution of the axion fields during the time $- \delta t_{\rm res} + t_{\times} \lesssim t \lesssim t_{\times} + \delta t_{\rm res}$ (see Fig.\,\ref{fig:masscross}), corresponding to Landau's approach (\ref{app:Landau_Approach}), and Zener's approach (\ref{app:Zener_Approach}).  These two methods determine the value of the axion fields before and after the resonance, thereby connecting the two WKB evolutions valid on opposite sides of the resonance. As a whole, this procedure provides an analytic determination of the asymptotic axion yields which may make up the dark matter. 


\subsection{Landau's Approach}
\label{app:Landau_Approach}
%%
Landau's method for determining the probability of conversion between two mass eigenstates after a non-adiabatic resonance involves  analytically continuing the adiabatic equation of motion along a path in the complex plane that bypasses the resonance time while always remaining adiabatic.

To see how this is done, first expand the effective $2\times2$ Hamiltonian $\mathcal{H}$ (Eqns.\,\eqref{eq:FVHamiltonianApproxPlus} and \eqref{eq:FVHamiltonianApproxMinus}) in terms of symmetric and antisymmetric diagonal pieces (equivalently, a linear combination of $\mathbb{1}$, $\mathbf{\sigma}_z$)
%%
%%
\begin{align}
    \label{eq:schrodingerEqFeshbachVillars2}
    i \partial_t
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix}
    &= 
    \pm
    \begin{pmatrix}
        \frac{m_H + m_L}{2} && 0
        \\
        0 &&  \frac{m_H + m_L}{2}
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix}
    +
    \begin{pmatrix}
        \pm\frac{m_H - m_L}{2} - \frac{i}{2}\frac{\dot{m_H}}{m_H}  &&  i \dot{\xi}
        \\
        -i \dot{\xi} &&  \mp\frac{m_H - m_L}{2}  - \frac{i}{2}\frac{\dot{m_L}}{m_L} 
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{H \pm}
        \\
        \tilde{a}_{L \pm}
    \end{pmatrix} \, .
\end{align} 
%%
%%  
The first, or symmetric term in Eq.\,\eqref{eq:schrodingerEqFeshbachVillars2} is just a phase mutual to both $\tilde a_{H,L}$, and hence can be removed by temporarily redefining the axion fields by $\tilde{a}_{\pm} \rightarrow \tilde{a}_{\pm} \exp[\pm i \int_{t_0}^t (m_H + m_L)/2]$. The second, or antisymmetric term is physical. 
For notational brevity, we hereafter write just the solutions to the positive modes, $\tilde{a}_{H+}$ and $\tilde{a}_{L+}$; the negative modes, $\tilde{a}_{H-}$ and $\tilde{a}_{L-}$ proceed in the same manner. 

According to the equation of motion, Eq.\,\eqref{eq:schrodingerEqFeshbachVillars2}, when $\dot{\xi} \ll m_H -m_L$, 
the axion fields evolve adiabatically as 
%%
\begin{align}
    \label{eq:adiabaticSolution}
    \tilde{a}_{H+}(t) &= \tilde{a}_{H+}(t_0)\sqrt{\frac{m_H(t_0)}{m_H(t)}}\exp\left[-i \int_{t_0}^t  dt' \frac{m_H(t')-m_L(t')}{2}\right]
    \\
    \tilde{a}_{L+}(t) &= \tilde{a}_{L+}(t_0)\sqrt{\frac{m_L(t_0)}{m_L(t)}}\exp\left[+i \int_{t_0}^t  dt' \frac{m_H(t')-m_L(t')}{2}\right]\,.
\end{align}
%%
Eq.\,\eqref{eq:adiabaticSolution} is a good approximation when a resonance or level-crossing has not occurred, or equivalently, when $t$ in the integral of \eqref{eq:adiabaticSolution} is $\ll$ than the level-crossing time, $t_\times$ (see Eq.\, \eqref{eq:tCross}). 

Now, consider what happens when a resonance between the two axion fields occurs at time $t_\times$. Eq.\,\eqref{eq:adiabaticSolution}  assumes the axion evolution is adiabatic, which \textit{is not true} at $t_\times$. Nevertheless, Eq.\,\eqref{eq:adiabaticSolution} can \textit{still} be used to solve the behavior of the axion system around $t_{\times}$ by integrating $t$ along a contour in the complex plane that is always adiabatic, a trick due to Landau \cite{Landau:1932vnv,landau1977quantum} (see also \cite{Pizzochero:1987fj,kuo1989nonadiabatic} for elaboration on Landau). The contour is shown in Fig.\,\ref{fig:LZComplexPlane}.

This can be seen by first noting that the integrand of Eq.\,\eqref{eq:adiabaticSolution} can be written as $m_H-m_L = (m_H^2-m_L^2)/(m_H+m_L)$ where
%%
\begin{align}
    \label{eq:massSqDifference}
    m_H^2-m_L^2 = \sqrt{(m_{aa}^2 - m_{ss}^2)^2 + 4 (m_{as}^2)^2} \, ,
\end{align}
%%
which follows from Eq.\,\eqref{eq:tan2xi}.
Eq.\,\eqref{eq:massSqDifference} demonstrates that $m_H^2 - m_L^2$ (and hence $m_H - m_L$) is never zero for any \textit{real} time. At the resonant time $t_\times$, $m_{aa}^2 - m_{ss}^2 = 0$,  and the two mass eigenvalues are at their closest approach in real time, though never actually degenerate (so-called \textit{avoided level-crossing}). In the complex plane, however, there \textit{is} an actual level-crossing. To see this, Taylor expand $m_{aa}^2$ and $m_{ss}^2$ about $t_{\times}$:
%%
\begin{align}
    m_{aa}^2 - m_{ss}^2 &\simeq  m_{aa}(t_\times)^2 - m_{ss}(t_\times)^2 
   +
   % \nonumber \\
    % &
    \left(\frac{d m_{aa}^2}{dt}\biggr\rvert_{t_\times}-\frac{d m_{ss}^2}{dt}\biggr\rvert_{t_\times}\right)(t-t_\times)
    \\
    \label{eq:LZTaylorExpand}
    &=  0 + \Delta' z \,.
\end{align}
%%
In Eq.\,\eqref{eq:LZTaylorExpand}, we have simplified the expression $m_{aa}^2 - m_{ss}^2$ by making use of the fact that $  m_{aa}(t_\times)^2 - m_{ss}(t_\times)^2  = 0$, and defined $\Delta' = \frac{d}{dt}(m_{aa}^2 - m_{ss}^2)\rvert_{t_\times}$ and $z \equiv t - t_\times$ as a complexified time.

Inserting Eq.\eqref{eq:LZTaylorExpand} into Eq.\,\eqref{eq:massSqDifference} indicates that there is a level-crossing ($m_H^2 = m_L^2$), or turning-point in the integrand of Eq.\eqref{eq:adiabaticSolution}, at the complex times
%%
\begin{align}
    \text{Complex Turning Points at }\pm z_0 = \pm 2 i \left|\frac{m_{as}^2}{\Delta'}\right| \, .
\end{align} 
%%
The two turning point values at $\pm z_0$ are branch points associated with the root behavior of $m_H^2- m_L^2$, as shown by the blue ragged line of Fig.\,\ref{fig:LZComplexPlane}. Consequently, when analytically continuing the time integration variable $t$ in the argument of Eq.\,\eqref{eq:adiabaticSolution} to the complex time $z$, complex phases associated with wrapping around the branch occur, as given by
%%
\begin{align}
    m_H - m_L &= \frac{m_H^2 - m_L^2}{m_H + m_L} 
    \nonumber \\
    &= \frac{\sqrt{(m_{aa}^2 - m_{ss}^2)^2 + 4 (m_{as}^2)^2}}{m_H + m_L} 
    \nonumber \\
    &\simeq \frac{\sqrt{(2m_{as}^2 + i\Delta' z)} \sqrt{(2m_{as}^2 - i\Delta' z)}}{m_H + m_L} 
     \nonumber
    \\
    &= \frac{\sqrt{(2 m_{as}^2)^2}}{m_H + m_L} \sqrt{z - z_0} \sqrt{z + z_0} = \frac{|2 m_{as}^2|}{m_H + m_L}|z -z_0|^{1/2}|z+z_0|^{1/2} e^{i \phi_1/2} e^{i \phi_2/2} e^{i 2\pi k/2} 
    \nonumber \\
    &= |m_H - m_L| e^{\frac{\scriptstyle i (\phi_1 + \phi_2 + 2\pi k)}{ \scriptstyle 2}}  \qquad \qquad \left(-\frac{\pi}{2} < \phi_i \leq \frac{3\pi}{2} , \; k \in \mathbb{Z} \right) \, .
    \label{eq:mHMinusmLPhases}
\end{align}
%%
Here, $\phi_1$ ($\phi_2$) is the angle between the real axis and a ray extending from $+z_0$ ($-z_0$) to an arbitrary complex time $z$ as shown in Fig.\,\ref{fig:LZComplexPlane} \cite{brown2009complex}. The branch along the imaginary axis limits $\phi_i$ to lie between $-\pi/2$ and $3\pi/2$. The values of $\phi_1$, $\phi_2$, and $\exp[i(\phi_1 + \phi_2)/2]$ along the negative real axis (contour $\mathcal{C}_1$), positive real axis ($\mathcal{C}_4$), and on opposite sides of the branch ($\mathcal{C}_2$ and $\mathcal{C}_3$), are shown in the right panel of Fig.\,\ref{fig:LZComplexPlane}. The integer $k$ is arbitrarily chosen to be unity so that $m_H - m_L = +|m_H - m_L|$ on the negative real time axis.
\noindent
\begin{minipage}[t]{0.53\textwidth}
 \vspace{0pt}
    \centering
    \includegraphics[width=1.0\linewidth]{Figures/LZ_Complex_Plane-compressed.pdf} 
    \captionof{figure}{Analytic continuation of adiabatic evolution.}
    \label{fig:LZComplexPlane}
\end{minipage}
\hfill
\begin{minipage}[t]{0.44\textwidth}
 \vspace{0pt}
    \centering
    \setlength{\tabcolsep}{2pt}
    \renewcommand{\arraystretch}{2.575}
    \small{
    \begin{tabular}{l | c c c}
         & $\phi_1$ & $\phi_2$ & $\exp\left[i\frac{\phi_1 + \phi_2}{2}\right]$ \\
        \hline
        $\mathcal{C}_1$ \;& $\pi + \mathrm{arg}(z - z_0)$ & $\pi - \mathrm{arg}(z - z_0)$ & $-1$ \\
        $\mathcal{C}_2$ \;& $\frac{3\pi}{2}$ & $\frac{\pi}{2}$ & $-1$ \\
        $\mathcal{C}_3$ \;& $-\frac{\pi}{2}$ & $\frac{\pi}{2}$ & $1$ \\
        $\mathcal{C}_4$ \;& $-\mathrm{arg}(z - z_0)$ & $\mathrm{arg}(z - z_0)$ & $1$
    \end{tabular}}
    \label{tab:complexPhases}
    \captionof{table}{Phases around the branch.}
\end{minipage}

As can be seen from the Table \ref{tab:complexPhases} and Eq.\,\eqref{eq:mHMinusmLPhases}, $m_H - m_L$ flips sign as one integrates over the branch, which is equivalent to switching the energy evolution phase of $a_H$ with $a_L$ (see Eq.\,\eqref{eq:adiabaticSolution}). The connection goes even deeper. Indeed, recall the value of $\xi$ is inferred from the inverse of Eq.\,\eqref{eq:tan2xi}; $\xi(t) = \arctan(2 m_{as}^2/(m_{aa}^2 - m_{ss}^2))$. In the complex plane, $\arctan$ also has branch points precisely at $\pm z_0$, so that traversing around the branch makes $\xi$ discontinuous by $\xi \rightarrow \xi + \pi/2$ \cite{brown2009complex,arctanComplex}. While $\tan(2\xi +\pi) = \tan 2\xi$ remains the same, $\cos(\xi+\pi/2)=-\sin\xi$ and $\sin(\xi+\pi/2) =\cos(\xi)$, which is precisely the transformation that flips the relationship between $a_H$ and $a_L$ according to the relationship of Eq.\,\eqref{eq:rot}. Thus, $a_H$ and $a_L$ flip when passing to a new  branch.


Quantitatively, the trick of Landau is to perform the time integration of Eq.\,\eqref{eq:adiabaticSolution} past the resonance by integrating along the red contour of Fig.\,\ref{fig:LZComplexPlane}, which is always adiabatic since it avoids the non-adiabatic region at the time $t_\times + 0i$  \cite{Landau:1932vnv,landau1977quantum}. This integral can be split up into four segments, corresponding to the contours labeled $\mathcal{C}_1,\mathcal{C}_2,\mathcal{C}_3,\mathcal{C}_4$ of Fig.\,\ref{fig:LZComplexPlane}. For example, integrating Eq.\,\eqref{eq:adiabaticSolution} for $\tilde{a}_{H+}$ gives:
\begin{widetext}
\begin{align}
    \label{eq:LZContourIntegration}
    \tilde{a}_{H+}(t > t_\times) &=  \tilde{a}_{H+}(t_0)\sqrt{\frac{m_H(t_0)}{m_L(t)}}\exp\left[-i\int_{t_0 - t_\times}^{- \epsilon} \frac{\Delta}{2} dz -i\int_{-\epsilon}^{z_0-\epsilon} \frac{\Delta}{2}dz + i\int_{z_0+\epsilon}^{\epsilon} \frac{\Delta}{2}dz +i\int_{\epsilon}^{t} \frac{\Delta}{2}dz \right] \, ,
\end{align}
\end{widetext}
%%
where $\Delta \equiv |m_H - m_L|$ for shorthand convenience.

Note the first two terms and last two terms have opposite signs, arising from being on opposite sides of the branch cut. In particular, the first term is a phase representing adiabatic evolution until right before $t_{\times}$, the second and third terms are equivalent, and the fourth term is the $\tilde{a}_{L+}(t)$ wavefunction, up to a phase. That is, wrapping around the branch converts an $\tilde{a}_H$ mass eigenstate into an $\tilde{a}_L$ mass eigenstate. The $\epsilon$ in the integration bounds makes explicit which side of the branch cut the contour resides, but is taken to $0$ at the end of the calculation. Similarly, the WKB coefficient $\sqrt{m_H(t_0)/m_H(t)}$ becomes  $\sqrt{m_H(t_0)/m_L(t)}$ after crossing the branch which follows from writing $m_H = \frac{1}{2}(m_H+m_L) + \frac{1}{2}(m_H-m_L)$ which becomes $\frac{1}{2}(m_H+m_L) - \frac{1}{2}(m_H-m_L) = m_L$ after the branch. Eq.\,\eqref{eq:LZContourIntegration} can therefore be written as
%%
\begin{align}
    \label{eq:a1Toa2Wavefunction}
    \tilde{a}_{H+}(t > t_\times) = \tilde{a}_{H+}(t_0) \sqrt{\frac{m_H(t_0)}{m_L(t_0)}} \exp[-i \Phi] \exp\left[2i \int_0^{z_0} \frac{|m_H - m_L|}{2} dz\right] \frac{\tilde{a}_{L+}(t)}{\tilde{a}_{L+}(t_0)} \, ,
\end{align}
%%
where $i\Phi = i\int_{t_0 - t_\times}^{-\epsilon} |m_H - m_L|$ is an unimportant complex phase, and $\tilde{a}_{L+}$ is the positive mode of the light energy eigenstate, given in Eq.\,\eqref{eq:adiabaticSolution}.
The residual integral from $0$ to $z_0$ along the branch, however, is entirely real and hence does not vanish when considering probabilities. The integral is
%%
\begin{align}
    I &\equiv 2i\int_0^{z_0} \frac{m_H - m_L}{2} dz 
    \\
    &=\int_0^{z_0} \frac{i(m_H^2 - m_L^2)}{m_H + m_L} dz
    \\
    &\simeq\int_0^{z_0} \frac{i\sqrt{(\Delta')^2 z^2 + 4(m_{as}^2)^2}}{m_H(t_\times) + m_L(t_\times)} dz
    \\
    \label{eq:LZInt}
    &= -\left|\pi \frac{m_{as}^2}{\Delta'}\frac{1}{m_H(t_\times) + m_L(t_\times)} \right| \, .
\end{align}
%%
Since $m_H$ and $m_L$ are nearly degenerate in the above integral, in the third line we approximate $m_H + m_L$ as a constant -- the value of their sum at the resonance time $t_\times$. 
%%
\footnote{The integral can still be done analytically without this approximation, but it is complex and unnecessary in this work.} 
%%

The same method, except by integrating below the branch cut instead of above, yields the  $\tilde{a}_{H-}$ solution after $t_\times$; it is the complex conjugate of Eq.\,\eqref{eq:a1Toa2Wavefunction}, as it must be, with $+$ fields replaced by their $ -$ counterparts. The linear combination of the $\tilde{a}_{H \pm}$ modes after $t_\times$ is then 
%%
\begin{align}
    \label{eq:combinedaHLZ}
    \tilde{a}_H(t > t_\times) = \tilde{a}_{H+}(t>t_\times) +\tilde{a}_{H-}(t>t_\times)= \frac{\tilde{a}_H(t_0)}{\tilde{a}_L(t_0)} ) \sqrt{\frac{m_H(t_0)}{m_L(t_0)}} e^I [e^{i\Phi} \tilde{a}_{L+}(t) + e^{-i\Phi} \tilde{a}_{L-}(t)] \, .
\end{align}
%%
After restoring the fields to their original definitions by the inverse phase factor $\tilde a_{\pm} \rightarrow \tilde{a}_{\pm} \exp[\mp i \int_{t_0}^t (m_H + m_L)/2]$, and inserting the definitions of $\tilde{a}_{L+}$ and $\tilde{a}_{L-}$, Eq.\,\eqref{eq:combinedaHLZ} reduces to
%%
\begin{align}
    \label{eq:combinedaHLZ2}
    \tilde{a}_H(t>t_\times) = \tilde{a}_H(t_0)\sqrt{\frac{m_H(t_0)}{m_L(t)}}e^I \cos\left(\int_{t_0}^t m_L  d\tau + \Phi\right) \, ,
\end{align}
%%
where we have used $|\tilde{a}_{L+}(t_0)| = |\tilde{a}_{L-}(t_0)|=\frac{1}{2}\tilde{a}_L(t_0)$.
Note, the right-hand-side of Eq.\,\eqref{eq:combinedaHLZ2} is an $\tilde{a}_L$ state. Hence the number density of $\tilde{a}_L$ after $t_\times$ that originate from $\tilde{a}_H$ before $t_\times$ is
%%
\begin{align}
    n_{H\rightarrow L} &= \frac{1}{2m_L}\left[m_L^2 \tilde{a}_H(t>t_\times)^2 + (\partial_t\tilde{a}_H(t>t_\times))^2\right] = \frac{1}{2}\tilde{a}_H(t_0)^2 m_H(t_0) e^{2I}
    \\
    &= n_H^{\rm WKB} P_{\rm LZ}
\end{align}
%%
where

%%
\begin{align}
    \label{eq:LZProbabilityAppendix}
    &P_{\rm LZ} \equiv \exp[2I] \equiv \exp\left[-\frac{\pi \gamma}{2}\right] 
    \qquad \gamma =  \left|\frac{4(m_{as}^2)^2}{\frac{d{m_{aa}^2}}{dt} - \frac{d{m_{ss}^2}}{dt}} \frac{1}{(m_H + m_L)} \right|_{t = t_\times} \, ,
\end{align}
%%
is the Landau-Zener probability of conversion, and is the main result of this appendix.

Note that the number density of $n_L$ after $t_\times$ also contains unconverted axions that originate from $\tilde{a}_L$ before $t_\times$ as well. In general, a wave function that starts off as $\tilde{a}_H$ before $t_\times$ will be after $t_\times$ a linear combination of $\tilde{a}_H$ and $\tilde{a}_L$, which are complete,
%%
\begin{align}
    \tilde{a}(t > t_\times) = C_1(t) \tilde{a}_H(t) + C_2(t) \tilde{a}_L(t) \, .
\end{align}
%%
As we have just demonstrated, $C_2(t)$, the projection of the new axion wave function in the $\tilde{a}_L$ direction, has a squared modulus given by Eq.\,\eqref{eq:LZProbabilityAppendix}. The coefficient $C_1(t)$ was lost along the integration of the contour in the upper complex plane because $\tilde{a}_H$ is exponentially suppressed relative to $\tilde{a}_L$ for positive imaginary time, as seen from Eq.\,\eqref{eq:adiabaticSolution}. Conversely, integrating Eq.\,\eqref{eq:adiabaticSolution} along a contour in the negative complex plane keeps only the $\tilde{a_H}$ projection, so that $C_1(t)$ can be extracted. It is simpler though to use conservation of probability over the brief duration of the resonance $\delta t_{\rm res}$, Eq.\,\eqref{eq:probabilityConservation}, to infer that $|C_1|^2 \simeq 1 - |C_2|^2$.


\subsection{Zener Approach}
\label{app:Zener_Approach}
%%
A complementary approach, inspired by the work of Zener, solves the Schrödinger-like Eqns.\,\eqref{eq:FVHamiltonianApproxPlus} and \eqref{eq:FVHamiltonianApproxMinus} asymptotically via perturbation theory for a two-level system initially prepared in a state $\left|a_S\right>$ that due to the off-diagonal interaction evolves to $\left|a\right>$ at later times. 
To this aim, it is convenient to return to the flavor basis. Writing 
$(a_H \; a_L)^T = U^\dagger (a \; a_S)$, Eq.\,\eqref{eq:massEigenstates}, the Schrödinger equation of motion, Eq.\,\eqref{eq:schrodingerEqFeshbachVillars2}, becomes 
%%
%%
\begin{align}
    \label{eq:schrodingerEqFlavorBasis}
    i \partial_t
    \begin{pmatrix}
        \tilde{a}_{\pm}
        \\
        \tilde{a}_{S \pm}
    \end{pmatrix}
    &= 
    \pm
      \frac{m_H + m_L}{2}
    \begin{pmatrix}
        1 && 0
        \\
        0 &&  1
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{\pm}
        \\
        \tilde{a}_{S \pm}
    \end{pmatrix}
    \pm \frac{m_H - m_L}{2}
    \begin{pmatrix}
        \cos(2\xi) &&  \sin(2\xi)
        \\
       \sin(2\xi) &&  -\cos(2\xi)
    \end{pmatrix}
    \begin{pmatrix}
        \tilde{a}_{\pm}
        \\
        \tilde{a}_{S \pm}
    \end{pmatrix} \, .
\end{align} 
%%
%%  
%%
Here, we have dropped the slow WKB evolution terms, $\dot{m_{H,L}}/m_{H,L}$, which are assumed to slowly change across the resonance.
Using the mixing angle definition, Eq.\,\eqref{eq:tan2xi}, the non-diagonal contribution of the Hamiltonian can be written as
%%
\begin{align}
    \frac{m_H - m_L}{2}
    \begin{pmatrix}
        \cos(2\xi) &&  \sin(2\xi)
        \\
       \sin(2\xi) &&  -\cos(2\xi)
    \end{pmatrix} = 
    \frac{1}{2(m_H + m_L)}
    \begin{pmatrix}
        m_{aa}^2 - m_{ss}^2 &&  2 m_{as}^2
        \\
       2 m_{as}^2 &&  -(m_{aa}^2 - m_{ss}^2)
    \end{pmatrix}
    \equiv 
    \begin{pmatrix}
    \epsilon_1 (t) & \epsilon_{12} (t)\\
    \epsilon_{12} (t) & \epsilon_2 (t)
    \end{pmatrix}\,.
\end{align}
%%
%%
Defining $\Delta \epsilon \equiv \epsilon_1 - \epsilon_2 = (m_{aa}^2 - m_{ss}^2)/(m_H + m_L)$, the solutions to Eq.~\eqref{eq:schrodingerEqFlavorBasis} then follow:
%
\begin{alignat}{3}\label{eq:diff1}
    i \partial_t a_+ & = \epsilon_{12} \, a_{S+} \, e^{i \int_{t_0}^t \Delta \epsilon \, dt'}  \qquad i \partial_t a_- &= & -\epsilon_{12} \, a_{S-} \, e^{-i \int_{t_0}^t \Delta \epsilon \, dt'} \, \,, \\
    \label{eq:diff2}
    i \partial_t a_{S+} & = \epsilon_{12}^{*} \, a_+\, e^{- i\int_{t_i}^t \Delta \epsilon \, dt'} \qquad i \partial_t a_{S-} &=& -\epsilon_{12} \, a_-\, e^{ i\int_{t_i}^t \Delta \epsilon \, dt'} \,.
\end{alignat}
As expected, the positive and negative frequency solutions are Hermitian conjugates of each other. For brevity, we will therefore focus on the just the positive solution modes with understanding that the negative frequency modes are the complex conjugated solutions. The initial conditions of each axion state are
\begin{align}
    a_+ (t_0) &= a_- (t_0)^* = \frac{1}{2}a(t_0) =0\,,\\
    a_{S+} (t_0) &=a_{S-}^* (t_0) = \frac{1}{2}a_{S} (t_0)\,.
\end{align}
%
%%
Equations~\ref{eq:diff1} and \ref{eq:diff2}
can be combined into a second-order differential equation that decouples the two states. For example, for the positive mode,
\begin{equation}
\label{eq:Lz_num}
    \ddot a_+ - \left(i \Delta \epsilon + \frac{\dot{ \epsilon_{12}}}{\epsilon_{12}}\right) \dot a_+ + \epsilon_{12}^2 a_+ = 0\,.
\end{equation}
%%

Assuming that $\epsilon_{12}$ is constant over the resonance, and that Taylor expanding $\Delta \epsilon$ about the resonance is linear in time (see Eq.\,\eqref{eq:LZTaylorExpand}), this equation can be solved analytically in terms of parabolic cylinder functions \cite{abramowitz1968handbook}; see~\cite{Carenza:2023nck, Ivakhnenko:2022sfl,HammarskioldSpendrup1879424} for recent reviews. The solution is \cite{Carenza:2023nck}
%%
\begin{align}
    a_+(t >t_\times) = a_{S+}(t_0)\sqrt{\frac{\gamma}{4}} e^{-\pi \gamma}D_{-1-n}\left(\frac{iw(t)}{\sqrt{n}}\right)\, ,
\end{align}
%% 
where $\gamma$ is the adiabatic parameter given in Eq.\,\eqref{eq:LZProbabilityAppendix}, $n = i \gamma/4$, $w(t)= \sqrt{\Delta \epsilon (t-t_\times)}$, and $D_\nu(z)$ is the parabolic cylindrical function \cite{abramowitz1968handbook}.
In particular, the probability that the system, initially prepared in the sterile flavor state, is identified with the active axion flavor state after crossing is
\begin{equation}\label{eq:PZener}
    \lim_{t\to \infty} \left|\frac{a_+(t>t_\times)}{a_{S+}(t_0)}\right|^2 = 1- \exp[-\pi \gamma/2]\,,\quad \text{with}\quad \gamma = \left|4\epsilon_{12}^2\left(\frac{d \Delta \epsilon}{dt}\right)^{-1}\right|_{t=t_\times} =  \left|\frac{4(m_{as}^2)^2}{\frac{d{m_{aa}^2}}{dt} - \frac{d{m_{ss}^2}}{dt}} \frac{1}{(m_H + m_L)} \right|_{t = t_\times}\,,
\end{equation}
which by the same logic as in Appendix \ref{app:Landau_Approach}, is the same probability of converting $a \rightarrow a_S$.

At first sight, this looks similar to the conversion probability derived in Eq.\,\eqref{eq:LZProbabilityAppendix}, except the probability here is $1-P_{\rm LZ}$ rather than $P_{\rm LZ}$. The difference lies in that after the resonance at $t_\times$, the main flavor state identified with the mass  eigenstates flips. That is \cite{kuo1989nonadiabatic},
%%
\begin{align}
\begin{split}
    P_{a_S \rightarrow a} &= |\langle a(t>t_\times)| a_S(t_0)\rangle|^2
    \\
    &= |\langle a(t>t_\times)|a_i(t>t_\times)\rangle \langle a_i(t>t_\times| a_j(t_0)\rangle\langle a_j(t_0)| a_S(t_0)\rangle|^2
    \\
    &= 
    \begin{pmatrix}
        0 & 1
    \end{pmatrix}
    \begin{pmatrix}
        \cos^2\xi(t>t_\times) & \sin^2\xi(t>t_\times)
        \\
         \sin^2\xi(t>t_\times) & \cos^2\xi(t>t_\times)
    \end{pmatrix}
    \begin{pmatrix}
        1-P_{\rm LZ} & P_{\rm LZ}
        \\
         P_{\rm LZ} &  1-P_{\rm LZ}
    \end{pmatrix}
    \begin{pmatrix}
        \cos^2\xi(t_0) & \sin^2\xi(t_0)
        \\
         \sin^2\xi(t_0) & \cos^2\xi(t_0)
    \end{pmatrix}
    \begin{pmatrix}
        1 & 0
    \end{pmatrix}
    \\
    \label{eq:probAtoAs}
    &= \frac{1}{2}\left[1+ (2 P_{\rm LZ} -1) \cos( 2 \xi(t>t_\times) \cos (2 \xi(t_0)  \right] \, .
\end{split}
\end{align}
%%
Here, we have inserted the resolution of the identity as a sum of outer products of the axion mass eigenstates in line 2, and used the unitary operator that rotates flavor eigenstates to mass eigenstates in line 3. To map on to the Landau approach of App.\ref{app:Landau_Approach}, we define as usual $P_{\rm LZ} \equiv |\langle a_i(t>t_\times)|a_j(t_0)\rangle|^2$ for $i \neq j$ as the probability of converting mass eigenstate $i$ to mass eigenstate $j$.

Since prior to $t_\times$, $m_{aa}^2 -m_{ss}^2 \ll m_{as}^2$ (or vice versa) and after $t_\times$, $m_{aa}^2 - m_{ss}^2 \gg m_{as}^2$ (or vice versa), $2\xi \simeq \pi$ before $t_\times$ and $2\xi \simeq 0$ after $t_\times$ (or vice versa), as can be seen from Eq.\eqref{eq:tan2xi}. Hence the product $\cos( 2 \xi(t>t_\times) \cos (2 \xi(t_0) \simeq -1$ and Eq.\eqref{eq:probAtoAs} can be approximately written as
%%
\begin{align}
    \label{eq:}
    P_{a_S\rightarrow a} \simeq 1 - P_{\rm LZ} \, .
\end{align}
%%

Comparing this with Eq.\,\eqref{eq:PZener}, we can identify $P_{\rm LZ} = \exp[-\pi \gamma/2]$, which is consistent with the Landau approach of App.\ref{app:Landau_Approach}.

\subsection{Validity of Landau-Zener Probability}
\label{app:LZValidity}

Importantly, the analytic integration of Eq.~\ref{eq:LZInt} in the Landau approach or Eq.~\ref{eq:Lz_num} in the Zener approach used to derive the LZ probability are obtained under two important assumptions: \textit{(1)} $m_{aa}^2 - m_{ss}^2$ is linear with time about $t_\times$ and \textit{(2)} the variation of the off-diagonal term, $m_{as}^2$, is negligible in comparison to that of $m_{aa}^2 - m_{ss}^2$ during the resonance.

%%
To check the first condition, let us fully Taylor expand $m_{aa}^2 -m_{ss}^2$ about $t_{\times}$ to determine when higher order terms in the expansion dominate over the linear term:
%%
\begin{align}
\label{eq:LZTaylorExpandLinearCheck}
    m_{aa}^2 -m_{ss}^2
    &= 0 + (t-t_{\times}) \frac{d \Delta}{dt} + \frac{1}{2}(t - t_{\times})^2\frac{d^2 \Delta}{dt^2} +  \frac{1}{6}(t - t_{\times})^3\frac{d^3\Delta}{dt^3} + ... \,.
\end{align}
%%
Here, $\frac{d^k}{dt^k}\Delta \equiv \frac{d^k}{dt^k}(m_{aa}^2 - m_{ss}^2)\biggr\rvert_{t_\times}$  as before, which is bounded by
%%
\begin{align}
    \frac{d^k}{dt^k} \Delta &\leq \frac{d^k}{dt^k}m^2 \biggr\rvert_{t_\times}
    \\
    &\leq \frac{d^k}{dt^k} \left(m_{a,0} \left(\frac{T}{T_{\rm QCD}}\right)^{-n} \right)^2 \biggr\rvert_{t_\times}
    \\
    &=\frac{d^{k-1}}{dt^{k-1}} \left(2n H m^2 \right)\biggr\rvert_{t_\times}
    \\
    \label{eq:LZderivativeOrder}
    &= (2n H(t_\times))^k  m(t_\times)^2 \, .
\end{align}
%%
In the third line, we have used entropy conservation to write $dT/dt = -H T$, where $H$ is Hubble. In the fourth line, we have dropped terms of order $(dH/dt)^l H^{k-l}$ which are small compared to terms of order $H^k$ in a radiation or matter-dominated cosmology.

From Eq.\,\eqref{eq:LZderivativeOrder}, we see that each term in Eq.\,\eqref{eq:LZTaylorExpandLinearCheck} is smaller (or larger) than the previous term by a factor of at least $2 H(t_\times)(t - t_\times)$. Thus, if $2 H(t_\times)\delta t_{\rm res} < 1$, where $\delta t_{\rm res}$ is the duration of the resonance where LZ is active, then the linear condition assumed for LZ is valid.

Quantitatively, it is convenient to define $\delta t_{\rm res}$ as the full width at half max of the $\sin^2 2\theta$ peak  \cite{kuo1989nonadiabatic}, meaning if $\sin^2 2\theta(t_\times) = 1$, then $\sin^2 2\theta(t_{\times} + \delta t_{\rm res}) = 1/2$. From Eq.\,\eqref{eq:tres}, this defines 
%%
%%
\begin{align}
    \delta t_{\rm res} = \left|\frac{2 m_{as}^2(t_\times)}{\Delta'}\right| = 2
    \sqrt{\gamma\frac{m_1(t_\times) + m_2(t_\times)}{\Delta'}} \, ,
\end{align}
%%
where we have used the definition of the adiabatic parameter, Eq.\,\eqref{eq:gamma}, to replace $m_{as}^2$ with $\gamma$. Unless there is a fine-tuned cancellation between $d m_{aa}^2/dt$ and $dm_{ss}^2/dt$ at $t_{\times}$, the typical value of $\Delta' \sim 2 n H(t_\times) m(t_\times)^2$, which is Eq.\,\eqref{eq:LZderivativeOrder} for $k = 1$. If we define $\delta$ as the degree of tuning of the two terms in $\Delta'$ compared to this expected value, ie $\Delta' \equiv 2 n H(t_{\times})m(t_\times)^2 \delta$ where $\delta \leq 1$, then linearity of LZ requires
%%
\begin{align}
    \label{eq:LZlinearityCondition}
    \delta t_{\rm res} H(t_\times) \approx 2 \sqrt{\frac{\gamma}{n \delta}\frac{H(t_{\times})}{m(t_\times)}} \ll 1 \qquad \text{(Linearity Condition of LZ)}\, \,
\end{align}
%%
which is satisfied unless $\delta \ll m(t_\times)/H(t_\times) n\gamma$, which is a small parameter since $m > H$ and $\gamma < 1$ in the non-adiabatic LZ regime. For example, for the axion mass matrix of Eq.\,\eqref{eq:massMatrix}, $\delta = 1-R_f^2$. Since level crossing does not occur for $R_f > 1$ for the potential of \eqref{eq:massMatrix}, $\delta$ is $\mathcal{O}(1)$ except potentially for some  $R_f$ very close to $1$. Similarly, for the axion mass matrix of Eq.\,\eqref{eq:VII}, $\delta = 1 - R_f^{-2}$, which agrees with the expected mapping of $R_f \rightarrow R_f^{-1}$ between the two example potentials as discussed in Sec.\,\ref{sec:PotentialII}. Since level crossing only occurs for $R_f > 1$ for this potential, $\delta$ is again $\mathcal{O}(1)$ for all of the parameter space except potentially near $R_f = 1$.

Last, to check the second condition, we note that $dm_{as}^2/dt \leq 2 n H m_{as}^2$. It follows that if the linearity condition of LZ is satisfied, \eqref{eq:LZlinearityCondition}, then the rate of change of $m_{aa}^2 - m_{ss}^2$ compared to the rate of change of $m_{as}^2$ around $t_\times$ is
%%
\begin{align}
    \label{eq:ratioOfDiagonaltoOffDiagonal}
    \frac{\frac{d}{dt}(m_{aa}^2 -m_{ss}^2)}{\frac{d}{dt}(m_{as}^2)} &=\frac{\Delta'}{\frac{d}{dt}(m_{as}^2)} 
    \\
    &\geq \frac{2n H(t_\times) m(t_\times)^2 \delta}{2n H(t_\times) m_{as}^2(t_\times)}
    \\
    & \geq \frac{2 m(t_\times)^3 /\gamma}{2n H(t_\times) m_{as}^2(t_\times)}
    \\
    & \geq \frac{m(t_\times)^2}{ m_{as}^2(t_\times)}\frac{1}{n \gamma}
\end{align}
%%
Thus, the range of change of $m_{as}^2$ can always be ignored in the LZ formalism if $m_{as}^2(t_\times)  < m^2/n\gamma$, where $m^2 = m_{aa}^2(t_\times) = m_{ss}^2(t_\times)$.
Since $\gamma \leq 1$ in the non-adiabatic regime, violation of this condition requires the off-diagonal element $m_{as}^2$, to be larger than either of the diagonal elements, $m_{aa}^2$ or $m_{ss}^2$, around $t_\times$, which is often not the case. For example, for the axion mass matrix of Eq.\,\eqref{eq:massMatrix}, the ratio of Eq.\,\eqref{eq:ratioOfDiagonaltoOffDiagonal} is infinite since $m_{as}^2 = m_S^2 R_f$ is independent of time. Hence ignoring the rate of change of $m_{as}^2$ is always satisfied. Similarly, for the axion mass matrix of Eq.\,\eqref{eq:VII}, the ratio of Eq.\,\eqref{eq:ratioOfDiagonaltoOffDiagonal} is $R_f(1-R_f^{-2})$. This ratio is satisfied for all $R_f$ except for $R_f \sim 1$ where the LZ linearity condition anyway breaks down.


