\ln\left[\frac{\frac{q_{\mathrm{max}}}{2k_x}+\sqrt{\left(\frac{q_{\mathrm{max}}}{2k_x}\right)^2-1}}{\frac{K}{2k_x}+\sqrt{\left(\frac{K}{2k_x}\right)^2-1}}\right]
-\ln\left[\frac{1}{\left(1-\left(K\frac{3a}{2\pi}\right)^2\right)^2\left(1-\frac{1}{2}\left(K\frac{3a}{2\pi}\right)^2\right)^2}\right]
\right)& , & 0<k_x<\frac{K}{2}\\
\\
\begin{aligned}
