\title[Separating Hausdorff measures]{Separating covering numbers and separating uniformity numbers of Hausdorff measures need large continuum}
\author{Tatsuya Goto}
\date{\today}
\address{
	Institute of Discrete Mathematics and Geometry, TU Wien
	Wiedner Hauptstrasse 8-10/104, 1040 Wien, Austria
}

\keywords{Set theory of the reals, Cardinal invariants, Hausdorff measures}
\subjclass[2020]{03E17}
\email{tatsuya.goto@tuwien.ac.at}

\begin{document}
	\begin{abstract}
		We show that if $\frakc = \aleph_2$ then all covering numbers of Hausdorff measures $\cov(\scrN^s(\R^d))$ ($0 < s < d, d \in \omega$) are equal and all uniformity numbers $\non(\scrN^s(\R^d))$ ($0 < s < d, d \in \omega$) are equal. This is a partial answer to Problem 5.3 and 5.4 of \cite{ES19}.
	\end{abstract}

	\maketitle

	\section{Introduction}

	Cardinal characteristics regarding Hausdorff measures are studied in \cite{ES19}, \cite{SS05} and \cite{Got25}.
	Elekes and Stepr\={a}ns, in \cite{ES19}, asked whether all covering numbers of Hausdorff measures $\cov(\scrN^s(\R^d))$ ($0 < s < d, d \in \omega$) are equal and whether all uniformity numbers of Hausdorff measures $\non(\scrN^s(\R^d))$ ($0 < s < d, d \in \omega$) are equal.
	In this paper, we prove that if $\frakc = \aleph_2$ then both statements are true.
	In other words, to separate these cardinals, we need large continuum ($\frakc > \aleph_2$).
	Therefore, the countable support iterated forcing is not suitable for this separation.

	The rest of this section is devoted to a review of fractal geometry. 

	We induce the metric on the Cantor space $2^\omega$ by $d(x, y) = 2^{-\min\{n: x(n) \ne y(n)\}}$ for $x \ne y$.



	\begin{defi}
		Let $X$ be a metric space.
		For $A \subseteq X$, $s$ a positive real number and $\delta \in (0, \infty]$, we define
		\[
		\Haus^s_\delta(A) = \inf \{ \sum_{n=0}^\infty (\diam(C_n))^s : C_n \subseteq X \text{ (for $n \in \omega$)} \text{ with } A \subseteq \bigcup_{n \in \omega} C_n \text{ and } (\forall n) (\diam(C_n) \le \delta) \},
		\]
		where $\diam$ is the diameter function.
		For $A \subseteq X$ and $s > 0$, we define
		\[
		\Haus^s(A) = \lim_{\delta \to 0} \Haus^s_\delta(A).
		\]
		We call $\Haus^s(A)$ the \textit{$s$-dimensional Hausdorff measure}.
	\end{defi}

	\begin{defi}
		For a metric space $X$ and for $0 < s < 1$, let $\scrN^s(X)$ be the $s$-dimensional Hausdorff measure zero ideal on $X$.
		When $X = 2^\omega$, then we omit it.
	\end{defi}

	\begin{defi}
		For a metric space $X$ and a subset $A \subseteq X$ and $\delta > 0$, $N_\delta(A)$ is the smallest number of sets of diameter at most $\delta$ which can cover $A$.
		Define $$\overline{\dim}_\mathrm{B}(A) = \limsup_{\delta \to 0} \frac{\log N_\delta(A)}{- \log \delta}.$$
		This is called the upper box counting dimension of $A$.
	\end{defi}

	\begin{defi}
		$\Ibox^s = \{ A \subseteq 2^\omega : \overline{\dim}_\mathrm{B}(A) < s \}$.
	\end{defi}

	\begin{defi}
		Let $X$ and $Y$ be metric spaces and $\alpha, c > 0$.
		A map $f\from X \to Y$ is said to be \textit{$\alpha$-H\"{o}lder} with constant $c$ if for all $x, x' \in X$ we have $d(f(x), f(x')) \le c \cdot d(x, x')^\alpha$. If the constant is not important, then we omit it to just say $f$ is $\alpha$-H\"{o}lder.
	\end{defi}

	\begin{fact}\label{fact:holderhaus}
		Let $X$ and $Y$ be metric spaces and $\alpha > 0$.
		If there is $\alpha$-H\"{o}lder map $f\from X \to Y$ with constant $c$, then for all $s > 0$ we have $\Haus^{s/\alpha}(f(X)) \le c^{s/\alpha} \Haus^s(X)$.
	\end{fact}


	\begin{defi}
		For a family $\scrI$ of subsets of $X$, we put $\cov(\scrI)  = \min \{ \abs{\mathcal{A}} : \mathcal{A} \subseteq \scrI, \bigcup \mathcal{A} = X \}$.
		This is called the covering number of $\scrI$.

		Also, we put $\non(\scrI)  = \min \{ \abs{Y} :Y \subseteq X, Y \not \in \scrI \}$.
		This is called the uniformity number of $\scrI$.
	\end{defi}

	Note that $\Ibox^s \subseteq \scrN^s$ and therefore $\cov(\scrN^s) \le \cov(\Ibox^s)$ and $\non(\Ibox^s) \le \non(\scrN^s)$.

	%Let $\mathbf{K}$ be the set of all compact subsets of $2^\omega$.
	%That $\cov(\Ibox^t \cap \mathbf{K}) = \cov(\Ibox^t)$ and 	that $\non(\Ibox^t \cap \mathbf{K}) = \non(\Ibox^t)$ are clear since the topological closure operator does not change the upper box counting dimension.

	We will employ the following facts.

	\begin{fact}[Proposition 4.1 of \cite{BK24}]\label{fact:holdermap}
		Let $X$ be a compact ultrametric space with positive $t$-dimensional Hausdorff measure and $Y$ be  a compact metric space with $\overline{\dim}_B(Y) < s$.
		Then there is a compact subset $A\subseteq X$ and $t/s$-Hölder onto map $f \colon A \to Y$.
	\end{fact}

	\begin{fact}[Lemma 5.1 of \cite{BK24}]\label{fact:lischitzretraction}
		Let $X$ be a compact ultrametric space and $A \subseteq X$ be a compact subset.
		Then there is a Lipschitz retraction $g \colon X \to A$.
	\end{fact}

	\section{The result with covering numbers}

	We first prove the result regarding covering numbers.

	\begin{defi}
		$\cov\left(\frac{\scrN^s}{\Ibox^t}\right) = \sup \{ \cov (\scrN^s(A)) : A \in \Ibox^t \}$.
	\end{defi}

	\begin{prop}\label{prop:fraction}
		For $0 < s < t < 1$, 
		$\cov\left(\frac{\scrN^s}{\Ibox^t}\right) \le \cov(\scrN^{s/t})$ holds.
	\end{prop}
	\begin{proof}
		Let $A$ be a member of $\Ibox^t$.
		We have to show that $\cov (\scrN^s(A)) \le \cov(\scrN^{s/t})$.
		We may assume that $A$ is compact because we can take the topological closure.

		By applying Fact \ref{fact:holdermap} and Fact \ref{fact:lischitzretraction}, there is a $(1 / t)$-Hölder onto map $h \colon 2^\omega \to A$.

		Let $\kappa = \cov(\scrN^{s/t})$ and $\{ B_i : i < \kappa \} \subseteq \scrN^{s/t}$ be a cover of $2^\omega$.
		Then $h(B_i) \in \scrN^s$ by Fact \ref{fact:holderhaus}.
		Also $\bigcup_{i < \kappa} h(B_i) = A$.
		Therefore we have $\cov (\scrN^s(A)) \le \cov(\scrN^{s/t})$.
	\end{proof}

	\begin{prop}\label{prop:main}
		Let $0 < s < t < 1$.
		If $\cov(\scrN^t) = \cov(\Ibox^t)$, then $\cov(\scrN^t) \cdot \cov(\scrN^{s/t}) = \cov(\scrN^s)$.
	\end{prop}
	\begin{proof}
		Take $\seq{A_i : i < \kappa}$ of $\Ibox^t$-small sets covering $2^\omega$ with $\kappa = \cov(\scrN^t) = \cov(\Ibox^t)$.
		We can assume each $A_i$ is compact since the closure operator does not change the upper box counting dimension.
		For each $i < \kappa$, $A_i$ can be covered $\cov(\scrN^{s/t})$-many $\scrN^s$-small sets by Proposition \ref{prop:fraction}.
		Collecting these sets, we obtain the desired equality.
	\end{proof}

	\begin{thm}\label{thm:covering}
		If $\cov(\scrN^s) = \frakc$ holds for some $0 < s < 1$, then $\abs{\{ \cov(\scrN^s) : 0 < s < 1\}} = 1$. In particular $\frakc = \aleph_2$ implies the same conclusion.
	\end{thm}
	\begin{proof}
		Suppose $0 < s < t < 1$ and $\cov(\scrN^{t}) < \cov(\scrN^s)$ and suppose temporarily $t^2 \le s < t$ and we are heading toward contradiction.

		Since we assumed $\cov(\scrN^s) = \frakc$, we have $\cov(\scrN^t) = \cov(\Ibox^t)$.
		Thus by Proposition \ref{prop:main}, we have $\cov(\scrN^t)  \cov(\scrN^{s/t}) = \cov(\scrN^s)$.
		But the left hand side is equal to $\cov(\scrN^{\min\{t, s/t\}})$, which is equal to $\cov(\scrN^t)$ since $t^2 \le s$. It is a contradiction.


		We can remove the assumption $t^2 \le s$ by filling in with a finite number of points $s_0 < \dots < s_n$ with $s_{i+1}^2 \le s_i < s_{i+1}$ for $i < n$.

	\end{proof}


	\section{The result with uniformity numbers}

	By reformulating the results of the previous section in terms of relational systems, we prove the result regarding uniformity numbers.

	First we recall the basic definitions of relational systems.

	\begin{defi}
		\begin{enumerate}
			\item If $X$ and $Y$ are sets and $R$ is a relation between $X$ and $Y$, then we call a triple $(X, Y, R)$ a relational system.
			\item Let $\mathbf{R} = (X, Y, R)$ and  $\mathbf{R'} = (X', Y', R')$ be two relational systems.
			Tukey relation $\mathbf{R} \le_\mathrm{T} \mathbf{R'}$ holds if there is a function $\phi \colon X \to X'$ and $\psi \colon Y' \to Y$ such that $\phi(x) R' y$ implies $x R \psi(y)$ for every $x \in X$ and $y \in Y'$.
			\item For a relational system $\mathbf{R} = (X, Y, R)$ , $\frakd(\mathbf{R}) := \min \{ \abs{D} : (\forall x \in X)(\exists y \in D) (x R y)\}$ and $\frakb(\mathbf{R}) := \min \{ \abs{E} : (\forall y \in Y)(\exists x \in E) \neg (x R y) \}$.
		\end{enumerate}
	\end{defi}

	\begin{fact}[Theorem 4.9 of \cite{blass2010combinatorial}]
		If a Tukey relation $\mathbf{R} \le_\mathrm{T} \mathbf{R'}$ holds then $\frakd(\mathbf{R}) \le \frakd(\mathbf{R}')$ and $\frakb(\mathbf{R}') \le \frakb(\mathbf{R})$ hold.
	\end{fact}

	\begin{defi}
		For a set $X$ and a family $\scrI$ of subsets of $X$, we define a relational system $\Cov(\scrI)$ by $\Cov(\scrI) = (X, \scrI, \in)$.
	\end{defi}

	It is easy to see that $\frakd(\Cov(\scrI)) = \cov(\scrI)$ and $\frakb(\Cov(\scrI)) = \non(\scrI)$.

	\begin{defi}
		For two relational systems $\mathbf{R} = (X, Y, R)$ and  $\mathbf{R'} = (X', Y', R')$, we define their sequential composition $\mathbf{R};\mathbf{R'} = (X'', Y'', R'')$ by
		$X'' = X \times {X'}^{Y}$ and $Y'' = Y \times Y'$ and $(x, f) R'' (y, y')$ iff $x R y$ and $f(y) R' y'$.
	\end{defi}

	\begin{fact}[Theorem 4.11 of \cite{blass2010combinatorial}]
		For two relational systems $\mathbf{R} = (X, Y, R)$ and  $\mathbf{R'} = (X', Y', R')$, we have $\frakd(\mathbf{R};\mathbf{R'}) = \max\{\frakd(\mathbf{R}), \frakd(\mathbf{R}')\}$ and $\frakb(\mathbf{R};\mathbf{R'}) = \min\{\frakb(\mathbf{R}), \frakb(\mathbf{R}')\}$.
	\end{fact}


	\begin{defi}
		For a family of relational systems $\bar{\mathbf{R}} = (\mathbf{R}_i)_{i \in I} = (X_i, Y_i, R_i)_{i \in I}$, we define their product by
		$\prod_{i \in I} \mathbf{R}_i = (\prod_{i \in I} X_i, \prod_{i \in I} Y_i, R^{\times})$ where $\bar{x} R^\times \bar{y}$ iff $x(i) R_i y(i)$ for all $i \in I$.
	\end{defi}

	\begin{fact}[Fact 3.9 of \cite{CM25}]
		For a family of relational systems $\bar{\mathbf{R}} = (\mathbf{R}_i)_{i \in I}$, we have
		$\sup_{i \in I} \frakd(\mathbf{R}_i) \le \frakd(\prod_{i \in I} \mathbf{R}_i) \le \prod_{i \in I} \frakd(\mathbf{R}_i)$ and $ \frakb(\prod_{i \in I} \mathbf{R}_i) = \min_{i \in I} \frakb(\mathbf{R}_i)$.
	\end{fact}

	Now that we finished to recall notions of relational systems, we proceed to the proof.

	\begin{prop}
		Let $0 < s < t < 1$.
		For every $A \in \Ibox^t$, $\non(\scrN^s(A)) \ge \non(\scrN^{s/t})$.
	\end{prop}
	\begin{proof}
		Again, we may assume that $A$ is compact.
		Thus there is $(1 / t)$-Hölder onto map $f \colon 2^\omega \to A$.
		Take a map $g \colon A \to 2^\omega$ such that $f \circ g = \id_A$.
		If $B \subseteq A$ is not a $\scrN^s$-small set, then $g(B)$ is not a $\scrN^{s/t}$-small set by Fact \ref{fact:holderhaus}.
		Therefore we obtain the conclusion.
	\end{proof}


	\begin{prop}\label{prop:main2}
		Let $0 < s < t < 1$.
		If $\non(\scrN^t) = \non(\Ibox^t)$, then $\min \{ \non(\scrN^t), \non(\scrN^{s/t}) \} = \non(\scrN^s)$.
	\end{prop}
	\begin{proof}
		We construct a Tukey morphism from $\Cov(\scrN^s)$ to $\Cov(\Ibox^t) ; \prod_{A \in \Ibox^t \smallsetminus \{\varnothing\}} \Cov(\scrN^s(A))$.
		To this end, we have to construct $\phi_0 \colon 2^\omega \to 2^\omega$, $\phi_1 \colon 2^\omega \times \Ibox^t \to \prod_{A \in \Ibox^t \smallsetminus \{\varnothing\}} A$ and $\psi \colon \Ibox^t \times \prod_{A \in \Ibox^t \smallsetminus \{\varnothing\}} \scrN^s(A) \to \scrN^s$ satisfying $\phi_0(x) \in A$ and $\phi_1(x, A) \in^{\times} \bar{C}$ implies $x \in \psi(A, \bar{C})$ for all $x \in 2^\omega$, $A \in \Ibox^t$ and $\bar{C} \in \prod_{A \in \Ibox^t \smallsetminus \{\varnothing\}} \scrN^s(A)$.

		We put 
		\[\phi_0 = \id_{2^\omega},\]
		\[\phi_1(x, A)(B) = \begin{cases} x & (\text{if $A=B$}) \\ y_B & (\text{otherwise}) \end{cases},\]
		\[\psi(A, \bar{C}) = C(A), \]
		where $y_B$ is a fixed element of $B$.
		These maps satisfy the above conditions.
	\end{proof}


	\begin{thm}\label{thm:uniformity}
		If $\non(\scrN^s) = \aleph_1$ holds for some $0 < s < 1$, then $\abs{\{ \non(\scrN^s) : 0 < s < 1\}} = 1$. In particular $\frakc = \aleph_2$ implies the same conclusion.
	\end{thm}
	\begin{proof}
		The same argument of Theorem \ref{thm:covering}.
	\end{proof}

	\begin{cor}
		If $\frakc = \aleph_2$, then $\abs{\{ \cov(\scrN^s(\R^d)) : 0 < s < d, d \in \omega\}} = \abs{\{ \non(\scrN^s(\R^d)) : 0 < s < d, d \in \omega\}} = 1$.
	\end{cor}
	\begin{proof}
		This can be proved by the same argument of Section 2 of \cite{Got25}.
		The points are there is a $1$-Hölder map from $2^\omega$ to $[0, 1]$ and an $\alpha$-Hölder map from a subset of $[0, 1]$ to $2^\omega$ for every $\alpha < 1$.
	\end{proof}

	\section{Discussion}

	It remains unclear whether the same conclusion can be reached without  $\frakc = \aleph_2$.
	Zapletal has shown the following.

	\begin{fact}[Corollary 6.1.13 of \cite{Zap08}]
		Suppose that $\scrI$ is iterable, $\sigma$-ideal on a Polish space $X$ satisfying the second dichotomy.
		Suppose that $\mathfrak{x}$ is a tame invariant.
		Then $\mathfrak{x} < \cov^*(\scrI)$ is consistent with $\mathsf{ZFC}+\mathsf{LC}$ if and only if $\aleph_1 = \mathfrak{x} < \cov^*(\scrI) = \aleph_2$ is.
	\end{fact}

	$\cov(\scrN^t)$ is clearly a tame invariant.
	Elekes and Stepr\={a}ns showed $\cov(\scrN^s_{\sigma\text{-fin}}) = \cov(\scrN^s)$ (Lemma 3.1 of \cite{ES19}), where $\scrN^s_{\sigma\text{-fin}}$ is the ideal of sets of $\sigma$-finite $\Haus^s$-measure.
	Also Zapletal showed $\scrN^s_{\sigma\text{-fin}}$ is proper (see Theorem 4.4.2 and Proposition 4.4.9 of \cite{Zap08}).
	But as Elekes and Stepr\={a}ns showed, $\scrN^s_{\sigma\text{-fin}}$ is not homogeneous (Theorem 2.1 of \cite{ES19}). Thus there is a possibility that $\cov^*(\scrN^s_{\sigma\text{-fin}}) \ne \cov(\scrN^s_{\sigma\text{-fin}})$.

