\section{Intertemporal Portfolio Choice} \label{ipc}

\noindent Let $W_t>0$ denote the investor’s wealth at time~$t$ and 
\[
\mathbf h_t
  \;=\;
  \bigl(h_{1,t},h_{2,t},\dots,h_{n,t}\bigr)^{\!\top}
\]
\noindent collect the $n$ conditional variances generated by the
MHN--GARCH$(1,1)$ recursion in equations described in section~\ref{MHN-GARCH Process}. The portfolio--weight vector is
\[
\boldsymbol\pi_t
  \;=\;
  \bigl(\pi_{0,t},\pi_{1,t},\dots,\pi_{n,t}\bigr)^{\!\top},
\qquad
\pi_{0,t}=1-\sum_{i=1}^{n}\pi_{i,t},
\]
\noindent where $\pi_{i,t}$ is the share of wealth invested in risky asset~$i$
and $\pi_{0,t}$ in the risk‑free asset. Let $\mathbf r_{t+1}=(r_{1,t+1},\dots,r_{n,t+1})^{\!\top}$ be the
one‑period log returns. With continuous compounding,
\begin{equation}
  W_{t+1}
  \;=\;
  W_t\,
  \exp\!\bigl(r+\boldsymbol\pi_t^{\!\top}\mathbf r_{t+1}\bigr),
\end{equation}

\noindent where $r$ is the risk‑free rate. The investor has CRRA utility with coefficient $\gamma>0$,
\(
U(W)=\tfrac{W^{1-\gamma}}{1-\gamma}.
\)
The value function is defined as:

\begin{equation}
V_t(W_t,\mathbf h_t)
  \;=\;
  \max_{\{\boldsymbol\pi_\tau\}_{\tau=t}^{T-1}}
  \mathbb E_t\!\bigl[U(W_T)\bigr].
\end{equation}

\noindent By homotheticity, conjecture
\begin{equation}
  V_t(W_t,\mathbf h_t)
  \;=\;
  \frac{W_t^{1-\gamma}}{1-\gamma}\,
  \exp\!\Bigl(
      D_t+\sum_{i=1}^{n}E_{i-1,t}\,h_{i,t}
      \Bigr),
  \label{eq:V-form}
\end{equation}

\noindent with deterministic functions
$D_t,E_{0,t},\dots,E_{n-1,t}$. 
\noindent Substituting (\ref{eq:V-form}) into the Bellman equation yields
\begin{align}
&\max_{\boldsymbol\pi_t}
  \log
  \mathbb E_t\!\Bigl[
    \exp\bigl(
      (1-\gamma)\bigl[r+\boldsymbol\pi_t^{\!\top}\mathbf r_{t+1}\bigr]
      +D_{t+1}
      +\sum_{i=1}^{n}E_{i-1,t+1}\,h_{i,t+1}
    \bigr)
  \Bigr].
\end{align}

\noindent Conditional log‑normality implies the first‑order conditions

\begin{align}
\pi_{i,t}^{\star}
  &=
  \frac{\bigl(\tfrac12+\lambda_i h_{i,t}\bigr)
        \bigl[1-2\alpha_iE_{i,t+1}\bigr]
        -2\alpha_i\theta_iE_{i,t+1}}
       {1-2\alpha_iE_{i,t+1}-\gamma},
  \qquad i=2,\dots,n,\\[4pt]
\pi_{1,t}^{\star}
  &=
  \frac{\bigl(\tfrac12+\lambda_1 h_{1,t}\bigr)
        \bigl[1-2\alpha_1E_{0,t+1}\bigr]
        -2\alpha_1\theta_1E_{0,t+1}}
       {1-2\alpha_1E_{0,t+1}-\gamma}
  -\sum_{i=2}^{n}a_i\,\pi_{i,t}^{\star}.
\end{align}

\noindent Matching coefficients of $h_{i,t}$ and the constant in the Bellman equation gives

\begin{align}
E_{0,t}
 &= (\beta_1+\alpha_1\theta_1^{2})E_{0,t+1}
    +G_0\!\bigl(E_{t+1},\boldsymbol\pi_t^{\star}\bigr),\\[2pt]
E_{i,t}
 &= (\beta_i+\alpha_i\theta_i^{2})E_{i,t+1}
    +G_i\!\bigl(E_{t+1},\boldsymbol\pi_t^{\star}\bigr),
    \quad i=1,\dots,n-1,\\[2pt]
D_t
 &= D_{t+1}
    +\gamma r
    +\omega_1E_{0,t+1}
    +\sum_{i=1}^{n-1}\omega_{i+1}E_{i,t+1}
    -\tfrac12\sum_{i=0}^{n-1}
       \log\!\bigl[1-2\alpha_{i+1}E_{i,t+1}\bigr],
\end{align}

\noindent with terminal conditions $E_{i,T}=0$ and $D_T=0$. The auxiliary functions $G_i(\cdot)$ correspond to the closed‑form expressions implemented in backward recursion, proved in \citet{escobar2025}.

\noindent Given optimal weights $\boldsymbol\pi_t^{\star}$, wealth evolves as
\begin{equation}
  W_{t+1}
  \;=\;
  W_t\,
  \exp\!\bigl(r+\boldsymbol\pi_t^{\star\top}\mathbf r_{t+1}\bigr),
  \qquad
  W_0=1,
\end{equation}

\noindent producing the \emph{forward‐looking} path
$\{W_t\}_{t=0}^{T}$. In contrast to the time-varying allocation approach, we also compute the Merton constant variance benchmark to demonstrate the tractability of the time-varying optimal solution with the theory of intertemporal risk sharing in portfolio optimization. Assume $\mathbf r_{t+1}$ is i.i.d.\ with mean $\boldsymbol\mu$ and covariance $\Sigma$. The investor chooses a \emph{constant} weight vector $\boldsymbol\pi$ to maximize
$\mathbb E\bigl[U(W_T)\bigr].$ Since $
\log W_T
  = \log W_0
  +\sum_{t=0}^{T-1}
     \bigl[r+\boldsymbol\pi^{\!\top}\mathbf r_{t+1}\bigr],
$ the optimization can be simplified to
\begin{equation}
  \max_{\boldsymbol\pi}\;
  (1-\gamma)
  \bigl[
    r+\boldsymbol\pi^{\!\top}\boldsymbol\mu
    -\tfrac12\gamma\,\boldsymbol\pi^{\!\top}\Sigma\boldsymbol\pi
  \bigr].
\end{equation}

\noindent First‑order necessary conditions give
\begin{equation}
      \boldsymbol\pi^{\star}_{\text{M}}
      \;=\;
      \frac{1}{\gamma}\,\Sigma^{-1}\boldsymbol\mu
\end{equation}

Wealth then follows
\[
  W_{t+1}^{\text{M}}
  = W_t^{\text{M}}
    \exp\!\bigl(r+\boldsymbol\pi_{\text{M}}^{\!\top}\mathbf r_{t+1}\bigr),
  \qquad
  W_0^{\text{M}}=1.
\]

\bigskip
\noindent The MHN–GARCH optimal policy rule adapts in dynamically to shocks in
$\mathbf h_t$, capturing both idiosyncratic and
systemic volatility, whereas the Merton strategy is static and
therefore ignores the intertemporal hedging opportunities
created by time‑varying joint risk.

\section{Standardized Innovations} \label{innov}

\noindent In equations (1) to (3) in section~\ref{MHN-GARCH Process}, the standardized NIG innovations are given by:

\begin{align}
z_{n,t} &= \frac{X_{n,t} - \left[X_{n,t-1} + r + \lambda_{1,n}\, h_{1,t} + \lambda_n\, h_{n,t} + a_{n}\, \sqrt{h_{1,t}}\, z_{1,t}\right]}{\sqrt{h_{n,t}}},\;\;n=1,2,\dots,
\end{align}

\noindent where $X_{1,t}$ is the log-price process of the index and $X_{n,t}$ is the log-price process of asset $n$. Additionally, $r$ is the risk-free rate, $\lambda_{1}$ is the market-price of the index, $\lambda_{n}$ is the market-price of asset $n$, and $\lambda_{1,2}$ is the co-market price of risk identifying the joint risk of the bivariate trading pair. $a_{n}$ is the correlation driver parameter uniquely identifying the correlation of the asset $n$'s volatility with that of the index. $h_{1,t}$ is the conditional volatility of the index whereas $h_{n,t}$ is the conditional volatility of asset $n$.

