\coordinate (B) at (1, \d*0.5 + 0.5);
\coordinate (C) at (1, \d*\d*0.5+\d*0.5+1);
\coordinate (D) at (1, \d*\d*0.5 +\d*0.5+1.5);
\coordinate (H) at (2, 0);
