\coordinate (A) at (2*\d-1, \d-1);
\coordinate (B) at (\d, 2*\d);
\coordinate (C) at (\d-1, \d);
\coordinate (D) at (3, \d-1);
\coordinate (E) at (1, 2*\d-1);
\coordinate (F) at (1, \d);
\coordinate (G) at (1, \d-1);
