\coordinate (I) at (0, \d);
\coordinate (J) at (0, 0);

\foreach \p in {A, B, C, D, E, F, G, H, I, J} {
    \fill[blue] (\p) circle (2pt);
}

\draw[red, thick] (A) -- (B) -- (H) -- (J) -- cycle;

