\section{Appendix C: Code}

\subsection{Partition-Aware Transition Function}

\begin{definition}[Partition-Aware Global Transition Function]
Let \( \delta : Q \times \Sigma \to Q \) be the base transition function of the distributed system automaton. Define the partition-aware transition function as:
\[
\delta_P(q, \sigma, P_t) =
\begin{cases}
\delta(q, \sigma), & \text{if } \operatorname{Comm}(\sigma) \cap P_t = \emptyset \\
q, & \text{otherwise}
\end{cases}
\]
where \( \operatorname{Comm}(\sigma) \subseteq C \) is the set of communication links required for executing event \( \sigma \), and \( P_t \subseteq C \) is the set of inactive links at time \( t \).
\end{definition}

\subsection{Feasible Strategy Projection}

\begin{definition}[Local Feasibility Filter]
Let \( q_i^t \in Q_i \) denote the local state of node \( n_i \), and let \( \mathcal{F}_i^t \) denote its observable communication state at time \( t \). Define the feasible local action set as:
\[
A_i^{\text{feasible}}(q_i^t, \mathcal{F}_i^t) := \left\{ \sigma \in \Sigma_i \ \middle|\ 
\begin{array}{l}
\sigma \text{ is locally enabled in } q_i^t, \\
\text{and } \operatorname{Comm}(\sigma) \text{ is consistent with } \mathcal{F}_i^t
\end{array}
\right\}
\]
\end{definition}

\subsection{Audit and Escrow Enforcement}

\begin{definition}[Economic Penalty Mechanism]
Let \( g : S \to Q \) be the strategy-to-outcome function. Define the audit rule \( \mathcal{A} \) as a predicate over traces. For each node \( n_i \), define the penalty function \( \pi_i : S_i \times Q \to \mathbb{R}_{\geq 0} \) such that:
\[
\pi_i(s_i, q) =
\begin{cases}
\lambda_i, & \text{if } \neg \mathcal{A}(s_i, q) \\
0, & \text{otherwise}
\end{cases}
\]
Escrow loss \( e_i \) is triggered if \( \pi_i(s_i, q) > 0 \). The total utility becomes:
\[
U_i = R_i - C_i - \pi_i(s_i, q) - e_i
\]
\end{definition}


\section{Appendix D: Merkle Commitment Logic}

\subsection{Merkle Tree Construction}

Let \( \mathcal{L} = [d_1, d_2, \dots, d_n] \) be an ordered list of data items. Define the Merkle tree \( \mathcal{M} \) recursively:

\begin{itemize}
  \item Each leaf node \( l_i \) is \( h(d_i) \), where \( h \) is a collision-resistant hash function.
  \item Each internal node is the hash of the concatenation of its children: if \( a, b \) are children, then the parent node is \( h(a \, \| \, b) \).
  \item The Merkle root \( r \) is the single value at the top of the tree.
\end{itemize}

\subsection{Merkle Proof Verification}

To verify that a data item \( d_i \) is included in a committed set with Merkle root \( r \), construct a proof \( \pi_i = [s_1, s_2, \dots, s_k] \) such that:

\[
r = h(\dots h(h(h(d_i) \, \| \, s_1) \, \| \, s_2) \dots \| \, s_k)
\]

Each \( s_j \) is a sibling hash along the path to the root, and ordering is preserved.

\subsection{Commitment Logic Semantics}

Let \( q \in Q \) be a state, and \( \operatorname{commit}(q) = r \) the Merkle root of the system state. Define the verification predicate:

\[
\operatorname{Verify}(d_i, \pi_i, r) := \text{True} \iff \text{MerklePath}(d_i, \pi_i) = r
\]

This ensures that any participant can independently validate state inclusion without access to the full state.

\subsection{Merkle Commitments in Transition}

If \( q \xrightarrow{\sigma} q' \), then:

\[
\operatorname{commit}(q') = h\left( \dots h\left( h(h(d_i') \, \| \, s_1') \, \| \, s_2' \right) \dots \right)
\]

and verification of \( \sigma \)'s effect requires recomputing only the affected branch and comparing the resulting root.

\subsection{Merkle-Based State Agreement}

A system achieves consistent replicated state if all honest nodes hold:

\[
\operatorname{commit}(q_1) = \operatorname{commit}(q_2) = \dots = \operatorname{commit}(q_k)
\]

Consensus over Merkle roots ensures strong convergence without full state transmission.



