\section{Notation and results}\label{S:results}

Given $1<p<\infty$ and $\alpha>0$, we write $H^\alpha_p(\mathbb{R}^n)$ for the \emph{fractional Sobolev space} (or \emph{Bessel potential space}) consisting of all $u\in L^p(\mathbb{R}^n)$ such that $((1+|\cdot|^2)^{\alpha/2} \hat u)^\vee \in L^p(\mathbb{R}^n)$; here $\varphi\mapsto \hat{\varphi}$ denotes the Fourier transform acting on tempered distributions and $\varphi\mapsto \check{\varphi}$ its inverse. Normed by 
\[\|u\|_{H^\alpha_p(\mathbb{R}^n)}:=\|((1+|\cdot|^2)^{\alpha/2} \hat u)^\vee\|_{L^p(\mathbb{R}^n)}\]
the spaces $H^\alpha_p(\mathbb{R}^n)$ are Banach spaces, for $p=2$ Hilbert. Given an open set $\Omega\subset \mathbb{R}^n$, we write $C_c^\infty(\Omega)$ for the space of all smooth functions with compact support in $\Omega$.

Given a compact set $K\subset\mathbb{R}^n$, its \emph{$(\alpha,p)$-capacity} is 
\[\cpct_{\alpha,p}(K):=\inf\big\lbrace  \|u\|_{H^\alpha_p(\mathbb{R}^n)}^p:\ u\in C_c^\infty(\mathbb{R}^n),\ u\geq 1\ \text{on $K$}\big\rbrace.\]
For open $G\subset\mathbb{R}^n$ we define $\cpct_{\alpha,p}(G):=\sup_K\cpct_{\alpha,p}(K)$, the supremum ranging over all compact $K\subset G$. For general Borel sets $E\subset \mathbb{R}^n$ we can consistently define $\cpct_{\alpha,p}(E):=\inf_G\cpct_{\alpha,p}(G)$ with the infimum taken over all open $G\supset E$. Background can be found in \cite[Section 2.2]{AH96}, a discussion of different notations and the equivalence of different definitions for $\cpct_{\alpha,p}$ in \cite[Remark 3.2]{HM2017}. A property which holds outside a set of zero $(\alpha,p)$-capacity is said to hold \emph{$(\alpha,p)$-quasi everywhere} or, for short, \emph{$(\alpha,p)$-q.e.} For $\alpha>\frac{n}{p}$ we have $H^\alpha_p(\mathbb{R}^n)\subset C(\mathbb{R}^n)$ by the Sobolev embedding theorem and, as a consequence, any nonempty set has positive $(\alpha,p)$-capacity, so that a property which holds $(\alpha,p)$-q.e.\ holds everywhere.

An extended real-valued function $v$ defined $(\alpha,p)$-q.e.\ on $\mathbb{R}^n$ is called \emph{$(\alpha,p)$-quasi continuous} if for any $\varepsilon>0$ there is an open set $G\subset\mathbb{R}^n$ with $\cpct_{\alpha,p}(G)<\varepsilon$ outside of which $v$ is continuous. For every $u\in H^\alpha_p(\mathbb{R}^n)$ we can find an $(\alpha,p)$-quasi continuous representative $\widetilde{u}$, that is, an $(\alpha,p)$-quasi continuous Borel function on $\mathbb{R}^n$ such that $\widetilde{u}=u$ $\mathcal{L}^n$-a.e. Here and below $\mathcal{L}^n$ denotes $n$-dimensional Lebesgue measure. Two $(\alpha,p)$-quasi continuous representatives $\widetilde{u}$ of $u \in H^\alpha_p(\mathbb{R}^n)$ can differ only on a set of zero $(\alpha,p)$-capacity. See \cite[Proposition 6.1.2 and Theorem 6.1.4]{AH96} for these properties. For $\alpha>\frac{n}{p}$ an $(\alpha,p)$-quasi continuous function is continuous, so that there is exactly one $(\alpha,p)$-quasi continuous representative $\widetilde{u}$ of $u\in H_p^\alpha(\mathbb{R}^n)$, and $\tilde u$ is continuous.



We call a non-decreasing and right-continuous function $h:[0,1)\to [0,\infty)$ a \emph{Hausdorff function} if $h(0)=0$, $h$ is strictly positive on $(0,1)$, and for some $c>1$ we have $h(2r)\leq c\,h(r)$, $0<r<\frac12$. We write $\mathcal{H}^h$ for the \emph{Hausdorff measure associated with $h$} \cite{AH96, Mazya85,Zaehle}. If $0\leq d\leq n$ and $h(r)=r^d$, $0\leq r<1$, then we write $\mathcal{H}^d$; this is \emph{$d$-dimensional Hausdorff measure}.


Let $\mu$ be a Radon measure \cite[Definition 1.5]{Mattila} on $\mathbb{R}^n$ and let $x\in\mathbb{R}^n$. Given a Hausdorff function $h$, the \emph{upper $h$-density of $\mu$ at $x$} is defined as
\[\bar{D}^h\mu(x):=\limsup_{r\to 0}\frac{\mu(B(x,r))}{h(r)}.\]
If $0\leq d\leq n$ and $h(r)=r^d$, $0\leq r<1$, then $\bar{D}^h\mu(x)$ is  called the \emph{upper $d$-density of $\mu$ at} $x$ and is denoted by $\bar{D}^d\mu(x)$. See \cite[Definition 6.8]{Mattila} and \cite[Definition 3.1]{Zaehle}. We also consider the locally uniform variant
\begin{equation}\label{E:uniform}
\bar{\mathbb{D}}^h\mu(x):=\lim_{r\to 0} \sup_{y\in B(x,r),\ 0<\varrho\leq r}\frac{\mu(B(y,\varrho))}{h(\varrho)},
\end{equation}
and write $\bar{\mathbb{D}}^d\mu(x)$ if $h(r)=r^d$, $0\leq r<1$. By the monotonicity in $r$ of the supremum the limit in \eqref{E:uniform} always exists. Obviously $\bar{D}^h\mu(x)\leq \bar{\mathbb{D}}^h\mu(x)$.

\begin{examples}\label{Ex:hybrid} Let $\Gamma_1\subset \mathbb{R}^2$ be the classical Koch curve \cite{Falconer97}, located so that it has starting point $(-1,0)$ and endpoint $(0,0)$, and let $\mu_1=\mathcal{H}^{d}|_{\Gamma_1}$ with $d=\frac{\log 4}{\log 3}$. Let $\Gamma_2=[0,1]\times \{0\}$, endowed with $\mu_2=\mathcal{H}^1|_{\Gamma_2}$. If
\[d(x)=\begin{cases} d & \text{for $x\in \Gamma_1\setminus \{(0,0)\}$,} \\ 1 & \text{for $x\in \Gamma_2$,}\end{cases}\]
and $\mu:=\mu_1+\mu_2$, then $0<\bar{D}^{d(x)}\mu(x)\leq \bar{\mathbb{D}}^{d(x)}\mu(x)<\infty$ for all $x\in \Gamma:= \Gamma_1\cup\Gamma_2=\supp{\mu}$.
\end{examples}

\begin{examples}\label{Ex:hybrid2}
Let $\Gamma_1=\overline{B(0,2)}\subset \mathbb{R}^2$, endowed with $\mu_1=\mathcal{L}^2|_{\Gamma_1}$, and $\Gamma_2=[-1,1]\times \{0\}$, endowed with $\mu_2=\mathcal{H}^1|_{\Gamma_2}$. If 
\[d(x)=\begin{cases} 2 & \text{for $x\in \Gamma_1\setminus \Gamma_2$,} \\ 1 & \text{for $x\in \Gamma_2$,}\end{cases}\]
and $\mu:=\mu_1+\mu_2$, then $0<\bar{D}^{d(x)}\mu(x)\leq \bar{\mathbb{D}}^{d(x)}\mu(x)<\infty$ for all $x\in \Gamma:=\Gamma_1\cup\Gamma_2=\supp{\mu}$.
\end{examples}

Our main result is the following.

\begin{theorem}\label{T:main}
Let $\mu$ be a non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and $1<p<\infty$. Suppose that $0<\alpha\leq \frac{n}{p}$ and that $d:\Gamma\to [0,\infty)$ is a Borel function such that 
\begin{equation}\label{E:traceconddx}
n-\alpha p<\inf_{x\in \Gamma}d(x),
\end{equation}
\begin{equation}\label{E:upperdensdx}
\bar{\mathbb{D}}^{d(x)}\mu(x)<\infty,\quad x\in\Gamma,
\end{equation}
 and 
\begin{equation}\label{E:suffconddx}
\cpct_{\alpha,p}(S_{d,\mu}(\Gamma))=0,
\end{equation}
where 
\begin{equation}\label{E:Sd}
S_{d,\mu}(\Gamma) := \{x\in\Gamma:\ \bar{D}^{d(x)}\mu(x)=0\}.
\end{equation}  
Then the equivalence \eqref{E:wish} holds for any $u\in H^\alpha_p(\mathbb{R}^n)$. 
\end{theorem}


\begin{remark}\label{R:trivial}
For convenience we require that $\alpha\leq \frac{n}{p}$ in our statement of Theorem \ref{T:main}. But, as noted above, if $\alpha>\frac{n}{p}$ then for any  $u\in H^\alpha_p(\mathbb{R}^n)$ the (unique) $(\alpha,p)$-quasi continuous representative $\widetilde{u}$ is continuous, so that \eqref{E:wish} holds trivially in that case.
\end{remark}

\begin{remark}\label{R:upregd} Let $\mu$ be a non-zero Radon measure on $\mathbb{R}^n$ and $\Gamma=\supp\mu$ and let $d:\Gamma\to [0,+\infty)$ be a Borel function.
\begin{enumerate}
\item[(i)] Condition \eqref{E:upperdensdx} on $d$ and $\mu$ implies that for each $x\in \Gamma$ there is some $r(x)>0$ such that for all $y\in B(x,r(x))$ and $0<\varrho\leq r(x)$ we have 
\begin{equation}\label{E:upregdx}
\mu(B(y,\varrho))\leq c(x)\varrho^{d(x)}, 
\end{equation}
where $c(x)=\max\{2\:\bar{\mathbb{D}}^{d(x)}\mu(x),1\}$. Together with \cite[Theorem 6.9]{Mattila} this implies that
\[d(x)\leq \dim_H(B(x,r(x))\cap \Gamma)\leq \dim_H\Gamma\leq n,\quad x\in \Gamma.\]
If the set $\Gamma$ is compact, then it admits a finite cover $\{B(x_i,r(x_i))\}_{i=1}^N$ by open balls with $x_i\in \Gamma$, $i=1,...,N$. In this situation $\mu$ is \emph{upper $\underline{d}:=\min_i d(x_i)$-regular}, i.e., for some $\underline{c}>0$ and $\underline{r}>0$ we have 
\[\mu(B(y,\varrho))\leq \underline{c}\,\varrho^{\underline{d}}\]
for all $y\in\Gamma$ and $0<\varrho\leq \underline{r}$. In fact this works with $\underline{c}:=\max_i c(x_i)$ and $\underline{r}:=\min_i r(x_i)$. 
\item[(ii)] Recall \eqref{E:Sd}. Since $\overline{D}^{d(x)}\mu(x)>0$ for all $x\in \Gamma\setminus S_{d,\mu}(\Gamma)$, we have $\overline{D}^s\mu(x)=\infty$ for all $x\in  \Gamma\setminus S_{d,\mu}(\Gamma)$ and $s>\sup_{x\in \Gamma\setminus S_{d,\mu}(\Gamma)}d(x)$. By \cite[Theorem 6.9]{Mattila} it follows that for any open ball $B$ we have $\mathcal{H}^s(B\cap \Gamma\setminus S_{d,\mu}(\Gamma))=0$, which implies that $\mathcal{H}^s(\Gamma \setminus S_{d,\mu}(\Gamma))=0$. Therefore 
\[\dim_H(\Gamma\setminus S_{d,\mu}(\Gamma))\leq \sup_{x\in \Gamma\setminus S_{d,\mu}(\Gamma)}d(x).\]
\item[(iii)] Suppose that \eqref{E:upperdensdx} holds and, for $x\in \Gamma$, let $r(x)$ be as in \eqref{E:upregdx}. For each $y\in \Gamma\cap B(x,r(x))\setminus S_{d,\mu}(\Gamma)$ there is a sequence $(\varrho_k)$ with $\varrho_k\downarrow 0$ as $k\to\infty$ such that $\mu(B(y,\rho_k))\geq \frac12 \bar{D}^{d(y)}\mu(y)\varrho_k^{d(y)}>0$. Together with \eqref{E:upregdx} this implies that $d(y)\geq d(x)$ for such $x$ and $y$. In particular, $d$ is lower semicontinuous on $\Gamma\setminus S_{d,\mu}(\Gamma)$.

\item[(iv)] One refers to the quantity
\[\underline{\dim}\,\mu(x):=\liminf_{r\to 0}\frac{\log \mu(B(x,r))}{\log r}\]
as the \emph{lower pointwise dimension of $\mu$ at $x$} \cite{Falconer97, Zaehle}. It is well known that $\bar{D}^{d(x)}\mu(x)<\infty$ implies $d(x)\leq \underline{\dim}\,\mu(x)$, while $0<\bar{D}^{d(x)}\mu(x)$ implies  $\underline{\dim}\,\mu(x)\leq d(x)$ \cite[Section 6.1]{Zaehle}. Therefore, if \eqref{E:upperdensdx} holds, then $d(x)= \underline{\dim}\,\mu(x)$ on $\Gamma\setminus S_{d,\mu}(\Gamma)$.
\item[(v)] In the case $\alpha=\frac{n}{p}$ %the statement of 
Theorem \ref{T:main} remains true with the weaker condition $\cpct_{\alpha,p}(\{x\in\Gamma:\underline{\dim}\,\mu(x)> d(x) \})=0$ in place of \eqref{E:suffconddx}; this is immediate from the proof of Lemma \ref{L:lessthanone} below.

\item[(vi)] If $0<\alpha\leq \frac{n}{p}$ and \eqref{E:traceconddx} and \eqref{E:upperdensdx} are assumed, then condition \eqref{E:suffconddx} implies that
\begin{equation}\label{E:notquite}
\mu(S_{d,\mu}(\Gamma))=0,
\end{equation}
cf. Lemma \ref{L:smooth} below. The converse implication is false. To see this, suppose that $d(\cdot)\equiv n=2$ is constant, $p=2$ and $\alpha=1$. Let $\Gamma=[0,1]^2$ and let $S\subset [0,1]^2$ be such that $\mathcal{L}^2(S)=0$ but  $\cpct_{1,2}(S)>0$.
Let $\varphi:[0,1]^2\to [0,\infty)$ be a continuous function with zero set $S$. Then the measure $\mu=\varphi\cdot\mathcal{L}^2|_{[0,1]^2}$ has support $\Gamma=[0,1]^2$, and we have $c^{-1}\varphi(x)\leq \bar{D}^2\mu(x)\leq c\:\varphi(x)$, $x\in [0,1]^2$, for some constant $c>1$. In this situation we have $\mu(\{\varphi=0\})=0$, which is \eqref{E:notquite}, but \eqref{E:suffconddx} does not hold. As one example we may choose $S=[0,1]\times \{0\}$ and $\varphi(x)=x_2$, $x=(x_1,x_2)\in [0,1]^2$.
\end{enumerate}
\end{remark}

The case of a constant function $d(\cdot)\equiv d$ is an important special case. If $0<d\leq n$ is constant and 
\begin{equation} \label{E:dset}
c^{-1}r^d\leq \mu(B(x,r))\leq cr^d, \quad 
x\in \Gamma=\supp \mu, \quad 0<r\leq 1,
\end{equation} 
where $c>1$ is a fixed constant, then $\mu$ is called a \emph{$d$-measure} and $\Gamma$ is called a \emph{$d$-set}. See \cite[Section II.1]{JW84} or \cite[Definition 3.1]{Triebel97}. In this case $\dim_H\Gamma=d$.

\begin{remark}\label{R:main}\mbox{}
\begin{enumerate}
\item[(i)] If $\Gamma$ is a $d$-set, then \eqref{E:dset} holds (for some possibly different $c>1$) with $\mu$ replaced by $\cH^d|_\Gamma$, see \cite[Theorem 3.4]{Triebel97}. For our calculations below we note that, if the second of the inequalities in \eqref{E:dset} holds for $x\in \Gamma$ and $0<r\leq 1$, then, by a simple triangle inequality argument, also  $\mu(B(x,r))\leq c\:2^dr^d$ for all $x\in \R^n$ and $0<r\leq \frac{1}{2}$.  
\item[(ii)] If $\mu$ is a $d$-measure and \eqref{E:dset} holds, then $\mu$ satisfies the doubling condition $\mu(B(x,2r))\leq c^22^d\mu(B(x,r))$, $x\in\Gamma$, $0<r\leq \frac12$. Theorem \ref{T:main} applies to certain measures for which no  doubling condition holds, such as the measures in Examples \ref{Ex:hybrid}, \ref{Ex:hybrid2} and in Corollary \ref{C:dset} below.
\end{enumerate}
\end{remark}

The following is a consequence of Theorem \ref{T:main}. Item (i) adresses the special case of $d$-measures $\mu$ and resulting $d$-sets $\Gamma$. Item (ii) includes item (i) as a special case and generalizes Examples \ref{Ex:hybrid} and \ref{Ex:hybrid2}. 

\begin{corollary}\label{C:dset}
Let $1<p<\infty$ and $0<\alpha\leq \frac{n}{p}$. 
\begin{enumerate}
\item[(i)] If $n-\alpha p<d\leq n$, $\mu$ is a $d$-measure and $\Gamma=\supp \mu$, then $\mu$ and $d$ satisfy the conditions \eqref{E:traceconddx}, \eqref{E:upperdensdx} and \eqref{E:suffconddx} of Theorem \ref{T:main} with $S_{d,\mu}(\Gamma)=\emptyset$, so that the equivalence \eqref{E:wish} holds for any $u\in H^\alpha_p(\mathbb{R}^n)$. 
\item[(ii)] Suppose that $J$ is a positive integer, and, for $j=1,\ldots, J$, that  $n-\alpha p <d_j\leq n$, $a_j>0$,  and $\Gamma_j\subset \R^n$ is a $d_j$-set. Let
$$
\mu := \sum_{j=1}^J a_j\cH^{d_j}|_{\Gamma_j}, \qquad \Gamma := \bigcup_{j=1}^J \Gamma_j = \supp \mu,
$$ 
and, for $x\in \Gamma$, let $I(x):= \{j\in \{1,\ldots,J\}:x\in \Gamma_j\}$ and $d(x):= \min\{d_j:j\in I(x)\}$. Then $\mu$ and $d$ satisfy the conditions \eqref{E:traceconddx}, \eqref{E:upperdensdx} and \eqref{E:suffconddx} of Theorem \ref{T:main} with $S_{d,\mu}(\Gamma)=\emptyset$, so that the equivalence \eqref{E:wish} holds for any $u\in H^\alpha_p(\mathbb{R}^n)$. 
\end{enumerate}
\end{corollary}


\begin{proof} To see (i) it sufficies to note that \eqref{E:dset} implies $c^{-1}\leq \bar{D}^d\mu(x)\leq \bar{\mathbb{D}}^d\mu(x)\leq c$ for all $x\in\Gamma$. We prove item (ii). Clearly $d$ is a Borel function, with $\inf_{x\in \Gamma}d(x)=\min\{d_1,\ldots,d_J\}>n-\alpha p$.  As noted in Remark \ref{R:main} (ii), since each $\Gamma_j$ is a $d_j$-set,  equation \eqref{E:dset} holds for some $c>1$ with $d$, $\Gamma$, and $\mu$ replaced by $d_j$, $\Gamma_j$, and $\cH^{d_j}|_{\Gamma_j}$, respectively, for $j=1,\ldots, J$, indeed, if $0<r\leq 1/2$, the right hand inequality in \eqref{E:dset} holds for all $x\in \R^n$ and all $j=1,...,N$ if $c$ is replaced by $c2^d$. Thus,
 for $x\in \Gamma$, where $\mu_j:= a_j\cH^{d_j}|_{\Gamma_j}$,
$$
\bar{\mathbb{D}}^{d(x)}\mu(x) \leq  \sum_{j=1}^J \bar{\mathbb{D}}^{d_j}\mu_j(x)  \leq  c2^d\sum_{j=1}^J a_j.
$$
Similarly, where $\underline{a}:=\min\{a_1,\ldots,a_J\}$, 
$\bar{D}^{d(x)}\mu(x) \geq c^{-1}\underline{a}$, for $x\in \Gamma$, since $I(x)\neq \emptyset$ for every $x\in \Gamma$.
\end{proof}

\begin{remark}\label{R:main2}
If $0<d<n$, $\frac{n-d}{p}<\alpha<\frac{n-d}{p}+1$, $\mu$ is a $d$-measure and $\Gamma=\supp \mu$, then the validity of \eqref{E:wish} for any $u\in H^\alpha_p(\mathbb{R}^n)$ also follows from an application of \cite[Proposition 6.7]{CHM21} in the special case of fractional Sobolev spaces, together with \cite[Corollary 10.1.2]{AH96}. The results provided in \cite[Section 6]{CHM21} are for both fractional Sobolev spaces and Besov spaces. If $p=2$ and $\alpha=\frac{n-d}{2}$, then \eqref{E:wish} follows from \cite[Corollary 18.12]{Triebel97} together with \cite[Remark 3.5 (i) and Proposition 4.3]{Caetano2002}. 
\end{remark}
%The additional upper bound on $\alpha$ in \cite[Proposition 6.7]{CHM21} ensures the applicability of an extension theorem \cite[Chapter VII, Theorem 1]{JW84}.

We state a logarithmic refinement of Theorem \ref{T:main} for the case $\alpha=\frac{n}{p}$. Note that for each $\kappa>0$ the function $h_\kappa(r)=(-\log r)^{-\kappa}$ is a Hausdorff function.

\begin{theorem}\label{T:main_logcase}
Let $\mu$ be a non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and $1<p<\infty$. Suppose that $\alpha=\frac{n}{p}$ and that $\kappa:\Gamma\to  [0,\infty)$ is a Borel function such that
\begin{equation}\label{E:tracecondhx}
p-1<\inf_{x\in \Gamma}\kappa(x).
\end{equation}
Suppose in addition that 
\begin{equation}\label{E:upperdenshx}
\bar{\mathbb{D}}^{h_{\kappa(x)}}\mu(x)<\infty,\quad x\in\Gamma,
\end{equation}
and 
\begin{equation}\label{E:suffcondh}
\cpct_{\alpha,p}(\{x\in\Gamma:\ \bar{D}^{h_{\kappa(x)}}\mu(x)=0\})=0.
\end{equation}
Then \eqref{E:wish} holds for any $u\in H^\alpha_p(\mathbb{R}^n)$.
\end{theorem}

\begin{remark}\label{R:upreghx} 
Under condition \eqref{E:upperdenshx} there is some $r(x)>0$ such that for all $y\in B(x,r(x))$ and $0<\varrho<r(x)$ we have 
\begin{equation}\label{E:upreghx}
\mu(B(y,\varrho))\leq c(x)h_{\kappa(x)}(\varrho), 
\end{equation}
where $c(x)=\max\{2\bar{\mathbb{D}}^{h_{\kappa(x)}}\mu(x),1\}$. If $\Gamma$ is compact, then $\mu(B(y,\varrho))\leq \underline{c}h_{\underline{\kappa}}(\varrho)$ for all $y\in\Gamma$ and $0<\varrho<\underline{r}$, where $\underline{\kappa}:=\min_i\kappa(x_i)$, and $\underline{c}$, $\underline{r}$ and $x_i$ are defined as in Remark \ref{R:upregd} (i).
\end{remark}


A well known statement ensures that under the assumptions of Theorems \ref{T:main} and \ref{T:main_logcase} any Borel set of zero capacity is a $\mu$-null set. 

\begin{lemma}\label{L:smooth}
Let $\mu$ be a  non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and $1<p<\infty$. If
\begin{enumerate}
\item[(i)] $0<\alpha\leq \frac{n}{p}$ and $d:\Gamma\to [0,\infty)$ is a Borel function such that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold or
\item[(ii)] $\alpha=\frac{n}{p}$ and $\kappa:\Gamma\to  [0,\infty)$ is a Borel function such that \eqref{E:tracecondhx} and \eqref{E:upperdenshx} hold,
\end{enumerate}
then, for all Borel sets $E\in \mathbb{R}^n$ with $\cpct_{\alpha,p}(E)=0$, we have $\mu(E)=0$.
\end{lemma}

For convenience we briefly state the standard arguments. Recall that $p'$ denotes the conjugate of $p$.
\begin{proof}
By \eqref{E:traceconddx} there is a number $n-\alpha p<d_0<\inf_{x\in \Gamma}d(x)$, and by \eqref{E:upperdensdx} we have $\overline{D}^{d_0}\mu(x)=0$, $x\in \Gamma$. Similarly, by \eqref{E:tracecondhx} we can find a number $p-1<\kappa_0<\inf_{x\in\Gamma}\kappa(x)$, and \eqref{E:upperdenshx} gives  $\overline{D}^{h_{\kappa_0}}\mu(x)=0$, $x\in \Gamma$. If $\cpct_{\alpha,p}(E)=0$, then by \cite[Theorem 5.1.13 and the Remark following it]{AH96} we have $\mathcal{H}^{d_0}(E)=0$, respectively $\mathcal{H}^{h_{\kappa_0}}(E)=0$, noting that $\int_0^1 h_{\kappa_0}(r)^{p'-1}\frac{dr}{r}<\infty$. If $\varepsilon>0$ and $G\supset E$ is an open set such that $\mathcal{H}^{d_0}(G)<\varepsilon$, respectively $\mathcal{H}^{h_{\kappa_0}}(G)<\varepsilon$, then $\mu(G)=0$ by \cite[Theorem 6.9]{Mattila} or \cite[Theorem 3.7]{Zaehle}.
\end{proof}

%\begin{remark}\mbox{}
%\begin{enumerate}
%\item[(i)] If the lemma is stated only for Borel sets $E$ of zero $(\alpha,p)$-capacity, the use of $\mathcal{B}(\mathbb{R}^n)^\mu$ can be avoided. 
%\item[(ii)] It is known that any set of $(\alpha,p)$-capacity zero is contained in a Borel set of $(\alpha,p)$-capacity zero, see for instance \cite[Proposition 2.3.7]{AH96}.
%\end{enumerate}
%\end{remark}

It is well known that any set of $(\alpha,p)$-capacity zero is contained in a Borel set of $(\alpha,p)$-capacity zero, see for instance \cite[Proposition 2.3.7]{AH96}. We therefore see that if the hypotheses of Lemma \ref{L:smooth} are satisfied, then for any $u\in H^\alpha_p(\mathbb{R}^n)$ the condition $\widetilde{u}=0$ q.e.\ on $\Gamma$ implies that  $\widetilde{u}=0$ on $\Gamma\setminus N$, where $N$ is a Borel set with $\mu(N)=0$. This gives one implication in \eqref{E:wish}. We will prove the converse implication under the additional assumption \eqref{E:suffconddx}, respectively \eqref{E:suffcondh}. The proof uses some further ideas and will be given in Sections \ref{S:iso} and \ref{S:proof}. Without any additional assumption the validity of this converse implication cannot be expected, as the following counterexample from \cite{FOT2011} shows.

\begin{remark}\label{R:counter}
Recall that a set $E\subset \mathbb{R}^n$ is called \emph{$(\alpha,p)$-quasi open} if for any $\varepsilon>0$ there is an open set $G\supset E$ such that $\cpct_{\alpha,p}(G\setminus E)<\varepsilon$. A set $E\subset \mathbb{R}^n$ is called \emph{$(\alpha,p)$-quasi closed} if its complement is $(\alpha,p)$-quasi open. If the symmetric difference $E_1\Delta E_2$ of two sets $E_1\subset \mathbb{R}^n$ and $E_2\subset \mathbb{R}^n$ has zero $(\alpha,p)$-capacity, then $E_1$ and $E_2$ are said to be \emph{$(\alpha,p)$-equivalent}, cf. \cite[p. 176]{AH96}.

In the special case $p=2$ and $0<\alpha\leq 1$ the scalar product associated with $\|\cdot\|_{H^\alpha_2(\mathbb{R}^n)}$ is a Dirichlet form \cite{FOT2011}. Suppose that we are in this Dirichlet form case and that $\mu$ is a  non-zero Radon measure such that $\mu(E)=0$ for any set of zero $(\alpha,2)$-capacity. A set $\widetilde{\Gamma}\subset \mathbb{R}^n$ is said to be a \emph{quasi support} for $\mu$ if (a) $\widetilde{\Gamma}$ is $(\alpha,2)$-quasi closed and $\mu(\mathbb{R}^n\setminus \widetilde{\Gamma})=0$, and (b) for any other set $\check{\Gamma}\subset \mathbb{R}^n$ satisfying (a) we have $\cpct_{\alpha,2}(\widetilde{\Gamma}\setminus \check{\Gamma})=0$. See \cite[p. 841]{FukushimaLeJan} or \cite[p. 190]{FOT2011}. In \cite[Theorem 3.3.(i)]{FukushimaLeJan} it was proved that any $\mu$ as specified admits a quasi support, see also \cite[Theorem 4.6.3]{FOT2011}. This quasi support is uniquely determined up to $(\alpha,2)$-equivalence. In \cite[Theorem 3.3.(ii)]{FukushimaLeJan} it was shown that for an $(\alpha,2)$-quasi closed set $\widetilde{\Gamma}\subset \mathbb{R}^n$ the property of being a quasi support for $\mu$ is equivalent to the property that for any $u\in H^\alpha_2(\mathbb{R}^n)$ we have $\widetilde{u}=0$ $\mu$-a.e.\ on $\widetilde{\Gamma}$ if and only if $\widetilde{u}=0$ $(\alpha,2)$-q.e.\ on $\widetilde{\Gamma}$. See also \cite[Theorem 4.6.2]{FOT2011}. Since any closed set is $(\alpha,2)$-quasi closed, condition \eqref{E:wish} is equivalent to saying that the support $\Gamma$ of $\mu$ is a quasi support for $\mu$.

An example of a  non-zero Radon measure $\mu$ on $\mathbb{R}^n$, $n\geq 3$, charging no set of zero $(1,2)$-capacity and having support $\Gamma=\mathbb{R}^n$ and a quasi support $\widetilde{\Gamma}\subset \mathbb{R}^n$ such that $\cpct_{1,2}(\Gamma\setminus \widetilde{\Gamma})>0$ was given in \cite[Examples 5.1.2, p. 240]{FOT2011}. Together with the preceding this is a counterexample for \eqref{E:wish} in the case $p=2$ and $\alpha=1$. The measure $\mu$ in \cite[Examples 5.1.2]{FOT2011} has  an $\mathcal{L}^n$-a.e.\ bounded density with respect to $\mathcal{L}^n$ and therefore satisfies \eqref{E:traceconddx} and \eqref{E:upperdensdx} with $d\equiv n$. Since $\mu(\Gamma\setminus \widetilde{\Gamma})=0$ we have $\bar{D}^n\mu(x)=0$ at $\mathcal{L}^n$-a.e.\ $x\in \Gamma\setminus \widetilde{\Gamma}$ \cite[Theorem 2.12]{Mattila}. 
The proof that $\Gamma\setminus \widetilde{\Gamma}$ has positive $(1,2)$-capacity proceeds by showing that $\mathcal{L}^n(\Gamma\setminus \widetilde{\Gamma})>0$. Consequently $\cpct_{1,2}(\{x\in \Gamma: \bar{D}^n\mu(x)=0\})>0$, which violates \eqref{E:suffconddx}.
\end{remark}


\section{Kernels of trace operators}\label{S:kernels}

Let $1<p<\infty$ and $\alpha>0$. We write
\[m_s:=\lceil\alpha\rceil - 1,\]
where $\lceil\cdot \rceil$ denotes the ceiling function. The number $m_s\geq 0$ (\enquote{s} for \enquote{Sobolev}) is the maximal order $|\beta|$ of multiindices $\beta$ such that $\alpha-|\beta|>0$. If $u\in H^\alpha_p(\mathbb{R}^n)$ and $|\beta|\leq m_s$, then the distributional derivative $D^\beta u$ of $u$ is an element of $H^{\alpha-|\beta|}_p(\mathbb{R}^n)$. In this case we can find 
a $(\alpha-|\beta|,p)$-quasi  continuous representative $(D^\beta u)^\sim$ of $D^\beta u$.

Let $\Gamma\subset \mathbb{R}^n$ and $|\beta|\leq m_s$. If $\cpct_{\alpha-|\beta|,p}(\Gamma)>0$, then we write $(D^\beta u)^\sim|_\Gamma=0$ whenever $(D^\beta u)^\sim=0$ $(\alpha-|\beta|,p)$-q.e.\ on $\Gamma$. If $\cpct_{\alpha-|\beta|,p}(\Gamma)=0$, then we abuse notation and agree to regard $(D^\beta u)^\sim|_\Gamma$ as identically zero for all $u\in H^\alpha_p(\mathbb{R}^n)$. Given a nonnegative integer $m\leq m_s$, we write $((D^\beta u)^\sim|_\Gamma)_{|\beta|\leq m}=0$ if all components $(D^\beta u)^\sim|_\Gamma$ are zero in the aforementioned sense.

By $\widetilde{H}^\alpha_p(\mathbb{R}^n\setminus \Gamma)$ we denote the closure of $C_c^\infty(\mathbb{R}^n\setminus \Gamma)$ in $H^\alpha_p(\mathbb{R}^n)$. A well known theorem by Netrusov states that
\begin{equation}\label{E:traceqe}
\widetilde{H}^\alpha_p(\mathbb{R}^n\setminus \Gamma)=\left\lbrace u\in H^\alpha_p(\mathbb{R}^n):\ ((D^\beta u)^\sim|_\Gamma)_{|\beta|\leq m_s}=0\right\rbrace,
\end{equation}
see \cite[Corollary 10.1.2]{AH96} and \cite{HedbergNetrusov07, Netrusov93}. Recall \eqref{E:capdim}. In the special case that $0<\alpha< \alpha_p(\Gamma)+1$ or $\alpha= \alpha_p(\Gamma)+1$ and $\cpct_{\alpha_p(\Gamma),p}(\Gamma)=0$ identity \eqref{E:traceqe} is equivalent to \eqref{E:kerTr}, which stated that $\ker\mathrm{Tr}_{\Gamma,0}= \widetilde{H}^\alpha_p(\mathbb{R}^n\setminus \Gamma)$, where $\mathrm{Tr}_{\Gamma,0}$ is the operator considered in \eqref{E:traceopqe}. Earlier variants of \eqref{E:traceqe} in this case were shown in \cite{Bagby72, Deny50, Havin68, Hedberg72, Sobolev63}, and earlier variants  of \eqref{E:traceqe} for \enquote{regular} $\Gamma$ can for instance be found in \cite{Necas67, Triebel78}.

Let 
\[m_c:=\left\lceil\alpha-\frac{n}{p}\right\rceil - 1.\]
If $m_c\geq 0$, then $m_c$ (\enquote{c} for \enquote{continuous}) indicates the the maximal order $|\beta|$ up to which the $D^\beta u$ are continuous. We have $m_c\geq 0$ if and only if $\alpha>\frac{n}{p}$. If $m_c<0$, then neither $u$ nor any of its derivatives are continuous. Note that $m_c<m_s$ if and only if the interval $[\alpha-\frac{n}{p},\alpha)$ contains an integer; in this case it contains the integers $m_c+1,\ldots,m_s$. 

Now suppose that $\Gamma$ is the support of a non-zero Radon measure $\mu$ and $d:\Gamma\to [0,\infty)$ is a such that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Let 
\begin{equation}\label{E:mt}
m_t:=\left\lceil\alpha - \frac{(n-\inf_{x\in\Gamma} d(x))}{p}\right\rceil - 1.
\end{equation}
The number $m_t\geq 0$ (\enquote{t} for \enquote{trace}) indicates the maximal order $|\beta|$ of multiindices $\beta$ such that 
\[n-(\alpha-|\beta|)p<\inf_{x\in\Gamma} d(x).\]
For such $\beta$ Lemma \ref{L:smooth} guarantees that all sets of zero $(\alpha-|\beta|,p)$-capacity are $\mu$-null sets.
In this case the $\mu$-equivalence class of $(D^\beta u)^\sim|_\Gamma$ is well defined, and we denote it by $[D^\beta u]_\mu$. 



Recall from Remark \ref{R:upregd} (i) that $d(x)\leq n$, $x\in\Gamma$. We have that
\[ m_s - n \leq m_c \leq m_t \leq m_s. \]

For any $0\leq m\leq m_t$ we can define a linear operator $[\mathrm{Tr}_{\Gamma,m}]_\mu:H^\alpha_p(\mathbb{R}^n)\to \bigotimes_{|\beta|\leq m} L^0(\Gamma,\mu)$ by
\[[\mathrm{Tr}_{\Gamma,m}]_\mu u:=([D^\beta u]_\mu)_{|\beta|\leq m},\quad u\in H^\alpha_p(\mathbb{R}^n);\]
here $L^0(\Gamma,\mu)$ denotes the space of $\mu$-equivalence classes of Borel functions on $\Gamma$. In the special case $m=0$ we recover the operator $[\mathrm{Tr}_{\Gamma,0}]_\mu$ considered in \eqref{E:traceopmu}. The kernel of $[\mathrm{Tr}_{\Gamma,m}]_\mu$ is 
\[\ker [\mathrm{Tr}_{\Gamma,m}]_\mu=\left\lbrace u\in H^\alpha_p(\mathbb{R}^n):\ [\mathrm{Tr}_{\Gamma,m}]_\mu u=0\right\rbrace; \]
here $[\mathrm{Tr}_{\Gamma,m}]_\mu u=0$ is understood in the natural sense that $[D^\beta u]_\mu=0$ $\mu$-a.e.\ on $\Gamma$ for all $|\beta|\leq m$. 

Under the assumptions stated before formula \eqref{E:mt} the identity $((D^\beta u)^\sim|_\Gamma)_{|\beta|\leq m}=0$ implies the identity $[\mathrm{Tr}_{\Gamma,m}]_\mu u=0$, but in general the converse implication is not clear. Theorem \ref{T:main} gives the following result.

\begin{corollary}\label{C:trace}
Let $\mu$ be a  non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$,  $1<p<\infty$ and $\alpha>0$. Let $d:\Gamma\to [0,\infty)$ be a Borel function such that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold.
\begin{enumerate}
\item[(i)] Suppose that either $0\leq m\leq m_c$, or $\max(m_c+1,0)\leq m\leq m_t$ and  
\begin{equation}\label{E:densitypos}
\bar{D}^{d(x)}\mu(x)>0\quad \text{for  $\ (\alpha-\max(m_c+1,0),p)$-q.e.\ $x\in \Gamma$.}
\end{equation}
Then, for any $u\in H^\alpha_p(\mathbb{R}^n)$,
\begin{equation}\label{E:muident}
[\mathrm{Tr}_{\Gamma,m}]_\mu u=0\quad \text{if and only if}\quad ((D^\beta u)^\sim|_\Gamma)_{|\beta|\leq m}=0.
\end{equation}
\item[(ii)] Suppose that either $m_c=m_s$, or $m_c<m_s$ and 
\begin{enumerate}
\item[(a)] either  $m_t= m_c$ or \eqref{E:densitypos} holds, and
\item[(b)] either $m_t=m_s$ or $\cpct_{\alpha-(m_t+1),p}(\Gamma)=0$.
\end{enumerate}
Then 
\begin{equation}\label{E:kerident}
\ker [\mathrm{Tr}_{\Gamma,m_t}]_\mu=\widetilde{H}^\alpha_p(\mathbb{R}^n\setminus \Gamma).
\end{equation}
\end{enumerate}
\end{corollary}

\begin{proof}
For every multiindex $\beta$ with $|\beta|\leq m_c$ the distributional derivative $D^\beta u$ has a unique continuous representative, so that the equivalence
\begin{align}
\label{E:deriv_equiv}
[D^\beta u]_\mu u=0\quad \text{if and only if} \quad ((D^\beta u)^\sim|_\Gamma)=0
\end{align}
follows similarly as Remark \ref{R:trivial}. This gives \eqref{E:muident} in the case $0\leq m\leq m_c$. If $\max(m_c+1,0)\leq m\leq m_t$, then for any $\beta$ with $\max(m_c+1,0)\leq |\beta|\leq m$ we have \eqref{E:deriv_equiv} by Theorem \ref{T:main} and since \eqref{E:densitypos} implies that $\bar{D}^{d(x)}\mu(x)>0$ for $(\alpha-|\beta|,p)$-q.e.\ $x\in \Gamma$. Here we use that a set of zero $(\sigma,p)$-capacity has zero $(\sigma',p)$-capacity for any $0<\sigma'\leq \sigma$. Together, this gives (i), and it gives \eqref{E:kerident} in the case that $m_t=m_s$. If $m_t\leq m_s-1$ then \eqref{E:deriv_equiv} holds for $m_t+1\leq |\beta|\leq m_s$ by the assumption that $\cpct_{\alpha-(m_t+1),p}(\Gamma)=0$, which, arguing as before, implies that $\cpct_{\alpha-|\beta|,p}(\Gamma)=0$ for all the $\beta$ in this range. This gives \eqref{E:kerident}, completing the proof of (ii).
\end{proof}

In the special case of $d$-measures $\mu$ and resulting $d$-sets $\Gamma$ we obtain the following.

\begin{corollary}\label{C:dsettrace} 
Let $0<d\leq n$, $\mu$ be a $d$-measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and $1<p<\infty$. Then \eqref{E:kerident} holds
for all $\alpha>\frac{n-d}{p}$.
\end{corollary}

\begin{proof}
In the case $m_t=m_s$ all hypotheses of Corollary \ref{C:trace} are obviously satisfied. If instead $m_t\leq m_s-1$, then we can use that, by the definition \eqref{E:mt} of $m_t$,
\begin{equation}\label{E:alphaleq}
\alpha\leq \frac{n-d}{p}+m_t+1.
\end{equation}
We claim that \eqref{E:alphaleq} implies
\begin{equation}\label{E:capzero}
\cpct_{\alpha-(m_t+1),p}(\Gamma)=0,
\end{equation}
so that again all hypotheses of Corollary \ref{C:trace} (ii) hold. To see \eqref{E:capzero}, assume first that the inequality in \eqref{E:alphaleq} is strict. Then $d<n-(\alpha-m_t-1)p$, and we can recycle an argument from the proof of \cite[Proposition 6.7]{CHM21}:  For any open ball $B$ we have $\mathcal{H}^d(B\cap \Gamma)<\infty$ and therefore $\mathcal{H}^{n-(\alpha-m_t-1)p}(B\cap \Gamma)=0$. Exhausting $\mathbb{R}^n$ by an increasing sequence of open balls and using the continuity of measures from below gives $\mathcal{H}^{n-(\alpha-m_t-1)p}(\Gamma)=0$, so that an application of \cite[Theorem 5.1.9]{AH96} proves \eqref{E:capzero}. See \cite[p. 35/36]{CHM21}. Now assume that equality holds in \eqref{E:alphaleq}. Then $\mathcal{H}^{n-(\alpha-m_t-1)p}(B\cap \Gamma)=\mathcal{H}^d(B\cap \Gamma)<\infty$ for any open ball $B$. Therefore, using first \cite[Theorem 5.1.9]{AH96} and then exhausting $\mathbb{R}^n$ by open balls and applying \cite[Proposition 2.3.12]{AH96}, we can conclude \eqref{E:capzero}. 
\end{proof}

%$\frac{n-d}{p}+m_t<\alpha<\frac{n-d}{p}+m_t+1$, 

\begin{remark}\label{R:improve} In \cite[Proposition 6.7]{CHM21} the equality \eqref{E:kerident} was shown for $d$-sets under the assumptions that $0<d<n$, $\alpha>\frac{n-d}{p}$ and $\alpha-\frac{n-d}{p}$ is not an integer, along with a similar result for Besov spaces. The exclusion of integer $\alpha-\frac{n-d}{p}$ was needed to apply an extension theorem \cite[Theorem VII.3]{JW84}. Note that the non-integer case corresponds to having $\frac{n-d}{p}+m_t<\alpha<\frac{n-d}{p}+m_t+1$ and the integer case to $\alpha=\frac{n-d}{p}+m_t+1$. Corollary \ref{C:dsettrace} is thus an extension of \cite[Proposition 6.7]{CHM21} in the case of fractional Sobolev spaces. Indeed, the question whether \eqref{E:kerident} holds for the integer case was formulated as an open problem in \cite[Remark 6.9]{CHM21}, and for the case of fractional Sobolev spaces Corollary \ref{C:dsettrace} gives an affirmative answer. For $p=2$ and $\frac{n-d}{2}<\alpha<\frac{n-d}{2}+1$ a slightly improved version of \cite[Proposition 6.7]{CHM21} was presented in \cite[Theorem 3.9]{CCh-WCGHM25}, including the case $d=n$ for, roughly speaking, \enquote{smoothness $\alpha=0$}. For $d=n$ and smoothness $\alpha=1$ the coincidence
\begin{equation}\label{E:kerident0}
\ker [\mathrm{Tr}_{\Gamma,0}]_\mu=\widetilde{H}^1_2(\mathbb{R}^n\setminus \Gamma)
\end{equation}
was stated as \cite[Assumption 3.12 (ii)]{CCh-WCGHM25}. For $d=n$ and $0<\alpha\leq 1$ we have $m_t=m_s=0$, so that Corollary \ref{C:dsettrace} gives \eqref{E:kerident0}. This means that \cite[Assumption 3.12 (ii)]{CCh-WCGHM25} is not needed for the validity of Corollary 3.13 and Lemma 3.15 in \cite{CCh-WCGHM25}.
\end{remark}

Recall that in \eqref{E:capdim} the number $\alpha_p(\Gamma)$ was defined to be $\alpha_p(\Gamma)=\frac{1}{p}(n-\dim_H\Gamma)$.

\begin{remark}\label{R:capdim} \mbox{}
\begin{enumerate}
\item[(i)] By a well-known characterization of the Hausdorff dimension in terms of Riesz capacities \cite[Theorem 8.9]{Mattila}, together with the fact that, for $\alpha>\frac{n}{p}$, points have positive $(\alpha,p)$-capacity, we have
\[\alpha_p(\Gamma)=\sup\{\alpha\geq 0:\ \cpct_{\alpha,p}(\Gamma)=0\}=\inf\{\alpha\geq 0:\ \cpct_{\alpha,p}(\Gamma)>0\},\]
for any nonempty Borel set $\Gamma\subset \mathbb{R}^n$. If $\cpct_{\alpha,p}(\Gamma)=0$, which happens in particular if $0<\alpha<\alpha_p(\Gamma)$, then, where $\widetilde{B}(\Gamma)$ is as defined in Section 1, $\widetilde{B}(\Gamma)=\{0\}$ and $\ker\mathrm{Tr}_{\Gamma,0}=H_p^\alpha(\mathbb{R}^n)=\widetilde{H}_p^\alpha(\mathbb{R}^n)$. In this case $\Gamma$ is said to be a removable set for $H_p^\alpha(\mathbb{R}^n)$, see for instance \cite[Section 2.9, p. 51]{AH96} or \cite{HKM17,HMS23} and the references cited there. If $\cpct_{\alpha,p}(\Gamma)>0$, which happens in particular if $\alpha>\alpha_p(\Gamma)$, then $\widetilde{H}_p^\alpha(\mathbb{R}^n\setminus \Gamma)\subset \ker\mathrm{Tr}_{\Gamma,0}\subsetneq H_p^\alpha(\mathbb{R}^n)$. If in addition $\alpha<\alpha_p(\Gamma)+1$ or $\alpha=\alpha_p(\Gamma)$ and $\cpct_{\alpha_p(\Gamma),p}(\Gamma)=0$, then by \cite[Corollary 10.1.2]{AH96} also $\ker\mathrm{Tr}_{\Gamma,0}\subset \widetilde{H}_p^\alpha(\mathbb{R}^n\setminus \Gamma)$.
\item[(ii)] Let $\mu$ be a non-zero Radon measure and $\Gamma=\supp\mu$. Then $\mu(B(x,r)\cap \Gamma)>0$ for all $x\in \Gamma$ and all $r>0$. Let $d:\Gamma\to [0,+\infty)$ be a Borel function satisfying \eqref{E:upperdensdx}. For $\alpha_p(\Gamma)<\alpha\leq \frac{1}{p}(n-\inf_{x\in\Gamma}d(x))$ there could be some $x\in \Gamma$ and $r>0$ such that $\cpct_{\alpha,p}(B(x,r)\cap \Gamma)=0$, see Example \ref{Ex:hybridcont} below. This is excluded by assumption \eqref{E:traceconddx}, which implies that $\cpct_{\alpha,p}(B(x,r)\cap \Gamma)>0$ for all $x\in \Gamma$ and all $r>0$ by Lemma \ref{L:smooth} (i). Now assume \eqref{E:traceconddx} and that $S_{d,\mu}(\Gamma)=\emptyset$. In this situation Remark \ref{R:upregd} (i) and (ii) imply that
\[\dim_H\Gamma=\sup_{x\in\Gamma}d(x)\]
and, as a consequence, that
\begin{equation}\label{E:supdx}
\alpha_p(\Gamma)=\frac{n-\sup_{x\in\Gamma}d(x)}{p}.
\end{equation}
\end{enumerate}
\end{remark}

A variant of the argument from \cite[p. 35/36]{CHM21} used in the proof of Corollary \ref{C:dsettrace} ensures the validity of (a special case of) the capacity condition in Corollary \ref{C:trace} (ii) (b), even if $\mu$ is not a $d$-set.

\begin{lemma}\label{L:variant}
Let $\mu$ be a  non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and  $1<p<\infty$. Suppose that $d:\Gamma\to[0,\infty)$ is a Borel function such that \eqref{E:upperdensdx} holds and $S_{d,\mu}(\Gamma)=\emptyset$. If 
\begin{equation}\label{E:variant}
\frac{n-\inf_{x\in\Gamma}d(x)}{p}<\alpha<\alpha_p(\Gamma)+1,
\end{equation}
then $\cpct_{\alpha-1,p}(\Gamma)=0$ and \eqref{E:kerTrmu} holds. If $\mathcal{H}^{\dim_H\Gamma}(B\cap \Gamma)<\infty$ for every open ball $B$, then the conclusion remains true for $\alpha=\alpha_p(\Gamma)+1$.
\end{lemma}

\begin{proof} By \eqref{E:supdx} and \eqref{E:variant}
we have 
\begin{equation}\label{E:supsmall}
\sup_{x\in\Gamma}d(x)<n-(\alpha-1)p,
\end{equation} 
which implies that $\bar{D}^{n-(\alpha-1)p}\mu(x)=\infty$ for all $x\in\Gamma$ and, by \cite[Theorem 6.9]{Mattila}, $\mathcal{H}^{n-(\alpha-1)p}(B\cap \Gamma)=0$ for any ball $B$. We can again use \cite[Theorem 5.1.9]{AH96}, exhaustion by balls and \cite[Proposition 2.3.12]{AH96} to obtain $\cpct_{\alpha-1,p}(\Gamma)=0$. Under the assumptions in the last statement of the lemma $\cpct_{\alpha-1,p}(\Gamma)=0$ follows as in the proof of Corollary \ref{C:dsettrace}.

To see \eqref{E:kerTrmu}, note first that by \eqref{E:supsmall} we have $m_t=0$ and, as a consequence, $m_c\leq 0$. Using  $\cpct_{\alpha-1,p}(\Gamma)=0$ to cover the case $m_s>0$, we see that all hypotheses of  Corollary \ref{C:trace} (ii) are satisfied, so that it gives \eqref{E:kerTrmu}. 
\end{proof}




\begin{examples}\label{Ex:hybridcont}
In Example \ref{Ex:hybrid} we have $\alpha_2(\Gamma)=1-\frac{\log 2}{\log 3}$. For $0<\alpha\leq \alpha_2(\Gamma)$ the set $\Gamma$ has zero $(\alpha,2)$-capacity, and for $\alpha_2(\Gamma)<\alpha\leq \frac12$ the set $\Gamma_2\setminus \Gamma_1$ has zero $(\alpha,2)$-capacity. If $\frac12<\alpha\leq 2-\frac{\log 2}{\log 3}$, then $B(x,r)\cap \Gamma$, for $x\in \Gamma$ and $r>0$, has positive $(\alpha,2)$-capacity and \eqref{E:kerTrmu} holds with $p=2$.
\end{examples}

Let the hypotheses of Lemma \ref{L:smooth} (i) or (ii) be satisfied. Recall from the introduction that $\widetilde{B}(\Gamma)$ denotes the space of $(\alpha,p)$-q.e.\ equivalence classes of restrictions $\widetilde{u}|_\Gamma$, $u\in H^\alpha_p(\mathbb{R}^n)$, and that it is a Banach space (Hilbert for $p=2$) if endowed with the (quotient) norm 
\begin{equation}\label{E:capnorm}
\|\varphi\|_{\widetilde{B}(\Gamma)}:=\inf\big\lbrace \|u\|_{H_p^\alpha(\mathbb{R}^n)}:\ u\in H_p^\alpha(\mathbb{R}^n),\ \mathrm{Tr}_{\Gamma,0} u=\varphi\big\rbrace,\quad \varphi\in \widetilde{B}(\Gamma).
\end{equation}
Recall also that $[\widetilde{B}(\Gamma)]_\mu$ denotes the space of $\mu$-equivalence classes of restrictions $\widetilde{u}|_\Gamma$, $u\in H^\alpha_p(\mathbb{R}^n)$, which is a Banach space (Hilbert for $p=2$) if endowed with the (quotient) norm 
\begin{equation}\label{E:munorm}
\|\varphi\|_{[\widetilde{B}(\Gamma)]_\mu}:=\inf\big\lbrace \|u\|_{H_p^\alpha(\mathbb{R}^n)}:\ u\in H_p^\alpha(\mathbb{R}^n),\ [\mathrm{Tr}_{\Gamma,0}]_\mu u=\varphi\big\rbrace, \quad \quad \varphi\in [\widetilde{B}(\Gamma)]_\mu.
\end{equation}
By definition the inclusion $[\widetilde{B}(\Gamma)]_\mu\subset L^0(\Gamma,\mu)$ is injective.

\begin{lemma}
Let the hypotheses of Lemma \ref{L:smooth} (i) or (ii) be satisfied. Then the following are equivalent: 
\begin{enumerate}
\item[(i)] the equivalence \eqref{E:wish} holds,  
\item[(ii)] the inclusion $\widetilde{B}(\Gamma)\subset L^0(\Gamma,\mu)$ is injective,
\item[(iii)] the spaces $\widetilde{B}(\Gamma)$ and $[\widetilde{B}(\Gamma)]_\mu$ coincide and the norms \eqref{E:capnorm} and \eqref{E:munorm} are equal.
\end{enumerate}
A sufficient additional condition for the validity of (i), (ii) and (iii) is \eqref{E:suffconddx} in the case that the hypotheses of Lemma \ref{L:smooth} (i) hold or \eqref{E:suffcondh} in the case that the hypotheses of Lemma \ref{L:smooth} (ii) hold.
\end{lemma}

\begin{remark}
The first-named author would like to correct a related imprecise claim made in \cite{HR-PT2023}: In \cite[formula (5) of Corollary 2.1]{HR-PT2023} the specification \enquote{$\mu$-a.e.} must be replaced by \enquote{q.e.} and \cite[Proposition 2.1]{HR-PT2023} should be disregarded. With these corrections all other results remain valid.
\end{remark}

\section{Applications to domains}\label{S:domains}

We discuss applications of our results to domains, i.e., non-empty open sets $\Omega\subset \mathbb{R}^n$. Recall from \cite{Hajlaszetal08} that a domain $\Omega\subset \mathbb{R}^n$ satisfies the measure density condition if there is some $c>0$ such that, for all $x\in \Omega$ and $0<r\leq 1$, 
\begin{equation}\label{E:measuredenscond}
\mathcal{L}^n(B(x,r)\cap \Omega)\geq c\:r^n.
\end{equation}

\begin{remark}\label{R:measuredenscond}
Domains satisfying the measure density condition \eqref{E:measuredenscond} are 
are called ``$n$-thick domains'' in \cite{Rychkov00}, ``interior regular domains'' in \cite{CHM21}, ``open $n$-sets'' in \cite{CCh-WH25}, and simply \enquote{$n$-sets} in \cite[p. 205]{JW84} or \cite{FarkasJacob2001}. (We note that in our definition \eqref{E:dset} we require an $n$-set to be closed.) 
\end{remark}


Our first observation is the following, which in fact, is a variant of the $n$-set case in Corollary \ref{C:dset} (i).

\begin{theorem}\label{T:domain}
Let $\Omega\subset \mathbb{R}^n$ be a domain satisfying the measure density condition. Then $\overline{\Omega}$ is an $n$-set, $\mathcal{L}^n(\partial\Omega)=0$, and for any $1<p<\infty$ and $\alpha>0$ we have 
\begin{equation}\label{E:domain}
\text{$u=0\ $ $\mathcal{L}^n$-a.e.\ on $\Omega$}\quad\text{if and only if}\quad\text{$\widetilde{u}=0$ $(\alpha,p)$-q.e.\ on $\overline{\Omega}$,} \qquad u\in H^\alpha_p(\R^n),
\end{equation}
where $\widetilde{u}$ denotes an arbitrary $(\alpha,p)$-quasi continuous representative of $u$.
\end{theorem}


\begin{proof} The first two claims are well known, cf. \cite[Section 1]{Hajlaszetal08} or \cite[Proposition 1, p. 205]{JW84}. To see \eqref{E:domain}, note first that every set of zero $(\alpha,p)$-capacity is an $\mathcal{L}^n$-null set. Thus it suffices to prove that if an element $u$ of $H^\alpha_p(\mathbb{R}^n)$ satisfies $u=0$ $\mathcal{L}^n$-a.e.\ on $\Omega$ then $\widetilde{u}=0$ $(\alpha,p)$-q.e.\ on $\overline{\Omega}$. However, together with the preceding arguments we see that $\widetilde{u}=0$ $\mathcal{L}^n$-a.e.\ on $\overline{\Omega}$ for any such $u$, so that an application of Corollary \ref{C:dset} (i) to the $n$-set $\overline{\Omega}$ gives $\widetilde{u}=0$ $(\alpha,p)$-q.e.\ on $\overline{\Omega}$ for any $0<\alpha\leq \frac{n}{p}$, while Remark \ref{R:trivial} gives it for $\alpha>\frac{n}{p}$.
\end{proof}

Given a domain $\Omega\subset \mathbb{R}^n$, $1\leq p<\infty$ and a positive integer $m$, we write $W^m_p(\Omega)$ for the Sobolev space of all $u\in L^q(\Omega)$ with $D^\beta u\in L^q(\Omega)$, $|\beta|\leq m$, endowed with the intrinsic norm $u\mapsto \sum_{|\beta|\leq m}\|D^\beta u\|_{L^q(\Omega)}$. We say that a domain $\Omega$ has the $W^m_p$-extension property if there is a bounded linear extension operator $\mathrm{E}_\Omega:W_p^m(\Omega)\to W^m_p(\R^n)$ with $(\mathrm{E}_\Omega u)|_\Omega=u$, $u\in W^m_p(\Omega)$. For $p=2$ and arbitrary positive integer $m$ every domain $\Omega$ for which the restriction $u\mapsto u|_\Omega$ is surjective from $W^m_2(\mathbb{R}^n)$ onto $W_2^m(\Omega)$ has the $W^m_2$-extension property, cf. \cite[p. 1221]{Hajlaszetal08}.

For $1<p<\infty$ and $\alpha>0$ we define $H_p^\alpha(\Omega)$ as the space of all $u\in L^p(\Omega)$ such that there is some $v\in H^\alpha_p(\mathbb{R}^n)$ with $u=v|_\Omega$, endowed with the quotient norm. We say that $\Omega$ has the $H^\alpha_p$-extension property if there is a bounded linear extension operator $\mathrm{E}_\Omega:H^\alpha_p(\Omega)\to H^\alpha_p(\R^n)$ with $(\mathrm{E}_\Omega u)|_\Omega=u$, $u\in H^\alpha_p(\Omega)$.  For $p=2$ and arbitrary $\alpha>0$ every domain $\Omega$  trivially has the $H_2^\alpha(\Omega)$-extension property \cite[p.~142]{Rychkov00}.


\begin{lemma}\label{L:extensiondomain} Let $\Omega\subset \mathbb{R}^n$ be a domain.
\begin{enumerate}
\item[(i)] If, for some $1\leq p<\infty$ and positive integer $m$, the restriction $u\mapsto u|_\Omega$ is surjective  from $W^m_p(\mathbb{R}^n)$ onto $W_p^m(\Omega)$, then $\Omega$ satisfies the measure density condition. This is true in particular if $\Omega$ has the $W^m_p$-extension property.
\item[(ii)] If $\Omega$  satisfies the measure density condition, then it has the $H^\alpha_p$-extension property for every $1<p<\infty$ and $\alpha>0$.
\item[(iii)]  If $1<p<\infty$, $m$ is a positive integer and $\Omega$ has the $W^m_p$-extension property, then $H^m_p(\Omega)$ equals $W^m_p(\Omega)$ in the sense of equivalently normed spaces.
\item[(iv)] If $\Omega$ is an $(\varepsilon,\delta)$-domain, then $\Omega$ has the $W^m_p$-extension property for every $1\leq p<\infty$ and every positive integer $m$.
\end{enumerate}
\end{lemma}

\begin{proof} In \cite[Theorem 2]{Hajlaszetal08} it was shown that with the assumptions in (i), the domain $\Omega$ satisfies the measure density condition. Item (ii) was proved in \cite[Theorem 1.1(a)]{Rychkov00}. Item (iii) is well-known and easy to see. Item (iv) was proved in \cite[Theorem 1]{Jones81}.
\end{proof}

\begin{remark}\mbox{}
\begin{enumerate}
\item[(i)] For $1<p<\infty$ the surjectivity of the restriction in (i) and the $W^m_p$-extension property are actually equivalent \cite[Theorem 5]{Hajlaszetal08}. 
\item[(ii)] It is well known that every Lipschitz domain is an $(\varepsilon,\delta)$-domain \cite{Jones81}. Well-known extension theorems for Lipschitz domains are \cite[Chapter VI, Theorem 5]{Stein70}, \cite[Corollary 1.6]{Strichartz67} and \cite[Theorem 1]{Kalyabin85}. Further extension results for  $(\varepsilon,\delta)$-domains are \cite[Theorem 8]{Rogers06} and \cite[Theorem 2]{Seeger89}. 
\item[(iii)] Related extension results for fractional Sobolev spaces on domains defined using intrinsic norms and in the case that $0<\alpha<1$ can be found in \cite{Zhou15}. Extension results for Haj\l asz-Triebel-Lizorkin space are provided in \cite{HIT16}.
\end{enumerate}
\end{remark}

\begin{remark} For $1<p<\infty$ and domains $\Omega$ having the $W^1_p$-extension property, the nontrivial implication in \eqref{E:domain} was proved in \cite[Theorem 6.1 and Remark 6.2]{Biegert09}; see also \cite[Theorems 3.20, 3.23 and 3.27]{Biegert09b}. For $p=2$,  $0<\alpha\leq 1$ and domains $\Omega$ having the $W^1_p$-extension property the nontrivial implication in \eqref{E:domain} can be shown using Dirichlet form methods, see \cite{ArendtWarma03},\cite[p. 53]{FOT2011} and the arguments used to prove \cite[Theorem 4.4]{FarkasJacob2001}. For smooth domains this kind of argument works for $p=2$ and $0<\alpha<\frac{3}{2}$ by combining interpolation \cite[Theorem 4.1]{Seeley72} and using suitably defined capacities \cite{FukushimaKaneko85}. Theorem \ref{T:domain} and Lemma \ref{L:extensiondomain} extend these results.
\end{remark}



Given a domain $\Omega$ having the $H^\alpha_p$-extension property and a closed subset $\Gamma$ of $\overline{\Omega}$, we consider the composition 
\[\mathrm{Tr}_{\Gamma,0}^\Omega:=\mathrm{Tr}_{\Gamma,0}\circ \mathrm{E}_\Omega.\]
For $\alpha=1$ this kind of trace operator was used, for example, in \cite{CHR-PT24} and \cite{HR-PT2021}. By $H^\alpha_{p,0}(\overline{\Omega}\setminus \Gamma)$ we denote the closure of $\{v|_\Omega:\ v\in C_c^\infty(\mathbb{R}^n\setminus \Gamma)\}$ in $H_p^\alpha(\Omega)$. In the special case $\Gamma=\partial\Omega$ we recover the familiar definition of $H^\alpha_{p,0}(\Omega)$ as the closure of $C_c^\infty(\Omega)$ in $H_p^\alpha(\Omega)$. In the following, $\widetilde{B}(\Gamma)$ and $[\widetilde{B}(\Gamma)]_\mu$ are as defined in Sections \ref{S:intro} and \ref{S:kernels}. Our next 
lemma extends \cite[Corollary 6.3]{Biegert09}, where it was shown for $\alpha=1$.

\begin{lemma}\label{L:traceop}
Let $1<p<\infty$ and $\alpha>0$. Let $\Omega\subset \mathbb{R}^n$ be a domain satisfying the measure density condition. Let $\Gamma$ be a closed subset of $\overline{\Omega}$ such that $\overline{\Omega}\setminus \Gamma$ is dense in $\overline{\Omega}$.
\begin{enumerate}
\item[(i)] The operator $\mathrm{Tr}_{\Gamma,0}^\Omega:H^\alpha_p(\Omega)\to \widetilde{B}(\Gamma)$ is bounded, linear and surjective. It does not depend on the 
particular choice of the extension operator $\mathrm{E}_\Omega$. 
\item[(ii)] If $0<\alpha<\alpha_p(\Gamma)+1$ or $\alpha=\alpha_p(\Gamma)+1$ and $\cpct_{\alpha_p(\Gamma),p}(\Gamma)=0$, then $\ker \mathrm{Tr}_{\Gamma,0}^\Omega=H^\alpha_{p,0}(\overline{\Omega}\setminus\Gamma)$.
\end{enumerate}
\end{lemma}
%, or $\alpha=\alpha_p(\Gamma)+1$ and $\cpct_{\alpha_p(\Gamma),p}(\Gamma)=0$

The special case $\Gamma=\partial\Omega$ in (ii) gives $\ker \mathrm{Tr}_{\partial\Omega,0}^\Omega=H^\alpha_{p,0}(\Omega)$. 

\begin{proof}
The linearity and boundedness of $\mathrm{Tr}_{\Gamma,0}^\Omega$ are clear. To prove the surjectivity, suppose that $f\in \widetilde{B}(\Gamma)$ and $u\in H^\alpha_p(\mathbb{R}^n)$ is such that $f=\mathrm{Tr}_{\Gamma,0} u$. Then $u|_\Omega\in H^\alpha_p(\Omega)$. For any extension operator $\mathrm{E}_\Omega$, since both $u$ itself and $\mathrm{E}_\Omega (u|_\Omega)$ extend $u|_\Omega$ to all of $\mathbb{R}^n$, we have 
$(\mathrm{E}_\Omega (u|_\Omega))^\sim=\widetilde{u}$ $(\alpha,p)$-q.e.\ on $\overline{\Omega}$ by Theorem \ref{T:domain}. 
In particular, 
$\mathrm{Tr}_{\Gamma,0}^\Omega u=\mathrm{Tr}_{\Gamma,0}(\mathrm{E}_\Omega (u|_\Omega))=\mathrm{Tr}_{\Gamma,0} u=f$. This gives (i).

To prove (ii), suppose first that $u\in H_p^\alpha(\Omega)$ is such that $\mathrm{Tr}_{\Gamma,0}^\Omega=0$ in $\widetilde{B}(\Gamma)$, that is, $(\mathrm{E}_\Omega u)^\sim|_\Gamma=0$ $(\alpha,p)$-q.e. Then $\mathrm{E}_\Omega u\in \widetilde{H}_p^\alpha(\mathbb{R}^n\setminus\Gamma)$ by \eqref{E:kerTr}, so that there is a sequence $(v_k)\subset C_c^\infty(\mathbb{R}^n\setminus \Gamma)$ converging to $\mathrm{E}_\Omega u$ in $H^\alpha_p(\mathbb{R}^n)$. Consequently also 
\begin{equation}\label{E:convinOm}
\lim_k v_k|_\Omega=u\quad \text{in $H^\alpha_p(\Omega)$},
\end{equation}
hence $u\in H_{p,0}^\alpha(\overline{\Omega}\setminus \Gamma)$. This shows that $\ker \mathrm{Tr}_{\Gamma,0}^\Omega\subset H^\alpha_{p,0}(\overline{\Omega}\setminus \Gamma)$. To see the converse inclusion $H^\alpha_{p,0}(\overline{\Omega}\setminus \Gamma)\subset \ker \mathrm{Tr}_{\Gamma,0}^\Omega$, suppose that $u\in H_{p,0}^\alpha(\overline{\Omega}\setminus \Gamma)$ and let $(v_k)\subset C_c^\infty(\mathbb{R}^n\setminus \Gamma)$ be such that \eqref{E:convinOm} holds. For any $k$, both $\mathrm{E}_\Omega (v_k|_\Omega)$ and $v_k$ itself are in $H_p^\alpha(\mathbb{R}^n)$, and therefore Theorem \ref{T:domain}  implies that $(\mathrm{E}_\Omega v_k)^\sim=\widetilde{v}_k=0$ $(\alpha,p)$-q.e.\ on $\Gamma$. 
On the other hand, $\lim_k \mathrm{E}_\Omega v_k=\mathrm{E}_\Omega u$ in $H^\alpha_p(\mathbb{R}^n)$, because $\mathrm{E}_\Omega$ is linear and bounded. This implies that there is a sequence $(k_\ell)$ with $k_\ell\to \infty$ as $\ell\to\infty$ such that $(\mathrm{E}_\Omega u)^\sim=\lim_\ell (\mathrm{E}_\Omega v_{k_\ell})^\sim=0$ $(\alpha,p)$-q.e.\ on $\Gamma$, see for instance \cite[Proposition 2.3.8]{AH96}. Consequently $\mathrm{Tr}_{\Gamma,0}^\Omega u=0$, as desired.
\end{proof}

Similar arguments give the following consequence of \eqref{E:traceqe}. 
%
%A priori the defining condition in the right-hand side of \eqref{E:traceqedomain} below makes sense if for any multiindex $\beta$ with $|\beta|\leq m_s$ the extension operator $\mathrm{E}_\Omega$ from \cite[Theorem 8]{Rogers06} is used. However, as a consequence of \eqref{E:domain}, the particular choice of $\mathrm{E}_\Omega$ for a given multiindex $\beta$ does not matter.

\begin{corollary}
Let $1<p<\infty$, let $\Omega\subset \mathbb{R}^n$ be a domain satisfying the measure density condition. Let $\Gamma$ be a closed subset of $\overline{\Omega}$ such that $\overline{\Omega}\setminus \Gamma$ is dense in $\overline{\Omega}$. Then, for every $\alpha>0$, 
\begin{equation}\label{E:traceqedomain}
H^\alpha_{p,0}(\overline{\Omega}\setminus \Gamma)=\{u\in H^\alpha_p(\Omega):\ \big((\mathrm{E}_\Omega D^\beta u)^\sim|_{\Gamma}\big)_{|\beta|\leq m_s}=0\};
\end{equation}
here the extension operators $\mathrm{E}_\Omega$ may be different for each $\beta$.
\end{corollary}


Given a domain $\Omega$ having the $H^\alpha_p$-extension property and a non-zero Radon measure $\mu$ with $\Gamma=\supp\mu
\subset \overline{\Omega}$ and satisfying the hypotheses of Lemma \ref{L:smooth} (i), we can consider the composition 
\[[\mathrm{Tr}_{\Gamma,0}^\Omega]_\mu:=[\mathrm{Tr}_{\Gamma,0}]_\mu\circ \mathrm{E}_\Omega.\] 
The next corollary gives new results for general measures $\mu$. It is an immediate consequence of Lemma \ref{L:variant}.

\begin{corollary}\label{C:traceop}
Let $1<p<\infty$ and $\alpha>0$. Let $\Omega\subset \mathbb{R}^n$ be a domain satisfying the measure density condition. Let $\mu$ be a non-zero Radon measure with support $\Gamma=\supp\mu$ contained in $\overline{\Omega}$ and such that $\overline{\Omega}\setminus \Gamma$ is dense in $\overline{\Omega}$.
\begin{enumerate}
\item[(i)] Suppose that $d:\Gamma\to [0,\infty)$ is a Borel function such that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Then the operator $[\mathrm{Tr}_{\Gamma,0}^\Omega]_\mu:H^\alpha_p(\Omega)\to [\widetilde{B}(\Gamma)]_\mu$ is bounded, linear and surjective and does not depend on the particular choice of the extension operator $\mathrm{E}_\Omega$. 
\item[(ii)] If in addition $S_{d,\mu}(\Gamma)=\emptyset$ and \eqref{E:variant} holds, then 
$\ker  [\mathrm{Tr}_{\Gamma,0}^\Omega]_\mu=H^\alpha_{p,0}(\overline{\Omega}\setminus \Gamma)$.
This identity remains true if instead of \eqref{E:variant} we have $\alpha=\alpha_p(\Gamma)+1$ and $\mathcal{H}^{\dim_H\Gamma}(B\cap \Gamma)<\infty$ for every open ball $B$.
\end{enumerate}
\end{corollary}

The special case $\Gamma=\partial\Omega$ in (ii) gives $\ker [\mathrm{Tr}_{\partial\Omega,0}^\Omega]_\mu=H^\alpha_{p,0}(\Omega)$. 

\begin{remark} In the special case that $\Omega$ is a bounded $(\varepsilon,\delta)$-domain, $\Gamma=\partial\Omega$ a $d$-set with $n-1\leq d<n$, $\mu=\mathcal{H}^d|_{\partial\Omega}$, $1<p<\infty$ and $\frac{n-d}{p}<\alpha\leq 1$ the equality $\ker  [\mathrm{Tr}_{\partial\Omega,0}^\Omega]_\mu=H^\alpha_{p,0}(\Omega)$ was shown in  \cite[Theorem 3.5]{FarkasJacob2001}. Corollary \ref{C:traceop} extends this result to the natural parameter range conjectured in \cite[Remark 3.7]{FarkasJacob2001} and beyond the $d$-set case. 
\end{remark}

In the special case of a $d$-measure $\mu$ we obtain the following counterpart of Corollary \ref{C:dsettrace}.

\begin{corollary}\label{C:dsetdomain} 
Let $1<p<\infty$, let $\Omega\subset \mathbb{R}^n$ be a domain satisfying the measure density condition. 
Let $0<d\leq n$ and let $\mu$ be a $d$-measure with support $\Gamma=\supp\mu$ contained in $\overline{\Omega}$ and such that $\overline{\Omega}\setminus \Gamma$ is dense in $\overline{\Omega}$. Then 
\begin{equation}\label{E:keridentdomain}
\ker [\mathrm{Tr}_{\Gamma,m_t}^\Omega]_\mu=H^\alpha_{p,0}(\mathbb{R}^n\setminus \Gamma).
\end{equation}
holds for every $\alpha>\frac{n-d}{p}$, where 
\[[\mathrm{Tr}_{\Gamma,m}^\Omega]_\mu u:=([D^\beta \mathrm{E}_\Omega u]_\mu)_{|\beta|\leq m},\quad u\in H^\alpha_p(\Omega);\]
here the extension operators $\mathrm{E}_\Omega$ may be different for each $\beta$.
\end{corollary}

\begin{remark}\mbox{}
\begin{enumerate}
\item[(i)] For $\Gamma=\partial\Omega$ and positive integer $\alpha$ the identity \eqref{E:keridentdomain} was proved in \cite[Theorem 3]{Wallin91}.
\item[(ii)] Based on Corollary \ref{C:trace} one can also formulate a variant of Corollary \ref{C:dsetdomain} for more general measures $\mu$. We leave this to the reader.
\end{enumerate}
\end{remark}


\section{The convergence of Galerkin schemes}
% and {\color{blue}isometric isomorphisms}
\label{S:Galerkin}

We briefly comment on an application; for further detail see \cite{Ch-WCHR-PS2025}. Suppose that $n\geq 2$, $p=2$, $0<\alpha\leq 1$, $\Gamma$ is compact and \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Let $\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)$ denote the orthogonal complement of $\widetilde{H}_2^\alpha(\mathbb{R}^n\setminus \Gamma)$ in $H_2^\alpha(\mathbb{R}^n)$ and let $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ denote its topological dual. By restriction and trivial extension the space $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ can be identified with the space of all elements $f$ of $H^{-\alpha}_2(\mathbb{R}^n)$ with support in $\Gamma$, e.g., \cite[Cor.~3.4]{Ch-WHM2017}. Let $L^2(\Gamma,\mu)$ be the Hilbert space of all $\mu$-square integrable elements of $L^0(\Gamma,\mu)$. 

Under the stated assumptions  $\mu$ is upper $\underline{d}$-regular, for some $\underline{d}>n-2\alpha$, by Remark  \ref{R:upregd} (i), so that $[\mathrm{Tr}_{\Gamma,0}]_\mu:H_2^\alpha(\mathbb{R}^n)\to L^2(\Gamma,\mu)$ is a bounded linear operator, see \cite[Theorem~1]{J79} or \cite[Theorem 7.2.2]{AH96}. 
Its restriction \[[\mathrm{tr_\Gamma}]_\mu:=[\mathrm{Tr}_{\Gamma,0}]_\mu|_{\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)}\] 
to  $\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)$ has the adjoint $[\mathrm{tr_\Gamma}]_\mu^\ast:L^2(\Gamma,\mu)\to (\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$.

\begin{corollary}\label{C:denserange}
Let $n\geq 2$, $p=2$, $0<\alpha\leq 1$, let $\Gamma$ be compact and assume that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Then the following are equivalent:
\begin{enumerate}
\item[(i)] the equivalence \eqref{E:wish} holds, %with $p=2$,
\item[(ii)] the operator $[\mathrm{tr_\Gamma}]_\mu$ is injective,
\item[(iii)] the operator $[\mathrm{tr_\Gamma}]_\mu^\ast$ has dense image.
\end{enumerate}
A sufficient additional condition for the validity of (i),(ii) and (iii) is \eqref{E:suffconddx}.
\end{corollary}

Item (iii) in Corollary \ref{C:denserange} ensures the convergence of Galerkin schemes for integral equation formulations of time-harmonic %arising in 
acoustic scattering problems  for  sound soft fractal obstacles \cite{Ch-WCHR-PS2025,CCh-WCGHM25, CCh-WGHM24, Ch-WHM2017, Ch-WHMB2021}. Formulated in terms of functional analysis, the task, given some non-empty compact $\Gamma\subset \R^n$, is to find an element $\phi$ of $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ such that 
\begin{equation}\label{E:IE}
A\phi=g,
\end{equation}
where $A:(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast\to \mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)$ is a given invertible linear operator which is the sum of a coercive and a compact operator and $g\in \mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)$ is a given function. Now it is desirable to find a suitable sequence $(W_k)$ of finite dimensional subspaces $W_k$ of $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ and a sequence $(\phi_k)$ of elements $\phi_k\in W_k$ converging to $\phi$ in $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$. Since 
\[ \left\langle[\mathrm{tr_\Gamma}]_\mu^\ast f,u\right\rangle_{(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast \times \mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)}=\left( f, [\mathrm{tr_\Gamma}]_\mu u\right)_{L^2(\Gamma,\mu)},\qquad f\in L^2(\Gamma,\mu),\ u\in \mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma),\]
it seems convenient to construct a suitable sequence $(V_k)$ of finite dimensional subspaces in $L^2(\Gamma,\mu)$ and to try to \enquote{transfer} them to $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ using $[\mathrm{tr_\Gamma}]_\mu^\ast$.
If $(\pi_k)$ is a sequence of finer and finer partitions $\pi_k$ of $\Gamma$ in a $\mu$-a.e.\ sense, the sequence $(V_k)$ of spaces $V_k$ of $\pi$-locally constant functions is a good choice.  (Indeed, in the case that $\Gamma$ is the boundary of a bounded Lipschitz domain, this choice for $(V_k)$ is precisely a standard piecewise-constant boundary element method; see \cite[Remark~4.2]{CCh-WCGHM25}, \cite[Remark~3.4]{Ch-WCHR-PS2025}.)
If the mesh sizes of the $\pi_k$ go to zero as $k\to\infty$, then $(V_k)$ is \emph{asymptotically dense in $L^2(\Gamma,\mu)$}, meaning that
\[\lim_{k\to\infty} \min_{f_k\in V_k}\|f_k-f\|_{L^2(\Gamma,\mu)}=0,\quad f\in L^2(\Gamma,\mu).\]
The key observation is the following immediate consequence of Corollary \ref{C:trace}. The last sentence of this corollary is part of standard theory for the Galerkin method in the case that $A$ is invertible and the sum of a coercive and a compact operator; for details see \cite[Corollary~4.2]{Ch-WCHR-PS2025}.

\begin{corollary}\label{C:asympdense}
Let $n\geq 2$, $p=2$, $0<\alpha\leq 1$, let $\Gamma$ be compact and assume that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Let $(V_k)$ be asymptotically dense in $L^2(\Gamma,\mu)$. Then the sequence $(W_k)$ of spaces $W_k:=[\mathrm{tr_\Gamma}]_\mu^\ast(V_k)$ is asymptotically dense in $(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$ if and only if one (and hence all) of the conditions (i), (ii) or (iii) in Corollary \ref{C:denserange} holds. The Galerkin scheme for \eqref{E:IE}, based on the sequence $(W_k)$, converges for every $g\in \mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)$ if and only if $(W_k)$ is asymptotically dense, so if and only if one of the conditions (i), (ii) or (iii) in Corollary \ref{C:denserange} holds.
\end{corollary} 


We comment on a related fact. By \eqref{E:traceqe} and the assumptions in this section the image $[\widetilde{B}(\Gamma)]_\mu=[\mathrm{Tr}_{\Gamma,0}]_\mu(H_2^\alpha(\mathbb{R}^n))$ satisfies 
\[[\widetilde{B}(\Gamma)]_\mu=[\mathrm{tr}_\Gamma]_\mu(\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))\subset L^2(\Gamma,\mu).\] 
By definition $[\mathrm{tr_\Gamma}]_\mu:\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma)\to [\widetilde{B}(\Gamma)]_\mu$ is surjective, and we use $[\mathrm{tr_\Gamma}]_{\mu,s}$ as a shortcut notation for this operator. Its adjoint is $([\mathrm{tr_\Gamma}]_{\mu,s})^\ast: ([\widetilde{B}(\Gamma)]_\mu)^\ast\to (\mathbb{H}^\alpha(\mathbb{R}^n\setminus \Gamma))^\ast$. We state another direct consequence of Corollary \ref{C:trace} (cf.~\cite[Proposition~3.6]{Ch-WCHR-PS2025}).

\begin{corollary}\label{C:isometries}
Let $n\geq 2$, $p=2$, $0<\alpha\leq 1$, let $\Gamma$ be compact and assume that \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold. Then the following are equivalent: 
\begin{enumerate}
\item[(i)] the equivalence \eqref{E:wish} holds, %with $p=2$,
\item[(ii)] the operator $[\mathrm{tr_\Gamma}]_{\mu,s}$ is an isometric isomorphism,
\item[(iii)] the operator $([\mathrm{tr_\Gamma}]_{\mu,s})^\ast$ is an isometric isomorphism.
\end{enumerate}
A sufficient additional condition for the validity of (i),(ii) and (iii) is \eqref{E:suffconddx}.
\end{corollary}


\section{Local isoperimetric inequalities}\label{S:iso}

We quote an \enquote{isoperimetric} inequality from \cite[Section 8.5]{Mazya85} which relates measures and capacities of Borel sets, see \eqref{E:mazyaoutput} below. Let $\Phi:[0,\infty)\to [0,\infty)$ be an increasing function such that $t\mapsto t\Phi(t^{-1})$ decreases at infinity with limit $\lim_{t\to \infty}t\Phi(t^{-1})=0$. Let 
\[\Psi(t):=\begin{cases}
(t\Phi(t^{-1}))^{p'-1}\ &\text{if $\alpha p<n$},\\
t(\Phi(t^{1-p}))^{p'-1}\ &\text{if $\alpha p=n$}.
\end{cases} \]

In the case $\alpha p<n$ we assume that, for some $c>0$,
\begin{equation}\label{E:intcondition}
\int_u^\infty \Psi(t)\frac{dt}{t}\leq c\:\Psi(u)
\end{equation}
for all $u>0$. In the case $\alpha p=n$ we assume that for any $u_0>0$ there is a constant $c>0$ such that \eqref{E:intcondition} holds for all $u\geq u_0$. 

\begin{examples} If $\alpha p\leq n$ and $p<q<\infty$, then $\Phi(t):=t^{q/p}$, $t\geq 0$, satisfies the above conditions.
For $\alpha p=n$ and $0<d<\infty$ also the function $\Phi(t):=\exp(-dt^{1-p'})$, $t>0$, $\Phi(0):=0$, satisfies them.
\end{examples}

We use the following variant of \cite[Section 8.5,  Corollary 2]{Mazya85}. 

\begin{lemma}\label{L:Mazya}
Let $\nu$ be a finite Borel measure on $\mathbb{R}^n$, $1<p<\infty$ and $0<\alpha\leq \frac{n}{p}$. Let $\Phi$ be as specified above. If there are constants $r_0>0$ and $c_0>0$ such that 
\begin{equation}\label{E:mazyainput}
\nu(B(y,\varrho))\leq\Phi\big(c_0\:\cpct_{\alpha,p}(B(y,\varrho))\big)
\end{equation}
for all $y\in\mathbb{R}^n$ and $0<\varrho<r_0$, then for any Borel set $E\subset \mathbb{R}^n$ with $\diam(E)<r_0$ and $\cpct_{\alpha,p}(E)<\infty$ we have 
\begin{equation}\label{E:mazyaoutput}
\nu(E)\leq c_1\,\Phi(c_1\,\cpct_{\alpha,p}(E)),
\end{equation}
where $c_1>0$ is constant depending only on $n$, $p$, $\alpha$, $\Phi$ and $c_0$.
\end{lemma}

The inequality \eqref{E:mazyaoutput} encodes an embedding, see \cite[Theorem 7.2.1]{AH96} or \cite[Section 8.6]{Mazya85}, a classical variant was used in \cite{Caetano2000, JW84, Wallin91, Ziemer}.


\begin{proof}
The original \cite[Section 8.5, Corollary 2]{Mazya85} follows from \cite[Section 8.5, Theorem]{Mazya85} and its  immediate consequence \cite[Section 8.5, Corollary 1]{Mazya85}.

For the case $\alpha p<n$ the assumptions stated above ensure that the conclusion of \cite[Section 8.5, Theorem]{Mazya85} holds; 
the proof there uses only the monotonicity of $\Phi$ and inequality \eqref{E:intcondition}. Arguing as in \cite[Section 8.5, Remark 2]{Mazya85}, we see that under the additional assumption that $\diam(E)<r_0$ also \cite[Section 8.5, Corollary 2]{Mazya85} can be applied to obtain \eqref{E:mazyaoutput}, even if \eqref{E:mazyainput} below holds only for $0<\varrho<r_0$ and not for all $\varrho>0$, as the original formulation of \cite[Section 8.5, Corollary 2]{Mazya85} would require. 

For the case $\alpha p=n$ an inspection of the second part \cite[p. 379/380]{Mazya85} of the proof of \cite[Section 8.5, Theorem]{Mazya85} shows that it suffices to have \eqref{E:intcondition} only for $u\geq u_0$. As in the other case, \cite[Section 8.5, Corollary 2]{Mazya85} then gives \eqref{E:mazyaoutput}, provided that $\diam(E)<r_0$.
\end{proof}


From Lemma \ref{L:Mazya} we deduce suitable localized estimates.

\begin{corollary}\label{C:isoper}
Let $\mu$ be a  non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$ and $1<p<\infty$. 
\begin{enumerate}
\item[(i)] If $0<\alpha<\frac{n}{p}$ and \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold, then for any $x\in \Gamma$ there are constants $c_2(x)>0$ and $r_2(x)>0$ such that for any Borel set $E\subset \mathbb{R}^n$ and any $0<\varrho<r_2(x)$ we have 
\begin{equation}\label{E:isoperd}
\mu(B(x,\varrho)\cap E)\leq c_2(x)\cpct_{\alpha,p}(B(x,\varrho)\cap E)^{\frac{q(x)}{p}},
\end{equation}
where $q(x)=\frac{pd(x)}{n-\alpha p}$. If $\alpha=\frac{n}{p}$ and \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold, then the same is true with \eqref{E:isoperd} replaced by
\begin{equation}\label{E:isoperexp}
\mu(B(x,\varrho)\cap E)\leq c_2(x)\exp\left(-d(x)c_1^{1-p'}\cpct_{\alpha,p}(B(x,\varrho)\cap E)^{1-p'}\right),
\end{equation}
where $c_1$ is as in \eqref{E:mazyaoutput}.
\item[(ii)] If $\alpha=\frac{n}{p}$ and \eqref{E:tracecondhx} and \eqref{E:upperdenshx} hold, then \eqref{E:isoperd} holds with $q(x)=\frac{p\kappa(x)}{p-1}$.
\end{enumerate}
\end{corollary}

\begin{proof}
To see (i), let $x\in \Gamma$, let $r(x)$ and $d(x)$ be as in \eqref{E:upregdx}; we may and do assume that $r(x)<1$. Consider the finite Borel measure $\nu:=\mu|_{B(x,r(x))}$. Similarly as in Remark \ref{R:main} (ii) we can see that \eqref{E:upregdx} implies 
\begin{equation}\label{E:aboveestimate}
\nu(B(y,\varrho))\leq 2^{d(x)}c(x)\varrho^{d(x)},\quad y\in \mathbb{R}^n,\ 0<\varrho<r_2(x), 
\end{equation}
where $r_2(x):=\frac{r(x)}{2}$. 

Suppose first that $0<\alpha<\frac{n}{p}$. It is well known that, for some constant $c_3>0$, $\cpct_{\alpha,p}(B(y,\varrho))\geq c_3\,\varrho^{n-\alpha p}$ for all $\varrho>0$ and $y\in\mathbb{R}^n$, see \cite[Propositions 5.1.2 and 5.1.4]{AH96}. Together with \eqref{E:aboveestimate} this gives 
\[\nu(B(y,\varrho))\leq 2^{d(x)}c(x)(c_3^{-1}\cpct_{\alpha,p}(B(y,\varrho)))^{q(x)/p},\quad y\in \mathbb{R}^n,\ 0<r<r_2(x),\]
which is \eqref{E:mazyainput} with $r_0=r_2(x)$, $c_0=c_3^{-1}$, and $\Phi(t)=2^{d(x)}c(x)t^{q(x)/p}$. By  Lemma \ref{L:Mazya} we have \eqref{E:isoperd} with $c_2(x)=2^{d(x)}c_1^{1+\frac{q(x)}{p}}c(x)$.

Now suppose that $\alpha=\frac{n}{p}$. In this case there is some $c_4>0$ such that 
\begin{equation}\label{E:logcap}
\cpct_{\alpha,p}(B(y,\varrho))\geq c_4\,(-\log \varrho)^{1-p} 
\end{equation}
for all $0<\varrho<r(x)$ and $y\in\mathbb{R}^n$, see \cite[Proposition 5.1.3]{AH96}. This fact, together with \eqref{E:aboveestimate}, gives
\[\nu(B(y,\varrho))\leq 2^{d(x)}c(x)\exp(-d(x)(c_4^{-1} \cpct_{\alpha,p}(B(y,\varrho)))^{1-p'}),\quad y\in \mathbb{R}^n,\ 0<r<r_2(x),\]
which is \eqref{E:mazyainput} with $r_0=r_2(x)$, $c_0=(c_4)^{-1}$ and 
\begin{equation}\label{E:Phi}
\Phi(t)=2^{d(x)}c(x)\exp(-d(x)t^{1-p'}). 
\end{equation}
By Lemma \ref{L:Mazya} we obtain \eqref{E:isoperexp} with $c_2(x)=2^{d(x)}c_1c(x)$.

To see (ii) we can proceed similarly. For any $x\in \Gamma$, estimate \eqref{E:upreghx} holds with numbers $c(x)$, $\kappa(x)$ and $r(x)<1$, and for $\nu$ as defined above, we find that 
\[\nu(B(y,\varrho))\leq c(x)2^{\kappa(x)}(-\log \varrho)^{-\kappa(x)}, \quad y\in \mathbb{R}^n,\ 0<\varrho<r_2(x),\]
where $r_2(x):=\min\{\frac{1}{4},\frac{r(x)}{2}\}$. Combining with \eqref{E:logcap}, we obtain 
\[\nu(B(y,\varrho))\leq c(x)2^{\kappa(x)}(c_4^{-1}\cpct_{\alpha,p}(B(y,\varrho)))^{\frac{\kappa(x)}{p-1}},\quad y\in \mathbb{R}^n,\ 0<r<r_2(x),\]
which is again \eqref{E:mazyainput}, now with $r_0=r_2(x)$, $c_0=(c_4)^{-1}$ and $\Phi(t)=2^{\kappa(x)}c(x)t^{q(x)/p}$. Lemma \ref{L:Mazya} gives \eqref{E:isoperd} with $c_2(x)=2^{\kappa(x)}c_1^{1+\frac{q(x)}{p}}c(x)$.
%
%{\color{blue} that} \eqref{E:mazyainput} {\color{blue} holds for $0<\varrho < r_0$,} with {\color{blue} $r_0=r_2(x)$, $c_0=c_3^{-1}$, and } 
%\begin{equation}\label{E:polyphi}
%\Phi(t)=2^{d(x)}c(x)t^{q(x)/p}, 
%\end{equation}
%and by  Lemma \ref{L:Mazya} we have \eqref{E:isoperd} with $c_2(x)=2^{d(x)}c_1^{1+\frac{q(x)}{p}}c(x)$. In the case $\alpha=\frac{n}{p}$ we can use the fact that{\color{blue}, for some $c_4>0$,} 
%\begin{equation}\label{E:logcap}
%\cpct_{\alpha,p}(B(y,\varrho))\geq {\color{blue}c_4}\,(-\log \varrho)^{1-p} 
%\end{equation}
%for all $0<\varrho<r(x)$ and $y\in\mathbb{R}^n$, see \cite[Proposition 5.1.3]{AH96}, to obtain \eqref{E:mazyainput} {\color{blue} for $0<\varrho < r_0$,} with {\color{blue} $r_0=r_2(x)$, $c_0=(c_4)^{-1}$, and }
%\begin{equation}\label{E:Phi}
%\Phi(t)=2^{d(x)}c(x)\exp(-d(x)t^{1-p'}).
%\end{equation} 
%Lemma \ref{L:Mazya} then gives \eqref{E:isoperexp} with $c_2(x)=2^{d(x)}c_1c(x)$. Item (ii) follows similarly, combining \eqref{E:polyphi} and \eqref{E:logcap}.
\end{proof}

\begin{remark} Recall the notion of $(\alpha,p)$-equivalence from Remark \ref{R:counter}. Under the hypotheses of Lemma \ref{L:smooth} any set $E\subset \mathbb{R}^n$ which is  $(\alpha,p)$-equivalent to a Borel set $A\subset \mathbb{R}^n$ is an element of the completion of the Borel $\sigma$-field on $\mathbb{R}^n$ with respect to $\mu$ and we have $\mu(E\Delta A)=0$. By the subadditivity of $\cpct_{\alpha,p}$ and the monotonicity of the functions $\Phi$, the conclusions of Corollary \ref{C:isoper} remain true if we only require that $E\subset \mathbb{R}^n$ is $(\alpha,p)$-equivalent to a Borel set.
\end{remark}

\section{Thin sets, fine continuity and averages}\label{S:proof}



Let $1<p\leq \frac{n}{\alpha}$. Recall that a set $E\subset \mathbb{R}^n$ is said to be \emph{$(\alpha,p)$-thin at $x\in\mathbb{R}^n$} if 
\begin{equation}\label{E:thin}
\int_0^1\left(\frac{\cpct_{\alpha,p}(B(x,r)\cap E)}{r^{n-\alpha p}}\right)^{p'-1}\frac{dr}{r}<\infty,
\end{equation}
see \cite[Definition 6.3.7]{AH96}. Original sources for the $(\alpha,p)$-case are \cite{AdamsMeyers, HedbergWolff, Meyers75}. Classical results on thin sets and further context can be found in \cite{Brelot40, Brelot44, PSz45, Wiener} and in particular in \cite[Chapitre IV]{Deny50}. 

Combining the notion of $(\alpha,p)$-thinness with the density conditions \eqref{E:suffconddx} and \eqref{E:suffcondh} we obtain the next observation.

\begin{lemma}\label{L:lessthanone}
Let $\mu$ be a  non-zero Radon measure on $\mathbb{R}^n$, $\Gamma=\supp\mu$, $1<p<\infty$ and $x\in \Gamma$. Let 
$E\subset \mathbb{R}^n$ be a Borel set that is $(\alpha,p)$-thin at $x$. If
\begin{enumerate}
\item[(i)] $0<\alpha\leq \frac{n}{p}$, \eqref{E:traceconddx} and \eqref{E:upperdensdx} hold and $\bar{D}^{d(x)}\mu(x)>0$ or
\item[(ii)] $\alpha=\frac{n}{p}$, \eqref{E:tracecondhx} and \eqref{E:upperdenshx} hold and $\bar{D}^{h_{\kappa(x)}}\mu(x)>0$,
\end{enumerate}
then there is a sequence $(r_k)$ such that $r_k\downarrow 0$ as $k\to \infty$ and  
\begin{equation}\label{E:lessthanone}
\sup_k\frac{\mu(B(x,r_k)\cap E)}{\mu(B(x,r_k))}<1.
\end{equation}
\end{lemma}

\begin{proof}
To see (i), suppose first that $0<\alpha<\frac{n}{p}$. Substituting $t=r^{\frac{\alpha p-n}{p-1}}$ we see that 
\eqref{E:thin} is equivalent to the integrability of the decreasing function $\varphi(t):=(\cpct_{\alpha,p}(B(x,t^{\frac{p-1}{\alpha p-n}})\cap E)^{p'-1}$ over $(1,\infty)$, which forces $\lim_{t\to\infty}t\varphi(t)=0$, cf. \cite[p. 170]{Deny50}. Together with \eqref{E:isoperd}, this gives 
\[\lim_{r\to 0}\frac{\mu(B(x,r)\cap E)^{p/q(x)}}{r^{n-\alpha p}}\leq c_5(x)\:\lim_{r\to 0}\frac{\cpct(B(x,r)\cap E)}{r^{n-\alpha p}}=0\]
with a suitable constant $c_5(x)>0$. Alternatively, one can use \cite[formula (6.3.2)]{AH96} and \eqref{E:isoperd}. We arrive at
\[\lim_{r\to 0}\frac{\mu(B(x,r)\cap E)}{r^{d(x)}}=0.\]
Since the upper density is positive, there is a sequence $(r_k)$ with $r_k\downarrow 0$ as $k\to \infty$ and some $\varepsilon>0$ such that $\mu(B(x,r_k))>\varepsilon\: r_k^{d(x)}$ for all $k$. Combining, we obtain \eqref{E:lessthanone}. Now suppose that $\alpha=\frac{n}{p}$. By \eqref{E:thin} and the substitution $t=-\log r$ we have 
\begin{equation}\label{E:Wienerlog}
\lim_{r\to 0}\cpct_{\alpha,p}(B(x,r)\cap E)(-\log r)^{p-1}=0.
\end{equation}
The strictly increasing function $\Phi$ in \eqref{E:Phi} is invertible, and $\Phi^{-1}(s)\geq (-\frac{2}{d(x)}\log(s))^{1-p}$ for all $s\leq \frac{1}{c(x)2^{d(x)}}$. 
This, together with \eqref{E:isoperexp} and \eqref{E:Wienerlog}, shows that given $\varepsilon>0$, we have 
\[\Big(-\frac{4}{d(x)}\log \mu(B(x,r)\cap E)\Big)^{1-p}<\varepsilon(-\log r)^{1-p}\] for all sufficiently small $r$. The positivity of the upper density gives
\[(-2 d(x)\log r_k)^{1-p}\leq \big(-\log\mu(B(x,r_k))\big)^{1-p}\]
along a sequence $(r_k)$ as before. Combining the above, and picking $\varepsilon$ to satisfy $0<\varepsilon<8^{1-p}$, gives
\[\big(-\log\mu(B(x,r_k)\cap E)\big)^{1-p}< (-\log \mu(B(x,r_k))^{1-p}\]
for all sufficiently large $k$. Applying the strictly increasing function $t\mapsto \exp(-t^{1-p'})$ to both sides gives   \eqref{E:lessthanone}. 

To prove (ii) one can proceed similarly, combining \eqref{E:isoperd} with $q(x)$ as in Corollary \ref{C:isoper} (ii) and \eqref{E:Wienerlog} to arrive at
\[\lim_{r\to 0}\big(\mu(B(x,r)\cap E)\big)^{p/q(x)}(-\log r)^{p-1}=0.\]
By the positivity of the upper density we can again find a sequence  $(r_k)$ as before and some $\varepsilon>0$ such that 
$\mu(B(x,r_k))^{p/q(x)}>\varepsilon(-\log r_k)^{1-p}$ for all $k$. Together this gives \eqref{E:lessthanone}.
\end{proof}

\begin{remark}
Lemma \ref{L:lessthanone} actually holds for $E\subset \mathbb{R}^n$ $(\alpha,p)$-equivalent to a Borel set and $(\alpha,p)$-thin at $x$.
\end{remark}

Recall that a function $g:\mathbb{R}^n\to\mathbb{R}$ is said to be \emph{$(\alpha,p)$-finely continuous at $x\in\mathbb{R}^n$} if for any $\varepsilon>0$ the set $E_x^\varepsilon(g):=\{y\in\mathbb{R}^n:\ |g(x)-g(y)|\geq \varepsilon\}$ is $(\alpha,p)$-thin at $x$. See \cite[Definition 6.4.2]{AH96}, plus \cite{Hedberg72, HedbergWolff, Meyers75} and \cite{Brelot71, Fuglede65, Fuglede71} for further background. It is well known that if $g$ is $(\alpha,p)$-finely continuous at $x\in\mathbb{R}^n$, then there is a set $E_x\subset\mathbb{R}^n$, $(\alpha,p)$-thin at $x$ and such that $\lim_{y\to x,\ y\in  \mathbb{R}^n\setminus E_x}g(y)=g(x)$, 
see \cite[Proposition 6.4.3]{AH96}. The proof of this result shows that one can take $E_x$ to be the union of intersections $E_x^{\varepsilon_k}(g)\cap B(x,r_k)$, where $(\varepsilon_k)$ and $(r_k)$ are sequences with $\varepsilon_k\downarrow 0$ and $r_k\downarrow 0$ as $k\to \infty$, see  \cite[p. 177]{AH96}. It is also well-known that an $(\alpha,p)$-quasi continuous function is $(\alpha,p)$-finely continuous at $(\alpha,p)$-q.e.\ $x\in\mathbb{R}^n$, see \cite[Theorem 6.4.5]{AH96}, \cite{Hedberg72, HedbergWolff, Meyers75} and \cite{Deny50, Fuglede65}.

We verify our main results by considering average limits based on fine continuity; their existence is ensured by assumptions \eqref{E:suffconddx} respectively \eqref{E:suffcondh} and Lemma \ref{L:lessthanone}.

\begin{proof}[Proof of Theorems \ref{T:main} and \ref{T:main_logcase}]
By Lemma \ref{L:smooth} it suffices to prove that the $\mu$-a.e.\ vanishing of $\widetilde{u}$ on $\Gamma$ implies its vanishing $(\alpha,p)$-q.e.\ on $\Gamma$.

We can find an $(\alpha,p)$-quasi continuous representative $\widetilde{u}$ which is a real valued Borel function on $\mathbb{R}^n$. This follows from \cite[Propositions 2.3.7 and 6.1.3]{AH96}. Alternatively, it can be concluded from the density of $C_c^\infty(\mathbb{R}^n)$ in $H^\alpha_p(\mathbb{R}^n)$, cf. \cite[Theorem 2.1.3]{FOT2011}. By the preceding we can find a set $N_0\subset \mathbb{R}^n$ of zero $(\alpha,p)$-capacity such that $\widetilde{u}$ is $(\alpha,p)$-finely continuous at all $x\in \mathbb{R}^n\setminus N_0$. For any such $x$, there is a Borel set $E_x\subset\mathbb{R}^n$, $(\alpha,p)$-thin at $x$, such that 
\begin{equation}\label{E:finelim}
\lim_{y\to x,\ y\in  \mathbb{R}^n\setminus E_x}\widetilde{u}(y)=\widetilde{u}(x).
\end{equation}
Note that since $\widetilde{u}$ is Borel, the sets $E_x^\varepsilon(\widetilde{u})$ are Borel sets and therefore also $E_x$, if chosen as described above, is a Borel set.

By \eqref{E:suffconddx} respectively \eqref{E:suffcondh} we can find a set $N_1\subset \mathbb{R}^n$ with $\cpct_{\alpha,p}(N_1)=0$ such that at all $x\in \Gamma\setminus N_1$ we have  $\bar{D}^{d(x)}\mu(x)>0$ respectively $\bar{D}^{h_{\kappa(x)}}\mu(x)>0$.

The set $N:=N_0\cup N_1$ has zero $(\alpha,p)$-capacity. Now let $x\in \Gamma\setminus N$. By Lemma \ref{L:lessthanone} there is a sequence $(r_k)$ such that $r_k\downarrow 0$ as $k\to \infty$ and $\mu(B(x,r_k)\setminus E_x)>0$ for all $k$. Using \eqref{E:finelim} we obtain  
\[\widetilde{u}(x)=\lim_{k\to\infty} \frac{1}{\mu(B(x,r_k)\setminus E_x)}\int_{B(x,r_k)\setminus E_x} \widetilde{u}(y)\mu(dy).\]
If now $\widetilde{u}=0$ $\mu$-a.e.\ on $\Gamma=\supp\mu$, then this gives $\widetilde{u}(x)=0$. It follows that $\widetilde{u}=0$ on $\Gamma\setminus N$, and this confirms the desired implication.
\end{proof}





