\section{Preliminaries}
\label{sec:prelim}
%\subparagraph*{Treewidth.}

All our statements concern undirected graphs with real positive edge weights.
In an unweighted graph, each weight is set to one. 

\begin{definition}[Treewidth]\label{def:prelim:tw}
A \emph{tree decomposition} of a graph $G$ is a pair $(T, \chi)$ where $T$ is a tree, and~$\chi \colon V(T) \to 2^{V(G)}$ is a function, such that:
\begin{enumerate}
    \item for each~$v \in V(G)$ the nodes~$\{t \mid v \in \chi(t)\}$ form a {non-empty} connected subtree of~$T$, \label{item:tree:based:connected}
    \item for each edge~$uv \in E(G)$ there is a node~$t \in V(T)$ with~$\{u,v\} \subseteq \chi(t)$. \label{item:tree:based:edge}
    %\item For each vertex~$v \in L$, there is a unique~$t \in V(T)$ for which~$v \in \chi(t)$,  with~$t$ being a leaf of~$T$. \label{item:tree:based:unique}
    %\item For each node~$t \in V(T)$, the graph~$G[\chi(t) \cap L]$ belongs to~$\hh$. \label{item:tree:h:decomp:base}
\end{enumerate}
{The \emph{width} of $(T, \chi)$ is defined as~$\max_{t \in V(T)} |\chi(t)| - 1$.}
The \emph{treewidth} of a graph $G$ (denoted $\tw(G))$ is the minimal width a tree decomposition of $G$.
\end{definition}

%Linear local treewidth for apex-minor-free \cite{DemaineH04} and new polynomial bound \cite{hendrey2025polynomial}.

\subparagraph*{VC dimension.}
A set system is a collection $\fcal$ of subsets of some set $U$.
We say that a subset $Y \sub A$ is {\em shattered} by $\fcal$ if $\{Y \cap S \colon S \in \fcal\} = 2^Y$ , that is,
every subset of $Y$ is an intersection of $Y$ with some $ S \in \fcal$. The VC dimension of a set system is the size of the largest  shattered subset. The notion of VC dimension
was introduced by Vapnik and Chervonenkis~\cite{vapnik2015uniform}. What is important to us, a set system of bounded VC dimension cannot be too large.

\begin{lemma}[Sauer–Shelah Lemma \cite{sauer1972density}]
\label{lem:size-bound}
    Let $\fcal$ be a set system  of VC dimension $d$ over a set of size $m$.
    Then $|\fcal| = \Oh(m^d)$.
\end{lemma}

\subsection{Additive core-sets}

For a vector $\bf x \in \mathbb{R}^k$ its $\ell_\infty$-norm is defined as $\ell_\infty({\bf x}) = \max_{i=1}^k |x_i|$.

\begin{definition}[\cite{li2019planar}]
For a sequence of vertices $S = (s_0,\dots,s_{k-1})$ from $G$ we define the {\em distance tuple} of $v$ with respect to $S$ as $\Phi_S(v) = \left(d_G(v,s_0), \dots, d_G(v,s_{k-1})\right)$.

For a vertex set $V$, a subset $V' \sub V$ is called a {\em $\delta$-additive core-set} with respect to $S$ if for every $v \in V$ there exists $v' \in V'$ such that $\ell_\infty(\Phi_S(v) - \Phi_S(v')) \le \delta$.
\end{definition}

We will take advantage of the bound on VC dimension of certain set systems related to a~graph metric.
Le and Wulff-Nilsen~\cite{LeW24} considered a slight modification of the set systems introduced by Li and Parter~\cite{li2019planar}, and so they denoted them by ${\cal \widehat{LP}}$.

\begin{definition}[\cite{LeW24}]
\label{def:vc}
    Let $G$ be an  edge-weighted graph, $S$ be a $k$-tuple of vertices from $G$, and $M \sub \rr$.
    For $v \in V(G)$ we define:

\[
\hat{X}_v = \{(i,\Delta) \colon i \in [1,k-1],\, \Delta \in M,\, d_G(v,s_i) - d_G(v,s_0) \le \Delta\}. 
\]
Let ${\cal \widehat{LP}}_{G,M}(S) = \{{\hat X}_v \colon v \in V(G)\}$ be a collection of subsets of the ground set $[k - 1] \times M$.
\end{definition}

\begin{theorem}[{\cite[Theorem 1.3]{LeW24}}]
\label{lem:vc-bound}
    Let $G$ be an  edge-weighted $K_h$-minor free graph and $S,M$ be as in \Cref{def:vc}.
    Then ${\cal \widehat{LP}}_{G,M}(S)$ has VC dimension at most $h-1$.
\end{theorem}

We adapt the construction of additive core-sets from~\cite{li2019planar} to rely on the set system ${\cal \widehat{LP}}$.

\lemCoreSet*
\begin{proof}
    Let $D \ =\diam(G)$, $\delta = \eps\cdot D/2$, and $z = \lceil 2/\eps \rceil$.
    Next, we choose $M = \{j\cdot \delta \colon j \in [-z,z]\}$.
    We will extend \Cref{def:vc} slightly.
    For vertices $u,v$ we define $d'(u,v)$ as the largest integer $j$ for which $j\cdot\delta \le d_G(u,v)$.
    Note that $d'(u,v)$ is always bounded by $z$.
    For a vertex $v$ let ${\hat X}^\circ_v$ be the pair $(d'(v,s_0), {\hat X}_v)$.
    By \Cref{lem:vc-bound} and \Cref{lem:size-bound}, the family $\{{\hat X}_v \colon v \in V(G)\}$ has size $\Oh\br{((k-1)\cdot |M|)^{h-1}} = \Oh\br{(k/ \eps)^{h-1}}$.
    It follows that the family $\{{\hat X}^\circ_v \colon v \in V(G)\}$ has  $\Oh\br{k^{h-1} \eps^{-h}}$ elements. 

    We construct $U'$ by picking for each $X \in \{{\hat X}^\circ_v \colon v \in V(G)\}$ an arbitrary vertex $v \in U$ with ${\hat X}^\circ_v = X$.
    Then $|U'| = \Oh\br{k^{h-1} \eps^{-h}}$.
    To show that $U'$ is an $(\eps D)$-additive core-set, pick $u \in U$.
    We need to prove that there exists $u' \in U'$ such that $\ell_\infty(\Phi_S(u) - \Phi_S(u')) \le \eps D$.
    By construction, there is $u' \in U'$ for which ${\hat X}^\circ_u = {\hat X}^\circ_{u'}$.
    Now we need to argue that for each $i \in [0,k-1]$ it holds that $|d_G(u,s_i) - d_G(u',s_i)| \le \eps D$. 

    The simplest case is for $i = 0$.
    As $d'(u,s_0) = d'(u',s_0)$, there is an integer $j$ such that both $d_G(u,s_0),\, d_G(u',s_0)$ belong to the interval $[j\cdot\delta,\, (j+1)\cdot\delta)$.
    Hence $|d_G(u,s_0) - d_G(u',s_0)| \le \delta = \eps D/2$. 

    Now consider $i \ge 1$.
    Let $j$ be the largest integer (possibly negative) for which $d_G(u,s_i) - d_G(u,s_0) \le j \cdot \delta$.
    We define $j'$ analogously with respect to $u'$.
    Note that $j,j' \in [-z,z]$. 
    Because ${\hat X}_u = {\hat X}_{u'}$ it must be $j=j'$.
    By the same argument as before, the numbers $x = d_G(u,s_i) - d_G(u,s_0)$, $y = d_G(u',s_i) - d_G(u',s_0)$ differ by at most $\delta$.
    Finally, since $|d_G(u,s_0) - d_G(u',s_0)| \le \delta$ we obtain that $|d_G(u,s_i) - d_G(u',s_i)| \le 2\delta = \eps D$.
\end{proof}

