\begin{restatable}[$\bigstar$]{lemma}{lemLocal}
\label{lem:local-tw}
    Let $H$ be an apex graph.
    Given a connected edge-weighted $n$-vertex $H$-minor-free graph $G$ and $\delta > 0$, we can in time $\Oh(n\log n)$ find a $\delta$-radius clustering $\ccal$ of $G$ and a layering function $\layer \colon V(G_\ccal) \to \nn$ such that the following hold.
    \begin{enumerate}
        %\item Removing each color class gives a subgraph of $G_\ccal$ of treewidth $\Oh_K(p)$.
        %\item For each $u,v \in V(G)$ there is a color $c \in [4p]$, depending only on colors of $u,v$, such that if $d_G(u,v) \le \delta\cdot p$ then the $(u,v)$-distance is preserved after removal of color $c$. \micr{return $p$ different graphs?}
        \item For an interval $I \sub \nn$
        of size $p$, the graph $G^I_\ccal$ has treewidth $\Oh_H(p)$.\label{item:local:interval}
        \item The treewidth of $G_\ccal$ is bounded by $\Oh_H(\diam(G) / \delta)$.\label{item:local:tw}
        \item For each $u,v \in V(G)$ and $p \in \nn$ satisfying $d_G(u,v) \le \delta\cdot p$, it holds that $|\layer(u) - \layer(v)| \le p$. In this case, there is an interval $I \sub \nn$ depending only on $(\layer(u),\layer(v),p)$, such that $|I| \le 2p+1$ and the
        $(u,v)$-distance is the same in $G$ and~$G^I$. \label{item:local:distance}
    \end{enumerate}
\end{restatable}
\hspace{0.1cm}

The proof constructs the layering by analyzing a shortest-path tree $T$ rooted at an arbitrary vertex $r$.
Then the $j$-th layer corresponds to vertices whose distance from $r$ belongs to $[j\cdot\delta, \,j\cdot\delta + \delta)$.
The clustering $\ccal$ is obtained by contracting all the edges in $T$ connecting vertices sharing the same layer.

Clearly, each root-to-leaf path in $T$ traverses at most $\diam(G) / \delta$ layers, which bounds the (unweighted) diameter of $G_\ccal$.
Since $G_\ccal$ is a contraction of $G$, it is $H$-minor-free as well and we can take advantage of the local treewidth property.
A similar argument yields \Cref{item:local:interval} while \Cref{item:local:distance} follows from the triangle inequality.

\Cref{lem:local-property} only guarantees that $\tw(G_\ccal)$ can be bounded in terms of $\eps$, without providing an efficient way to construct a tree decomposition. 
Moreover, the known algorithms for computing optimal (or $\Oh(1)$-approximate) tree decomposition require time exponential in treewidth, whereas we aim at polynomial dependence on $\eps$.
Luckily, there is one algorithm available that suits our needs, with a bit worse width guarantee.

While several algorithms rely on dynamic programming over a tree decomposition to compute the diameter exactly~\cite{AbboudWW16, Eppstein00, Husfeldt16}, we cannot afford such an strategy due to prohibitive error accumulation.
Instead, we will turn the decomposition into a balanced one, %(so that its depth is $\Oh(\log n)$), 
again by increasing its width slightly, and use it to build our data structures. %~\cite{chatterjee2014optimal}.

\begin{lemma}\label{lem:prelim:twd-compute}
    There is an algorithm that, given a graph $G$ of treewidth at most $k$, runs in time $\Oh(k^7\cdot n\log n)$ and outputs a binary rooted tree decomposition of $G$ of width $\Oh(k^2)$, depth $\Oh(\log n)$, and size $\Oh(n)$.
\end{lemma}
\begin{proof}
    First, in time $\Oh(k^7\cdot n\log n)$ one can compute a tree decomposition $(T,\chi)$ of $G$ of width $k' = \Oh(k^2)$~\cite{FominLSPW18}.
    By a standard argument, we can modify $(T,\chi)$ to have size $\Oh(n)$.
    Next, we turn $(T,\chi)$ into a binary rooted tree decomposition of depth $\Oh(\log n)$ and width at most $4k' + 3$ in time $\Oh(n)$~\cite{chatterjee2014optimal}.
    This also preserves the bound $|V(T)| = \Oh(n)$.
    %The running time of the latter procedure is linear in the size of $T$, which is obviously  bounded by the running time of the first procedure.
\end{proof}

\section{Processing a Tree Decomposition}
\label{sec:tree}

We will need an  argument to reroute paths to go through a center $c_i$ of some cluster $C_i$.

\begin{lemma}\label{lem:path-touch}
    Let $G$ be an edge-weighted graph, $u,v,w \in V(G)$, and let $C$ be a vertex set contained in the $\delta$-radius ball around $w$.
    Suppose there is a shortest $(u,v)$-path $P$ in $G$ that intersects $C$.
    Then $d_G(u,w) + d_G(w,v) \le d_G(u,v) + 2\delta$.
\end{lemma}
\begin{proof}
    Orient the path $P$ from $u$ to $v$ and define $u',v'$ as the first and the last vertices from $C$ appearing on $P$.
    Since $u',v'$ lie on a shortest $(u,v)$-path, we have $d_G(u,u') + d_G(v',v) \le d_G(u,v)$.
    Next, it holds that each of $d_G(w,u')$, $d_G(w,v')$ is at most $\delta$.
    Hence $d_G(u,w) \le d_G(u,u') + \delta$ and $d_G(w,v) \le d_G(v',v) + \delta$, which yields the desired inequality.
\end{proof}



We will now show how, using a tree decomposition of the cluster graph of width $\Oh((1/\eps)^2)$, to construct a distance oracle and estimate eccentricities.
We give a unified proof for both statements because %the two results rely on common data structures and
the constructed oracle is directly applied to obtain the second result.  
The presented algorithm is arguably simpler than the recursive schemes based on shortest path separators since in the analysis we only need to manage $\Oh(1)$ rounding errors, rather than $\Oh(\log n)$.
We no longer need to assume that the excluded minor is an apex graph and this will allow us later to apply \Cref{thm:preprocessing} in a more general setting.

\begin{theorem}\label{thm:preprocessing}
    Suppose we are given an edge-weighted $n$-vertex $K_h$-minor-free graph $G$, $\delta > 0$, a $\delta$-radius clustering $\ccal$ of $G$, and a binary rooted tree decomposition $(T, \chi)$  of $G_{\cal C}$ of width~$w$, depth $\Oh(\log n)$, and size $\Oh(n)$.
    \begin{enumerate}
        \item In time $\Oh_h(w \cdot n \log n)$
        we can build a data structure that, when queried for $u, v \in V(G)$, outputs $x \in [d_G(u,v),\, d_G(u,v)+2\cdot\delta]$ in time $\Oh(w \cdot \log n)$.\label{item:thm:oracle}

        \item Assume additionally that $G$ is connected and let  $\tau = \diam(G) / \delta$. In time $\Oh_h(w^{h+1}\cdot \tau^{h} \cdot n \log^2 n)$ we can compute eccentricity of each vertex $v \in V(G)$ within additive error $16\cdot\delta$. Moreover, within the same time we can also output a vertex $u \in V(G)$ for which $d_G(v,u) \ge \ecc_G(v) - 16\cdot\delta$.\label{item:thm:ecce}
    \end{enumerate}
\end{theorem}

Let us clarify that the parameter $\tau$ does not have to be given and it only appears in the analysis.
However, we can always assume that the diameter is known within factor 2 after computing any eccentricity.

