    \begin{claim}\label{claim:inner-path}
        For each $u, v \in V(G)$
        there exist $t \in V(T)$ and $i \in \ccal$ such that:
        \begin{enumerate}
            %\item $u,v \in V_t$, \label{item:inner-path:uv}
            \item $(t,i,u)$ and $(t,i,v)$ are valid triples, \label{item:inner-path:valid}
            \item $\inner[t,i,u] + \inner[t,i,v] \le d_G(u,v) + 2\delta$. \label{item:inner-path:dist}
        \end{enumerate}
    \end{claim}
    \begin{claimproof}
        Let $Q$ be a shortest $(u,v)$-path in $G$.
        Next, let $\ccal_Q \sub \ccal$ denote the set of clusters intersected by $Q$ and let $T_Q \sub V(T)$ be the set of nodes in which $\ccal_Q$ appear, i.e., $T_Q = \chi^{-1}(\ccal_Q)$.
        Since $G_\ccal$ is a contraction of $G$, the subgraph $G_\ccal[\ccal_Q]$ is connected.
        %The anti-image of connected set forms a connected subtree
        Consequently, $T_Q$ induces a connected subtree of $T$.
        Let $t \in T_Q$ be the node that is closest to the root among $T_Q$.
        Note that $t = \loc(i)$ for some $i \in \ccal_Q$.

        We claim that the pair $(t,i)$ satisfies the requested conditions.
        Note that for each $j \in \ccal_Q$ the node $\loc(j)$ lies in the subtree of $T$ rooted at $t$.
        Hence $\ccal_Q \sub U_t$ and so $V(Q) \sub V_t$.
        In particular, we obtain that $u,v \in V_t$ %(\Cref{item:inner-path:uv}) 
        so $(t,i,u)$, $(t,i,v)$ are valid triples (\Cref{item:inner-path:valid}).

        Since $Q$ is a shortest $(u,v)$-path and $V(Q) \sub V_t$, we infer that the $(u,v)$-distance in $G[V_t]$ equals their distance in $G$.
        Now we apply \Cref{lem:path-touch} to the graph $H = G[V_t]$ and $C = C_i,\, w = c_i$.
        Because $i \in \ccal_Q$, we know that $Q$ intersects $C_i$.
        It is crucial that all $C_i$-vertices are within distance $\delta$ from $c_i$ when considering distances within $G[C_i]$ (\Cref{def:clustering}(\ref{item:def:strong})), not just in $G$.
        As $C_i \sub V_t$, this property carries over to the graph $H$.
        \Cref{lem:path-touch} implies that $d_H(u,c_i) + d_H(c_i,v) \le d_H(u,v) + 2\delta$.
        We have $\inner(t,i,u) = d_H(u,c_i)$, $\inner(t,i,v) = d_H(c_i,v)$, and $d_H(u,v) = d_G(u,v)$, which yields \Cref{item:inner-path:dist}.     
    \end{claimproof}

    \begin{claim}[Oracle]\label{claim:oracle}
        Let $u, v \in V(G)$ be given. 
        Using the table $\inner$ we can output $x \in [d_G(u,v),\, d_G(u,v) + 2\delta]$ in time
         $\Oh(w\cdot \log n)$.
    \end{claim}
    \begin{claimproof}
        We iterate over all pairs $t\in V(T),\, i \in \ccal$ for which $(t,i,u)$ and $(t,i,v)$ are valid triples. 
        There are only $\Oh(\log n)$ candidates for $t$ just because $(t,i,u)$ is a valid triple and so $t$ must lie on the $\loc(u)$-to-root path.
        For each such $t$ there are clearly at most $w+1$ candidates for $i$.

        We return $x$ equal to the minimum value of $\inner[t,i,u] + \inner[t,i,v]$ taken over all such pairs $(t,i)$.
        %Let us refer to this value as $x$.
        For each $(t,i)$ the considered sum is either $\infty$ or it equals the length of some $(u,v)$-walk in $G[V_t]$.
        This implies that $x \ge d_G(u,v)$.
        The inequality $x \le d_G(u,v) + 2\delta$ follows from
        \Cref{claim:inner-path}.
    \end{claimproof}

Claims \ref{claim:inner-compute} and \ref{claim:oracle} yield the additive distance oracle (\Cref{item:thm:oracle}).
Now we move on to a proof sketch for \Cref{item:thm:ecce}, whose full proof is postponed to \Cref{app:ecce}.


