\subparagraph*{Eccentricities.} 
%We will no longer need the notion of a valid triple but we continue to refer to the sets $V_t$.
For a non-root $t \in V(T)$ we refer to its parent in $T$ as $\parent(t)$.
For $u,v \in V(G)$ let $\apxdist(u,v)$ denote the value returned by the oracle from \Cref{claim:oracle} when queried for the pair $u,v$. %\micr{unnecessary here}
This is a well-defined function because the oracle is deterministic.
Recall the concept of an additive core-set from \Cref{lem:corest-exist} and that $\tau = \diam(G) / \delta$.

\begin{restatable}[$\bigstar$]{claim}{claimCoreset}
%\begin{claim}
\label{claim:corset-compute}
        In total time $\Oh\br{(w\cdot\tau)^h \cdot n + w^2 \cdot n\log^2 n}$
        we can compute for each non-root $t \in V(T)$ a~subset $V'_t \sub V_t$ of size $\Oh\br{w^{h-1}\tau^{h}}$ that is a $(10\cdot\delta)$-additive core-set of $V_t$ with respect to $\chi(\parent(t))$.
\end{restatable}

The total number of distances we care about is $(w+1) \cdot \sum_{t\in V(T)} |V_t| = \Oh(w \cdot n\log n)$.
Each of them can be estimated using the oracle in time $\Oh(w \log n)$.
We would like to use those numbers to compute the additive core-sets, however a priori the bound from \Cref{lem:corest-exist} might not hold for approximate distances.
Nevertheless, we prove that a greedy procedure still constructs a small core-set, even after perturbation of distances.
A similar issue is handled in \cite{li2019planar} via randomization but we can afford a simpler argument because our strategy allows us to first query the oracle for all the distances between $V_t$ and $\chi(\parent(t))$.


In the next claim, we argue that the core-sets suffice to estimate the maximal distance between $v$ and $u$, where $v$ is fixed and $u$ is quantified over all vertices from some subtree. 
    There are three sources of accuracy loss: relying on the additive core-set, on the approximate distance oracle, and stretching the paths along a center from $\chi(t)$ (\Cref{lem:path-touch}).

    \begin{restatable}[$\bigstar$]{claim}{claimAnal}
    \label{claim:corset-analysis}
        Consider $t \in V(T)$ with children $t_1, t_2$.
        Let $v \in V_{t_1}$ and $V' \sub V_{t_2}$ be a $\rho$-additive core-set with respect to $\chi(t)$.
        Let $y = \max d_G(v,u)$ over all $u \in V_{t_2}$, and $x$ be defined as follows:

        \[x = \max_{u \in V'}  \min_{i \in \chi(t)} (\apxdist(v,c_i) +  \apxdist(c_i,u)).\]
        Then $|x - y|
        \le \rho + 6\cdot \delta$.
        Furthermore, the vertex $u^* \in V'$ realizing $x$ satisfies $d_G(v,u^*) \ge y - \rho - 6\cdot \delta$.
    \end{restatable}


We now use the additive core-sets %precomputed in \Cref{claim:corset-compute} 
 to estimate the eccentricity of a vertex.
 Essentially, we apply \Cref{claim:corset-analysis} for each choice of the lowest common ancestor of $v,u$; hence $\Oh(\log n)$ times.

    \begin{restatable}[$\bigstar$]{claim}{claimEcce}\label{claim:ecce}
    %\begin{claim}[Eccentricity]\label{claim:ecce}
        For a given vertex $v \in V(G)$ we can compute its eccentricity within additive error $16\cdot\delta$ in time $\Oh\br{w^{h+1}\cdot\tau^{h} \cdot \log^2 n}$.
        Within the same time, we can output a vertex $u$ for which $d_G(v,u) \ge \ecc_G(v) - 16\cdot\delta$.
    \end{restatable}

\Cref{thm:preprocessing}(\ref{item:thm:ecce}) follows by applying \Cref{claim:ecce} to each vertex.
