\begin{claim}\label{claim:separator}
        Consider $t \in V(T)$ with distinct children $t_1, t_2$.
        Let $u_1 \in V_{t_1}, u_2 \in  V_{t_2}$.
        Then there is $i \in \chi(t)$ for which $d_{G}(u_1,c_i) + d_{G}(c_i,u_2) \le d_G(u_1,u_2) +2\delta$. 
    \end{claim}
    \begin{claimproof}
        Let $j_1,j_2 \in \ccal$ denote the clusters of $u_1,u_2$, respectively.
        We have $j_1 \in U_{t_1}, j_2 \in U_{t_2}$ and this in particular implies $j_1,j_2 \not\in\chi(t)$.
        Since all the bags containing $j_1$ (resp. $j_2$) are located within the subtree rooted at $t_1$ (resp. $t_2$), we know that $\chi(t)$ is a $(j_1,j_2)$-separator in $G_\ccal$.
        As $G_\ccal$ is a contraction of $G$, it follows that $\bigcup_{i \in \chi(t)} C_i$ is a $(u_1,u_2)$-separator in $G$.

        Let $Q$ be a shortest $(u_1,u_2)$-path in $G$.
        By the argument above, there is some $i \in \chi(t)$ for which $Q$ intersects $C_i$.
        The claim follows from \Cref{lem:path-touch}.
    \end{claimproof}

In the next claim, we argue that the core-sets suffice to estimate the maximal distance between $v$ and $u$, where $v$ is fixed and $u$ is quantified over all vertices from some subtree. 

