\section{Proofs of Theorems 3 and 4}
\label{app:main}

In order to design a distance oracle with multiplicative error, we need one auxiliary lemma.

\begin{lemma}\label{lem:oracle-delta}
    Let $H$ be an apex graph.
    Given an edge-weighted $n$-vertex $H$-minor-free graph $G$ and  $\eps, \Delta \in \rr_+$, we can in time $\Oh_H(\eps^{-8}\cdot n\log n)$ 
    build a data structure that supports the following queries.
    For given $u,v \in V(G)$ it either correctly concludes that $d_G(u,v) > \Delta$ or
     outputs a number %$x \in \rr$ such that 
   $x \in [d_G(u,v),\, d_G(u,v) + \eps\Delta/2]$.
    A single query is processed in time $\Oh_H(\eps^{-2}\cdot\log n)$.
\end{lemma}
\begin{proof}
    We apply \Cref{lem:local-tw} for $\delta = \eps\Delta/4$ in time $\Oh(n \log n)$.
    Let $\ccal$ denote the obtained $\delta$-radius clustering of $G$ with layering function $\layer$, and $k$ denote the highest assigned layer number.
    Set $p = \lceil 4/\eps \rceil$. % with ceiling.
    Let ${\cal I}$ be the family of all intervals of length $2p+1$ 
    that intersect the interval $[0,k]$.
    For each $I \in {\cal I}$ we know from \Cref{lem:local-tw}(\ref{item:local:interval}) that $\tw(G^I_\ccal) = \Oh_H(p)$.
    We use \Cref{lem:prelim:twd-compute} to build a balanced tree decomposition of $\tw(G^I_\ccal)$ of width $\Oh_H(p^2)$; this takes time $\Oh_H(|V(G^I)| \cdot p^7\log n)$.
    Such a decomposition
    can be supplied to 
    \Cref{thm:preprocessing}(\ref{item:thm:oracle}):
    in time $\Oh_H(|V(G^I)| \cdot p^2\log n)$ we build a distance oracle that given $u,v \in V(G^I)$ returns their distance in $G^I$ with additive positive error $2\delta = \eps\Delta/2$ in time $\Oh(p^2\log n)$.

    We analyze the running time of setting up all the oracles.
    For each vertex $v \in V(G)$ there are at most $2p+1$ intervals $I \in {\cal I}$ for which $\layer(v) \in I$.
    Hence $\sum_{I \in {\cal I}} |V(G^I)| \le (2p+1)\cdot n$.
    Therefore, the total time needed to build all the oracles is $\Oh_H(p^8\cdot  n\log n)$.

    Suppose now that we are asked for a distance between $u,v \in V(G)$.
    Due to \Cref{lem:local-tw}(\ref{item:local:distance}), if $d_G(u,v) \le \Delta \le p \cdot \delta$ then $|\layer(u) - \layer(v)| \le p$.
    If the latter condition does not hold, we can answer that  $d_G(u,v) > \Delta$.
    Otherwise, \Cref{lem:local-tw}(\ref{item:local:distance}) states that there is $I \in {\cal I}$, depending only on $(\layer(u),\layer(v),p)$ for which the $(u,v)$-distance is the same in $G$ and $G^I$.
    We can therefore use the prepared oracle for $G^I$ to compute $x \in [d_G(u,v),\, d_G(u,v) + \eps\Delta/2]$ in time  $\Oh(p^2\log n)$.
    %As $2\delta = \eps\Delta$, the concludes the proof.
\end{proof}

\thmOracle*
\begin{proof}
    We can assume that $W$ is approximately known due to 2-approximation of diameter.
    Next, we can assume that the smallest distance equals 1 by scaling.
    Let $\ell = \lceil \log_2 W \rceil$.
    For each $i \in [\ell]$ we build the data structure from \Cref{lem:oracle-delta} for $\Delta = 2^{i}$.

    Consider a query $(u,v)$.
    We ask all the $\ell$ oracles for the $(u,v)$-distance and output the smallest answer.
    We claim that this is a good approximation for $d_G(u,v)$.
    Let $i \in [\ell]$ be such that $d_G(u,v) \in [2^{i-1}, 2^i]$.
    Then the oracle for $\Delta = 2^{i}$  returns $x \in [d_G(u,v), \, d_G(u,v) + \eps\cdot 2^{i-1}]$.
    This is a $(1+\eps)$-approximation because $2^{i-1} \le d_G(u,v)$.
    Finally, observe that no oracle can underestimate the $(u,v)$-distance so the smallest answer is guaranteed to lie inside this interval.
\end{proof}

We move on to the last theorem.

\thmApexDiam*
\begin{proof}
    Let $H$ of size $h$ be the apex graph excluded by $\cal H$.
    Because $G$ must be $K_{h+c}$-minor-free, we can use the linear  algorithm for computing single-source distances~\cite{TazariM09}.
    First we compute the eccentricity of an arbitrary vertex $v$ in linear time and set $D_0 = \ecc_G(v)$.
    We know that $D_0 \le \diam(G) \le 2D_0$.
    Let $k = \lceil 1/\eps \rceil$ and $D_0 < D_i < \dots < D_k = 2D_0$ divide the interval $[D_0,\, 2D_0]$ evenly. %into intervals of length $\eps D_0$, so $\tau = 1/\eps + 1$.
    %We will apply \Cref{lem:diam-reduction} for each $D = D_i$.

    \begin{claim}\label{claim:apx-step}
        There is an algorithm that, given the input to \Cref{thm:apex}  and $D \in [D_0,\, 2D_0]$, runs in time $\Oh_{h+c}(\eps^{-\alpha}\cdot n\log^2 n)$, where $\alpha = \Oh((h+1)(c+1))$, and correctly reports that either $\diam(G) > D$ or $\diam(G) \le  (1 + \eps)\cdot D$.
        %returns $\Delta \in \rr$ which satisfies the following conditions.\micr{or we get a report}
        \iffalse
        \begin{enumerate}
            \item correctly reports that $\diam(G) > D$, or
            \item outputs $\Delta \in \rr$ satisfying 
            \begin{enumerate}
            \item $\Delta \ge \diam(G) - \eps D$ and \label{item:apx-step:ub}
            \item $\Delta \le (1 + \eps)\cdot D$.\label{item:apx-step:lb}
            \end{enumerate}
        \end{enumerate}
        \fi
    \end{claim}
    \begin{claimproof}
        Note that $2D \ge \diam(G)$ so we are allowed to
        apply \Cref{lem:diam-reduction} with $\eps' = \eps/3$.
        If we receive the message that $\diam(G) > D$, we propagate it.
        Otherwise, let $(G', A')$ be the output of the algorithm.
        We have $\diam(G') \ge \diam (G)$ and, assuming $\diam(G) \le D$, also $\diam(G') \le (1 + \frac\eps 3)\cdot D$.
        Let $\delta = \eps D / 48$.
        Each connected component $G^i$ of $G'- A'$ 
        satisfies $\diam(G^i) = \Oh_c(\eps^{-c}\cdot D)$ so  $\diam(G^i) / \delta = \Oh_c(\eps^{-(c+1)})$.
        Next, $G^i$
        is $H$-minor-free and so we can apply \Cref{lem:local-tw} to get a $\delta$-radius clustering $\ccal^i$ of $G^i$ so that the treewidth of the cluster graph $G^i_{\ccal^i}$ is $\Oh_h(\diam(G^i) / \delta) = \Oh_{h+c}(\eps^{-(c+1)})$.
        We combine those to get a $\delta$-radius clustering $\ccal'$ of $G'$ by assigning each $w \in A'$ a singleton cluster.
        Observe that the treewidth of the combined cluster graph grows by at most $|A'| = c$
        with respect to $\max(\tw(G^i_{\ccal^i}))$
        because one can simply insert the additional $c$ cluster-vertices to all the bags. 

