\begin{abstract}We extend Burq's logarithmic  wave decay rate \cite{burq98} to general compactly supported scatterers in dimension two. The main novelty is using recent results on low-frequency expansions to remove the requirement that the spectrum be regular at zero. This allows us to include, among other examples, arbitrary smooth obstacles with variable boundary conditions.
\end{abstract}
\maketitle 


\section{Introduction}

Accurate estimation and computation of decay rates is an important problem in the study of linear and nonlinear waves \cite{dz,sch21,hh,bs}. In \cite{burq98}, Burq showed that, for Dirichlet obstacles in $\mathbb R^d$, waves decay at least logarithmically fast, \textit{regardless} of the shape of the obstacle. This optimal universal estimate has since been generalized very widely (see \cite{mos,shapiro24,gh}  for some recent results and references), but always requiring suitable regularity of the spectrum at low frequencies.

Such spectral regularity holds naturally for many examples, such as the Dirichlet or Neumann Laplacian on an exterior domain. But not always: in general, lower order terms and variable boundary conditions contribute nontrivially in dimension two. In this paper, we use recent results on wave expansions \cite{cd2,cdy} to remove the regularity requirement, and prove an unconditional result. We focus on $d=2$ because this dimension has the richest low frequency phenomena, but Theorem \ref{t:main} below is an abstract result applicable in any dimension, and also in non-Euclidean (e.g.~conic and Aharonov--Bohm) scattering, as in \cite{cdy}.
%to general trapping scatterers in $\mathbb R^2$. The main novelty is obtaining the precise contribution at zero energy when zero energy is not assumed to be regular. 


Our motivating example is the classical obstacle problem. Let $\mathcal B \subset \mathbb R^2$ be a ball, and let $\mathcal O \subset \mathcal B$ be an \textit{obstacle}: i.e. a (possibly empty) open set with smooth boundary, such that $\Omega = \mathbb R^2 \setminus \overline{\mathcal O}$ is connected. Let $P$ be an elliptic, self-adjoint, differential operator on $\Omega$ which equals the Laplacian away from $\mathcal B$. In this paper, we compute asymptotics for the wave equation associated to $P$.

More precisely, let
\begin{equation}
    \label{eq:operator}
     P = -\sum_{j,k=1}^2 a_{j,k}(x) \partial_{x_j}\partial_{x_k} + \sum_{j=1}^2 b_j(x) \partial_{x_j} + V(x),
\end{equation}
where $a_{j,k} - \delta_{j,k}$, $b_j$, and $V$ are all in $C_c^\infty(\mathbb R^2)$, and  the matrix $a_{j,k}(x)$ is positive definite for all $x$. We write the boundary $\partial \Omega$ as
\[\partial \Omega = \Gamma_D \cup \Gamma_N,\]
where $\Gamma_D$ and $\Gamma_N$ are separated (and either or both may be empty). Let $\gamma  \in C^\infty(\Gamma_N)$, and equip $P$ with the domain
\begin{equation}
    \label{eq:domain}
     \mathcal D = \{ u \in H^2(\Omega) \colon u|_{\Gamma_D} = 0, \ (\partial_\nu u + \gamma u)|_{\Gamma_N} = 0\},
\end{equation}
where $\partial_\nu$ is the normal derivative to the boundary with respect to the metric $g = (a_{j,k})^{-1}$. 

\begin{theorem}\label{t:intro}
Let $P$ be as in \eqref{eq:operator}, and suppose that $P$ is self-adjoint  on $L^2(\Omega)$ with domain $\mathcal D$. Let $f \in C_c^\infty(\Omega)$, and let $u \in C^\infty(\Omega \times \mathbb R)$ be the solution to 
\[
(\partial_t^2 + P)u(x,t) = 0, \qquad u|_{t=0} = 0, \quad \partial_t u|_{t=0} =f, \quad u(\cdot,t) \in \mathcal D.
\]
Then
\[
 u(x,t) = u_d(x,t) + u_z(x,t) + u_r(x,t).
\]
Here
\begin{enumerate}
\item[(i)] $u_d$ is the contribution of any negative eigenvalues: 
\[u_d(x,t) = \sum_{\ell=1}^{N_E} \frac{\sinh(\sqrt{-E_\ell}t)}{\sqrt{-E_\ell}}(\Pi_\ell f)(x),\] where $E_1 < \cdots < E_{N_E} <0$ are the negative eigenvalues of $P$, and $\Pi,\dots,\Pi_{N_E}$ the corresponding $L^2(\Omega)$ projections.
\item[(ii)] $u_z$ is the contribution of zero energy:
\begin{equation}
    \label{eq:uz}
     u_z(x,t) = t (\Pi_0f)(x) + \sum_{m=1}^M \langle f, U_{\omega_m}\rangle\mathfrak{J}_m(t) U_{\omega_m}(x),
\end{equation}
where $\Pi_0\colon L^2(\Omega) \to L^2(\Omega)$ the projection onto the zero eigenspace of $P$, $M \in \{0,1,2\}$,  $\mathfrak{J}_m$ is defined in \eqref{eq:Jm} and satisfies $\mathfrak{J}_m(t) = t((\log t)^{-1} + O((\log t)^{-2}))$ as $t \to \infty$, and the $U_{\omega_m}$ are certain $p$-resonant states. 
\item[(iii)] $u_{r}$ is a remainder, tending to zero logarithmically fast, in the sense that for every compact set $K \subset \Omega$, positive number $M$ and multiindex $\alpha$, we have
\begin{equation}\label{e:ur}
\lim_{t \to \infty} \log(t)^M\max_{x \in K} |\partial^\alpha u_r(x,t)| = 0.
\end{equation}
\end{enumerate}
\end{theorem}
The remainder bound \eqref{e:ur} follows from a more precise estimate bounding each Sobolev norm of the remainder $u_r$ in terms of a Sobolev norm of the initial data $f$; see Theorem~\ref{t:main} below. It is proved using Burq's universal exponential resolvent bound \cite{burq98, burq02}. This exponential bound is known to hold for broader classes of operators, and in particular we may allow $P$ to be an operator on a manifold, and to have rougher coefficients; see \cite{mps20,llr,dgs, o24, shapiro24,gras,gh,v25} for some recent results and further references in this active area.

It is well-known that a remainder bound of the form \eqref{e:ur} is optimal at our level of generality. This follows from an argument of Ralston \cite{r69}, deducing wave non-decay from sequences of quasimodes; see Theorem 1.2 of \cite{dmst} for a recent result of this kind in a setting close to the present one, and \cite{hs,keir,gh} for recent such results in general relativity.


The most interesting terms in our expansions are those in \eqref{eq:uz} coming from $p$-resonances at zero, when $P$ has these. Recall that $u\in \mathcal{D}_{\operatorname{loc}}$ is a $p$-resonant state if $Pu = 0$ and $u \in L^q(\Omega) \Leftrightarrow q>2$, i.e. $u$ just barely fails to be in $L^2(\Omega)$. Such resonances can occur when we allow variable lower order terms in the coefficients of the operator or the boundary condition, as in the case of the Robin (impedance) boundary condition. See Section \ref{sec:p-res} for examples.

With more control of high frequencies, we can continue the expansion. If the resolvent obeys a polynomial bound, as in situations of no trapping or mild trapping, the next terms are additional zero energy contributions: see \cite{cdy}. On the other hand, if there is stable trapping, then resonances approach the real axis quickly, and they should contribute next; see Theorem 7.20 of \cite{dz} for a related result.



Prior work on this problem has obtained the result of Theorem \ref{t:intro} under assumptions that require regularity at zero energy which rules out terms $u_d$ and $u_z$, for example requiring $P$ to be a Laplace--Beltrami operator with Dirichlet or Neumann (not Robin) boundary conditions \cite{burq98}, or with a spectral cutoff away from zero energy \cite{burq02}; see \cite{mos,shapiro24,gh}  for some recent results and references.

Wave decay results similar to ours have been much studied for decades. The field is too wide-ranging to survey here. Let us mention the seminal work of Morawetz \cite{m61}, and the surveys and works in \cite[Epilogue]{lp89}, \cite[Chapter X]{va}, \cite{dr}, \cite{tat}, \cite{dz}, \cite{vasy}, \cite{sch21}, \cite{hh}, \cite{klainerman}, \cite{lo24}, \cite{lsv}.

\subsection*{Structure of the paper}
In Section \ref{sec:thm2}, we prove our main abstract theorem on the asymptotic expansion of solutions to the wave equation in a general setting. In Section \ref{sec:thm1}, we apply Theorem \ref{t:main} to prove Theorem \ref{t:intro} on the wave asymptotics for the operator $P$ in \eqref{eq:operator} with domain $\mathcal{D}$ in \eqref{eq:domain}. In Section \ref{sec:p-res}, we give examples of operators having $p$-resonances.  

\section{The Main Expansion}
\label{sec:thm2}

Let $P$ be  self-adjoint operator on a Hilbert space $\mathcal{H}$ with domain $\mathcal{D}$. We denote the resolvent of $P$ by $R(\lambda)=(P- \lambda^2)^{-1}$, mapping $\mathcal{H} \rightarrow \mathcal{H}$ whenever $\text{Im}\, \lambda>0$ and $\lambda^2$ is not an eigenvalue of $P$. For $s\geq 0$, define $\mathcal{D}^s = \langle P\rangle^{-s}\mathcal{H}$, with norm \[\|g \|_{\mathcal{D}^s}=\|\langle P \rangle^s \,g \|_{\mathcal{H}}, \qquad  \langle P\rangle =(P^2+I)^{1/2}.\]

We make the following assumptions:

\begin{enumerate}
    \item The spectrum of   $P$ consists of $[0,\infty)$ together with up to finitely many negative eigenvalues $E_1 < \cdots < E_n < 0$ with corresponding orthogonal projections $\Pi_1,\, \ldots \,, \Pi_n$.
    \item There exist positive constants $\lambda_0$, $C$, $C'$, and a bounded operator $\chi\colon \mathcal H \to \mathcal H$, such that $\chi R(\lambda)\chi$ continues analytically to
    \[\left\{\lambda \in \mathbb C \colon  |\text{Im}\, \lambda| < \frac{1}{C} e^{-C'|\text{Re}\,\lambda|},\, \text{Re}\, \lambda \neq 0\ \right\}. \] 
      Moreover, for some $p,q\geq0$, we have
    \[ \|\chi R(\lambda)\chi\|_{\mathcal{D}^p \rightarrow \mathcal{D}^q} \leq C|\lambda|^{-2}e^{C'|\text{Re}\, \lambda|}, \qquad \text{when }  |\text{Im}\, \lambda| < \frac{1}{C} e^{-C'|\text{Re}\,\lambda|}, \ \text{Re} \lambda \ne 0.\]
    \item There are operators $\chi A_{j,k}\chi:\mathcal{D}^p \to \mathcal{D}^q$, with $p,q$ as in Assumption (2), and numbers $\nu_j \in \mathbb{R}$, $b_{j,k} \in \mathbb{C} \backslash i[0,\infty)$, such that
    \[
    \chi R(\lambda)\chi = \sum_{j,k} \chi A_{j,k} \chi \lambda^{\nu_j} \log^k(b_{j,k}\lambda),
    \]
    where the sum $\sum_{j,k}$ converges absolutely and uniformly on compact subsets of 
    \[
    \left\{ \lambda \mid \arg \lambda \in \left( -\frac{\pi}{2},\frac{3 \pi}{2}\right), |\lambda| < \lambda_0 \right\}.
    \]    
 \end{enumerate}


 We consider the solution $u(t) = \frac{\sin(t\sqrt{P})}{\sqrt{P}} f$ of the wave equation  
\[
\begin{cases} 
(\partial_t^2 +P)u =0, \\
u|_{t=0}=0,\quad \partial_t u|_{t=0} = f.
\end{cases}
\]

  To analyze the solution, use the following contours. 
