        \draw (1,-3) node{$\F$};
        \draw (0,0) node{$\bullet$};
        \draw (0,0) node[above]{\small$w$};
        \draw [->] (.05,-.05) -- (0.95,-.95);
        \draw (1,-1) node{$\bullet$};
        \draw (1,-1) node[below]{\small$v$};
        \draw [->] (.05,.05) -- (1.95,.95);
        \draw (2,1) node{$\bullet$};
