\begin{lemma}\label{lem:book-morphism}
    Let $\F=(X,R)$ be a frame and $w,u\in X$. For each $n\in\mathbb{Z}^+$, let $n\phi:X^n_{w,u}\to X$ be the map defined by $n\phi:x_k\mapsto x$ for all $x\in X$ and $k<n$. Then $n\phi$ is a t-morphism from $\F^n_{w,u}$ to $\F$. Moreover, if $\F$ is transitive, then $n\phi:(\F^n_{w,u})^t\twoheadrightarrow\F$.
\end{lemma}
\begin{proof}
    For all $x_i\in X^n_{w,u}$, $n\phi[R^n_{w,u}[x_i]]=R[n\phi(x_i)]=R[x]$ and $n\phi[\breve{R}^n_{w,u}[x_i]]=\breve{R}[n\phi(x_i)]=\breve{R}[x]$.
\end{proof}

\begin{lemma}\label{lem:book-degree}
    Let $\F=(X,R)\in\mathsf{Fr}_r$, $x,w,u\in X$ and $k,n\in\omega$ such that $w\neq u$ and $k<4n+2$. Let $\F^{4n+2}_{w,u}=(Y,S)$. Then the following holds:
    \begin{enumerate}[(1)]
        \item $S_\sharp[x_k]\sub\bigcup\cset{X[i]:i<4n+2,k\leq i+1\text{ and }i\leq k+1}$. 
        \item $S_\sharp^n[x_k]\neq Y$.
        \item if $\tup{w,u}\not\in R^t$, then $(S^t)_\sharp[x_k]\sub\bigcup\cset{X[i]:i<4n+2,k\leq i+2\text{ and }i\leq k+2}$. 
        \item if $\tup{w,u}\not\in R^t$, then $(S^t)_\sharp^n[x_k]\neq Y$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    For (1), suppose $k$ is even. If $k=0$, then $S_\sharp[x_k]\sub X[0]\cup X[1]$. If $k>0$, then $S_\sharp[x_k]\sub\cset{w_{k-1}}\cup X[k]\cup (R[k+1])_\sharp[u_{k+1}]\sub X[k-1]\cup X[k]\cup X[k+1]$. Suppose $k$ is odd. Then $S_\sharp[x_k]\sub\cset{u_{k-1}}\cup X[k]\cup (R[k+1])_\sharp[w_{k+1}]\sub X[k-1]\cup X[k]\cup X[k+1]$. Thus (1) holds.
    By (1), we see $S_\sharp^n[x_k]\sub\bigcup\cset{X[i]:i<4n+2,k\leq n+i\text{ and }i\leq k+n}\neq Y$, from which (2) follows immediately.

    For (3), suppose $k$ is odd. Take any $y_j\in (S^t)_\sharp[x_k]$. It suffices to show that $k\leq j+2$ and $j\leq k+2$. Suppose $j>k+2$. Since $y_j\in (S^t)_\sharp[x_k]$, either $S^tx_ky_j$ or $S^ty_jx_k$. Suppose $S^tx_ky_j$. By Fact~\ref{fact:plus-reachability}, we see $(R^t)^rxu$ and $S^tu_ky_j$. By applying Fact~\ref{fact:plus-reachability} twice, we have $(R^t)^ruw$ and $(R^t)^rwu$. Since $w\neq u$, we have $R^twu$, which contradicts $\tup{w,u}\not\in R^t$. By Fact~\ref{fact:plus-reachability}, $S^ty_jx_k$ implies $(\breve{R}^t)^ruw$ and so $R^twu$, which also gives a contradiction. Thus $j\leq k+2$. By a similar argument, we see that $k\leq j+2$. The proof for the case when $k$ is exactly the dual one. Thus (3) holds. By (3), we see $S_\sharp^n[x_k]\sub\bigcup\cset{X[i]:i<4n+2,k\leq 2n+i\text{ and }i\leq k+2n}\neq Y$, (4) follows immediately.
\end{proof}

\begin{corollary}\label{coro:Kt-large-rdg}
    Let $\phi\in\L$. If $\phi$ is satisfied by some finite rooted frame other than $\bullet$, then for each $n\in\omega$, there exists $\F=(X,R)\in\mathsf{Fin}_r(L)$ such that $\F\not\md\neg\phi$ and $\mathsf{rdg}(\F)\geq n$.
\end{corollary}
\begin{proof}
    Suppose $\phi$ is satisfied by some rooted frame $\G=(Y,S)\neq\bullet$. Suppose $|Y|=1$. Then $S=Y\times Y$. Let $\F$ be a finite $\ST$-frame of r-degree greater than $n$, for example, $\G_{n+1}$ defined in \cite[Definition 7.1]{Chen2024}. Note that $\F\twoheadrightarrow\G$ and $\G\not\md\neg\phi$, we see that $\F\not\md\neg\phi$. Suppose $|Y|\geq 2$. Then there exists $w,u,y\in Y$ such that $\G,y\not\md\neg\phi$ and $w\neq u$. By Lemmas~\ref{lem:book-morphism} and \ref{lem:book-degree}(2), we see that $\G^{4n+2}_{w,u},y_0\not\md\neg\phi$ and $\mathsf{rdg}(\G^{4n+2}_{w,u})\geq n$.
\end{proof}

\begin{corollary}\label{coro:Tr-large-rdg}
    Let $\phi\in\L$ and $L\in\cset{\mathsf{K4}_t,\mathsf{S4}_t}$. If $\phi$ is satisfied by some rooted non-symmetric $L$-frame, then for each $n\in\omega$, there exists $\F=(X,R)\in\mathsf{Fin}_r(L)$ such that $\F\not\md\neg\phi$ and $\mathsf{rdg}(\F)\geq n$.
\end{corollary}
\begin{proof}
    Let $\G=(Y,S)$ be a non-symmetric $L$-frame and $y\in Y$ such that $\G,y\not\md\neg\phi$. Then there exists $w\neq u$ with $\tup{w,u}\not\in R$. By Lemmas~\ref{lem:book-morphism} and \ref{lem:book-degree}(4), we see that $\G^{4n+2}_{w,u},y_0\not\md\neg\phi$ and $\mathsf{rdg}(\G^{4n+2}_{w,u})\geq n$. Note that $\G^{4n+2}_{w,u}\md L$ whenever $\G\md L$, take $\F=\G^{4n+2}_{w,u}$ and we are done.
\end{proof}

\section{Kripke-incompleteness in $\K$ and $\LT$}\label{sec:DKI-Kt-K4t}

In this section, we generalize Blok's dichotomy theorem for $\mathsf{NExt}(\mathsf{K})$ to the lattices $\mathsf{NExt}(\mathsf{K}_t)$ and $\LT$ of tense logics. For $\mathsf{NExt}(\mathsf{K}_t)$ and $\LT$, we prove the dichotomy theorems by showing that the union-splittings of $\K$ and $\LT$ are exactly those having the degree of Kripke-incompleteness $1$, and all other tense logics have the degree of Kripke-incompleteness $2^{\aleph_0}$, respectively.

\subsection{Degree of Kripke-incompleteness in $\K$}\label{subsec:degree-Kt}
Let us focus on the degree of Kripke-incompleteness in $\K$ and we write $\mathsf{deg}$ for $\mathsf{deg}_{\mathsf{K}_t}$ in this section. By Theorem~\ref{thm:splittings-Kt-K4t}, $\tup{\mathsf{Log}(\bullet),\mathsf{K}_t/\mathsf{Log}(\bullet)}$ is the unique splitting pair in $\K$. Clearly, $\mathsf{Log}(\bullet)=\mathsf{K}_t\oplus(\B\bot\wedge\bb\bot)$. To simplify our notation, in this section, we write $L^*$ for $\mathsf{K}_t/\mathsf{Log}(\bullet)$. The reader can readily check that $\cset{\mathsf{K}_t,L^*}$ is exactly the set of union-splittings of $\K$. Moreover, since $\mathsf{K}_t$ is Kripke-complete, we see immediately that $\mathsf{deg}(\mathsf{K}_t)=1$.

\begin{proposition}\label{prop:deadend-frame}
    Let $\gf\in\mathsf{GF}_r$. Then $\gf\md\D\top\vee\bd\top$ if and only if $\gf\ncong\bullet$.
\end{proposition}
\begin{proof}
    The left-to-right direction is trivial. Suppose $\gf\ncong\bullet$. Since $\gf$ is rooted, we see that $\R[x]\neq\ve$ for any $x\in X$. Thus $\gf\md\D\top\vee\bd\top$. 
\end{proof}

\begin{proposition}\label{prop:axiom-L*-Kt}
    $L^*=\mathsf{K}_t\oplus(\D\top\vee\bd\top)$.
\end{proposition}
\begin{proof}
    Since $\bullet\not\md\D\top\vee\bd\top$ and $L^*=\mathsf{K}_t/\mathsf{Log}(\bullet)$, we get $L^*\sub\mathsf{K}\oplus(\D\top\vee\bd\top)$. Take any $\gf\in\mathsf{GF}_r(L^*)$. Then $\gf\ncong\bullet$. By Proposition~\ref{prop:deadend-frame}, $\gf\md\D\top\vee\bd\top$. Hence $\D\top\vee\bd\top\in\mathsf{Log}(\mathsf{GF}_r(L^*))=L^*$.
\end{proof}

\begin{proposition}\label{prop:splitting-Kt}
    Let $L\in\mathsf{NExt}(\mathsf{K}_t)$. Then $L\subsetneq L^*$ if and only if $L=\mathsf{K}_t$. 
\end{proposition}
\begin{proof}
    Suppose $L\subsetneq L^*$. Then $L\nsupseteq L^*$ and so $L\sub\mathsf{Log}(\bullet)$. Thus $\bullet\in\mathsf{Fr}(L)$. By Proposition~\ref{prop:deadend-frame}, $\mathsf{GF}_r(L)=\mathsf{GF}_r(\mathsf{K}_t)$, which entails $L\sub\mathsf{Log}(\mathsf{GF}_r(L))\sub\mathsf{Log}(\mathsf{GF}_r(\mathsf{K}_t))=\mathsf{K}_t$.
\end{proof}

\begin{lemma}\label{lem:no-more-iterated-splitting-Kt}
    There exists no logic splits $\NExt(L^*)$.
\end{lemma}
\begin{proof}
    Towards a contradiction, suppose there exists a logic $L$ splits $\NExt(L^*)$. Since $L\supseteq L^*$, $L\nsubseteq\mathsf{Log}(\bullet)$. By Theorem~\ref{thm:splittings-Kt-K4t}, $L$ does not split $\K$. By Fact~\ref{fact:splitting}, $\bigcap_{i\in I}L_i\sub L$ for a family of logics $\mathcal{K}=\cset{L_i\in\K:L_i\nsubseteq L, i\in I}$. Let $\mathcal{K}'=\cset{L_i\oplus(\D\top\vee\bd\top):i\in I}$. Take any $\phi\not\in L$. Since $L^*\sub L$, $(\D\top\vee\bd\top)\to\phi\not\in L$. Since $\bigcap_{i\in I}L_i\sub L$, $(\D\top\vee\bd\top)\to\phi\not\in L_i$ for some $i\in I$. Then there exists $\gf\in\mathsf{GF}(L_i)$ such that $\gf\not\md(\D\top\vee\bd\top)\to\phi$. By Proposition~\ref{prop:deadend-frame}, it is not hard to see that $\gf\md(\D\top\vee\bd\top)$ and $\gf\not\md\phi$. Thus $\phi\not\in L_i\oplus(\D\top\vee\bd\top)$. Since $\phi$ is arbitrarily chosen, we see that $\bigcap\mathcal{K}'\sub L$. Note that $L$ splits $\NExt(L^*)$ and $L\sub L_i\oplus L\nsubseteq L_1$ for any $i\in I$, we see that $\bigcap_{i\in I}L_i\oplus L\nsubseteq L_1$, which leads to a contradiction.
\end{proof}

\begin{theorem}\label{thm:iterated=union-Kt=L*}
    Let $L\in\K$. Then the following are equivalent:
    \begin{enumerate}[(1)]
        \item $L$ is an iterated splittings in $\K$.
        \item $L$ is a union-splitting in $\K$.
        \item $L\in\cset{\mathsf{K}_t,L^*}$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    By Lemma~\ref{lem:no-more-iterated-splitting-Kt}, $\mathsf{K}_t$ and $L^*$ are the only two iterated splittings in $\K$. Thus (1) is equal to (3). By \cite[Theorem~22]{Kracht1992}, (2) is equal to (3).
\end{proof}

\begin{theorem}\label{thm:degreeL*-Kt}
    Let $L$ be a union-splitting in $\K$. Then $\mathsf{df}(L)=1$.
\end{theorem}
\begin{proof}
    By Theorem~\ref{thm:iterated=union-Kt=L*}, $L\in\cset{\mathsf{K}_t,L^*}$. Clearly, $\mathsf{df}_{\mathsf{K}_t}(\mathsf{K}_t)=1$. Let $L=L^*$. Suppose $\mathsf{Fin}(L')=\mathsf{Fin}(L^*)$ for some $L'\neq L^*$. Note that $L^*=\mathsf{K}_t\oplus(\D\top\vee\bd\top)$ has the FMP, we see $L'\subsetneq L^*$. By Proposition~\ref{prop:splitting-Kt}, $L'=\mathsf{K}_t$. Thus $\bullet\in\mathsf{Fin}(L')$, which contradicts to $\mathsf{Fin}(L')=\mathsf{Fin}(L^*)$.
\end{proof}

It is now sufficient to fix a tense logic $L\in\K\setminus\cset{\mathsf{K}_t,L^*}$ and show that $\mathsf{deg}(L)=2^{\aleph_0}$. The main proof idea is as follows: to show that there exists a continual family of tense logics which share the same Kripke frame as $L$, we construct for each $I\sub\mathbb{Z}^+$ a general frame $\gf_I$ such that $\mathsf{Fr}(L\cap\mathsf{Log}(\gf_I))=\mathsf{Fr}(L)$. Let $L_I=L\cap\mathsf{Log}(\gf_I)$. Then $\mathsf{deg}(L)\geq|\cset{L_I:I\sub\mathbb{Z}^+}|$ and we are done once we show that $L_I\neq L_J$ for any different $I,J\sub\mathbb{Z}^+$. 

Let $I\sub\mathbb{Z}^+$ be arbitrarily chosen and we start with the construction of $\gf_I$. Intuitively, the general frame $\gf_I$ will be a combination of a finite rooted frame $\F_L$ and a general frame $\gf'_I$. On one hand, the finite frame $\F_L$ is designed to refute some formula in $L$, since we have to ensure that $L_I\neq L_J$ for any different $I,J\sub\mathbb{Z}^+$, which requires $L\neq L\cap\mathsf{Log}(\gf_I)$. On the other hand, we have to construct $\gf'_I$ properly to make the logics $L_I$ pairwise different and share the same frames as $L$. The trick here is to choose $\F_L$ to be a finite frame of large enough r-degree, which ensures that $\gf'_I$ and $\F_L$ both work well after being combined. More precisely, we have the following lemma holds: 

\begin{lemma}\label{lem:large-enough-finite-model-Kt}
    For all $\phi\not\in L^*$ and $n\in\omega$, there exists $\F\in\mathsf{Fin}_r$ such that $\F\not\md\phi$ and $\mathsf{rdg}(\F)\geq n$.
\end{lemma}
\begin{proof}
    Take any $\phi\not\in L^*$. By Proposition~\ref{prop:axiom-L*-Kt}, $L^*=\mathsf{K}\oplus(\D\top\vee\bd\top)$ has the FMP and so $\G\not\md\phi$ for some $\G\in\mathsf{Fin}_r(L^*)$. By Propositions~\ref{prop:deadend-frame}, $\gf\ncong\bullet$. Then existence of required $\F$ follows from Corollary~\ref{coro:Kt-large-rdg}.
\end{proof}
By Proposition~\ref{prop:splitting-Kt}, there exists a formula $\phi_L\in L\setminus L^*$. By Lemma~\ref{lem:large-enough-finite-model-Kt}, there is a finite rooted frame $\F_L=(X_L,R_L)$ and $w_L,u_L\in X$ such that $\F_L,w_L\not\md\phi_L$ and $u_L\not\in R_\sharp^{\mathsf{md}(\phi)}[w_L]$.

\begin{definition}
    For each $I\sub\mathbb{Z}^+$, let $\gf'_I=(Y_I,S_I,B_I)$ be the general frame defined as follows:
\begin{itemize}
    \item $Y_I= \omega\cup\cset{i^*:i\in I\cup\cset{0}}$.
    \item $S_I= \cset{\tup{n,m}\in\omega\times\omega:n<m}\cup\cset{\tup{i^*,j}:i\in I\cup\cset{0}\text{ and }i\leq j}$.
    \item $B_I$ is the internal set generated by $\ve$.
\end{itemize}
\end{definition}
The general frames $\gf'_I$ were introduced in \cite{Chen.Ma2024}. The tense logic of $\gf'_I$ has no consistent proper extension and no Kripke frame \cite[Proposition 5.7]{Chen.Ma2024}.  
Now we define the general frame $\gf_I$ to be $(\tup{\F_Lu_L+0^*\kappa\gf'_I},A_I)$, where $A_I$ the internal set generated by $\mathcal{P}(X_L)$.

