Let $k\in\omega$ be such that $|\F_L|<k$ and $X_I={R_I}_\sharp^{k}[v]$ for all $v\in X_I$. For each $n\in\omega$ and $m\in\mathbb{Z}^+$, we define the formulas $\gamma_n$ and $\gamma^*_m$ as follows:
\begin{itemize}
    \item $\gamma_0=\bb\bot\wedge\D\bb^2\bot\wedge\D^k\bb^{k+1}\bot$ and $\gamma_{l+1}=\bd\gamma_l\wedge\bb^2\neg\gamma_l$.
    \item $\gamma^*_m=\D\gamma_m\wedge\B\neg\gamma_{m-1}\wedge\bb\bot\wedge\B\D^k\top$.
\end{itemize}

\begin{lemma}\label{lem:gamma-truth}
    For all $n\in\omega$, $m\in\mathbb{Z}^+$ and $x\in X_I$,
\begin{enumerate}[(1)]
    \item $\gf_I,x\md\gamma_n$ if and only if $x=n$;
    \item $\gf_I,x\md\gamma^*_m$ if and only if $m\in I$ and $x=m^*$.
\end{enumerate}
\end{lemma}
\begin{proof}
    For (1), we prove by induction on $n$. Let $n=0$. Note that $\breve{R_I}[0]=\ve$, $k\in R_I^k[0]$ and $\breve{R_I}^{k+1}[k]=\ve$, we have $\gf_I,0\md\gamma_0$. Suppose $\gf_I,x\md\gamma_0$. Then $\gf_I,x\md\D^k\bb^{k+1}\bot$, which entails that there exists a strict chain $\tup{x_i:i\leq k}$ with $x=x_0$. Since $|\F_L|<k$, we see $x\not\in X_L$. Since $\gf_I,x\md\bb\bot\wedge\D\bb^2\bot$, we have $x\not\in\mathbb{Z}^+\cup\cset{i^*:i\in I}$. Thus $x=0$. Let $n>0$. By induction hypothesis, for all $y\in X_I$, $\gf_I,y\md\gamma_{n-1}$ if and only if $y=n-1$. Since $n-1\in\breve{R_I}[n]\setminus\breve{R_I}^2[n]$, we have $\gf_I,n\md\gamma_n$. Suppose $\gf_I,x\md\gamma_n$. By induction hypothesis, $x\in R_I[n-1]\setminus R_I^2[n-1]$, which entails $x=n$.

    (2) The right-to-left direction is trivial. Suppose $\gf_I,x\md\gamma^*_m$. By $\gf_I,x\md\D\gamma_m\wedge\B\neg\gamma_{m-1}$, we have $x\not\in X_L\cup\cset{l,l^*\in X_I:l<m-1\text{ or }l>m}\cup\cset{m,(m-1)^*}$. Since $\gf_I,x\md\bb\bot\wedge\B\D^k\top$, $x\neq m-1$. By $x\in X_I=X_L\uplus(\omega\cup\cset{i^*:i\in I})$, we see $m\in I$ and $x=m^*$.
\end{proof}

\begin{lemma}\label{lem:no-frame-for-gfi-Kt}
    $\mathsf{Fr}(\mathsf{Log}(\gf_I))=\ve$.
\end{lemma}
\begin{proof}
    Suppose there exists $\G=(Y,S)\in\mathsf{Fr}(\mathsf{Log}(\gf_I))$. By an easy induction, we see that for all $V\in A_I$, $V\cap\omega$ and $V\cap\cset{i^*:i\in I\cup\cset{0}}$ are either finite or co-finite. Thus $\gf_I,1\md\B(\B p\to p)\to\B p$. By Lemma~\ref{lem:gamma-truth}(1), $\gf_I\md\gamma_i\to\D\gamma_{i+1}$ for all $i\in\omega$. Thus we have
    \begin{center}
        $\G\md\gamma_1\to(\B(\B p\to p)\to\B p)$ and $\G\md\cset{\gamma_i\to\D\gamma_{i+1}:i\in\omega}$.
    \end{center}
    Note that $\gf_I\md\Delta^k\gamma_1$ and $\gamma_1$ is variable-free, there exists $y\in Y$ such that $\G,y\md\gamma_1$. Since $\G\md\cset{\gamma_i\to\D\gamma_{i+1}:i\in\omega}$, we see that there exists an infinite strictly ascending $S$-chain $\tup{u_i:i\in\mathbb{Z}^+}$ such that $y=u_1$ and $\G,u_i\md\gamma_i$ for all $i\in\mathbb{Z}^+$. Let $U$ be a valuation in $\G$ such that $U(p)=\cset{u_{2i}:i\in\mathbb{Z}^+}$. Then we see that $\G,U,y\not\md\B(\B p\to p)\to\B p$. Hence $\G\not\md\gamma_1\to(\B(\B p\to p)\to\B p)$, which contradicts $\G\in\mathsf{Fr}(\mathsf{Log}(\gf_I))$.
\end{proof}

\begin{lemma}\label{lem:same-frame-Kt}
    For all $I\in\mathcal{P}(\mathbb{Z}^+)$, $\mathsf{Fr}(L)=\mathsf{Fr}(L_I)$.
\end{lemma}
\begin{proof}
    By Lemmas~\ref{lem:intersection-rooted-frame} and \ref{lem:no-frame-for-gfi-Kt}, $\mathsf{Fr}_r(L_I)=\mathsf{Fr}_r(L)\cup\mathsf{Fr}_r(\mathsf{Log}(\gf_I))=\mathsf{Fr}_r(L)$.
\end{proof}

\begin{lemma}\label{lem:pairwise-diff-Kt}
    For all $I,J\in\mathcal{P}(\mathbb{Z}^+)$, $I\neq J$ implies $L_I\neq L_J$.
\end{lemma}
\begin{proof}
    Take any distinct $I,J\in\mathcal{P}(\mathbb{Z}^+)$. Let $i\in I\setminus J$. It suffices to show that 
    \begin{center}
        $\neg\phi_L\to\Delta^{k}\gamma^*_{i}\in L_I\setminus L_J$.
    \end{center}
    By Lemma \ref{lem:gamma-truth}(2), $\gf_I,i^*\md\gamma^*_i$ and so $\gf_I\md\Delta^k\gamma^*_i$. Since $\phi_L\in L$, we see that $\neg\phi_L\to\Delta^{k}\gamma^*_{i}\in L\cap\mathsf{Log}(\gf_I)= L_I$. Since $i\not\in J$, by Lemma \ref{lem:gamma-truth}(2), we see $\gf_J\md\neg\gamma^*_i$. Note that $\gf_J\rsto{R_J}_\sharp^{\mathsf{md}(\phi_L)}[w_L]\cong\F_L\rsto{R_L}_\sharp^{\mathsf{md}(\phi_L)}[w_L]$, we have $\gf_J,w_L\not\md\phi_L$. Thus $\gf_J,w_L\not\md\phi_L\vee\Delta^k\gamma^*_i$ and so $\neg\phi_L\to\Delta^{k}\gamma^*_{i}\not\in L_J$.
\end{proof}

Since $L$ is chosen arbitrarily, by Lemmas~\ref{lem:same-frame-Kt} and \ref{lem:pairwise-diff-Kt}, we have
\begin{theorem}\label{thm:degreeKt-continuum}
    Let $L\in\K\setminus\cset{\mathsf{K}_t,L^*}$. Then $\mathsf{deg}(L)=2^{\aleph_0}$.
\end{theorem}

We conclude this section by the following characterization theorems in $\mathsf{NExt}(\mathsf{K}_t)$:
\begin{theorem}\label{thm:degreeKt-main}
    Let $L\in\K$. Then the following are equivalent:
    \begin{enumerate}[(1)]
        \item $L$ is a union-splitting in $\K$.
        \item $L$ is an iterated splitting in $\K$.
        \item $\mathsf{df}(L)=1$.
        \item $\mathsf{deg}(L)=1$.
        \item $\mathsf{df}(L)\neq 2^{\aleph_0}$.
        \item $\mathsf{deg}(L)\neq 2^{\aleph_0}$.
    \end{enumerate}    
\end{theorem}
\begin{proof}
    The equivalence of (1), (2) and (3) follows from Theorem~\ref{thm:iterated=union-Kt=L*}. Since $|\K|\leq 2^{\aleph_0}$, by Proposition~\ref{prop:deg-leq-df}, (3) implies (4), and (5) implies (6). Clearly (3) implies (5), and (4) implies (6). Finally, by Theorem~\ref{thm:degreeKt-continuum}, (6) implies (1), which concludes the proof.
\end{proof}


The following dichotomy theorem follows immediately:
\begin{theorem}\label{thm:dichotomy-Kt}
    For all $L\in\K$, $\mathsf{deg}(L)=\mathsf{df}(L)\in\cset{1,2^{\aleph_0}}$.
\end{theorem}


\subsection{Degree of Kripke-incompleteness in $\LT$}\label{subsec:degree-K4t}
The proof idea of the dichotomy theorem for $\LT$ is similar to the one for $\K$. In this section, we always presume that frames are transitive and write $\mathsf{deg}$ for $\mathsf{deg}_{\mathsf{K4}_t}$. By \cite[Theorem 10]{Kracht1992}, $\tup{\mathsf{Log}(\bullet),\mathsf{K4}_t/\bullet}$ is the unique splitting pair in $\LT$. In this section, we write $L^*$ for $\mathsf{K4}_t/\bullet$. Similar to the case for $\K$, the logics $\mathsf{K4}_t$ and $L^*$ are exactly the union-splittings in $\LT$. Since $\mathsf{K4}_t$ is Kripke complete, $\mathsf{deg}(\mathsf{K4}_t)=1$. Moreover, by arguments similar to those in Section~\ref{subsec:degree-Kt}, we have

\begin{proposition}\label{prop:L*-K4t}
    Let $\gf\in\mathsf{GF}_r(\mathsf{K4}_t)$. Then (i) $\gf\md\D\top\vee\bd\top$ if and only if $\gf\ncong\bullet$; (ii) $L^*=\mathsf{K}\oplus(\D\top\vee\bd\top)$; and (iii) for all $L\in\mathsf{NExt}(\mathsf{K4}_t)$, $L\subsetneq L^*$ if and only if $L=\mathsf{K4}_t$.
\end{proposition}

\begin{theorem}\label{thm:iterated=union-K4t=L*}
    Let $L\in\LT$. Then the following are equivalent:
    \begin{enumerate}[(1)]
        \item $L$ is an iterated splittings in $\LT$.
        \item $L$ is a union-splitting in $\LT$.
        \item $L\in\cset{\mathsf{K4}_t,L^*}$.
    \end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:degreeK4tL*}
    For all union-splittings $L$ in $\LT$, $\mathsf{df}_{\mathsf{K4}_t}(L)=\mathsf{deg}_{\mathsf{K4}_t}(L)=1$.
\end{theorem}

It is sufficient now to prove that $\mathsf{deg}(L)=2^{\aleph_0}$ for all $L\in\LT\setminus\cset{\mathsf{K4}_t,L^*}$. The method we use here is similar to the one in Section~\ref{subsec:degree-Kt} and the key lemma is the following:

\begin{lemma}\label{lem:large-enough-finite-model}
    Let $\phi\not\in L^*$. Then (i) $\phi$ is refuted by some non-symmetric $\G\in\mathsf{Fin}_r(\mathsf{K4}_t)$; (ii) for all $n\in\omega$, there exists $\F\in\mathsf{Fin}_r(\mathsf{K4}_t)$ such that $\F\not\md\phi$ and $\mathsf{rdg}(\F)\geq n$.
\end{lemma}
\begin{proof}
    For (i), take any $\phi\not\in L^*$. By Proposition~\ref{prop:L*-K4t}, $L^*=\mathsf{K4}_t\oplus(\D\top\vee\bd\top)$ has the FMP. Then there exists $\F'=(X',R')\in\mathsf{Fin}_r(L^*)$ such that $\F'\not\md\phi$. If $\F'$ is already non-symmetric, then take $\G=\F'$ we are done. Suppose $\F'$ is symmetric. Since $\F'$ is rooted and transitive, $\F$ is a cluster. Note that $\F'\md\D\top\vee\bd\top$, we see that $R'_\sharp[x']\neq\ve$ for each $x'\in X'$ and so $R'=X'\times X'$. Let $\G=(X,R)$ where $X=X'\times\cset{0,1}$ and $R=\cset{\tup{\tup{x,a},\tup{y,b}}\in X\times X:a\leq b}$. Consider the map $f:X\to X'$ defined by $f:\tup{x,a}\mapsto x$ for all $\tup{x,a}\in X$. Obviously, $f$ is a t-morphism from $\G$ to $\F'$. Thus $\G\not\md\phi$. Hence (i) holds. By Corollary~\ref{coro:Tr-large-rdg}, (ii) follows from (i) immediately.
\end{proof}

We can now prove the following theorem:

\begin{theorem}\label{thm:degreeK4t-continuum}
    Let $L\in\LT\setminus\cset{\mathsf{K4}_t,L^*}$. Then $\mathsf{deg}(L)=2^{\aleph_0}$.
\end{theorem}
\begin{proof}
    Let $L\in\LT\setminus\cset{\mathsf{K4}_t,L^*}$. By Proposition~\ref{prop:L*-K4t}, $L\nsubseteq L^*$ and so there exists $\phi_L\in L\setminus L^*$. By Lemma \ref{lem:large-enough-finite-model}, there is a finite rooted frame $\F_L=(X_L,R_L)$ and $w_L,u_L\in X$ such that $\F_L,w_L\not\md\phi_L$ and $u_L\not\in R_\sharp^{\mathsf{md}(\phi)}[w_L]$. For each $I\in\mathbb{Z}^+$, we define $\gf_I$ to be the general frame $(\tup{\F_Lu_L+^t0^*\kappa\gf'_I},A_I)$, where $A_I$ the internal set generated by $\mathcal{P}(X_L)$. Then we see that $\gf$ is transitive. By almost same proofs as those of Lemmas~\ref{lem:gamma-truth}, \ref{lem:no-frame-for-gfi-Kt}, \ref{lem:same-frame-Kt} and \ref{lem:pairwise-diff-Kt}, we have
    \begin{itemize}
        \item $\mathsf{Fr}(L)=\mathsf{Fr}(L_I)$ for all $I\sub\mathbb{Z}^+$;
        \item $I\neq J$ implies $L_I\neq L_J$ for all $I,J\sub\mathbb{Z}^+$.
    \end{itemize}
    It follows immediately that $2^{\aleph_0}=|\cset{L_I:I\sub\mathbb{Z}^+}|\leq\mathsf{deg}(L)\leq 2^{\aleph_0}$. Hence $\mathsf{deg}(L)=2^{\aleph_0}$.
\end{proof}

By Theorems~\ref{thm:iterated=union-K4t=L*}, \ref{thm:degreeK4tL*} and \ref{thm:degreeK4t-continuum}, we have the following characterization theorem:
\begin{theorem}\label{thm:degreeK4t-main}
    Let $L\in\LT$. Then the following are equivalent:
    \begin{enumerate}[(1)]
        \item $L$ is a union-splitting in $\LT$.
        \item $L$ is an iterated splitting in $\LT$.
        \item $\mathsf{df}(L)=1$.
        \item $\mathsf{deg}(L)=1$.
        \item $\mathsf{df}(L)\neq 2^{\aleph_0}$.
        \item $\mathsf{deg}(L)\neq 2^{\aleph_0}$.
    \end{enumerate}    
\end{theorem}

Again, the following dichotomy theorem follows immediately:
\begin{theorem}\label{thm:dichotomy-K4t}
    For all $L\in\LT$, $\mathsf{deg}(L)=\mathsf{df}(L)\in\cset{1,2^{\aleph_0}}$.
\end{theorem}

\section{Kripke-incompleteness in $\mathsf{NExt}(\mathsf{S4}_t)$}\label{sec:DKI-S4t}

In this section, we focus on the degree of Kripke-incompleteness in $\NExt(\ST)$. In what follows, we write $\mathsf{deg}(L)$ for the degree of Kripke-incompleteness of $L$ in $\NExt(\ST)$. Our aim is to prove the dichotomy theorem for $\NExt(\ST)$. We first characterize the iterated splittings in $\NExt(\ST)$ and show that every iterated splitting has the degree of Kripke-incompleteness $1$. Then by constructing some frames generalizing the Nishimura-Rieger ladder, we show that all other tense logics in $\NExt(\ST)$ are of the degree of Kripke-incompleteness $2^{\aleph_0}$, which gives a characterization theorem for the degree of Kripke-incompleteness in $\NExt(\ST)$ and completes the proof of the dichotomy theorem. 

Let $n\in\mathbb{Z}^+$. Then we write $\C_n$ for the reflexive transitive chain of length $n$ and $\mathfrak{Cl}$ for the $n$-cluster, that is, $\C_n=(n,\leq)$ and $\mathfrak{Cl}_n=(n,n\times n)$.

\begin{lemma}\label{lem:iterated-splitting-S4t}
    Let $L\in\NExt(\ST)$. Then $L$ is an iterated splitting if and only if $L\in\NExt(\mathsf{S5}_t)\cup\cset{\ST}$.
\end{lemma}
\begin{proof}
    For the right-to-left direction, note first that $\ST$ and $\mathsf{S5}_t=\ST/\C_2$ are iterated splittings. By \cite[Lemma 6.6]{Chen2024}, $\NExt(\mathsf{S5}_t)$ is isomorphic to $(\omega,\geq)$ and every consistent extension of $\mathsf{S5}_t$ is of the form $\mathsf{Log}(\mathfrak{Cl}_k)$. Then we have $\L=\mathsf{S5}_t/\mathsf{Log}(\mathfrak{Cl}_1)$ and $\mathsf{Log}(\mathfrak{Cl}_k)=\mathsf{S5}_t/\mathsf{Log}(\mathfrak{Cl}_{k+1})$ for all $k\in\mathbb{Z}^+$. Suppose $L=\ST/L_1/\cdots/L_n$ is an iterated splitting. If $n=0$, then $L=\ST$. If $n=1$, by \cite[Theorem 21]{Kracht1992}, $L\in\cset{\mathsf{S5}_t,\L}\sub\NExt(\mathsf{S5}_t)$. If $n\geq 2$, then $L\supseteq L/L_1\supseteq\mathsf{S5}_t$. Thus $L\in\NExt(\mathsf{S5}_t)\cup\cset{\ST}$.
\end{proof}

\begin{lemma}\label{lem:deg=1}
    Let $L$ be an iterated splitting in $\NExt(\ST)$. Then $\mathsf{df}(L)=1$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:iterated-splitting-S4t}, $L\in\NExt(\mathsf{S5}_t)\cup\cset{\ST}$. Clearly, $\mathsf{df}(\ST)=1$. Let $L\in\NExt(\mathsf{S5}_t)$. Take any $L'\in\NExt(\ST)$ such that $\mathsf{Fin}(L')=\mathsf{Fin}(L)$. Then $\C_2\not\md L'$. By \cite[Theorem 21]{Kracht1992}, $\tup{\mathsf{Log}(\C_2),\mathsf{S5}_t}$ is a splitting pair in $\NExt(\ST)$, which entails $L'\in\NExt(\mathsf{S5}_t)$. By \cite[Lemma 6.6]{Chen2024}, every extension of $\mathsf{S5}_t$ has the FMP and so $L=\mathsf{Log}(\mathsf{Fin}(L))=\mathsf{Log}(\mathsf{Fin}(L'))=L'$. Hence $\mathsf{df}(L)=1$.
\end{proof}
Recall from \cite[Theorem 21]{Kracht1992} that $\tup{\mathsf{Log}(\C_2),\mathsf{S5}_t}$ and $\tup{\mathsf{Log}(\C_1),\L}$ are the only two splitting pairs in $\NExt(\ST)$. Then $\cset{\L,\mathsf{S5}_t,\ST}$ is exactly the set of union-splittings in $\NExt(\ST)$ and so every union-splitting has the degree of Kripke-incompleteness $1$. However, since there are countably many tense logics in $\NExt(\mathsf{S5}_t)$, Lemma~\ref{lem:deg=1} indicates that logics of the degree of Kripke-incompleteness $1$ are not necessary union-splittings, which shows that Blok's characterization of the degree of Kripke-incompleteness for $\NExt(\mathsf{K})$ can not be generalized to $\NExt(\ST)$.


\begin{lemma}\label{lem:large-enough-finite-model-S4t}
    Let $\phi\not\in\ST$. Then (i) $\phi$ is refuted by some non-symmetric $\G\in\mathsf{Fin}_r(\mathsf{S4}_t)$; (ii) for all $n\in\omega$, there exists $\F\in\mathsf{Fin}_r(\mathsf{S4}_t)$ such that $\F\not\md\phi$ and $\mathsf{rdg}(\F)\geq n$.
\end{lemma}
\begin{proof}
    For (i), take any $\phi\not\in\ST$. Since $\ST$ has the FMP, there exists $\F'=(X',R')\in\mathsf{Fin}_r(\ST)$ such that $\F'\not\md\phi$. If $\F'$ is non-symmetric, then take $\G=\F'$ we are done. Suppose $\F'$ is symmetric. Then $R'=X'\times X'$. Let $\G=(X,R)$ where $X=X'\times\cset{0,1}$ and $R=\cset{\tup{\tup{x,a},\tup{y,b}}\in X\times X:a\leq b}$. Then the map $f:X\to X'$ defined by $f:\tup{x,a}\mapsto x$ for all $\tup{x,a}\in X$ is a t-morphism from $\G$ to $\F'$. Thus $\G\not\md\phi$. Hence (i) holds. By Corollary~\ref{coro:Tr-large-rdg}, (ii) follows from (i) immediately.
\end{proof}
Let $L\in\NExt(\ST)$ be an arbitrarily fixed logic such that $L\not\in\NExt(\mathsf{S5}_t)\cup\cset{\ST}$. Since $L\supsetneq\ST$, there exists $\phi_L\in L\setminus\mathsf{S4}_t$. Then there exists $\F_L\in\mathsf{Fin}_r(\ST)$ and $w_L,u_L\in X_L$ with $\F_L,w_L\not\md\phi_L$ and $u_L\not\in R_\sharp^{\mathsf{md}(\phi)}[w_L]$.
As what we did in Section~\ref{sec:DKI-Kt-K4t}, to show that $L$ is of the degree of Kripke-incompleteness $2^{\aleph_0}$, it suffices to construct a continual family of general frames $\tup{\gf_I:I\sub\mathbb{Z}^+}$ such that $\Fr(L)=\Fr(L\cap\mathsf{Log}(\gf_I))$ and $L\cap\mathsf{Log}(\gf_I)\neq L\cap\mathsf{Log}(\gf_I)$ for any $I\neq J\sub\mathbb{Z}^+$.

\begin{definition}
    Let $I\in\mathcal{P}(\mathbb{Z}^+)$. The frame $\F'_I=(Y_I,S_I)$ is defined as follows:
    \begin{itemize}
        \item $Y_I=A\cup B\cup C_I\cup\cset{x_0,x_1,x_2,y_0,y_1,r_0,r_1,r_2,r'}$, where $A=\cset{a_i:i\in\omega}$, $B=\cset{b_i:i\in\omega}$ and $C=\cset{c_i:i\in I\cup\cset{0}}$;
        \item $S_I$ is the reflexive-transitive closure of the union of the following binary relations:
        \begin{itemize}
            \item $\cset{\tup{x_0,x_1},\tup{x_2,x_1},\tup{x_2,a_0},\tup{y_1,y_0},\tup{y_1,b_0},\tup{r_0,r'},\tup{r_0,r_1},\tup{r_2,r_1}}$;
            \item $\cset{\tup{c_i,c_j}:i>j\text{ and }i,j\in I\cup\cset{0}}$;
            \item $\cset{\tup{a_i,a_j}:i>j\in\omega}\cup\cset{\tup{a_i,b_j}:i>j\in\omega}$;
            \item $\cset{\tup{b_i,b_j}:i>j\in\omega}\cup\cset{\tup{b_i,a_j}:i>j+1\in\omega}$.
        \end{itemize}
    \end{itemize}
    The general frame $\gf_I=(X_I,R_I,A_I)$, where $\F_I=(X_I,R_I)=\tup{\F_Lu_L+^tr_3\F'_I}$ and $A_I$ is the internal set generated by $\mathcal{P}(X_L)$.
\end{definition}
An example of the underlying frame $\F_I$ is as depicted in Figure~\ref{fig:fi-S4t}. Clearly, $\gf_I\in\mathsf{GF}(\ST)$. The reader might notice that Rieger-Nishimura ladder can be embedded into $\F'_I$ by an order-preserving map. Let us take a closer look at $\gf_I$ by showing some of its properties. 










