    Let $k\in\omega$ be such that $|\F_L|+5<k$ and $X_I={R_I}_\sharp^{k}[v]$ for all $v\in X_I$. Then
    \begin{enumerate}[(1)]
        \item $\gf_I\md\mathsf{bw}^+_k\wedge\mathsf{bw}^-_k\wedge\mathsf{bz}_k$;
        \item $\gf_I\md(\mathsf{grz}^+\wedge\mathsf{grz}^-)\vee(\mathsf{alt}^+_k\wedge\mathsf{alt}^-_k)$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    For (1), by Fact~\ref{fact:bounds}, it suffices to notice that there exists no anti-chain or zigzag of size greater than $k$.
    For (2), by Fact~\ref{fact:bounds}, $\gf_I,x\md\mathsf{alt}^+_k\wedge\mathsf{alt}^-_k$ for all $x\in X_L\cup\cset{r_1}$ and $\gf_I,x\md\mathsf{grz}^+$ for all $x\not\in X_L\cup\cset{r_1}$. We now claim that the following holds:
    \begin{center}
        (\dag) For all admissible set $U\in A_I$ and chain $C\sub A\cup B\cup C_I$, either $U\cap C$ of $C\setminus U$ is finite.
    \end{center}
    We prove (\dag) by induction on the construction of $U$. Clearly, either $U\cap C$ of $C\setminus U$ is finite for all $U\in\mathcal{P}(X_I)$. The Boolean cases are straightforward. Let $U=\breve{R}[V]$. If $C\cap V\neq\ve$, then $C\setminus U$ is finite. If $C\cap V=\ve$, then $C\cap U=\ve$ is finite. Let $U=R[V]$. Take any chain $C\sub A\cup B\cup C_I$. If $r_0\in V\cap C$, then $C\setminus U=\ve$ is finite. Suppose $r_0\not\in V\cap C$. By induction hypothesis, $C\cap V$ or $C\setminus V$ is finite. Note that $C\cap U$ and $C\setminus U$ is finite iff $C\cap V$ and $C\setminus V$ is finite, respectively. Thus (\dag) holds.
    Take any $x_0\not\in X_L\cup\cset{r_1}$. Suppose $\gf_I,V,x_0\not\md\mathsf{grz}^-$ for some valuation $V$ in $\gf_I$. Then $x_0\not\in V(p)$ and $x_1\in V(\neg p\wedge\bd p)$ for some $x_1\in\breve{R}[x_0]$. By repeating this construction, there exists a co-chain $C=\cset{x_i:i\in\omega}\sub\breve{R}[x]$ such that $C\cap V(\neg p)=\cset{x_{2i}:i\in\omega}$. Thus $|C\cap V(p)|=|C\setminus V(p)|=\aleph_0$, which contradicts (\dag). Hence $\gf_I,x\md\mathsf{grz}^-$ and so $\gf_I\md(\mathsf{grz}^+\wedge\mathsf{grz}^-)\vee(\mathsf{alt}^+_k\wedge\mathsf{alt}^-_k)$.
\end{proof}

\begin{lemma}\label{lem:no-inf-Kripke-frame-S4tFi}
    $\mathsf{Fin}_r(\mathsf{Log}(\gf_I))=\mathsf{Fr}_r(\mathsf{Log}(\gf_I))$.
\end{lemma}
\begin{proof}
    Take any $\G=(Y,S)\in\mathsf{Fr}_r(\mathsf{Log}(\gf_I))$. By Lemma~\ref{lem:gfi-S4t-prop}(1), $\G$ is $k$-transitive and of both forth-width and back-width no more than $k$. By Lemma~\ref{lem:gfi-S4t-prop}(2) and Fact~\ref{fact:grz}, there is no infinite chain or infinite cluster in $\G$. Then the readers can readily check that $S_\sharp[y]$ is finite for all $y\in Y$, which entails $\G\in\mathsf{Fin}_r(\mathsf{Log}(\gf_I))$.
\end{proof}

Let $L_I=L\cap\mathsf{Log}(\gf_I)$. To show $\Fr(L)=\Fr(L_I)$, we introduce some auxiliary notions from \cite{Chen2024}.

\begin{lemma}\label{lem:t-morphism-source}
    Let $\gf=(X,R,A)\in\mathsf{GF}$, $\G=(Y,S)\in\Fr$, $f:\gf\twoheadrightarrow\G$ and $x,y\in X$. Suppose $f(x)=f(y)$. Then $f[R[x]]=f[R[y]]$ and $f[\breve{R}[x]]=f[\breve{R}[y]]$. %
\end{lemma}
\begin{proof}
    By $f:\gf\twoheadrightarrow\G$, $f[R[x]]=S[f(x)]=S[f(y)]=f[R[y]]$. Symmetrically, $f[\breve{R}[x]]=f[\breve{R}[y]]$. 
\end{proof}

\begin{definition}
    Let $\gf=(X,R,A)\in\mathsf{GF}_r$, $\G=(Y,S)\in\Fr_r$ and $f:\gf\twoheadrightarrow\G$. A subset $Z\sub X$ is called {\em sufficient} if for all $z\in Z$, there exist $u,v\in Z$ such that $f(z)=f(u)=f(v)$ and $R[u]\cup\breve{R}[v]\sub Z$. 
\end{definition}

\begin{lemma}\label{lem:sufficient-full}
    Let $\gf=(X,R,A)\in\mathsf{GF}_r$, $\G=(Y,S)\in\Fr_r$ and $f:\gf\twoheadrightarrow\G$. Suppose $Z\sub X$ is sufficient. Then $f[Z]=Y$.
\end{lemma}
\begin{proof}
    Take any $z\in Z$. It suffices to show $S_\sharp^n[f(z)]\sub f[Z]$ for all $n\in\omega$. The proof proceeds by induction on $n$. For details, see the proof of \cite[Lemma 3.8]{Chen2024}.
\end{proof}

It is no longer possible to show that $\mathsf{Log}(\gf_I)$ has no Kripke frame as in Section~\ref{sec:DKI-Kt-K4t}. However, we can still show that adding the general frame $\gf_I$ brings no new Kripke frame to $L$.

\begin{lemma}\label{lem:no-nontrivial-image}
    $\Fr_r(\mathsf{Log}(\gf_I))=\mathsf{TM}(\C_2)$.
\end{lemma}
\begin{proof}
    Note that $\mathsf{Log}(\gf_I)\not\in\NExt(\mathsf{S5}_t)$ and $\tup{\mathsf{Log}(\C_2),\mathsf{S5}_t}$ is a splitting pair in $\NExt(\ST)$, we have $\C_2\md\mathsf{Log}(\gf_I)$ and so $\Fr_r(\mathsf{Log}(\gf_I))\supseteq\mathsf{TM}(\C_2)$. Take any $\G\in\Fr_r(\mathsf{Log}(\gf_I))$. By Lemma~\ref{lem:no-inf-Kripke-frame-S4tFi}, $\G$ is finite. Let $\J^{k}(\G)$ be the Jankov-formula of $\G$ of degree $k$. Since $\G\not\md\neg\J^{k}(\G)$, we see that $\gf_I\not\md\neg\J^{k}(\G)$. Note that $\gf_I$ is $k$-transitive and rooted, by Theorem~\ref{thm:JankovLemma}, $\G$ is a t-morphic image of $\gf_I$. Let $f:\gf_I\twoheadrightarrow\G$. 
    Now it suffices to show that $\G\in\mathsf{TM}(\C_2)$. Suppose $\G\not\in\mathsf{TM}(\C_2)$. Then

    \noindent\textbf{Claim 1.} For all $u\in X_I\setminus X_L$, $f(u)=f(x_0)$ implies $u=x_0$.

    \noindent\textbf{Proof of Claim 1.} Take any $u\in X_I\setminus X_L$ such that $f(u)=f(x_0)$. Towards a contradiction, suppose also $u\neq x_0$. Then we have the following cases:
    \begin{enumerate}[(1)]
        \item $u\in\cset{x_1,y_0,r'}$. By Lemma~\ref{lem:t-morphism-source}, $S[f(x_0)]=S[f(u)]=f[R[u]]=\cset{f(u)}$ and $\breve{S}[f(x_0)]=f[\breve{R}[x_0]]=\cset{f(x_0)}$. Thus $\G\iso\C_1$ and contradicts the assumption.
        \item $u=x_2$. Then clearly $\cset{x_0,x_1,x_2}$ is sufficient, which entails $Y=\cset{f(x_0),f(x_1)}$. Note that $f(x_0)\not\in S[f(x_1)]$, $\G\cong\C_2$ and contradicts the assumption.
        \item $u=y_1$. Similar to (2), we see $\cset{x_0,x_1,y_0,y_1}$ is sufficient and so $\G\cong\C_2$, which contradicts the assumption.
        \item None of (1)-(3) holds. Then $u\in R[r_0]\setminus\cset{r'}$. By Lemma~\ref{lem:t-morphism-source}, $f(r_0)\in f[\breve{R}[u]]=f[\breve{R}[x_0]]=\cset{f(x_0)}$. By Lemma~\ref{lem:t-morphism-source} again, we see that $f(r')\in\cset{f(x_0),f(x_1)}$. By (1), $f(r')=f(x_1)$, which entails that $\cset{x_0,x_1,r_0,r'}$ is sufficient. Thus $\G\cong\C_2$, which contradicts the assumption.
    \end{enumerate}
    Hence we conclude that $f(u)=f(x_0)$ implies $u=x_0$.

    \noindent\textbf{Claim 2.} $f(a_0)\neq f(b_0)\neq f(b_1)\neq f(a_0)$.

    \noindent\textbf{Proof of Claim 2.} Suppose $f(a_0)=f(b_0)$. By Lemma~\ref{lem:t-morphism-source}, $f(x_0)\in f[\breve{R}[R[\breve{R}[b_0]]]]$. By Claim~1, the only possible case is that $f(r_0)=f(x_2)$, $f(r_1)=f(x_1)$ and $f(x_0)=f(u)$ for some $u\in X_L\cap\breve{R}[r_1]$. Then $f(r')\in f[R[x_2]]=\cset{f(a_0),f(x_1),f(x_2)}$. It is not hard to see that $f(r')=f(x_2)$ implies $\G\cong\C_1$, and $f(r')=f(x_1)$ contradicts to Claim~1. Thus $f(r')=f(a_0)=f(b_0)$, which entails $f(y_1)\in f[\breve{R}[r']]=\cset{f(a_0),f(x_2)}$. Since $\G\not\in\mathsf{TM}(\C_2)$, we have $f(y_1)=f(x_2)$ and $f(y_0)=f(x_1)$, which again contradicts to Claim~1. Thus $f(a_0)\neq f(b_0)$. 
    Note that $f(a_0)=f(b_1)$ implies $f(a_0)=f(b_0)$, we have $f(a_0)\neq f(b_1)$. 

    Suppose $f(b_0)=f(b_1)$. Since $f(y_1)\neq f(b_1)$, $f(y_1)=f(v)$ for some $v\in\breve{R}[b_1]\setminus\cset{b_1}$. Note that $v\in\breve{R}[a_0]$ and $f(a_0)\neq f(b_0)$, it is not hard to show that $f(y_0)=f(a_0)$, which entails that $f(x_0)\in f[\R^3[y_0]]$ and contradicts Claim~1.

    \noindent\textbf{Claim 3.} For all $n\in\omega$, $|Z_n|=2n+3$, where $Z_n=\cset{f(a_i):i\leq n}\cup\cset{f(b_i):i\leq n+1}$.

    \noindent\textbf{Proof of Claim 3.} The proof proceeds by induction on $n\in\omega$. The case $n=0$ follows from Claim~2 immediately. Let $n>0$. By induction hypothesis, it suffices to show $f(a_n),f(b_{n+1})\not\in f[Z_{n-1}]$ and $f(a_n)\neq f(b_{n+1})$. Since $\cset{f(a_{n-1}),f(b_{n-1})}\sub f[R[a_n]]\cap f[R[b_{n+1}]]$ and $\cset{f(a_{n-1}),f(b_{n-1})}\nsubseteq f[R[v]]$ for any $v\in Z_{n-1}$, we have $f(a_n),f(b_{n+1})\not\in f[Z_{n-1}]$. Note that $f(b_n)\in f[R[b_{n+1}]]\setminus f[R[a_n]]$, we see that $f(a_n)\neq f(b_{n+1})$.

    By Claim~3, $\G$ is infinite, which contradicts Lemma~\ref{lem:no-inf-Kripke-frame-S4tFi}. Hence $\Fr_r(\mathsf{Log}(\gf_I))=\mathsf{TM}(\C_2)$.
\end{proof}

\begin{lemma}\label{lem:same-frame-S4t}
    For all $I\sub\mathbb{Z}^+$, $\Fr(L)=\Fr(L_I)$.
\end{lemma}
\begin{proof}
    Since $L\not\in\NExt(\mathsf{S5}_t)$ and $\tup{\mathsf{Log}(\C_2),\mathsf{S5}_t}$ is a splitting pair in $\NExt(\ST)$, we have $\C_2\md L$ and so $\mathsf{TM}(\C_2)\sub\Fr_r(L)$. By Lemmas~\ref{lem:intersection-rooted-frame} and \ref{lem:no-nontrivial-image}, $\Fr_r(L_I)=\Fr_r(L)\cup\Fr_r(\mathsf{Log}(\gf_I))=\Fr_r(L)$. Hence $\Fr(L)=\Fr(L_I)$ for all $I\in\mathbb{Z}^+$.
\end{proof}

So far, we obtain a family of logics which share the same class of frames as $L$. It remains to show that the set $\cset{L_I:I\sub\mathbb{Z}^+}$ of tense logics is of the cardinality $2^{\aleph_0}$.

\begin{definition}
    Let $\phi_0:=\neg\mathsf{bd}_k[q_i/p_i]\wedge\bb\neg p$, where $p,q_0,\cdots,q_k\in\mathsf{Prop}$ are propositional variables which do not occur in $\phi_L$. Then we define
    \begin{itemize}
        \item $\phi_{x_0}:=\Delta^k\neg\phi_L\wedge\Delta^4_p\phi_0\wedge\nabla^3\neg\phi_0$, $\phi_{x_1}:=\bd\phi_{x_0}\wedge\neg\phi_{x_0}$ and $\phi_{x_2}:=\D\phi_{x_1}\wedge\neg\phi_{x_1}$;
        \item $\phi_{y_0}:=\Delta_p^7\phi_{x_0}\wedge\Delta^6\neg\phi_{x_0}$ and $\phi_{y_1}:=\D\phi_{y_0}\wedge\neg\phi_{y_0}$;
        \item $\phi_{a_0}:=\bd\phi_{x_2}\wedge\neg\phi_{x_2}$, $\phi_{b_0}:=\bd\phi_{y_1}\wedge\neg\phi_{y_1}$ and $\phi_{b_1}:=\D\phi_{b_0}\wedge\B\neg\phi_{a_0}\wedge\neg\phi_{b_0}$;
        \item $\phi_{AB}=\B(\phi_{b_0}\vee\phi_{b_1}\vee\D\bd\D\bd\phi_{x_0})$;
        \item for all $l\in\mathbb{Z}^+$, $\phi_{a_l}:=\phi_{AB}\wedge\D\phi_{a_{l-1}}\wedge\D\phi_{b_{l-1}}\wedge\B\neg\phi_{b_l}$ and $\phi_{b_{l+1}}:=\phi_{AB}\wedge\D\phi_{a_{l-1}}\wedge\D\phi_{b_{l}}\wedge\B\neg\phi_{a_l}$;
        \item for all $n\in\mathbb{Z}^+$, $\phi_{c_n}:=\neg\phi_{AB}\wedge\D\phi_{a_{n}}\wedge\B\neg\phi_{a_{n+1}}$.
    \end{itemize}
\end{definition}

\begin{lemma}\label{lem:sep-formulas-S4t}
    Let $U=A\cup B\cup\cset{x_0,x_1,x_2,y_0,y_1}$. For all $u\in U$ and $v\in X_I$, 
    \begin{enumerate}[(1)]
        \item $\gf_I,u\not\md\phi_u\to\nabla^k\phi_L$,
        \item for all valuation $V$ in $\gf_I$, $V(\phi_{x_0})\neq\ve$ implies $V(\phi_{AB})=A\cup B$ and $V(\phi_u)=\cset{u}$.
        \item $\gf_I,v\not\md\neg\phi_u$ implies $u=v$,
        \item $\gf_I\md\neg\phi_{c_j}$ for any $j\not\in I$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    For (1), recall first that $\F_L,w_L\not\md\phi_L$. Then there exists a valuation $V':\mathsf{Prop}\to\mathcal{P}(X_L)$ such that $\F_L,V',w_L\md\neg\phi_L$. Note that $\gf_I$ is differentiated, there exists a valuation $V$ in $\gf_I$ such that the following conditions hold: (i) $V\rsto X_L=V'$, (ii) $V(p)=R[b_k]\cup\cset{x_0,x_1,x_2,y_0,y_1}$ and (iii) $V(q_i)=R[b_i]$ for all $i\leq k$. Let $\M=(\gf_I,V)$. Then $\M,b_{k+1}\md\phi_0$ and $\M,w_L\md\neg\phi_L$. Since $\gf_I$ is $k$-transitive, $\M,x_0\md\nabla^3\mathsf{bd}_k$ and there exists a $p$-path from $x_0$ to $b_{k+1}$ of length $4$, we see that $\M,x_0\md\phi_{x_0}$. Moreover, note that $\M,r_0\md\neg p$ and $V(\phi_0)\sub Y_I$, we have $\M,u\md\Delta^3\phi_0\vee\neg\nabla_p^4\phi_0$ for each point $u\in X_I\setminus\cset{x_0}$. Thus $x_0$ is the unique point satisfying $\phi_{x_0}$. By the construction the formulas $\phi_u$, the reader can now easily check that $V(\phi_{AB})=A\cup B$ and $\M,u\md\phi_u$ for all $u\in U$. Since $w_L\in\R^k[u]$, we have $\M,u\md\phi_u\wedge\Delta^k\neg\phi_L$.

    For (2), let $V$ be a valuation in $\gf_I$ and $\M=(\gf_I,V)$. Suppose $\M,v_0\md\phi_{x_0}$ for some $v_0\in X_I$. Then $\M,v_0\md\Delta_p^4\phi_0$ and $\M,v_1\md\phi_0$ for some $v_1\in X_I$. Since $\phi_0:=\neg\mathsf{bd}_k[q_i/p_i]\wedge\bb\neg p$, $R[v_1]$ contains a chain of length greater than $k$. Thus $v_1\in R[r_0]\setminus\cset{a_0,b_0,b_1,c_0}$ and so $\M,r_0\md\neg p$. Then $\M,w\md\Delta^3\phi_0\vee\neg\nabla_p^4\phi_0$ for each point $w\in X_I\setminus\cset{x_0}$, which entails that $V(\phi_{x_0})=\cset{x_0}$. Then clearly, $V(\phi_{AB})=A\cup B$ and $V(\phi_{w})=\cset{w}$ for all $w\in U$.

    For (3), take any $u\in U$ and $v\in X_I$. Suppose $\gf_I,v\not\md\neg\phi_u$. Then there exists a valuation $V$ in $\gf_I$ such that $\gf_I,V,v\md\phi_u$. Let $\M=(\gf_I,V)$. By the construction $\phi_u$, we always have $\md\phi_u\to\Delta^m\phi_{x_0}$ for some $m\in\omega$. Thus $V(\phi_{x_0})\neq\ve$. By (2), $V(\phi_{w})=\cset{w}$ for all $w\in U$, which entails $u=v$.

    For (4), take any $j\not\in I$. Suppose $\gf_I\not\md\neg\phi_{c_j}$. Then there exists $v\in X_I$ and a valuation $V$ in $\gf_I$ such that $\gf_I,V,v\md\phi_{c_j}$. Thus $V(\phi_{x_0})\neq\ve$. By (2),$V(\phi_{AB})=A\cup B$ and $V(\phi_w)=\cset{w}$ for $w\in\cset{a_{j},a_{j+1}}$. Since $j\not\in I$, we have $\breve{R}[a_j]\setminus(A\cup B\cup\breve{R}[a_{j+1}])=\ve$ and so $\M\md\neg\phi_{c_j}$, which is a contradiction. %
\end{proof}

\begin{lemma}\label{lem:pairwise-diff-S4t}
    For all $I,J\in\mathcal{P}(\mathbb{Z}^+)$, $I\neq J$ implies $L_I\neq L_J$.
\end{lemma}
\begin{proof}
    Take any distinct $I,J\in\mathcal{P}(\mathbb{Z}^+)$. Let $i\in I\setminus J$. It suffices to show that 
    \begin{center}
        $\phi_{c_i}\to\nabla^k\phi_L\in L_J\setminus L_I$.
    \end{center}
    By Lemma~\ref{lem:sep-formulas-S4t}(1), $\phi_{c_i}\to\nabla^k\phi_L\not\in\mathsf{Log}(\gf_I)\supseteq L_I$. By Lemma~\ref{lem:sep-formulas-S4t}(4), $\neg\phi_{c_i}\in\mathsf{Log}(\gf_J)$. Since $\phi_L\in L$, we see $\nabla^k\phi_L\in L$. Note that we may always assume that $\phi_L$ and $\phi_{c_i}$ contains no common variable, $\neg\phi_{c_i}\vee\nabla^k\phi_L\in L\cap\mathsf{Log}(\gf_J)$. Hence $\phi_{c_i}\to\nabla^k\phi_L\in L_J$.
\end{proof}

Note that $L\in\NExt(\ST)\setminus(\NExt(\mathsf{S5}_t)\cup\cset{\ST})$ is arbitrarily chosen, by Lemmas~\ref{lem:same-frame-S4t} and \ref{lem:pairwise-diff-S4t}, the following theorem holds:

\begin{theorem}\label{thm:degreeS4t-continuum}
    For all $L\in\NExt(\ST)\setminus(\NExt(\mathsf{S5}_t)\cup\cset{\ST})$, $\mathsf{deg}(L)=2^{\aleph_0}$.
\end{theorem}

Finally, we obtain our main results in this section: 
\begin{theorem}\label{thm:degreeS4t-main}
    Let $L\in\NExt(\ST)$. Then the following are equivalent:
    \begin{enumerate}[(1)]
        \item $L$ is an iterated splitting in $\NExt(\ST)$.
        \item $\mathsf{df}(L)=1$.
        \item $\mathsf{deg}(L)=1$.
        \item $\mathsf{df}(L)\neq 2^{\aleph_0}$.
        \item $\mathsf{deg}(L)\neq 2^{\aleph_0}$.
    \end{enumerate}    
\end{theorem}
\begin{proof}
    By Lemma~\ref{lem:deg=1}, (1) implies (2). Note that $|\NExt(\ST)|\leq 2^{\aleph_0}$, by Proposition~\ref{prop:deg-leq-df}, we see that (2) implies (3), as well as (4) implies (5). Clearly (3) implies (5), and (2) implies (4). It remains to note that (5) implies (1) follows from Theorem~\ref{thm:degreeS4t-continuum} and Lemma~\ref{lem:iterated-splitting-S4t}.
\end{proof}

It follows immediately that the following dichotomy theorem holds:
\begin{theorem}\label{thm:dichotomy-S4t}
    For all $L\in\NExt(\ST)$, $\mathsf{deg}(L)=\mathsf{df}(L)\in\cset{1,2^{\aleph_0}}$.
\end{theorem}

\begin{remark}\label{remark:better-iterated}
    As we can see, union-splittings in $\NExt(\ST)$ are still strictly Kripke-complete, while there exist strictly Kripke-complete logics in $\NExt(\ST)$ which are not union-splittings. Hence, so far, the notion of iterated splitting fits better with strictly Kripke-completeness, in the sense that for $L\in\cset{\mathsf{K},\mathsf{K}_t,\mathsf{K4}_t,\ST}$, the iterated splittings in $\NExt(L)$ are exactly the strictly Kripke-complete logics. 
\end{remark}

\section{Conclusions}

The present work contributes a series of results on the degree of Kripke-incompleteness in lattices of tense logics. We started with the lattice $\NExt(\mathsf{K}_t)$ of all tense logics. By giving a characterization of the degree of Kripke-incompleteness in $\NExt(\mathsf{K}_t)$, we proved the dichotomy theorem for $\NExt(\mathsf{K}_t)$, that is, $\mathsf{deg}_{\mathsf{K}_t}(L)\in\cset{1,2^{\aleph_0}}$ for all $L\in\NExt(\mathsf{K}_t)$. By the same method, we gave a characterization of the degree of Kripke-incompleteness in $\LT$ and proved the dichotomy theorem for $\LT$. Finally, we turned to Kripke-incompleteness in $\NExt(\ST)$. We showed that iterated splittings are strictly Kripke-complete and all other extensions of $\ST$ are of the degree $2^{\aleph_0}$. By showing that the degree of Kripke-incompleteness coincide with the degree of FMP in all the lattices mentioned above, we obtain also dichotomy theorem for the degree of FMP is these lattices.

We claim that we could obtain more results on the degree of Kripke-incompleteness in lattices of tense logics by the method given in this work. For example, consider the tense logic $\mathsf{K4D}^+_t=\mathsf{K4}_t\oplus\D\top$, which is the tense logic of serial frames. It is not hard to see that $\F_L\md\D\top$ implies $\gf_I\md\D\top$ for all $\gf_I$ defined in Section~\ref{subsec:degree-K4t}. Note that serial frames are closed under reflective unfolding, we claim that $\mathsf{deg}_{\mathsf{K4D}^+_t}(L)=2^{\aleph_0}$ for all proper extension $L$ of $\mathsf{K4D}^+_t$. Similarly, since $\F_L\md\mathsf{grz}^+$ implies $\gf_I\md\mathsf{grz}^+$ for all $\gf_I$ defined in Section~\ref{sec:DKI-S4t}, we claim that the dichotomy theorem holds for $\mathsf{Grz}^+=\mathsf{K}_t\oplus\mathsf{grz}^+$. Given that the frames $\F_I$ are frames for the bi-intuitionistic logic $\mathsf{biInt}$ and every finite bi-p-morphic image of $\F_I$ is a bi-p-morphic image of $\C_2$, we claim that the dichotomy theorem for the degree of FMP holds for $\mathsf{Ext}(\mathsf{biInt})$. These are left for future work.

There are still a lot of worth-studying future work and we outline a few topics here:

By Blok's characterization theorem, the union-splittings in $\NExt(\mathsf{K})$ are exactly the strictly Kripke-complete logics. Results obtained in this work showed that Blok's characterization theorem can be generalized to the lattices $\NExt(\mathsf{K}_t)$ and $\LT$. However, as we mentioned in Remark~\ref{remark:better-iterated}, every union-splitting in $\NExt(\ST)$ is strictly Kripke-complete while the inverse does not hold. Instead, iterated splittings fit perfectly with strictly Kripke-complete logics. So it is natural to ask: what is the relation between union-splittings, iterated splittings and strictly Kripke-complete logics in the lattices of tense logics? For example, is an iterated splitting always a union-splitting? Is it true that for all tense logic $L_0$ and $L$, $L$ is a union-splitting in $\NExt(L)$ implies $\mathsf{deg}_{L_0}(L)=1$? Is a strictly Kripke-complete tense logics always an iterated splitting?

As the reader might already notice, our method relies heavily on the reflective unfolding of Kripke frames. Recall that a tense logic $L$ is called finitely transitive if it is $n$-transitive for some $n\in\omega$. Our method used in this paper applies to only those lattices $\NExt(L_0)$ where $L_0$ is finitely transitive. An important future work is to study the degree of Kripke-incompleteness in lattices of finitely transitive tense logics, for example, $\NExt(\mathsf{S4.2}_t)$ and $\NExt(\mathsf{S4.3}_t)$. By \cite[Proposition~23]{Kracht1992}, there are infinite splittings in both of these lattices, which indicates that the case is quite different from the one for $\NExt(\ST)$. We believe these topics will require new methods and techniques.

As we have shown in Sections~\ref{sec:DKI-Kt-K4t} and \ref{sec:DKI-S4t}, the degree of FMP and the degree of Kripke-incompleteness coincide in the lattices $\K$, $\LT$ and $\NExt(\ST)$. The dichotomy theorem for the degree of FMP holds for all these three lattices. Bezhanishvili et al. \cite{Bezhanishvili.Bezhanishvili.ea2025} showed the anti-dichotomy theorem for the degree of FMP for $\NExt(\mathsf{K4})$ and $\NExt(\mathsf{S4})$. Here is a natural follow-up question: Is there any tense logic $L$ such that the anti-dichotomy theorem holds for $\NExt(L)$?

