%        \item (1) 
%        \item (2) $
%        \sup_{\pi \in \mathcal{A}(x_0)}E^P\left[\left\Vert Z^B\right\Vert_2^{3(1+w)}\right] < \infty$.
%    \end{itemize} 
% \end{assumption}

% \begin{remark}
%     For the sampling of $N \sim \text{Geo}(R)$, we can either sample before sampling i.i.d. samples from $\mu$, or we can sample for each $b \sim \mu$, a sample $N_b \sim \text{Geo}(R)$. These two approaches are not different in theory (from independence). 
% \end{remark}

\begin{remark}
    When $n_0 = 0$, then our estimator is exactly the same as the estimator in \cite{Y_b} and \cite{Yanan}. Note that $N^{b_i}$ does not depend on $b_i$, and the notation represents the i.i.d. copies of the shifted geometric random variable. The reason to introduce the non-negative shift $n_0$ is that the estimator $\mathcal{E}$ loses the concavity due to the definition of $\Delta_{N^b}^b$, but if we make $n_0$ properly large, then $\Delta_{N^b}^b$ looks more like a concave function, thus help the numerical optimization steps in terms of $(\lambda, \beta)^T$.
\end{remark}
We make the following assumption that will be important in the analysis of the variance of the estimator when the prior has a continuous density. The case when the prior is finitely supported can be analyzed similarly.
\begin{assumption}\label{finitevari}
    The map $b \mapsto Z^b$ is continuously differentiable and injective on the support of $B$.  
\end{assumption}

\begin{theorem}\label{unbiasedth}
Suppose Assumption \ref{ass0.5}, \ref{ass2} and \ref{ass3} hold, then  $\mathcal{E}_{\pi, \delta, \lambda, \beta}$ is an unbiased estimator of the quantity $\int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(Z^b\right)d\mu(b).$ If Assumption \ref{finitevari} is satisfied, $\mu$ is compactly supported with a continuous density, then $\text{Var}\left(\mathcal{E}^{b_1}_{\lambda, \beta}\right)$ and $\text{Var}\left(\mathcal{E}_{\pi, \delta, \lambda, \beta}\right)$ are both finite.
\end{theorem}
% \begin{theorem}[Worst case probability characterization]\label{KLworst}
% Only for KL divergence in theory, which is an exponentially tilted measure.
% \end{theorem}

% With the first and second order conditions (See Appendix \ref{derivatives}), the Newton's method makes sure that the estimator converges to the global optimal quadratically if the initial value is sufficiently closed to the optimal value. 
We define the DRBC policy evaluation estimator $\hat{Q}_{\text{DRBC}}(\pi) = \sup_{\substack{\lambda > 0 \\ \beta \in \mathbb{R}}}\left\{\beta - \lambda \delta + \mathcal{E}_{\pi, \delta, \lambda, \beta}\right\}$ (see Algorithm \ref{DROPE} in Appendix \ref{defer}). Note that this empirical version of optimization problem is no longer strictly concave in $(\lambda, \beta)^T$ for finite sample size (it is strictly concave for $n \to \infty$). It is natural to have the following assumption, thus have the following $\mathcal{O}_p\left(n^{-1/2}\right)$ convergence rate guarantee.
\begin{assumption}\label{assempbound}
  For a fixed $\pi \in \mathcal{A}(x_0)$, with probability 1, $\arg\max\hat{Q}_{\text{DRBC}}(\pi)$ has the same bounds as the bounds for $\arg\max Q_{\text{DRBC}}(\pi)$ in Assumption \ref{ass0}.  
\end{assumption} 
% For the outer layer, we can sample from $B \sim \mu$ and then achieve the classical Monte Carlo error, hence once we sample a realization $b \in \mathbb{R}$ from $B$, for this fixed $b$ we need an estimator $Z(b)$ such that $E[Z(b)] = \Phi_{\lambda,\beta}\left(E^{P^b}\left[u(X_T)\right]\right)$. To do this, we need an unbiased estimator $Y(b)$ such that $E[Y(b)] = E^{P^b}\left[u(X_T)\right]$. From $Y(b)$, using techniques in \citet{Y(b)} we can do this nonlinear transformation of expectations. In order to get an unbiased estimator with a suitable CLT, we refer to \citet{ZhengBlanchetGlynn2018} and \citet{RheeGlynn2015}, which give us a CLT to derive an $\mathcal{O}\left(\frac{1}{\epsilon^2}\log\left(\frac{1}{\epsilon^2}\right)\right)$ sample complexity (in terms of computational budget, detail this later), which is basically (in practice) $\mathcal{O}\left(\frac{1}{\epsilon^2}\right)$, the canonical rate.

% \begin{theorem}\label{convergeneral}
%     Convergence without assumption on compact support.
% \end{theorem}

\begin{theorem}\label{CLT}
    Suppose Assumption \ref{ass0}, \ref{ass0.5}, \ref{ass2}, \ref{ass3}, \ref{finitevari}, and \ref{assempbound} hold, $\mu$ is compactly supported with a continuous density. For fixed $\pi \in \mathcal{A}(x_0)$, let  $n$ denote the number of i.i.d. samples of $\{E^{b_i}_{\lambda, \beta}\}_{1 \leq i \leq n}$, then 
    $$\sqrt{n}\left(\hat{Q}_{\text{DRBC}}(\pi) - Q_{\text{DRBC}}(\pi)\right)\Rightarrow \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \beta^*}\right)\right),$$
    where $\Rightarrow$ denotes convergence in distribution, $\left(\lambda^*, \beta^*\right)^T$ is defined in Section \ref{dual}, and $\mathcal{N}(0, \sigma^2)$ represents a normal distribution with mean $0$ and standard deviation $\sigma > 0$.
\end{theorem}

