\section{Policy Learning Step}\label{inneroptimization}
This section concentrates on the policy learning step. Section \ref{toy} focuses on the KL divergence case with a finitely-supported prior. In Section \ref{general}, we slightly modify the class of admissible controls and propose a general deep learning method, utilizing techniques from stochastic analysis. Interestingly, when the Lagrangian multipliers $\lambda$ and $\beta$ are fixed, the policy learning step is equivalent to solve a smooth ambiguity problem with functional parameters from the strong duality (Theorem \ref{duality}).
% Interestingly, this policy learning step can be viewed as numerical solvers for some financial problems (see Section \ref{smps} and Appendix \ref{KMM}).
\subsection{A Finite Prior Example: Duality Theory}\label{toy}
In the KL divergence case, if we fix $\lambda >0$, then we essentially need to solve 
\begin{equation}\label{toyexample}
   \sup_{\pi \in \mathcal{A}(x_0)}\left\{- \lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\}. 
\end{equation}
In fact, Problem (\ref{toyexample}) is equivalent to a problem in mathematical finance called the ambiguity aversion measured by the entropic risk measure \citep{schied2007optimal}. Because of the special form of the KL divergence, we obtain the duality form and thus a semi-closed form of the optimal solution.
% \subsubsection{Existence of Optimal Controls}
We define a class of equivalent probability measures $\mathcal{AC}$ on the set (quotient space with respect to the weak topology)
\begin{equation*}
\mathcal{AC}_{\text{pre}} 
= \left\{\begin{aligned}
  &\tilde{Q} \in \mathcal{P}(\Omega, \mathcal{F}), \\ &\tilde{Q} \ll P
\end{aligned}
\;\middle|\;
\begin{aligned}
    & \tilde{Q}(B \in A) = \nu(A) \text{ for some } %\\
     \nu \in \mathcal{P}(\mathbb{R}), \forall A \in \mathcal{B}(\mathbb{R}), \\
    & W \text{ is a standard Brownian} 
    \,  \text{motion under } \tilde{Q} \text{ and } B \perp W.
\end{aligned}
\right\}
\end{equation*}with respect to the equivalent relation $\sim$ defined in Section \ref{amset} That is, $\mathcal{AC} = \mathcal{AC}_{\text{pre}}/ \sim$. Then obviously, $\mathcal{U}_{\delta} \subset \mathcal{AC}$.
\begin{lemma}\label{ACset}
    For all $\tilde{Q} \in \mathcal{AC}$, there exists $\nu \ll \mu$ such that $\frac{d\tilde{Q}}{dP} = \frac{d\nu}{d\mu}(B)$ $P$-almost surely and $D_{\phi}\left(\tilde{Q} \parallel P\right) = D_{\phi}\left(\nu \parallel \mu\right)$. 
\end{lemma}
\begin{theorem}\label{dualityKL}
    \begin{align*}
        &\sup_{\pi \in \mathcal{A}(x_0)}\left\{- \lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\}= \sup_{\pi \in \mathcal{A}(x_0)}\inf_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[u(X_T)\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}.
    \end{align*}
\end{theorem}

% Note that Theorem \ref{dualityKL} transforms the maximization problem into a max-min problem with another constraint set about the probability measures, which is different from the uncertainty set of the prior distributions. 

Recall that for a fixed $\tilde{Q} \in \mathcal{AC}$, the problem becomes Problem (\ref{OriginalKaratzas}), thus it would be easier to solve the problem if we could interchange the sup and inf. In order to achieve this, we would like to apply Sion's min-max theorem (see Theorem \ref{Sionth} in Appendix \ref{prelim}) to the functional 
$f(\tilde{Q},\pi):= E^{\tilde{Q}}\left[u(X_T)\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right)$, which is defined on $\mathcal{AC} \times \mathcal{A}(x_0) \subset \mathcal{P}\left(\mathbb{R}\right) \times \mathcal{A}(x_0)$.

\begin{theorem}\label{optimaltoy}
    Assume that $\mu$ is finitely supported, $m = \text{ess inf }X_T$ exists, $P(X_T = m) > 0$, then there exists an optimal pair $\left(\tilde{Q}^*, \pi^*\right)$ such that $\pi^*$ is the optimal solution for Problem (\ref{OriginalKaratzas}) with underlying probability measure $\tilde{Q}^*$ (see Theorem \ref{Karatzassolution}) and
    \begin{align*}
        &\sup_{\pi \in \mathcal{A}(x_0)}\left\{- \lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\}
      = \sup_{\pi \in \mathcal{A}(x_0)}\inf_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}\\
      =& \inf_{\tilde{Q}\in \mathcal{AC}}\sup_{\pi \in \mathcal{A}(x_0)}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}
      = f\left(\tilde{Q}^*, \pi^*\right).
    \end{align*}
\end{theorem}
We focus on a commonly used example when the prior distribution takes value on a finite set of points $\left\{b_1, \ldots, b_d\right\}$ with probability mass function $P\left(B = b_i\right) = p_i \in (0,1)$, for $i = 1, 2, \ldots, d,$ where $d \geq 1$. For the fixed prior $\mu$, the optimal value function becomes 
$$\tilde{V}(\boldsymbol{p}) := \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(\tilde{F}_{\boldsymbol{p}}(T,z)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha},$$
where $\tilde{F}_{\boldsymbol{p}}(t,z) = \sum_{i=1}^dp_iL_t(b_i,z)$. If we want to find the optimal probability measure $\tilde{Q}^*(\lambda)$, then it suffices to solve the convex minimization problem (Theorem \ref{convex})
\begin{align}\label{toyopti}
&\inf_{\substack{\boldsymbol{q} = (q_1, \ldots, q_d)\\\sum_{i=1}^d q_i = 1,\text{and }q_i \geq 0}}V(\boldsymbol{q})=
    \inf_{\substack{\boldsymbol{q} = (q_1, \ldots, q_d)\\\sum_{i=1}^d q_i = 1,\text{and }q_i \geq 0}}\tilde{V}(\boldsymbol{q}) + \lambda\sum_{i=1}^d q_i \log \frac{q_i}{p_i}.
\end{align}
The DRBC algorithm to iteratively solve Problem (\ref{DRO}) (Algorithm \ref{DROKLA}) (we use (stochastic) gradient descent here) can be found in Appendix \ref{defer2}. The precise algorithm for updating $\pi$ is given in Algorithm \ref{DROpo} in Appendix \ref{algo}. We remark that the DRBC learning steps are done via simulated (training) samples $\{S_t\}_{t \in [0,T]}$ before we observe the real market data ($\{\tilde{S}_t\}_{t \in [0,T]}$). In other words, we derive optimal policies of the form in Theorem \ref{Karatzassolution} with a worst-case probability, and $\hat{\pi}_{\text{DRBCKL}}$ is computed by this worst-case probability and $\{\tilde{S}_t\}_{t \in [0,T]}$.
