\subsection{General Case: Deep Learning Approach}\label{general}
In this section, we consider the case for the general $\phi$-divergence, thus we need to solve for fixed $(\lambda,\beta)^T$, \begin{equation}\label{inner}
    \sup_{\pi \in \mathcal{A}(x_0)} \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{P^b}\left[u(X_T)\right]\right)d\mu(b).
\end{equation}
Under Assumption \ref{ass0.5}, $\Phi_{\lambda,\beta}$ is strictly concave and strictly increasing in $x$, thus Problem (\ref{inner}) is a continuous-time smooth ambiguity problem \citep{Klibanoff2005}. Such problems can be solved recursively in discrete-time \citep{Klibanoff2009}, but in continuous-time only few blue cases can be solved in closed-form, and there is few literature in numerical methods for this with generality.

We utilize tools from stochastic calculus and results from \cite{GLS22} to design a deep learning method to solve Problem (\ref{inner}). This motivates an alternate definition of the set of admissible controls $\tilde{\mathcal{A}}(x_0)$ that contains the optimal policy for a large class of Bayesian control problems (see Appendix \ref{alterdef}): the collection of all alternate admissible controls $\pi$, which is a subset of $\mathcal{A}(x_0)$ such that 
there exists a function $v \sim u$ such that there exists corresponding function $h: \mathbb{R} \to \mathbb{R}$ and a functional $\rho: L^1 \to \mathbb{R}$ such that for the controlled terminal wealth $X_T^{\pi}$,
$
\int_{\mathbb{R}}E^{P^b}\left[v(X_T^{\pi})\right]\lambda(b)d\mu(b) = h(x_0)\rho(\lambda)    
$
and $
    h(1) = v(e^{rT}).
$
For a fixed $b \in \mathbb{R}$, define $\eta^{b*}_t = \exp\left(-\frac{B-b}{\sigma}W_t - \frac{(B-b)^2}{2\sigma^2}t\right)$, $\frac{dQ^b}{dP} \Big|_{\mathcal{F}^S_t} = \eta^{b*}_t$, and $W_t^{b} = W_t + \frac{B-b}{\sigma}t$ for $t \in [0,T]$, then under $Q^b$, the process $W^b$ is an $\mathcal{F}^S$-Brownian motion that is independent from $B$, hence under $Q^b$, the stock price $S$ evolves as
$dS_t = S_t\left(bdt + \sigma dW^b_t\right)$
. Moreover,
$d X_t = (X_t - \pi_t) r \, d t + \pi_t \left(b d t + \sigma d W^b_t\right).$
For a fixed $b \in \mathbb{R}$,
$E^{P^b}\left[u(X_T)\right] = E^{Q^b}\left[u(X_T)\right],$
therefore it is equivalent to study the problem
$\sup_{\pi \in \tilde{\mathcal{A}}(x_0)} \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{Q^b}\left[u(X_T)\right]\right)d\mu(b),$
% \begin{equation}\label{newinner}
%     \sup_{\pi \in \tilde{\mathcal{A}}(x_0)} \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{Q^b}\left[u(X_T)\right]\right)d\mu(b).
% \end{equation}
which is solved in \cite{GLS22} with the introduction of new notations.
Let $b_0 = E^P[B]$ and if $b = b_0$, then we denote $W^{b_0}$ as $\hat{W}$. We also define for $t \in [0,T]$,
$\eta_t = \exp\left(-\nu\hat{W}_t - \frac{1}{2}\nu^2t\right),$
where $\nu = \frac{b_0-r}{\sigma}.$ For a fixed $b \in \mathbb{R}$, we define $t \in [0,T]$,
$\eta^{b}_t = \exp\left(-\nu_b\hat{W}_t - \frac{1}{2}\nu_b^2t\right),$
where $\nu_b = \frac{b_0-b}{\sigma}.$
% Even though for a fixed $b \in \mathbb{R}$,
% $E^{P^b}\left[u(X_T)\right] = E^{Q^b}\left[u(X_T)\right],$ 
The families of measures $\{P^b\}_{b \in \mathbb{R}}$ and $\{Q^b\}_{b \in \mathbb{R}}$ are quite different. 
For example, the distribution of $B$ under $Q^b$ is still $\mu$ (see Appendix \ref{transformderive}), where under $P^b$, $B$ is a constant $b$.
In the rest of this section, we assume that $\mu \sim \mathcal{N}\left(\mu_0, \sigma_0^2\right)$. Now, we are able to derive sufficient conditions that an optimal terminal wealth satisfies. Theorem \ref{system} motivates a loss function that also ensures numerical stability (Appendix \ref{algo3}).
\begin{theorem}\label{system}
If Assumption \ref{ass0.5} holds, $X_T$ is a terminal wealth such that there exists a constant $\kappa \in \mathbb{R}$ with $E^{Q^{r}} \left[ X_T  \right] = x_0 e^{r T}$ and $L_{\kappa}(X_T) = 0$
with
\begin{align*}
L_{\kappa}(X_T) &=
\kappa - \log\left(u'(X_T)\right)  - \frac{K_2^2}{4K_1} +\log\left(\frac{\sigma_0}{\sigma_Q}\right)\notag+ \frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T\notag \\
& +K_3+\log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right) \notag -\log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}'\left(E^{Q^a}[u(X_T)]\right)d\mu_A(a)\right)\notag 
\end{align*}
$D = W_T + \frac{B-b_0}{\sigma}T$, $K_1 = \dfrac{T}{2 \sigma^2} + \dfrac{1}{2 \sigma_0^2}$, $K_2 = \dfrac{T b_0}{\sigma^2} + \dfrac{D}{\sigma} + \dfrac{\mu_0}{\sigma_0^2}$, $K_3 = \dfrac{T b_0^2}{2 \sigma^2} + \dfrac{b_0 D}{\sigma} + \dfrac{\mu_0^2}{2 \sigma_0^2}$, $\mu_A \sim \mathcal{N}\left( \mu_Q, \sigma_Q^2 \right )$, $\sigma_Q^2 = \left( \dfrac{T}{\sigma^2} + \dfrac{1}{\sigma_0^2} \right )^{-1}$, and $\mu_Q = \sigma_Q^2 \left( \dfrac{W_T}{\sigma} + \dfrac{B T}{\sigma^2} + \dfrac{\mu_0}{\sigma_0^2} \right )$,
    then $X_T$ is the optimal terminal wealth for Problem (\ref{inner}).
\end{theorem}

