\section{Preliminaries}\label{prelim}
In this section, we present preliminary definitions and results that will be used for the proofs. 

\subsection{Preliminary Definitions}
\begin{definition}\label{C-R-def}
The \textit{Cressie-Read divergence} is a $\phi$- divergence where the convex function is taken by for a fixed $k > 1$,
$$f_k(t) = \frac{t^k - kt + k-1}{k(k-1)}.$$
\end{definition}

\begin{definition}\label{lineargrowth}
    Suppose $g: \mathbb{R}^d \to \mathbb{R}$ is a function, then we say $g$ satisfies the \textit{linear growth condition} if there exists a constant $c > 0$ such that $$\left|g(x)\right| \leq c\left(1 + \left\Vert x\right\Vert\right),$$ where $\left\Vert .\right\Vert$ denotes a norm in the Euclidean space.
\end{definition}

\begin{definition}
    Suppose $f: D \subset \mathbb{R}^d \to \mathbb{R}$ is a function, then we say $f$ is \textit{H\"{o}lder continuous} with parameter $w$ and bounding constant $K$ if there exists $K > 0$ and $w > 0$ such that for any $x, y \in D$, 
    \begin{equation}\label{Holdercont}
       \left|f(x) - f(y)\right| \leq K\left\Vert x-y\right\Vert^w. 
    \end{equation}
    We say $f$ is \textit{locally H\"{o}lder continuous} with parameter $w$ and bounding constant $K$ if Equation (\ref{Holdercont}) holds inside each compact neighborhood.
\end{definition}

\begin{definition}\label{directionalderivativfe}
    Let $B_1$ and $B_2$ be Banach spaces and $G: B_1 \to B_2$ be a mapping. It is said that $G$ is directionally differentiable at a considered point $\mu \in B_1$ if the limits
\[
G'_\mu(d) = \lim_{t \downarrow 0} \frac{G(\mu + t d) - G(\mu)}{t}
\]
exist for all $d \in B_1$.

Furthermore, it is said that $G$ is \textit{Gâteaux directionally differentiable} at $\mu$ if the directional derivative $G'_\mu(d)$ exists for all $d \in B_1$ and $G'_\mu(d)$ is linear and continuous in $d$. For ease of notation, we also denote $D_\mu(\mu_0)$ the operator $G'_\mu(\cdot)$.

Finally, it is said that $G$ is \textit{Hadamard directionally differentiable} at $\mu$ if the directional derivative $G'_\mu(d)$ exists for all $d \in B_1$ and
\[
G'_\mu(d) = \lim_{t \downarrow 0} \frac{G(\mu + t d') - G(\mu)}{t}, \quad d' \to d.
\]

\end{definition}

