\begin{theorem}\label{AbsBayesth}
(Abstract Bayes Theorem \citep{absBayes})  
 Suppose $(\Omega, \mathcal{F}, P)$ is a probability space and $\mathcal{G} \subseteq \mathcal{F}$ is a sub-$\sigma$-field. Suppose $\bar{P}$ is another probability measure absolutely continuous with respect to $P$ and with Radon-Nikodym derivative $\frac{d\bar{P}}{dP} = \Lambda$. Then if $\phi$ is any $\bar{P}$-integrable random variable
\[
E^{\bar{P}}[\phi \mid \mathcal{G}] = \psi \quad \text{where} \quad 
\psi = \frac{E^P[\Lambda \phi \mid \mathcal{G}]}{E^P[\Lambda \mid \mathcal{G}]} \quad \text{if } E^P[\Lambda \mid \mathcal{G}] > 0
\]
and $\psi = 0$ otherwise.
\end{theorem}

