\begin{theorem}\label{LemmaGW}
(\cite{YG23})
    Let $(Z_1, Z_2)$ be a 2-stage stochastic process and there exists $p \geq 1$, such that $E[|Z_2|^p] < \infty$. Conditioning on $Z_1$, sample i.i.d. $Z_2(1), \dots, Z_2(n)$. Then there exists a constant $B_p$ depending only on $p$ such that 
\[
E \left[ \left| \frac{1}{n} \sum_{i=1}^n Z_2(i) - E[Z_2 \mid Z_1] \right|^p \right] 
\leq 
\begin{cases} 
    B_p \frac{E[|Z_2|^p]}{n^{p/2}} & p > 2, \\
    B_p \frac{E[|Z_2|^p]}{n^{p-1}} & 1 \leq p \leq 2.
\end{cases}
\]
\end{theorem}

\begin{theorem}\label{Danskin}
(Danskin Theorem \citep{bonnans2013perturbation})
Let \( \Theta \subset \mathbb{R}^d \) be a nonempty compact set and \( B \) be a Banach space. Suppose the mapping \( G : B \times \Theta \to \mathbb{R} \) satisfies that \( G(\mu, \theta) \) and \( D_\mu(\mu, \theta) \) are continuous on \( O_{\mu_0} \times \Theta \), where \( O_{\mu_0} \subset B \) is a neighborhood around \( \mu_0 \). Let \( \phi : B \to \mathbb{R} \) be the inf-functional
\[
\phi(\mu) = \inf_{\theta \in \Theta} G(\mu, \theta)
\]
and \( \bar{\Theta}(\mu) = \operatorname{arg\,max}_{\theta \in \Theta} G(\mu, \theta) \). Then, the functional \( \phi \) is directionally differentiable at \( \mu_0 \) and
\[
G'_{\mu_0}(d) = \inf_{\theta \in \bar{\Theta}(\mu_0)} D_\mu(\mu_0, \theta) d.
\]
\end{theorem}

\begin{theorem}\label{Deltath}
(Delta Theorem \citep{shapiro2009stochastic})  
Let \( B_1 \) and \( B_2 \) be Banach spaces, equipped with their Borel \( \sigma \)-algebras, \( Y_N \) be a sequence of random elements of \( B_1 \), \( G : B_1 \to B_2 \) be a mapping, and \( \tau_N \) be a sequence of positive numbers tending to infinity as \( N \to \infty \). Suppose that the space \( B_1 \) is separable, the mapping \( G \) is Hadamard directionally differentiable at a point \( \mu \in B_1 \), and the sequence \( X_N = \tau_N (Y_N - \mu) \) converges in distribution to a random element \( Y \) of \( B_1 \). Then,
\[
\tau_N \big( G(Y_N) - G(\mu) \big) \Rightarrow G'_\mu(Y),
\]
and
\[
\tau_N \big( G(Y_N) - G(\mu) \big) = G'_\mu(X_N) + o_p(1).
\]
\end{theorem}

\begin{theorem}\label{Hadamard}(\citep{shapiro2009stochastic})
Let $B_1$ and $B_2$ be two Banach spaces, $G: B_1 \to B_2$ and $\mu \in B_1$. Then the following statements are true:
\begin{itemize}
    \item (1) If $G$ is Hadamard directionally differentiable at $\mu$, then the directional derivative $G'_{\mu}$ is continuous.
    \item (2) If $G$ is Lipschitz continuous in a neighborhood of $\mu$ and directionally differentiable at $\mu$, then $G$ is Hadamard directionally differentiable at $\mu$.
\end{itemize}

\end{theorem}

\begin{theorem}\label{Sionth}
(Sion's minmax Theorem \citep{sion1958minimax})
Let $M$ be any convex topological space and $O$ is a compact and convex space, $h: M \times O \to \mathbb{R}$ is a function such that
\begin{itemize}
    \item (1) For any fixed $x \in M$, $h(x,.)$ is lower semi-continuous and quasi-convex. 
    \item (2) For any fixed $y \in O$, $h(.,y)$ is upper semi-continuous and quasi-concave. 
\end{itemize}Then 
$$\sup_{x \in M}\inf_{y \in O}h(x,y) = \inf_{y \in O}\sup_{x \in M}h(x,y).$$
\end{theorem}

\section{Review of Bayesian and Martingale Methods}\label{mgmethod}
\subsection{Martingale Method Review}
In the classical literature \citep{Merton1971, cox1991variational, Karatzas1991}, $B$ is not a random variable but is a fixed real number. This problem is called Merton's problem in financial literature. In this case, we assume the controls are all $\mathcal{F}$-adapted. There are two ways to solve Problem (\ref{OriginalKaratzas}) in this case: dynamic programming and martingale method. 

The dynamic method is to guess a Hamilton–Jacobi–Bellman equation (HJB) equation (which is typically a nonlinear partial differential equation in the portfolio optimization problems) that the optimal control may satisfy, and then we use a verification method to show that solution (with some regularity) of this HJB equation indeed gets the optimal control. The final step is to either solve the HJB equation in closed-form or numerically.  
The dynamic programming method works well in the time-consistent case, but not well in the time-inconsistent case (See, for example, a discussion in \cite{HeZhou2016}). Thus, in this review section, we focus on another method. We remark that the traditional distributionally robust control are done via a dynamic programming approach, which we will revisit in Appendix \ref{Shengbo}.

On the other hand, the martingale and duality method, which we will call martingale method later, is a more probabilistic approach and works well for portfolio optimization problems in both time consistent and inconsistent cases (notice that this is only for the financial problems which allows replication of the portfolios \citep{bjork2009arbitrage}). Thus, we focus on the martingale method in this section now.

Recall that we want to solve 
\begin{equation*}
  V(x_0) = \sup_{\pi \in \mathcal{A}(x_0)}E^P\left[u(X_T)\right],  
\end{equation*}
where $\mathcal{A}(x_0)$ is the collection of all $\mathcal{F}$-progressively measurable stochastic processes $\pi= \{\pi_t\}_{t \in [0,T]}$ such that 
$\int_0^T \left \Vert \pi_t \right\Vert_2^2dt < \infty$ and 
     Equation (\ref{wealthp}) with $B$ being a fixed constant admits a unique strong solution.
The hardness of this problem is that the optimal control is indeed a stochastic process, which is infinite-dimensional. A change of measure argument will convert this problem into one-dimensional (i.e. with respect to a single random variable rather than a stochastic process).

Consider the set of all portfolios that can be generated starting with an initial capital of \( x \). By design, our final wealth \( X_T \) lies within this set, making it a suitable search domain for optimization with respect to \( X_T \). Since we only have one risky asset, then the market is complete, and according to the fundamental theorem of asset pricing (essentially Girsanov's theorem), \citep{KaratzasShreve1998} there exists a unique probability measure $Q$ that is equivalent to $P$ such that under $Q$, the discounted processes $e^{-rt}S_t$ and $e^{-rt}X_t$ are martingales. Thus the original problem becomes \begin{equation*}
  V(x_0) = \sup_{X_T \in \mathcal{A}(L^2)} E^P\left[u(X_T)\right], 
\end{equation*}where $\mathcal{A}(L^2)$ is the collection of $L^2$ random variables such that $e^{-rt}X_t$ is a martingale, which is equivalent to $$E^Q\left[e^{-rT}X_T\right] = x_0 = E^P\left[\frac{dQ}{dP}e^{-rT}X_T\right] = E^P\left[\rho_TX_T\right],$$
where $\rho_t = \exp\left(-\left(r+ \frac{\theta^2}{2} - \theta W_t\right)\right)$ and $\theta = \frac{B-r}{\sigma}$ is called the market price of risk. (For the computation of $\frac{dQ}{dP}$, see \cite{Karatzas1991}). Thus, writing down the Lagrangian duality of the new problem and using the point-wise optimization technique \citep{liang2019central}, we derive the optimal terminal wealth $X_T^*$.

Next we use the martingale property to derive the optimal wealth process by computing $$X_t^* = \frac{1}{\rho_t}E^P\left[\rho_TX_T^*|\mathcal{F}_t\right].$$

Finally, from the martingale representation theorem \citep{oksendal2003sde} (since $\rho_t X_t$ is a martingale under $P$), there exists an $\mathcal{F}$-adapted process $\{\phi_t\}_{t \in [0,T]}$ such that
\begin{equation*}
    \rho_t X_t^* = x_0 + \int_0^t \phi_s dW_s,
\end{equation*}
where $W_t$ is the $P$-Brownian motion driving the dynamics of the risky asset. Applying It\^o's lemma to $X_t^*$, we can match the diffusion term $\pi_t \sigma dW_t$ in the wealth equation to the diffusion term $\phi_t dW_t$. This gives
\begin{equation*}
    \pi_t^* = \frac{\phi_t}{\sigma}.
\end{equation*}

Thus, the optimal control $\pi_t^*$ is directly expressed in terms of the martingale representation process $\phi_t$, which is determined by the terminal condition $X_T^*$.

There are two takeaways from this method. Firstly, as long as we can construct the appropriate change of measure and the duality theory (in the complete market), then solving for the optimal control is equivalent to solving for the optimal terminal wealth. Secondly, the explicit computation based on the martingale property and It\^o's lemma depends highly on the Gaussian (Brownian motion) assumptions, thus this may not generalize to other cases (without specific distributions).

\subsection{Bayesian Technique Review and Proof of Theorem \ref{Karatzassolution}}\label{98review}
In practice, to use Merton's model to guide the investment, constants $B$ and $\sigma$ need to be estimated from the market data, then the model can be fitted with these estimators. However, in practice, even though the estimation of $\sigma$ is relatively easy, the estimation of $B$ as a constant is hard \citep{MehraPrescott1985}. Thus, it is natural to consider the Bayesian technique to randomized $B$ as a random variable that is independent of the Brownian motion $W$, and the prior distribution of $B$ can be chosen via experts' advice. This is why this stochastic diffusion control problem is called Bayesian. In this case, martingale method combined with Bayesian and filtering techniques can be used to derive the closed-form solution, where for the dynamic programming approach we still need to solve a second-order nonlinear partial differential equation \citep{BGP19, Rieder2005}.

\cite{KZ98} builds the solvability of Problem (\ref{OriginalKaratzas}), but the prior distribution is given to the random market price of risk $\Theta = \frac{B-r}{\sigma}$, which is equivalent to our setting theoretically, but the 
exact closed form solution will be slightly different. In this section, we adapt the theory in \cite{KZ98} to give the optimal solution of Problem (\ref{OriginalKaratzas}) in Theorem \ref{Karatzassolution}.

\begin{theorem}\label{Karatzassolution}
    The optimal value function of Problem (\ref{OriginalKaratzas}) is given by
   $$V(x_0) = \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(F(T,z)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha},$$
   and the optimal fraction invested in the stock for each time $t \geq 0$ is given by
   $$\frac{\pi^*_t}{X^*_t} = \frac{\int_{\mathbb{R}}\nabla F\left(T,z+Y_t\right)\left(F\left(T,z+Y_t\right)\right)^{\frac{\alpha}{1-\alpha}}\varphi_{T-t}(z)dz}{(1-\alpha)\sigma \int_{\mathbb{R}}\left(F\left(T,z+Y_t\right)\right)^{\frac{1}{1-\alpha}}\varphi_{T-t}(z)dz},$$
   where $\varphi_T$ is the density function of $\mathcal{N}(0,T)$, $Y_t = \frac{B-r}{\sigma}t + W_t$, and $F(t,y): =F_{\mu}(t,y) = \int_{\mathbb{R}}L_t(z,y)d\mu(z)$ with $L_t(z,y) = 1$ if $t = 0$ and $L_t(z,y) = \exp\left(\frac{z-r}{\sigma}y - \frac{1}{2}\left(\frac{z-r}{\sigma}\right)^2t\right)$ if $t > 0$. Moreover, the filtration generated by the process $\{Y_t\}_{t \in [0,T]}$ is the same as $\mathcal{F}^S$.
\end{theorem}

\begin{proof}
To begin with, from Girsanov's theorem \citep{KaratzasShreve1991}, 
$$\frac{1}{Z_t} = L_t^{-1}(B,Y_t) = \exp\left(-\frac{B-r}{\sigma}Y_t + \frac{1}{2}\left(\frac{B-r}{\sigma}\right)^2t\right)$$
is a $\mathcal{G}$-martingale under $P$ (hence also $\mathcal{F}^S$-martingale under $P$). If we define a probability measure $\tilde{P}$ by $\frac{d\tilde{P}}{dP} = \frac{1}{Z_T}$, then under $\tilde{P}$, $B$ still has the distribution $\mu$ and is independent of the Brownian motion $Y$.

Next, from the tower property, for fixed $t\in[0,T]$, 
\begin{align*}
    \hat{Z}_t := \tilde{E}\left[Z_T|\mathcal{F}^S_t\right]= \tilde{E}\left[\tilde{E}\left[Z_T|\mathcal{G}_t\right]|\mathcal{F}^S_t\right] = F(t,Y_t).
\end{align*}
Moreover, from the abstract Bayes' rule \citep{absBayes}, the conditional expectation of $B$ given the stock price is $$\widehat{B}_t: = E^P\left[B |\mathcal{F}^S_t\right] = G(t,Y_t),$$
where $G(t,y) = \left(\frac{\nabla F}{F}\right)(t,y)$.

Next, we introduce the so-called innovations process of filtering theory 
$$N_t = Y_t - \int_0^t G(s,Y_s)ds,$$
and from It\^o's lemma with $\hat{\Lambda}_t := \frac{1}{\hat{Z}_t}$, ($\langle ., . \rangle_t$ denotes the quadratic variation)
\begin{align*}
    d\left(\widehat{\Lambda}_t \cdot e^{-rt} X_t\right)
    &= \widehat{\Lambda}_t d\left(e^{-rt} X_t\right) + e^{-rt} X_t d\widehat{\Lambda}_t + d\langle e^{-rt} X, \widehat{\Lambda} \rangle_t \notag \\
    &= e^{-rt} \left[\widehat{\Lambda}_t \pi_t \sigma dY_t - \widehat{\Lambda}_t X_t \widehat{B}_t dN_t - \widehat{\Lambda}_t\pi_t\sigma \widehat{B}_t dt\right] \notag \\
    & = e^{-rt} \widehat{\Lambda}_t \left[\sigma \pi_t - X_t \widehat{B}_t\right] dN_t. 
\end{align*}
Therefore, the process $f$ is an $(\mathcal{F}^S, P)$ local martingale, where $f(t) = e^{-rt} \widehat{\Lambda}_tX_t$, thus we can use the martingale method as usual. If we define $$I(x) = \left(u'\right)^{-1}(x),$$
then it is not hard to show 
the optimal terminal wealth $X^*_T$ is given by 
$X^*_T = I\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right),$ \citep{KZ98}where $\mathcal{K}(x_0)$ is a well-defined constant. Then Example 3.5 in \cite{KZ98} gives the formulas of Theorem \ref{Karatzassolution}.

Finally, it suffices to show that there exists a measurable function $f$ such that $Y_t = f(t, S_t)$. 
We denote $S_0 = s_0 > 0$, then for $t \in [0,T]$,
\[
S_t = s_0 \exp\left( \left( B - \frac{\sigma^2}{2} \right) t + \sigma W_t \right).
\]Therefore,
\[
\log S_t = \log s_0 + \left( B - \frac{\sigma^2}{2} \right) t + \sigma W_t,
\]
which implies that
\[
W_t = \frac{ \log \left( \frac{S_t}{s_0} \right) - \left( B - \frac{\sigma^2}{2} \right) t }{ \sigma }.
\]
Hence
\begin{equation}\label{YS}
   Y_t = \frac{ \ln \left( \frac{S_t}{s_0} \right) }{ \sigma } + \left( \frac{ \sigma }{ 2 } - \frac{ r }{ \sigma } \right) t, 
\end{equation}
which finishes the proof.\end{proof}

\section{Proof of Results in Section \ref{set}}
\subsection{Proof of Theorem \ref{uncertaintyset}}
\begin{proof}
    \begin{itemize}
    \item (1) It is easy to see by checking the definitions, Equation (\ref{relation}) defines an equivalence relation, then the set of all equivalence classes under the quotient topology defines $\mathcal{U}_{\delta}$.
        \item (2) Fix $Q \in \mathcal{U}_{\delta}$, then there are 4 cases to check.
        \begin{itemize}
            \item (a) $\frac{dQ}{dP} = f(B)$, where $f: \mathbb{R} \to \mathbb{R}$ is bounded and (Borel) measurable. Then from definition of the uncertainty set, for any $A \in \mathcal{B}\left(\mathbb{R} \right)$, there exists $\nu \ll \mu$ such that
            \begin{align*}
                Q(B \in A) &= E^{Q}\left[\mathbf{1}_{\{B \in A\}}\right] = E^P\left[\frac{dQ}{dP}\mathbf{1}_{\{B \in A\}}\right] = E^P\left[f(B)\mathbf{1}_{\{B \in A\}}\right] \\ &= \nu(A) = \int_A \frac{d\nu}{d\mu}d\mu =  E^P\left[\frac{d\nu}{d\mu}(B)\mathbf{1}_{\{B \in A\}}\right],
            \end{align*}
            which implies that $\frac{dQ}{dP} = \frac{d\nu}{d\mu}(B)$ $P$-almost surely from the uniqueness of Radon-Nikodym derivative.
            \item (b) $\frac{dQ}{dP} = f(W)$, where $f: \Omega \to \mathbb{R}$ is bounded and measurable. In this case, it is convenient to assume $\Omega = C\left([0,T];\mathbb{R}\right)$. Thus the standard Brownion motion $W: \Omega \to \Omega$ can be viewed as a function-valued random element. Therefore, for $A \in \mathcal{B}(\Omega)$, 
            \begin{align*}
               Q(W \in A) &= E^{Q}\left[\mathbf{1}_{\{W \in A\}}\right] = E^P\left[\frac{dQ}{dP}\mathbf{1}_{\{W \in A\}}\right] \\
               &= E^P\left[f(W)\mathbf{1}_{\{W \in A\}}\right] 
               \neq P(W \in A)
            \end{align*}unless $f = 1$, which is equivalent to the case when $\frac{dQ}{dP} = \frac{d\nu}{d\mu}(B)$ with $\nu = \mu$.
            \item (c) $\frac{dQ}{dP} = f(B, W)$, where $f: \mathbb{R} \times \Omega \to \mathbb{R}$ is bounded and jointly measurable. From part (b) and independence between $B$ and $W$, it is easy to construct a contradiction. 
            \item (d) $\frac{dQ}{dP} = f(Y)$, where $f: \Omega \to \mathbb{R}$ is bounded and  measurable, and $Y$ is a stochastic process that is independent of both $B$ and $W$. From the definition of the equivalence classes, this case is equivalent to the case when $\frac{dQ}{dP} = \frac{d\nu}{d\mu}(B)$ with $\nu = \mu$.
        \end{itemize}
        Moreover, \begin{align*}
           D_{\phi}(Q \parallel P) = \int \phi\left(\frac{dQ}{dP}\right) \, dP &= \int \phi\left(\frac{d\nu}{d\mu}(B)\right) \, dP= \int \phi\left(\frac{d\nu}{d\mu}\right) \, d\mu = D_{\phi}(\nu \parallel \mu).
        \end{align*}
        % \item (3) 
    \end{itemize}
\end{proof}

