    Since the topological and convexity structures are the preserved, then with a similar argument as in Section 3.2 in \cite{Shapiro17}, the Lagrangian of the problem $\inf_{\hat{Q} \in \hat{\mathcal{U}_{\delta}}} E^{\hat{Q}}\left[E^{Q^B}\left[u(X_T)\right]\right]$ is given by
\begin{align*}\mathcal{L}_Z\left(\hat{X},\lambda,\beta\right) &= \int_{\Omega}Z\hat{X}dP + \lambda\left(\int_{\Omega}\phi\left(\hat{X}\right)dP-\delta\right) + \beta\left(1-\int_{\Omega}\hat{X}dP\right)\\
&=\beta - \lambda \delta + \int_{\Omega}\left(Z\hat{X} + \lambda \phi\left(\hat{X}\right)-\beta\hat{X}\right)dP,
    \end{align*}
and the Lagrangian dual problem is $$\sup_{\lambda \geq 0, \mu \in \mathbb{R}}\inf_{\hat{X} \geq 0}\mathcal{L}_Z\left(\hat{X},\lambda,\beta\right).$$
Since the space $L^p\left(\Omega, \hat{\mathcal{F}}, \hat{P}\right)$ is decomposable, then as in \cite{Shapiro17}, 
\begin{align*}
    \inf_{\hat{X} \geq 0}\mathcal{L}_Z\left(\hat{X},\lambda,\beta\right)
    &=\beta - \lambda \delta +  \inf_{\hat{X} \geq 0}\left\{\int_{\Omega}\left(Z\hat{X} + \lambda \phi\left(\hat{X}\right)-\beta\hat{X}\right)d\hat{P}\right\}\\
    &= \beta - \lambda \delta + \int_{\Omega}\inf_{x \geq 0}\left(Zx + \lambda \phi(x) - \beta x\right)d\hat{P}\\
    &= \beta - \lambda \delta + \int_{\Omega}-\left(\lambda \phi\right)^*(\beta - Z)d\hat{P}\\
    &= \beta - \lambda \delta + E^{\hat{P}}\left[-\left(\lambda \phi\right)^*(\beta - E^{P^B}\left[u(X_T)\right])\right]\\
    &= \beta - \lambda \delta + E^{\hat{P}}\left[\Phi_{\lambda, \beta}\left(E^{P^B}\left[u(X_T)\right]\right)\right].
    % &= \beta - \lambda \delta + \lambda \int_{\Omega}\inf_{\hat{X} \geq 0}\left\{\left(\phi(\hat{X}) - \frac{\beta - Z}{\lambda}\hat{X}\right)\right\}d\hat{P}\\
    % &= \beta - \lambda \delta + \lambda\int_{\Omega}(-\phi^*)\left(\frac{\beta - Z}{\lambda}\right)d\hat{P}\\
    % &= \beta - \lambda \delta + \lambda\int_{\Omega}\Phi_{\lambda, \beta}\left(E^{P^B}[u(X_T)]\right)d\hat{P}\\
    % &= \beta - \lambda \delta + \lambda E^{\hat{P}}\left[\Phi_{\lambda,\beta}\left(E^{P^B}\left[u(X_T)\right]\right)\right].
\end{align*}
    Therefore,
    \begin{align*}
       \inf_{Q \in \mathcal{U}_{\delta}} E^Q\left[u(X_T)\right] 
       &=\inf_{Q \in \mathcal{U}_{\delta}} E^Q\left[E^{Q^B}\left[u(X_T)\right]\right]\\
       &= \inf_{\hat{Q} \in \hat{\mathcal{U}_{\delta}}} E^{\hat{Q}}\left[E^{Q^B}\left[u(X_T)\right]\right] \\
       &=\sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta +  E^{\hat{P}}\left[\Phi_{\lambda,\beta}\left(E^{P^B}\left[u(X_T)\right]\right)\right]\right\}\\
       &=\sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta +  E^{P}\left[\Phi_{\lambda,\beta}\left(E^{P^B}\left[u(X_T)\right]\right)\right]\right\}\\
       &= \sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta +  \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{P^b}\left[u(X_T)\right]\right)d\mu(b)\right\}, 
    \end{align*}which finishes the proof. 
\end{proof}
\begin{remark}
If we plug in $u(X_T)$ as an $\mathcal{F}$-measurable random variable, then the strong duality would look like $$\inf_{Q \in \mathcal{U}_{\delta}} E^Q\left[u(X_T)\right] = \sup_{\lambda > 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta + \lambda E^P\left[G_{\lambda,\beta}(X_T)\right]\right\},$$
where for fixed $\lambda > 0, \beta \in \mathbb{R}$ (assuming multipliers nonzero),
$$G_{\lambda, \beta}(x) := (-\phi^*)\left(\frac{\beta-u(x)}{\lambda}\right).$$
The strong duality looks better than the one stated in Theorem \ref{duality} since it is more tractable. However, this is wrong since $\mathcal{U}_{\delta}$ is not law invariant with respect to $\mathcal{F}$. As in the language of \cite{Shapiro17}, suppose we have a Radon-Nikodym derivative $X = f(B)$, where $f$ is a measurable function and $B \in \mathcal{N}(0,1)$, define $Y = f(W_1)$, then $X$ and $Y$ are distributionally equivalent but $Y$ cannot induce a probability measure that belongs to $\mathcal{U}_{\delta}$ (by Theorem \ref{uncertaintyset}).
\end{remark}

\subsection{Proof of Theorem \ref{KLduality}}
\begin{proof}
Since $\phi(x) = x\log x -x +1$, then $\Phi_{\lambda, \beta}(x) = \lambda\left(1-\exp\left(\frac{\beta-x}{\lambda}\right)\right)$ if $\lambda > 0$. Therefore, if optimal $\lambda^* \neq 0$, then
\begin{align*}
    \inf_{Q \in \mathcal{U}_{\text{KL},\delta}} E^Q\left[u(X_T)\right] &= \sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta + \int_{\mathbb{R}}\lambda \left(1-\exp\left(\frac{\beta-E^{P^b}[u(X_T)]}{\lambda}\right)\right)d\mu(b)\right\}.
\end{align*}
If we take derivative with respect to $\beta$, then we get the optimal $\beta^*$
$$\beta^* = - \lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-E^{P^b}\left[u(X_T)\right]}{\lambda}\right)d\mu(b)\right).$$
After plugging in, we have
$$
     \inf_{Q \in \mathcal{U}_{\text{KL},\delta}} E^Q\left[u(X_T)\right] =\sup_{\lambda \geq 0}\left\{-\lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-E^{P^b}\left[u(X_T)\right]}{\lambda}\right)d\mu(b)\right)\right\}.
$$ The case when $\lambda = 0$ is from discussion of case 1 after Assumption 1 in \cite{HuHong2013}.
\end{proof}

\subsection{Extension to Cressie-Read Divergence}\label{C-R}
We give a theorem for the Cressie-Read divergence with the uncertainty set is denoted as $\mathcal{U}_{k,\delta}$ for $\phi_k(x) = \frac{x^k-kx+k-1}{k(k-1)}$ with $k \in (1, \infty)$. We further define $k_* = \frac{k}{k-1}$ and $c_k(\delta) = \left(1+k(k-1)\delta\right)^{\frac{1}{k}}$.
\begin{theorem}\label{C-Rdivergence}
   \begin{align*}
    \inf_{Q \in \mathcal{U}_{k,\delta}} E^Q\left[u(X_T)\right] = \sup_{\beta \in \mathbb{R}}\left\{
     \beta - c_k(\delta) \left(\int_{\mathbb{R}}\left(\beta - E^{P^b}\left[u(X_T)\right]\right)_+^{{k_*}}d\mu(b)\right)^{\frac{1}{k_*}}\right\}.
 \end{align*}   
\end{theorem}
\begin{proof}
From \cite{JohnDuchi}, we know that 
$$\phi_k^* (x) = \frac{1}{k}\left((k-1)x + 1\right)_+^{k_*} - \frac{1}{k}.$$
Therefore, by plugging in this to Theorem \ref{duality}, we have
\begin{align*}
&\inf_{Q \in \mathcal{U}_{k,\delta}} E^Q\left[u(X_T)\right]\\&= \sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \delta + \lambda E^P\left[\Phi_{\lambda,\beta}\left(E^{P^B}\left[u(X_T)\right]\right)\right]\right\}\\
&=\sup_{\lambda \geq 0, \beta \in \mathbb{R}}\left\{\beta - \lambda \left(\delta - \frac{1}{k}\right) - \lambda^{1-k_*} \frac{(k-1)^{k_*}}{k}
E^P\left[\left(\beta - E^{P^B}\left[u(X_T)\right]+ \frac{\lambda}{k-1}\right)_+^{{k_*}}\right]\right\}\\
&=\sup_{\lambda \geq 0, \tilde{\beta} \in \mathbb{R}}\left\{\tilde{\beta} - \lambda \left(\delta + \frac{1}{k(k-1)}\right) - \lambda^{1-k_*} \frac{(k-1)^{k_*}}{k}
E^P\left[\left(\tilde{\beta} - E^{P^B}\left[u(X_T)\right]\right)_+^{{k_*}}\right]\right\},
\end{align*}
where we define $\tilde{\beta} = \beta + \frac{\lambda}{k-1}$ thus the last equality holds. Noting that $\frac{k_* - 1}{k_*} = \frac{1}{k}$ and taking derivatives with respect to $\lambda$ to minimize the preceding expression, we have 
$$\lambda = (k-1)\left(\delta k (k-1)+1\right)^{-\frac{1}{k_*}}\left(E^P\left[\left(\tilde{\beta} - E^{P^B}\left[u(X_T)\right]\right)_+^{{k_*}}\right]\right)^{\frac{1}{k_*}}.$$
By substituting back, we have
\begin{align*}
    &\inf_{Q \in \mathcal{U}_{k,\delta}} E^Q\left[u(X_T)\right] \\ &= \sup_{\tilde{\beta} \in \mathbb{R}}\left\{\tilde{\beta} - \left(\delta k (k-1)+1\right)^{\frac{1}{k}} \left(E^P\left[\left(\tilde{\beta} - E^{P^B}\left[u(X_T)\right]\right)_+^{{k_*}}\right]\right)^{\frac{1}{k_*}}\right\}\\
    &= \sup_{\tilde{\beta} \in \mathbb{R}}\left\{\tilde{\beta} - c_k(\delta) \left(\int_{\mathbb{R}}\left(\tilde{\beta} - E^{P^b}\left[u(X_T)\right]\right)_+^{{k_*}}d\mu(b)\right)^{\frac{1}{k_*}}\right\},
\end{align*}
which finishes the proof.
\end{proof}

\subsection{Existence and Uniqueness of the Dual Optimizer}\label{upperboundsec}
\begin{theorem}\label{KL1}
 Assume Assumption \ref{ass2} and \ref{ass3} hold, then for a fixed $\pi \in \mathcal{A}(x_0)$, there exist positive and finite $\Bar{\lambda}$ and $\underline{\lambda}$ such that any optimal $\lambda^*(\pi) \in [\underline{\lambda}, \Bar{\lambda}]$.
\end{theorem}

\begin{proof}
From Jensen's inequality, we have
$$\log\left(\int_{\mathbb
R}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right) \geq \int_{\mathbb
R}\log\left(\exp\left(\frac{-Z^b}{\lambda}\right)\right)d\mu(b)= \frac{-1}{\lambda}E^P[Z^B],$$
thus $$-\lambda\log\left(\int_{\mathbb
R}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)-\lambda \delta \leq E^P[Z^B]-\lambda \delta \leq M -\lambda \delta.$$
On the other hand, 
$$\inf_{Q \in \mathcal{U}_{\text{KL},\delta}} E^Q\left[u(X_T)\right] \geq \text{ess inf }u(X_T) \geq 0$$
since $X_T \geq 0$ and $u$ is strictly increasing, then $M - \lambda \delta \geq 0$ gives the upper bound $\lambda^*(\pi) \leq \Bar{\lambda} := \frac{M}{\delta}$.

For the lower bound, it suffices to show there exists $\lambda > 0$ such that $$-\lambda\log\left(\int_{\mathbb
R}\exp\left(\frac{-E^{P^b}[u(X_T)]}{\lambda}\right)d\mu(b)\right)-\lambda \delta > \text{ess inf }E^{P^B}[u(X_T)] \geq u(m),$$
which is equivalent to 
$$E\left[\exp\left(\frac{-E^{P^b}[u(X_T)] + u(m)}{\lambda}\right)\right] < e^{-\delta}.$$
Since as $\lambda \to 0$, LHS $\to 0$ (as a left limit), thus as long as we pick $\lambda > 0$ small enough, then the inequality is achieved, thus the optimal $\lambda^* >0$, thus the optimal $\lambda^*$ is attained inside the interval $[\underline{\lambda}, \Bar{\lambda}]$.
\end{proof}

\begin{remark}
    We remark that for the proof of upper bound of the dual optimizer, the moment condition can be relaxed to $\int_{\mathbb{R}}
      V_b(x_0)d\mu(b) < \infty$. The bound $\int_{\mathbb{R}}
      \bigl(V_b(x_0)\bigr)^{3(1+w)}d\mu(b) < \infty$ is essential in the construction of the rMLMC estimator.
\end{remark}

\begin{theorem}\label{KL2}
   If Assumption \ref{ass2} and \ref{ass1} satisfied, then for a fixed $\pi \in \mathcal{A}(x_0)$, there exist positive and finite $\Bar{\lambda}$ and $\underline{\lambda}$ such that any optimal $\lambda^*(\pi) \in [\underline{\lambda}, \Bar{\lambda}]$. 
\end{theorem}
\begin{proof}
    The proof of the upper bound is the same as proof of Theorem \ref{KL1}. For the lower bound, even though the same proof as Theorem \ref{KL1} can be done, we adapt the proof of Lemma A12 from \cite{NianSi} to illustrate the usefulness of the stronger Assumption  \ref{ass1}.

    Essentially, the proof of density and mass function cases are the same, so without loss of generality, we use $f$ to denote the continuous density of $E^{P^B}[u(X_T)]$ on a compact set $K$, thus $\Bar{b} = \sup_{x \in K}f(x) < \infty$ exists. Further, we define for a fixed $\pi \in \mathcal{A}(x_0)$, $g(\lambda) = g_{\pi}(\lambda) = -\lambda \log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right) - \lambda \delta$. Therefore, since $$\displaystyle{\lim_{\lambda \to 0}}g(\lambda) = 0,$$ it suffices to show that $$\displaystyle{\liminf_{\lambda \to 0}}\frac
    {dg(\lambda)}{d\lambda} > 0.$$
    Indeed,
    $$\frac
    {dg(\lambda)}{d\lambda} = \frac{\int_{\mathbb{R}}\frac{-Z^b}{\lambda}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)}{\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)} - \delta - \log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right).$$
We notice that 
$$\displaystyle{\lim_{\lambda \to 0}}- \log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right) = \infty$$and
\begin{align*}
\displaystyle{\liminf_{\lambda \to 0}}\frac{\int_{\mathbb{R}}\frac{-Z^b}{\lambda}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)}{\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)} &= \displaystyle{\liminf_{\lambda \to 0}}\frac{\int_{\mathbb{R}}\frac{-Z^b}{\lambda}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)/\lambda}{\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)/\lambda}  \geq -\frac{\Bar{b}}{b} 
\end{align*}since $$\int_0^{\infty}\frac{y}{\lambda}e^{-\frac{y}{\lambda}}dy = \int_0^{\infty}e^{-\frac{y}{\lambda}}dy = \lambda.$$
As a result, $$\displaystyle{\liminf_{\lambda \to 0}}\frac
    {dg(\lambda)}{d\lambda} = \infty.$$
Since the objective function is strictly concave in $\lambda$ (Theorem \ref{KLderivatives}), then the uniqueness is shown, thus finishes the proof.
\end{proof}
\begin{remark}
    Similarly, mild assumptions on the moments \citep{JohnDuchi} gives the uniqueness and strictly concavity of the objective function in the Cressie-Read divergence case.
\end{remark}

\section{Supplementary for Section \ref{outeroptimization}}
We first provide two lemmas that will be used in the proof of Theorem \ref{unbiasedth}.
\begin{lemma}\label{compactlemma}
 Suppose Assumption \ref{finitevari} holds and $\mu$ is compactly supported with a continuous density, then for each fixed $\pi \in \mathcal{A}(x_0)$, there exists a constant $M > 0$ such that with probability one, 
 $$0 \leq Z^B = E^{P^B}[u(X_T)] \leq M.$$
 That is, the random variable $Z^B$ has a compact support.
\end{lemma}
\begin{proof}
    Since function $b \mapsto Z^b$ is continuously differentiable and monotone on its support, thus the random variable $Z^B$ has a continuous density. Since the support is compact, then with probability one, $Z^B$ has attainable maximum and minimum.
\end{proof}

\begin{remark}
    Lemma \ref{compactlemma} helps establish the finite variance of the estimator $\mathcal{E}_{\pi, \delta, \lambda, \beta}$. The same result will be automatically true if Assumption \ref{ass1} holds.
