    &= D\Phi_{\lambda, \beta}\left(Z^B\right)\left(\frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right) +  \frac{1}{2}D^2\Phi_{\lambda, \beta}\left(\xi_{n+1}^B\right)\left(\frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right)^2 \\
    & - \frac{1}{2}\left[D\Phi_{\lambda, \beta}\left(Z^B\right)\left(\frac{S^{O,B}_{2^{n}}}{2^{n}} - Z^B\right) + \frac{1}{2}D^2\Phi_{\lambda, \beta}\left(\xi_{n}^{O,B}\right)\left(\frac{S^{O,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right]\\
    & - \frac{1}{2}\left[D\Phi_{\lambda, \beta}\left(Z^B\right)\left(\frac{S^{E,B}_{2^{n}}}{2^{n}} - Z^B\right) + \frac{1}{2}D^2\Phi_{\lambda, \beta}\left(\xi_{n}^{E,B}\right)\left(\frac{S^{E,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right].
\end{align*}
Since $\hat{Z}^B$ is an unbiased estimate of $Z^B$, then from the boundedness of second derivative (Equation (\ref{LBS})),
\begin{align*}
    &E^P\left[\left(\Delta_n^B \right)^2\right] \leq \frac{1}{4} E^P\left[\left\Vert D^2\Phi_{\lambda, \beta}\left(\xi_{n+1}^B\right)\left(\frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right)^2\right\Vert_2^2\right] \\
    &+ \frac{1}{8}E^P\left[\left\Vert D^2\Phi_{\lambda, \beta}\left(\xi_{n}^{O,B}\right)\left(\frac{S^{O,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right\Vert_2^2\right]
    + \frac{1}{8}E^P\left[\left\Vert D^2\Phi_{\lambda, \beta}\left(\xi_{n}^{E,B}\right)\left(\frac{S^{E,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right\Vert_2^2\right]\\
    &\leq \frac{K}{4} E^P\left[\left\Vert \left(\frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right)^2\right\Vert_2^2\right] + \frac{K}{8}E^P\left[\left\Vert \left(\frac{S^{O,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right\Vert_2^2\right]+ \frac{K}{8}E^P\left[\left\Vert \left(\frac{S^{E,B}_{2^{n}}}{2^{n}} - Z^B\right)^2\right\Vert_2^2\right].
\end{align*}
From  Jensen's inequality and Lemma \ref{LemmaGW}, there exists a constant $K_2$ such that
$$E^P\left[\left\Vert \left(\frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right)^2\right\Vert_2^2\right] \leq E^P\left[\left\Vert \frac{S^B_{2^{n+1}}}{2^{n+1}} - Z^B\right\Vert_2^4\right]\leq \frac{K_2}{2^{2(n+1)}} E^P\left[\left\Vert Z^B\right\Vert_2^4\right] \lesssim \mathcal{O}\left(2^{-2n}\right),$$
where $f(n) \lesssim \mathcal{O}\left(2^{-2n}\right)$ means there is a constant $C > 0$ such that $f(n) \leq C2^{-2n}$.

 Therefore, there exists a constant $C>0$ such that
 \begin{align*}
 E^P\left[\left(\frac{\Delta_N^B}{p(N)}\right)^2\right] &= \sum_{n = 0}^{\infty} \frac{E^P\left[\left(\Delta_n^B\right)^2\right]}{p(n)}
 \leq C\sum_{n = 0}^{\infty}\frac{2^{-2n}}{p(n)} < \infty,
 \end{align*}from the discussion of in Section 3 in \cite{Y_b}. Therefore, $\text{Var}\left(\mathcal{E}_{\pi, \delta, \lambda, \beta}\right)$ is also finite.


