\subsection{First and Second Order Conditions}\label{derivatives}
In this section, we give the first and second order conditions for the general $\phi$-divergence case with $\Phi_{\lambda, \beta}$ strictly concave and strictly increasing in $(\lambda, \beta)^T$ for large $n$. We remark that for a fixed $n \in \mathbb{N}$, the value function is not strictly concave in $(\lambda, \beta)^T$ since the definition of rMLMC estimator introduces negative linear combination of strictly concave functions. Since the estimator is not strictly concave and is random, it may be better to use the (stochastic) gradient descent method to escape from irregular points (e.g. saddle points).
\begin{theorem}\label{Hessian}
Define $F(\lambda, \beta; \pi, \delta) = \beta - \lambda \delta + \mathcal{E}$ for fixed $\delta > 0$ and policy $\pi$, then $F$ is strictly concave in $(\lambda, \beta)$ as $n \to \infty$ under Assumption \ref{ass0.5} and its first and second (mixed) partial derivatives admit the expressions
\begin{equation}\label{dlambda}
  \frac{\partial F}{\partial \lambda} :=\frac{\partial F(\lambda, \beta; \pi, \delta)}{\partial \lambda} = \frac{1}{n}\sum_{i=1}^n \frac{\Delta_{N^{b_i}, \lambda}^{b_i}}{p(N^{b_i})} - \delta + \frac{\partial \Phi_{\lambda, \beta}}{\partial \lambda}\left(\frac{S^{b_i}_{2^{n_0}}}{2^{n_0}}\right),  
\end{equation}
\begin{equation}\label{dbeta}
  \frac{\partial F}{\partial \beta} :=\frac{\partial F(\lambda, \beta; \pi, \delta)}{\partial \beta} = \frac{1}{n}\sum_{i=1}^n \frac{\Delta_{N^{b_i}, \beta}^{b_i}}{p(N^{b_i})} + 1 + \frac{\partial \Phi_{\lambda, \beta}}{\partial \beta}\left(\frac{S^{b_i}_{2^{n_0}}}{2^{n_0}}\right),  
\end{equation}
\begin{equation}\label{dlambdabeta}
  \frac{\partial^2 F}{\partial \lambda \partial \beta} :=\frac{\partial^2 F(\lambda, \beta; \pi, \delta)}{\partial \lambda \partial \beta} = \frac{1}{n}\sum_{i=1}^n \frac{\Delta_{N^{b_i}, \lambda, \beta}^{b_i}}{p(N^{b_i})} + \frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \lambda \partial \beta }\left(\frac{S^{b_i}_{2^{n_0}}}{2^{n_0}}\right),  
\end{equation}
\begin{equation}\label{d2lambda}
  \frac{\partial^2 F}{\partial \lambda^2} :=\frac{\partial^2 F(\lambda, \beta; \pi, \delta)}{\partial \lambda^2} = \frac{1}{n}\sum_{i=1}^n \frac{\Delta_{N^{b_i}, \lambda^2}^{b_i}}{p(N^{b_i})}+ \frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \lambda^2}\left(\frac{S^{b_i}_{2^{n_0}}}{2^{n_0}}\right),  
\end{equation}and
\begin{equation}\label{d2beta}
  \frac{\partial^2 F}{\partial \beta^2} :=\frac{\partial^2 F(\lambda, \beta; \pi, \delta)}{\partial \beta^2} = \frac{1}{n}\sum_{i=1}^n \frac{\Delta_{N^{b_i}, \beta^2}^{b_i}}{p(N^{b_i})}+ \frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \beta^2}\left(\frac{S^{b_i}_{2^{n_0}}}{2^{n_0}}\right),  
\end{equation}
where for fixed $b \in \mathbb{R}$, $n \in \mathbb{N}$, and $y,y' \in \{\lambda, \beta\}$, 
\begin{align*}
    \Delta_{n,y}^b &= \frac{\partial}{\partial y}\Phi_{\lambda,\beta}\left(\frac{S_{2^{n+1}}^b}{2^{n+1}}\right) \\
    &- \frac{1}{2}\frac{\partial}{\partial y}\left(\Phi_{\lambda,\beta}\left(\frac{S^{O,b}_{2^{n}}}{2^{n}}\right) + \Phi_{\lambda,\beta}\left(\frac{S^{E,b}_{2^{n}}}{2^{n}}\right)\right),
\end{align*}
\begin{align*}
    \Delta_{n,y^2}^b &= \frac{\partial^2}{\partial y^2}\Phi_{\lambda,\beta}\left(\frac{S_{2^{n+1}}^b}{2^{n+1}}\right) \\
    &- \frac{1}{2}\frac{\partial^2}{\partial y^2}\left(\Phi_{\lambda,\beta}\left(\frac{S^{O,b}_{2^{n}}}{2^{n}}\right) + \Phi_{\lambda,\beta}\left(\frac{S^{E,b}_{2^{n}}}{2^{n}}\right)\right),
\end{align*}and
\begin{align*}
    \Delta_{n,y,y'}^b &= \frac{\partial^2}{\partial y \partial y'}\Phi_{\lambda,\beta}\left(\frac{S_{2^{n+1}}^b}{2^{n+1}}\right) \\
    &- \frac{1}{2}\frac{\partial^2}{\partial y \partial y'}\left(\Phi_{\lambda,\beta}\left(\frac{S^{O,b}_{2^{n}}}{2^{n}}\right) + \Phi_{\lambda,\beta}\left(\frac{S^{E,b}_{2^{n}}}{2^{n}}\right)\right).
\end{align*}
\end{theorem}
\begin{proof}
   Since $\Phi_{\lambda, \beta}$ is strictly concave in $(\lambda, \beta)^T$ and $\mathcal{E}$ is an unbiased and consistent estimator, then so is $F$ as $n \to \infty$. The computation of derivatives is elementary.
\end{proof}
% \subsection{Proof of Theorem \ref{convergeneral}}
% \begin{proof}

% \end{proof}
Next, we give a specific example of the KL divergence case.
Recall that in this case, \begin{align*}
   Q_{\text{DRBCKL}}(\pi)=\sup_{\substack{\lambda > 0}}\left\{- \lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\},
\end{align*}
which has a form that is more complicated than the general case: in the KL case there are two nonlinear transformations $\log$ and $\exp$ in the nested expectation, thus to get an unbiased estimator of $Q_{\text{DRBCKL}}(\pi)$ we need to apply the rMLMC method recursively \citep{YG23}.

Another way is to keep the form when there are two multipliers $\lambda$ and $\beta$ rather than using the form $Q_{\text{DRBCKL}}(\pi)=\sup_{\substack{\lambda > 0}}\left\{- \lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\}$. This can avoid the multi-layer nested expectation and nonlinear transformations if the $\Phi_{\lambda, \beta}$ corresponding to the KL divergence is strictly concave. However, this is always false.
\begin{theorem}\label{HessianKL}
    When $\phi(x) = x\log x - x +1$, then $\Phi_{\lambda, \beta}$ is concave but it is never strictly concave in $(\lambda, \beta)^T$ (jointly).
\end{theorem}

\begin{proof}
  If $\phi(x) = x\log x - x +1$, then $\Phi_{\lambda, \beta}(x) = \lambda\left(1-\exp\left(\frac{\beta-x}{\lambda}\right)\right)$ if $\lambda > 0$. Therefore, if optimal $\lambda^* \neq 0$, then 
  $$\frac{\partial}{\partial \lambda}\Phi_{\lambda, \beta}(x) = 1 + \exp\left(\frac{\beta - x}{\lambda}\right) \left(\frac{\beta - x}{\lambda} - 1\right),$$
  $$\frac{\partial}{\partial \beta}\Phi_{\lambda, \beta}(x) = -\exp\left(\frac{\beta - x}{\lambda}\right),$$
  $$\frac{\partial^2}{\partial \lambda \partial \beta}\Phi_{\lambda, \beta}(x) = \frac{\beta - x}{\lambda^2} \exp\left(\frac{\beta - x}{\lambda}\right),$$
  $$\frac{\partial^2}{\partial \lambda^2}\Phi_{\lambda, \beta}(x) = -\frac{(\beta - x)^2}{\lambda^3} \exp\left(\frac{\beta - x}{\lambda}\right),$$and $$\frac{\partial^2}{\partial \beta^2}\Phi_{\lambda, \beta}(x) =  -\frac{1}{\lambda} \exp\left(\frac{\beta - x}{\lambda}\right).$$
  Therefore, \begin{align*}
      \left|H(\Phi_{\lambda, \beta})\right| &= \left|\begin{bmatrix}
\frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \lambda^2} & \frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \lambda \partial \beta} \\
\frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \lambda \partial \beta} & \frac{\partial^2 \Phi_{\lambda, \beta}}{\partial \beta^2}
\end{bmatrix}\right| \\
&= \exp\left(\frac{2(\beta - x)}{\lambda}\right)\left(\beta-x\right)^2\left(\frac{1}{\lambda^3 \cdot \lambda} - \frac{1}{\lambda^2 \cdot \lambda^2}\right) = 0,
  \end{align*}thus $\Phi_{\lambda, \beta}$ is never strictly concave in $(\lambda, \beta)^T$.
\end{proof}

A solution to this is to focus on the form when there is only one multiplier term. We can do the recursive rMLMC method to get an unbiased final estimate, but we can also do the plug-in method (which is biased) to get the same central limit theorem in the KL case as Theorem \ref{CLT}. Doing this not only simplify the code and the numerical analysis, but also keep the same rate of convergence. To be more specific, let $\Phi_{\lambda}(x) = \exp\left(\frac{-x}{\lambda}\right)$ for $x > 0$ and $\lambda > 0$, the rMLMC estimator first samples $b \sim \mu$, then independently samples a random $N^b = \tilde{N}^b + n_0$, where $n_0$ is a fixed non-negative integer and $\tilde{N}^b \sim \text{Geo}(R)$ with $R \in \left(\frac{1}{2},\frac{3}{4}\right)$, finally generates $2^{N^b + 1}$ unbiased estimates $\left\{\hat{Z}^b_i\right\}_{1 \leq i \leq 2^{N^b}}$ of $Z^b = E^{P^b}[u(X_T)]$, and the random estimator of $\int_{\mathbb{R}}\Phi_{\lambda}\left(Z^b\right)d\mu(b)$ is given by 
$\mathcal{E}^b_{\text{KL}} = \mathcal{E}^b_{\lambda, \text{KL}} = \frac{\Delta_{N^b}^b}{p(N^b)} + \Phi_{\lambda}\left(\frac{S^b_{2^{n_0}}}{2^{n_0}}\right)$, where $p(.)$ is the probability mass function of $N^b$ and $S^b_{l} = \sum_{i=1}^l \hat{Z}^b_i$. For $N^b \geq n_0$, we define
\begin{align*}
    \Delta_{N^b}^b &= \Phi_{\lambda}\left(\frac{S_{2^{N^b+1}}^b}{2^{N^b+1}}\right)- \frac{1}{2}\left(\Phi_{\lambda}\left(\frac{S^{O,b}_{2^{N^b}}}{2^{N^b}}\right) + \Phi_{\lambda}\left(\frac{S^{E,b}_{2^{N^b}}}{2^{N^b}}\right)\right),
\end{align*}where 
 $S^{O,b}_{l} = \sum_{i=1}^l \hat{Z}^{O,b}_i$ and $S^{E,b}_{l} = \sum_{i=1}^l \hat{Z}^{E,b}_{i}$ with $\left\{\hat{Z}^{E,b}_{i}\right\}_{1 \leq i \leq 2^{N^b+1}}$ and $\left\{\hat{Z}^{O,b}_i\right\}_{1 \leq i \leq 2^{N^b+1}}$ denotes the estimates indexed by even and odd values, respectively. The estimator $\mathcal{E}_{\text{KLpre}}$ for $\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)$ is (for fixed $\pi$ and $\delta$)
\begin{equation}\label{rMLMC1}
    \mathcal{E}_{\text{KLpre}} = \mathcal{E}_{\pi, \delta, \lambda, \text{KL}}= \frac{1}{n}\sum_{i=1}^n \mathcal{E}_{\text{KL}}^{b_i},
\end{equation}given $n$ i.i.d. samples $\left\{b_i\right\}_{1 \leq i \leq n}$ generated from $\mu$. 
% Based on the discussion in Section \ref{outeroptimization}, if Assumption \ref{ass2}, \ref{ass3}, \ref{finitevari}, and \ref{assempbound} hold, $\mu$ is compactly supported with a continuous density, then $E_{\text{KLpre}}$ is an unbiased estimator for $\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)$ and has a finite variance.
We then use the plug-in estimator $\mathcal{E}_{\text{KL}} = -\lambda \delta -\lambda\log\left(\mathcal{E}_{\text{KLpre}}\right)$ as a biased but consistent estimator for $-\lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)$. Similarly as the general case, we define $\hat{Q}_{\text{DRBCKL}}(\pi) := \sup_{\lambda > 0}\left\{\mathcal{E}_{\text{KL}} \right\}$.

The first order condition is given by Theorem \ref{KLderivatives} and the steps are given by Algorithm \ref{KLevaluate}. Because of the complexity of the derivative information, we will use (stochastic) gradient method in this case. We also provide the theoretical guarantee in Theorem \ref{KLCLT}. The proofs are given in Appendix \ref{KLProof}.

\begin{theorem}\label{KLderivatives}
The map $\lambda \mapsto -\lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b }{\lambda}\right)d\mu(b)\right)$ is strictly concave, $$\displaystyle{\lim_{n \to \infty}}P\left(\mathcal{E}_{\text{KL}}\text{ is strictly concave}\right) = 1,$$ and the derivative of the map $\lambda \mapsto \mathcal{E}_{\text{KL}}$ admits the expression
\begin{align}\label{firstlambda}
    &\frac{\partial}{\partial \lambda}\mathcal{E}_{\text{KL}} = -\delta - \log\left(\mathcal{E}_{\text{KLpre}}\right) \\ &- \frac{1}{\mathcal{E}_{\text{KLpre}}}\frac{1}{n}\sum_{i=1}^n\left(A\left(\frac{S_{2^{n_0}}^{b_i}}{2^{n_0}\lambda}\right)+ \frac{1}{p(N^{b_i})}\left[A\left(\frac{S_{2^{N^{b_i}+1}}^{b_i}}{2^{N^{b_i}+1}\lambda}\right) - \frac{1}{2}\left(A\left(\frac{S_{2^{N^{b_i}}}^{O,b_i}}{2^{N^{b_i}}\lambda}\right) + A\left(\frac{S_{2^{N^{b_i}}}^{E,b_i}}{2^{N^{b_i}}\lambda}\right)\right)\right]\right),\notag
\end{align}where $A(x) = xe^{-x}$ for $x > 0$.
% \begin{equation}\label{secondlambda}
%     \frac{\partial^2}{\partial \lambda^2}E_{\text{KL}} = .
% \end{equation}
\end{theorem}

\begin{theorem}\label{KLCLT}
    Suppose Assumption \ref{ass2}, \ref{ass3}, \ref{finitevari}, and \ref{assempbound} hold, $\mu$ is compactly supported with a continuous density. For fixed $\pi \in \mathcal{A}(x_0)$, let  $n$ denote the number of i.i.d. samples of $\{\mathcal{E}^{b_i}_{\text{KL}}\}_{1 \leq i \leq n}$, then 
    $$\sqrt{n}\left(\hat{Q}_{\text{DRBCKL}}(\pi) - Q_{\text{DRBCKL}}(\pi)\right)\Rightarrow \mathcal{N}\left(0, \frac{\left(\lambda^*\right)^2\text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \text{KL}}\right)}{\left[\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)\right]^2}\right),$$
    where $\lambda^*$ is defined in Section \ref{dual}.
\end{theorem}


\begin{algorithm}\label{KLevaluate}
\caption{rMLMC DRBC Policy Evaluation Step in the KL Divergence Case}\label{KLevaluate}
\textbf{Input:} A simulator $\mathcal{S}$, rMLMC parameter $R \in (\frac{1}{2},\frac{3}{4})$, prior distribution $\mu$, parameter $n_0$, initialization of $\lambda$ and $k = 0$, policy $\pi$, step-size sequence $\{\alpha_k : k \in \mathbb{Z}_{\geq 0}\}$.\\
\textbf{Output:} Estimator of rMLMC DRBC policy value $\hat{Q}_{\text{DRBCKL}}(\pi)$.\\
\textbf{repeat}
\begin{itemize}
\item Draw $n$ i.i.d. samples $\{b_i\}_{1 \leq i \leq n}$ from $\mu$. For each $i = 1,2,\ldots, n$, sample $\tilde{N}^{b_i} \sim \text{Geo}(R)$ independently, and compute $N^{b_i} = \tilde{N}^{b_i} + n_0$, then give $b_i$ to $\mathcal{S}$ and generate $2^{N^{b_i}+1}$ i.i.d. samples of $\hat{Z}_i^b$.
\item Compute $\mathcal{E}_{\text{KLpre}}$, $\mathcal{E}_{\text{KL}}$, and $\text{GF} :=\frac{\partial}{\partial \lambda}\mathcal{E}_{\text{KL}}$ (Theorem \ref{KLderivatives}).
\item Update $\lambda = \lambda + \alpha_k \text{GF}$ and update $k = k+1$.
\end{itemize}
\textbf{until} $\lambda$ converges.\\
\textbf{Return }$\hat{Q}_{\text{DRBCKL}}(\pi) = \mathcal{E}_{\text{KL}}$ (Equation (\ref{rMLMC1})).
\end{algorithm}

\subsection{Proof of Theorem \ref{CLT}}
\begin{proof}
   The proof is adapted from the proof of Theorem 1 from \cite{NianSi}. Since the estimator (\ref{rMLMC}) is unbiased and has finite variance under the assumptions, then from (the classical) central limit theorem, 
   \begin{equation}\label{classicalCLT}
       \sqrt{n}\left(\mathcal{E}_{\pi, \delta, \lambda, \beta} - \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(Z^b\right)d\mu(b)\right) \Rightarrow \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda, \beta}\right)\right).
   \end{equation}
From Assumption \ref{ass0}, there exists $lb,ub \in \mathbb{R}$ such that $\left\Vert (\lambda^*, \beta^*)^T\right\Vert_2^2 \in K = [lb,ub]$. Without loss of generality, we abuse the notation and denote the support of optimizers as $K$. Since the function $(\lambda, \beta)^T \mapsto \mathcal{E}_{\pi, \delta, \lambda, \beta}$ over $K$ is Lipschitz continuous (continuously differentiable on a compact set), then 
\begin{equation}\label{uniCLT}
\sqrt{n}\left(f(.) - g(.)\right) \Rightarrow L(.)    
\end{equation}
uniformly in the Banach space $C\left(K; \mathbb{R}\right)$ of continuous functions $\varphi: K \to \mathbb{R}$ equipped with the sup norm, where
$f((\lambda, \beta)) = \mathcal{E}_{\pi, \delta, \lambda, \beta},$
$g((\lambda, \beta)) = \int_{\mathbb
R}\Phi_{\lambda, \beta}\left(Z^b\right)d\mu(b),$ and $L((\lambda, \beta)) \sim \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda, \beta}\right)\right).$ $L$ is a random element taking values in $C\left(K; \mathbb{R}\right)$. 

Define the functionals 
$$G\left(\varphi, (\lambda, \beta)^T\right) = -\beta + \lambda \delta - \varphi(\lambda, \beta) $$ and 
$$V(\varphi) = \inf_{(\lambda, \beta)^T \in K}G\left(\varphi, (\lambda, \beta)\right),$$
then by Danskin theorem, $V$ is directionally differentiable at any $\mu \in C\left(K; \mathbb{R}\right)$ with $\mu > 0$ and for any $\nu \in C\left(K; \mathbb{R}\right)$,
$$V'_{\mu}(\nu) = \inf_{(\lambda, \beta)^T \in \Bar{X}(\mu)}-\nu(\lambda, \beta),$$
where $\Bar{X}(\mu) = \arg \min_{(\lambda, \beta)^T \in K}\left\{-\beta + \lambda \delta - \mu(\lambda, \beta)\right\}$ and $V'_{\mu}(\nu)$ is the directional derivative of $V$ at $\mu$ in the direction of $\nu$. In addition, $V$ is Hadamard directionally differentiable at $g(.)$ since 
\begin{equation}\label{lbound}
  g((\lambda, \beta)) = \int_{\mathbb
R}\Phi_{\lambda, \beta}\left(E^{P^b}[u(X_T)]\right)d\mu(b) \geq  \int_{\mathbb
R}\Phi_{\lambda, \beta}\left(u(m)\right)d\mu(b) > 0  
\end{equation}
and $V(\varphi)$ is Lipschitz continuous if $\varphi$ is bounded below away from zero.

Therefore, by the Delta Theorem, we have
$$\sqrt{n}\left(V\left(f(.)\right) - V\left(g(.)\right)\right) \Rightarrow V_{g(.)}'\left(L\right).$$
Since the map $(\lambda, \beta)^T \mapsto -\beta + \lambda \delta - \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(Z^b\right)d\mu(b)$ is strictly convex, then we have the uniqueness of the optimizer and 
\begin{align*}
    V_{g(.)}'\left(L\right) &= -L\left(\lambda^*, \beta^*\right)
    \sim \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \beta^*}\right)\right).
\end{align*}
Recall that
$$Q_{\text{DRBC}}(\pi) = -\inf_{\substack{\lambda > 0 \\ \beta \in \mathbb{R}}}\left\{-\beta + \lambda \delta -\int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(Z^b\right)d\mu(b)\right\} = -V\left(g(.)\right)$$and $$\hat{Q}_{\text{DRBC}}(\pi)= -\inf_{\substack{\lambda > 0 \\ \beta \in \mathbb{R}}}\left\{-\beta + \lambda \delta - \mathcal{E}_{\pi, \delta, \lambda, \beta}\right\}.$$
% Next we want to show
Notice that from Assumption \ref{assempbound} we have
\begin{equation}\label{last}
  \displaystyle{\lim_{n \to \infty}}P\left(\hat{Q}_{\text{DRBC}}(\pi) \neq -V\left(f(.)\right) \right) \to 0.  
\end{equation}
Then from Slutsky's theorem, 
\begin{align*}
    \sqrt{n}\left(\hat{Q}_{\text{DRBC}}(\pi) - Q_{\text{DRBC}}(\pi)\right) &= \sqrt{n}\left(\hat{Q}_{\text{DRBC}}(\pi) + V\left(f(\lambda, \beta)\right)\right) + \sqrt{n}\left(V\left(f(\lambda, \beta)\right) - V\left(g(\lambda, \beta)\right)\right)\\
    & \Rightarrow 0 + \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \beta^*}\right)\right) \sim \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \beta^*}\right)\right),
\end{align*}which finishes the proof.
