\subsection{Proof of Results for the KL Divergence Case}\label{KLProof}
\subsubsection{Proof of Theorem \ref{KLderivatives}}
\begin{proof}
    Since $\mathcal{E}_{\text{KL}}$ is a consistent estimator of $-\lambda \delta -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b }{\lambda}\right)d\mu(b)\right)$, it suffices to show the strict concavity of $g(\lambda) = -\lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b }{\lambda}\right)d\mu(b)\right)$. To do this, we compute the first and second order derivatives:
    $$\frac{\partial}{\partial \lambda}g(\lambda)=-\log\left(\int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)\right) 
    - \frac{\int_{\mathbb{R}} Z^b e^{-Z^b/\lambda} \, d\mu(b)}{\lambda \int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)}$$and
    \begin{align*}
    &\frac{\partial^2}{\partial \lambda^2}g(\lambda) =-\frac{\int_{\mathbb{R}} (Z^b)^2 e^{-Z^b/\lambda} \, d\mu(b)}{\lambda^3 \int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)} 
    + \frac{\left(\int_{\mathbb{R}} Z^b e^{-Z^b/\lambda} \, d\mu(b)\right)^2}{\lambda^3 \left(\int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)\right)^2}\\ 
    &= \frac{1}{\lambda^3 \left(\int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)\right)^2}\left(\left(\int_{\mathbb{R}} Z^b e^{-Z^b/\lambda} \, d\mu(b)\right)^2 - \int_{\mathbb{R}} (Z^b)^2 e^{-Z^b/\lambda} \, d\mu(b)\int_{\mathbb{R}} e^{-Z^b/\lambda} \, d\mu(b)\right)\\
    &\leq 0,
    \end{align*}where from Cauchy Schwartz inequality, the equality holds if and only if $Z^B$ is constant almost surely, which is not true in our case. Therefore, strict concavity is shown. Then the computations of the derivatives are elementary.

\end{proof}

\subsubsection{Proof of Theorem \ref{KLCLT}}
\begin{proof}
    The proof is similar to the proof of Theorem \ref{CLT}; the only difference is that we will have more explicit forms of the limiting Gaussian variance. Since the function $\Phi_{\lambda}(x) = \exp\left(\frac{-x}{\lambda}\right)$ satisfies Assumption \ref{ass0.5}, together with other assumptions, it is easy to see that $\mathcal{E}_{\text{KLpre}}$ is an unbiased estimator for $\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)$ and has a finite variance. Therefore, from central limit theorem, \begin{equation}\label{classicalCLTKL}
       \sqrt{n}\left(\mathcal{E}_{\text{KLpre}} - \int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right) \Rightarrow \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda, \text{KL}}\right)\right).
   \end{equation}
Recall that from Theorem \ref{KL1}, the optimal $\lambda^* \in K$, where $K = [\underline{\lambda}, \bar{\lambda}] \subset \mathbb{R}$ is compact. From the Lipschitz continuity of $\lambda \mapsto \mathcal{E}_{\text{KLpre}}$ over $K$, we have
\begin{equation}\label{uniCLTKL}
\sqrt{n}\left(f(.) - g(.)\right) \Rightarrow L(.)   
\end{equation}
uniformly in the Banach space $C\left(K; \mathbb{R}\right)$ of continuous functions $\varphi: K \to \mathbb{R}$ equipped with the sup norm, where
$f(\lambda) = \mathcal{E}_{\text{KLpre}},$
$g(\lambda) = \int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b),$ and $L(\lambda) \sim \mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda, \text{KL}}\right)\right).$ $L$ is a random element taking values in $C\left(K; \mathbb{R}\right)$. We next define the functionals
$$G\left(\varphi,\lambda\right) = \lambda \log\left(\varphi(\lambda)\right) + \lambda \delta$$ and 
$$V(\varphi) = \inf_{\lambda \in K}G\left(\varphi,\lambda\right),$$
then by Danskin theorem, $V$ is directionally differentiable at any $\mu \in C\left(K; \mathbb{R}\right)$ with $\mu > 0$ and for any $\nu \in C\left(K; \mathbb{R}\right)$,
$$V'_{\mu}(\nu) = \inf_{\lambda \in \Bar{X}(\mu)}\lambda \left(\frac{1}{\mu(\lambda)}\right)\nu(\lambda),$$
where $\Bar{X}(\mu) = \arg \min_{\lambda \in K}\left\{\lambda \log\left(\mu(\lambda)\right) + \lambda \delta\right\}$ and $V'_{\mu}(\nu)$ is the directional derivative of $V$ at $\mu$ in the direction of $\nu$. In addition, $V$ is Hadamard directionally differentiable at $g(.)$ since (Assumption \ref{ass2})
\begin{equation}\label{lboundKL}
  g(\lambda) = \int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b) > 0  
\end{equation}
and $V(\varphi)$ is Lipschitz continuous if $\varphi$ is bounded below away from zero.

Therefore, by the Delta Theorem, we have
$$\sqrt{n}\left(V\left(f(.)\right) - V\left(g(.)\right)\right) \Rightarrow V_{g(.)}'\left(L\right).$$
Since the map $\lambda \mapsto \int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)$ is strictly convex, then we have the uniqueness of the optimizer and 
\begin{align*}
    V_{g(.)}'\left(L\right) &= \lambda^*\left(\frac{1}{\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)}\right)L\left(\lambda^*\right)\\
    &\sim \left(\frac{\lambda^*}{\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)}\right)\mathcal{N}\left(0, \text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \text{KL}}\right)\right)\\
     &\sim \mathcal{N}\left(0, \frac{\left(\lambda^*\right)^2\text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \text{KL}}\right)}{\left[\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)\right]^2}\right).
\end{align*}
Recall that
$$Q_{\text{DRBCKL}}(\pi) = -\inf_{\substack{\lambda > 0}}\left\{\lambda \delta + \lambda\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)\right\} = -V\left(g(.)\right)$$and $$\hat{Q}_{\text{DRBCKL}}(\pi)= -\inf_{\substack{\lambda > 0}}\left\{\mathcal{E}_{\text{KL}}\right\}.$$
% Next we want to show
Notice that from Assumption \ref{assempbound} we have
\begin{equation}\label{lastKL}
  \displaystyle{\lim_{n \to \infty}}P\left(\hat{Q}_{\text{DRBCKL}}(\pi) \neq -V\left(f(.)\right) \right) \to 0.  
\end{equation}
Then from Slutsky's theorem, 
\begin{align*}
    &\sqrt{n}\left(\hat{Q}_{\text{DRBCKL}}(\pi) - Q_{\text{DRBCKL}}(\pi)\right) = \sqrt{n}\left(\hat{Q}_{\text{DRBCKL}}(\pi) + V\left(f(\lambda)\right)\right) + \sqrt{n}\left(V\left(f(\lambda)\right) - V\left(g(\lambda)\right)\right)\\
    & \Rightarrow 0 + \mathcal{N}\left(0, \frac{\left(\lambda^*\right)^2\text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \text{KL}}\right)}{\left[\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)\right]^2}\right) \sim \mathcal{N}\left(0, \frac{\left(\lambda^*\right)^2\text{Var}\left(\mathcal{E}^{b_1}_{\lambda^*, \text{KL}}\right)}{\left[\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda^*}\right)d\mu(b)\right]^2}\right),
\end{align*}which finishes the proof.
\end{proof}

