\subsection{Proof of Theorem \ref{dualityKL}}
\begin{proof}
    If we denote $\gamma = \frac{1}{\lambda}$, then from a dual representation of the entropic risk measure \citep{FoellmerSchied},
    \begin{align*}
        &\sup_{\pi \in \mathcal{A}(x_0)}\left\{- \lambda\log\left(\int_{\mathbb{R}}\exp\left(\frac{-Z^b}{\lambda}\right)d\mu(b)\right)\right\}\\&=\sup_{\pi \in \mathcal{A}(x_0)}\left\{- \frac{1}{\gamma}\log\left(\int_{\mathbb{R}}\exp\left(- \gamma E^{P^b}\left[u(X_T)\right]\right)d\mu(b)\right)\right\}\\
      &= \sup_{\pi \in \mathcal{A}(x_0)}\left\{ -\sup_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[-E^{\tilde{Q}^b}\left[u(X_T)\right]\right] - \frac{1}{\gamma}D_{\text{KL}}\left(\tilde{Q} \parallel P\right)\right\}\right\}\\
      &= \sup_{\pi \in \mathcal{A}(x_0)}\left\{\inf_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[E^{\tilde{Q}^b}\left[u(X_T)\right]\right] + \frac{1}{\gamma}D_{\text{KL}}\left(\tilde{Q} \parallel P\right)\right\}\right\}\\
      &= \sup_{\pi \in \mathcal{A}(x_0)}\inf_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[u(X_T)\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}.
    \end{align*}
\end{proof}

\subsection{Proof of Theorem \ref{optimaltoy}}
\begin{proof}
    In order to use Sion's minmax theorem, we need the compactedness of $\mathcal{AC}$, which is not true in general. However, since $m = \text{essinf}X_T$ exists and $P(X_T = m) > 0$, we denote the set where $X_T = m$ as $E$ and define a measure such that for any measurable set $A$, 
    $$Q(A) = \frac{P(A \cap E)}{P(E)},$$
    then $Q \in \mathcal{AC}$ and for any $\tilde{Q} \in \mathcal{AC}$, $$E^{\tilde{Q}}[u(X_T)] \geq u(m) = E^Q[u(X_T)],$$
    thus $Q$ is an optimizer of $\inf_{\tilde{Q} \in \mathcal{AC}}E^{\tilde{Q}}[u(X_T)]$. 
Moreover, 
$$\frac{dQ}{dP} = \frac{\mathbf{1}_{E}}{P(E)}, $$ thus for a fixed integer $p > 1$, $\left \Vert \frac{dQ}{dP} \right\Vert_p \leq \frac{1}{P(E)}$, thus the optimal $Q$ for $\inf_{\tilde{Q} \in \mathcal{AC}}E^{\tilde{Q}}[u(X_T)]$ is attained inside a compact set $K_1$ in the topology of weak convergence by Prokhorov’s theorem.
    Note that the proof of the above argument does not use the finite support assumption.

On the other hand, since $\mu$ is finitely supported, and for any $\tilde{Q} \in \mathcal{AC}$, there exists $\nu \ll \mu$ such that $\frac{d\tilde{Q}}{dP} = \frac
{d\nu}{d\mu}(B)$, then $\nu$ is also finitely supported and $\tilde{Q} \in \mathcal{P}(K_0)$, where $K_0$ is compact. Thus we can also restrict the choice of $Q$ to a weakly compact set $K_2$ and define $K = K_1 \cap K_2$, thus $K$ is compact. As a conclusion, $\inf_{\tilde{Q} \in \mathcal{AC}}E^{\tilde{Q}}[u(X_T)] = \inf_{\tilde{Q} \in K}E^{\tilde{Q}}[u(X_T)]$. 

In addition, we notice that the mapping $\tilde{Q} \mapsto E^{\tilde{Q}}[u(X_T)] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right)$ is convex and weakly continuous since the first part is linear and the second part is convex, and the mapping $\pi \mapsto E^{\tilde{Q}}[u(X_T)] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right)$ is concave, and the constraint sets are both convex, then from Sion's minmax theorem,
\begin{align*}
&\sup_{\pi \in \mathcal{A}(x_0)}\inf_{\tilde{Q}\in \mathcal{AC}}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}\\&= \sup_{\pi \in \mathcal{A}(x_0)}\inf_{\tilde{Q}\in K}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}\\ &= \inf_{\tilde{Q}\in K}\sup_{\pi \in \mathcal{A}(x_0)}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\}\\ &= \inf_{\tilde{Q}\in \mathcal{AC}}\sup_{\pi \in \mathcal{A}(x_0)}\left\{E^{\tilde{Q}}\left[u(X_T^{\pi})\right] + \lambda D_{\text{KL}}\left(\tilde{Q} \parallel P\right) \right\},
\end{align*}where the last equality holds since if we assume the existence of optimal $\pi^*$ for the inner supremum problem, then for a fixed control, the optimal $\tilde{Q}^*$ is taken in a weakly compact set. Finally, since $\mu$ is finitely supported, then the optimizers are attained from this compactedness, which finishes the proof.
\end{proof}

