\subsection{Alternate Admissible Controls}\label{alterdef}
In this section, we give the definition of the admissible controls that will help the tractability of the general case.

To illustrate our definition of the admissible set, we go back to Problem (\ref{OriginalKaratzas}) with the strictly concave utility function $u$. (For a full review, see Appendix \ref{98review}) It is shown that the optimal terminal wealth $X^*_T$ is given by 
$X^*_T = I\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)$ \citep{KZ98}.  
For a density function $\lambda: \mathbb{R} \to \mathbb{R}$, we define the inner product $\left\langle E^{P^.}\left[u(X^*_T)\right], \lambda \right\rangle := \int_{\mathbb{R}}E^{P^b}\left[u(X^*_T)\right]\lambda(b)d\mu(b) = \int_{\mathbb{R}}E^{P^b}\left[\left(u \circ I\right)\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b).$
% \begin{align*}
% \int_{\mathbb{R}}E^{P^b}\left[u(\hat{X}_T)\right]\lambda(b)d\mu(b) &= \int_{\mathbb{R}}E^{P^b}\left[u\left(I\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right)\right]\lambda(b)d\mu(b)\\
% &= \int_{\mathbb{R}}E^{P^b}\left[\left(u \circ I\right)\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b).
% \end{align*}
% With some regularity assumptions in Assumption 3.1 in \citet{KZ98}, $\mathcal{K}$ is a continuous and invertible function of $x$.
We want to see whether there exists a function $h: \mathbb{R} \to \mathbb{R}$ and a functional $\rho: L^1 \to \mathbb{R}$ such that
\begin{equation}\label{eq1}
\int_{\mathbb{R}}E^{P^b}\left[u(X^*_T)\right]\lambda(b)d\mu(b) = h(x_0)\rho(\lambda)    
\end{equation}
and \begin{equation}\label{eq2}
    h(1) = u(e^{rT}).
\end{equation}

\begin{theorem}\label{decompose}
    For the following cases (1) and (2), the conditions (\ref{eq1}) and (\ref{eq2}) are met, where for case (3), the conditions are not met: 
    \begin{itemize}
        \item (1) $u(x) = \frac{1}{\alpha}x^{\alpha} $, where $\alpha < 1$ and $\alpha \neq 0$.
        \item (2) $u(x) = \frac{-1}{\gamma}e^{-\gamma x} $, where $\gamma > 0$.
        \item (3) $u(x) = \log(x)$.
    \end{itemize}
\end{theorem}

\begin{proof}
    \begin{itemize}
        \item (1) Here, $$I(y) = y^{\frac{1}{1-\alpha}},$$ thus $$(u\circ I)(y) = \frac{1}{\alpha}y^{\frac{\alpha}{1-\alpha}},$$
        which implies that 
        \begin{align*}
\int_{\mathbb{R}}E^{P^b}\left[u(X^*_T)\right]\lambda(b)d\mu(b) &=  \int_{\mathbb{R}}E^{P^b}\left[\left(u \circ I\right)\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b)\\
&=\int_{\mathbb{R}}E^{P^b}\left[\frac{1}{\alpha}
\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)^{\frac{\alpha}{1-\alpha}}\right]\lambda(b)d\mu(b)\\
&=\frac{1}{\alpha}\left(\mathcal{K}(x_0)e^{-rT}\right)^{\frac{\alpha}{1-\alpha}}\int_{\mathbb{R}}E^{P^b}\left[
\left(F(T,Y(T))\right)^{\frac{\alpha}{\alpha-1}}\right]\lambda(b)d\mu(b)\\
&= h(x_0)\rho(\lambda),
        \end{align*}
        where $$h(x) = \frac{1}{\alpha}\left(\mathcal{K}(x)e^{-rT}\right)^{\frac{\alpha}{1-\alpha}} $$
        and 
        $$\rho(\lambda) = \int_{\mathbb{R}}E^{P^b}\left[
\left(F(T,Y(T))\right)^{\frac{\alpha}{\alpha-1}}\right]\lambda(b)d\mu(b).$$
        \item (2) Here, $$I(y) = \frac{-1}{\gamma}\log(y),$$ thus $$(u\circ I)(y) = \frac{-1}{\gamma}y,$$
        which implies that 
        \begin{align*}
\int_{\mathbb{R}}E^{P^b}\left[u(X^*_T)\right]\lambda(b)d\mu(b) &=  \int_{\mathbb{R}}E^{P^b}\left[\left(u \circ I\right)\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b)\\
&=\int_{\mathbb{R}}E^{P^b}\left[\frac{-1}{\gamma}\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b)\\
&= h(x_0)\rho(\lambda),
        \end{align*}
        where $$h(x) = \frac{-1}{\gamma}\mathcal{K}(x_0)e^{-rT} $$
        and 
        $$\rho(\lambda) = \int_{\mathbb{R}}E^{P^b}\left[
\frac{1}{F(T,Y(T))}\right]\lambda(b)d\mu(b).$$
\item (3) Here, $$I(y) = \frac{1}{y} \text{ and }\mathcal{K}(x_0) = \frac{1}{x_0},$$ thus $$(u\circ I)(y) = -\log(y),$$
        which implies that 
        \begin{align*}
\int_{\mathbb{R}}E^{P^b}\left[u(X^*_T)\right]\lambda(b)d\mu(b) &=  \int_{\mathbb{R}}E^{P^b}\left[\left(u \circ I\right)\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b)\\
&=  \int_{\mathbb{R}}E^{P^b}\left[-\log\left(\frac{\mathcal{K}(x_0)e^{-rT}}{F(T,Y(T))}\right)\right]\lambda(b)d\mu(b)\\
&=x_0 + rT + \int_{\mathbb{R}}E^{P^b}\left[\log\left(F(T,Y(T))\right)\right]\lambda(b)d\mu(b),
        \end{align*}which shows that the decomposition is impossible.
    \end{itemize}
\end{proof}

\begin{remark}
    In general, if $u \circ I$ satisfies $$u \circ I\left(\frac{a}{b}\right) = f(a)g(b),$$
    then the decomposition condition holds. There are other examples satisfying this condition.
\end{remark}

% We first denote the set $\tilde{\mathcal{A}}(x_0)$ as the collection of all $\mathcal{F}^S$-progressively measurable stochastic processes $\alpha= \{\alpha_t\}_{t \in [0,T]}$ such that 
% \begin{itemize}
%     \item (1) $\int_0^T \left \Vert \alpha_t \right\Vert_2^2dt < \infty$.
%     \item (2) The SDE Eq. (\ref{wealthp}) admits a unique strong solution.
% \end{itemize}
Now we define a subset $ \tilde{\mathcal{A}}(x_0) \subset \mathcal{A}(x_0)$ such that for all $\pi \in \tilde{\mathcal{A}}(x_0)$, there exists corresponding function $h: \mathbb{R} \to \mathbb{R}$ and a functional $\rho: L^1 \to \mathbb{R}$ such that for the controlled terminal wealth $X_T^{\pi}$,
$\int_{\mathbb{R}}E^{P^b}\left[u(X_T^{\pi})\right]\lambda(b)d\mu(b) = h(x_0)\rho(\lambda)    
$
and $h(1) = u(e^{rT}).$
Thus for some utility functions, Problem (\ref{OriginalKaratzas}) is equivalent to 
$\sup_{\pi \in \tilde{\mathcal{A}}(x_0)}E^P\left[u(X_T)\right].$
Besides, if we define a function $\tilde{u}(x) = u(x) + C$, where $C$ is a constant that does not depend on $x$, then the problems $\sup_{\pi \in \tilde{\mathcal{A}}(x_0)}E^P\left[u(X_T)\right]$
and $\sup_{\pi \in \tilde{\mathcal{A}}(x_0)}E^P\left[\tilde{u}(X_T)\right]$
should have the same optimal solution (not the same value function), at least in the definition of the classical problem. However this is not true if we follow our current definition of admissible controls since the decomposition cannot be satisfied by these two problems at the same time.

To rescue this, we firstly define an equivalence relation for two real-valued function $f$ and $g$
\begin{equation*}
f \sim g \iff 
\begin{aligned}
    & \text{ there exists a constant }C\text{ such that } f(x) = g(x) + C.
\end{aligned}
\end{equation*}
We call $\tilde{\mathcal{A}}(x_0)$ the collection of all alternate admissible controls $\pi$, which is a subset of $\mathcal{A}(x_0)$ such that 
there exists a function $v \sim u$ ($u$ is the utility function in the objective function) such that there exist corresponding function $h: \mathbb{R} \to \mathbb{R}$ and a functional $\rho: L^1 \to \mathbb{R}$ such that for the controlled terminal wealth $X_T^{\pi}$,
$
\int_{\mathbb{R}}E^{P^b}\left[v(X_T^{\pi})\right]\lambda(b)d\mu(b) = h(x_0)\rho(\lambda)    
$
and $
    h(1) = v(e^{rT}).
$

In the DRBC formulation, since the deviation from the prior distribution and its corresponding underlying probability space is small, it is reasonable to continue to search for optimal solutions in the space of $\tilde{\mathcal{A}}(x_0)$ for those utilities. Thus we call $\tilde{\mathcal{A}}(x_0)$ the collection of all alternate admissible controls and Problem (\ref{inner}) becomes
\begin{equation}\label{quasinewinner}
    \sup_{\pi \in \tilde{\mathcal{A}}(x_0)} \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{P^b}\left[u(X_T)\right]\right)d\mu(b).
\end{equation}

