\subsection{Discussion on Closed-form Computations}\label{closed}
% In general, it is almost impossible to get the closed form solution even with our newly defined admissible controls unless the utility function depends on the optimal multipliers (therefore a similar closed form computation as in Section 4 in \citet{GLS22} can be done).

% However, this artificial utility has problems: \begin{itemize}
%     \item (1) It is hard to check whether this utility will lead to a candidate solution which satisfies the decomposition condition, even $u$ satisfies since the multipliers contains complex information of the problem.
%     \item (2) Even though the sanity check is passed, it is almost impossible or too hard to find a numerical method to conduct with this artificial utility.
% \end{itemize}
In this section, we review how the closed-form computation for a smooth ambiguity problem is derived in some special cases, and how does this method fail in our case.

Recall that the DRBC problem becomes \begin{align*}
   \sup_{\pi \in \tilde{\mathcal{A}}(x_0)} 
\inf_{Q \in \mathcal{U}_{\delta}} E^Q\left[u(X_T)\right] = \sup_{\pi \in \tilde{\mathcal{A}}(x_0)}\sup_{\substack{\lambda > 0 \\ \beta \in \mathbb{R}}}\left\{\beta - \lambda \delta +  \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(E^{P^b}[u(X_T^{\pi})]\right)d\mu(b)\right\}. 
% \\&=\sup_{\substack{\lambda > 0 \\ \beta \in \mathbb{R}}}\left\{\beta - \lambda \delta + \lambda \sup_{\pi \in \mathcal{A}(x_0)} \int_{\mathbb{R}}\Phi_{\lambda,\beta}\left(Z^b\right)d\mu(b)\right\}.
\end{align*}
For simplicity, suppose there exists a unique pair $(\pi^*, \lambda^*, \beta^*)$ such that 
$$\sup_{\pi \in \tilde{\mathcal{A}}(x_0)} 
\inf_{Q \in \mathcal{U}_{\delta}} E^Q\left[u(X_T)\right] = \beta^* - \lambda^* \delta +  \int_{\mathbb{R}}\Phi_{\lambda^*,\beta^*}\left(E^{P^b}[u(X_T^{\pi^*})]\right)d\mu(b),$$
thus it suffices to solve the smooth ambiguity problem with strictly concave and strictly increasing function $\Phi_{\lambda^*,\beta^*}$:
\begin{equation}\label{temp}
   \sup_{\pi \in \tilde{\mathcal{A}}(x_0)}\left\{ 
 \int_{\mathbb{R}}\Phi_{\lambda^*,\beta^*}\left(E^{P^b}[u(X_T^{\pi})]\right)d\mu(b) \right\}. 
\end{equation}
 We remark that this unique pair assumption is hard to check because of the jointly non-convexity in terms of $\pi$ and $(\lambda, \beta)^T$. For notational convenience, we use $(\lambda, \beta)^T$ in the rest of this section instead of $(\lambda^*, \beta^*)^T$.

 Therefore, the duality theory in \cite{GLS22} can be applied (for a brief review, see Section \ref{general}) and we derive the conditions to derive the optimal terminal wealth: From Corollary 3.8 in \cite{GLS22}, if $X_T$ is a terminal wealth such that there exists a constant $\kappa > 0$ with
\begin{equation}\label{temp1}
\left\{
\begin{aligned}
& u'(X_T) = \frac{\kappa \eta_T \int_\mathbb{R} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)}{\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) \eta_T^b \, d\mu(b)}\\
& E^{Q^{r}} \left[ X_T  \right] = x_0 e^{r T},
\end{aligned}
\right.
\end{equation}
    then $X_T$ is the optimal terminal wealth corresponding to Problem (\ref{temp}).
In \cite{GLS22}, a closed-form solution is provided when the nonlinear transformation function (Problem (\ref{temp}) with $\Phi_{\lambda, \beta}$ changed to $\phi$) is \[
\phi(x) =
\begin{cases}
\frac{x^{\gamma}}{\gamma}, & \text{if } x \geq 0, \\
\frac{-(-x)^{\gamma}}{\gamma}, & \text{if } x < 0,
\end{cases}
\quad \text{where } \gamma \in (0,1) \text{ is a fixed constant.}
\]

With the nonlinear function $\phi$ and the utility function $u(x) = \frac{1}{\alpha}x^{\alpha}$ with $\alpha \in (0,1)$, we guess that the optimal terminal wealth $X^*_T$ has the form ($p$,$q$, and $c$ are parameters to solve later)
\[
X^*_T = \exp\left(\frac{1}{\alpha} \left( \frac{p}{2T} \hat{W}_T^2 + q\hat{W}_T + c \right) \right).
\]
Hence,
\begin{align*}
   E^{Q^b} \left[ u(X^*_T) \right] &= E^{\hat{Q}} \left[ \frac{1}{\alpha} X^*_T{^\alpha} \eta_T^b \right]\\
   &= \frac{1}{\alpha \sqrt{1-p}} \exp\left(\frac{pT}{2(1-p)} \nu_b^2 - \frac{qT}{1-p} \nu_b + \frac{q^2T}{2(1-p)} + c \right).
\end{align*}
Therefore, if we assume $\mu \sim \mathcal{N}\left(\mu_0, \sigma_0^2\right)$, then 
\begin{align}\label{4.9}
    &\int_{\mathbb{R}} \phi'\left(E^{Q^b}[u(X^*_T)]\right) \eta_T^b d\mu(b)\\
    &\propto \int_{\mathbb{R}} \exp\left({\frac{(\gamma-1)}{2} \frac{pT}{1-p} \nu_b^2 - (\gamma-1) \frac{qT}{1-p} \nu_b - \frac{T}{2} \nu_b^2 - \hat{W}_T \nu_b - \frac{\sigma_0^2 T}{2} \nu_b^2}\right) d\nu_b \notag\\
    & \propto \exp\left( \frac{1}{2T \left( \frac{1-\gamma p}{1-p} + \sigma_0^2 \right)} \left( \hat{W}_T^2 + \frac{2(\gamma-1)Tq}{1-p} \hat{W}_T \right) \right). \notag
\end{align}
Substituting Equation (\ref{4.9}) into Equation (\ref{temp1}), we obtain the following equations
\[
\begin{cases}
(\gamma + \sigma_0^2)p^2 - \left(\sigma_0^2 + \frac{1}{1-\alpha}\right)p + \frac{\alpha}{1-\alpha} = 0, \\
\frac{(1-\alpha)(1-\gamma p)}{\alpha(1-p)}q = \nu, \\
\exp\left( \frac{\left(\nu - \frac{q}{\alpha}\right)^2}{2\left(1-\frac{p}{\alpha}\right)T} - \frac{1}{2} \nu^2 T + \frac{c}{\alpha} \right) = x_0e^{rT},
\end{cases}
\]which admits a solution of pair $(p,q,c)$ if $p <1$.

The essential part of the above computation is that when we plug in the composition of power and exponential functions, the result is still exponential and this fits well with the computation of Gaussian integrals. However, in our case, the nonlinear transformation is defined by for fixed $\lambda \geq 0, \beta \in \mathbb{R}$, 
    $$\Phi_{\lambda,\beta}(x):= -(\lambda\phi)^*(\beta-x).$$
Thus, even though we use the $\phi$-divergence which induces a power-type $\Phi_{\lambda,\beta}$ (e.g. the Cressie-Read divergence), the above computation cannot be adapted unless the utility function $\tilde{u} = u +C(\lambda, \beta)$ (we call it an artificial utility) contains the information of the optimal $\lambda$ and $\beta$, which is highly non-practical and it seems that this is only true in theory.

However, the validity of this artificial utility is not guaranteed. To begin with, note that we cannot simply regard $\lambda$ and $\beta$ as constants and thus $u$ and $\tilde{u}$ are not equivalent. Thus, even though $u$ is a good utility function with the alternative admissible controls (Theorem \ref{decompose}), we do not know whether $\tilde{u}$ is also a good one. Thus, the method may not apply in this case.

\subsection{Properties of $Q^b$}\label{transformderive}
\begin{theorem}
    Under $Q^b$ for any $b \in \mathbb
    {R}$, the distribution of $B$ is still $\mu$.
\end{theorem}
\begin{proof}
    Let $A \in \mathcal{F}$, then from independence of $B$ and $W$, we have
    \begin{align*}
        \mu_b(A) &= Q^b(B \in A) = E^{Q^b}\left[\mathbf{1}_{\{B \in A\}}\right] \\
        &= E^P\left[\frac{dQ^b}{dP}\mathbf{1}_{\{B \in A\}}\right] = E^P\left[\exp\left(-\frac{B-b}{\sigma}W_T - \frac{(B-b)^2}{2\sigma^2}T\right)\mathbf{1}_{\{B \in A\}}\right]\\
        &= \int_{A}\int_{\mathbb{R}}\exp\left(-\frac{x-b}{\sigma}y - \frac{(x-b)^2}{2\sigma^2}T\right)\mu(x)f_{W_T}(y)dydx\\&= 
        \int_{A}\int_{\mathbb{R}}\exp\left(-\frac{x-b}{\sigma}y - \frac{(x-b)^2}{2\sigma^2}T\right)\mu(x)\frac{1}{\sqrt{T}}\varphi\left(\frac{y}{\sqrt{T}}\right)(y)dydx.
    \end{align*}
    Therefore, \begin{align*}
        \mu_b(x) &= \mu(x)\int_{\mathbb{R}}\frac{1}{\sqrt{T}}\exp\left(-\frac{y(x-b)}{\sigma} - \frac{(x-b)^2}{2\sigma^2}T\right)\varphi\left(\frac{y}{\sqrt{T}}\right)dy\\
        &= \frac{\mu(x)}{\sqrt{2\pi T}}\int_{\mathbb{R}}\exp\left(\frac{y(b-x)}{\sigma} - \frac{(x-b)^2}{2\sigma^2}T - \frac{y^2}{2T}\right)dy\\
        &= \frac{\mu(x)}{\sqrt{2\pi T}}\int_{\mathbb{R}}\exp\left(-\frac{1}{2T}\left(y^2 - \frac{2Ty(b-x)}{\sigma} + \frac{(x-b)^2}{\sigma^2} T^2\right)\right)dy\\
        &= \frac{\mu(x)}{\sqrt{2\pi T}}\int_{\mathbb{R}}\exp\left(-\frac{1}{2T}\left(y-\frac{b-x}{\sigma}T\right)^2\right)dy\\
        &= \mu(x).
        % &= \frac{\mu(x)}{\sqrt{2\pi T}}\int_{\mathbb{R}}\exp\left(-\frac{y(x-b)}{\sigma} - \frac{(x-b)^2}{2\sigma^2}T - \frac{y^2}{2T}\right)dy\\
        % &= \frac{\mu(x)}{\sqrt{2\pi T}}\int_{\mathbb{R}}\exp\left(-\frac{1}{2T}\left(y^2 + \frac{2T(x-b)}{\sigma}y\right)-\frac{(x-b)^2}{\sigma}T\right)dy\\
        % &= \frac{\mu(x)}{\sqrt{2\pi T}}\exp\left(-\frac{(x-b)^2}{2\sigma^2}T\right)\int_{\mathbb{R}}\exp\left(-\frac{1}{2T}\left(y + T\frac{(x-b)^2}{\sigma}\right)^2\right)dy\\
        % &= \mu(x)\exp\left(-\frac{(x-b)^2}{2\sigma^2}T\right).
    \end{align*}
    % If $\mu \sim \mathcal{N}\left(\mu_0, \sigma_0^2\right)$, then 
    % \begin{align*}
    %    \mu_b(x) &= \frac{1}{\sqrt{2\pi}\sigma_0}\exp\left(-\frac{1}{2\sigma_0}\left(x-\mu_0\right)^2\right)\exp\left(-\frac{(x-b)^2}{2\sigma^2}T\right)\\
    %    &= \frac{1}{\sqrt{2\pi}\sigma_0}\exp\left(-\frac{(x-\mu_0)^2}{2\sigma_0^2}-\frac{(x-b)^2}{2\sigma^2}T\right)\\
    %    &= \frac{1}{\sqrt{2\pi} \sigma_b}\exp\left(-\frac{1}{2\sigma_b^2}\left(x-\mu_b\right)^2\right),
    % \end{align*}where $\mu_b = \frac{T\sigma_0^2 b + \sigma^2 \mu_0}{T\sigma_0^2 + \sigma^2}$ and $\sigma_b = \frac{\sigma_0^2 \sigma^2}{T\sigma_0^2 + \sigma^2}$, which finishes the proof.
\end{proof}

\subsection{Proof of Theorem \ref{system}}
\begin{proof}
From Corollary 3.8 in \cite{GLS22}, if $X_T$ is a terminal wealth such that there exists a constant $\kappa > 0$ with
\begin{equation}\label{explode}
\left\{
\begin{aligned}
