& E^{Q^{r}} \left[ X_T  \right] = x_0 e^{r T},
\end{aligned}
\right.
\end{equation}
    then $X_T$ is the optimal terminal wealth corresponding to Problem (\ref{inner}).
Since $u$ and $\Phi_{\lambda, \beta}$ are both strictly increasing and strictly concave, then $u' > 0$ and $\Phi_{\lambda, \beta}' > 0$, hence the first equation is equivalent to (we abuse the notation by using $\kappa$ for both the positive multiplier and its logarithm) \begin{align*}
    \log\left(u'(X_T)\right) &= \kappa + \log(\eta_T) + \log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right) \\
    &-\log\left(\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) \eta_T^b \, d\mu(b)\right),
\end{align*}
where $\log(\eta_T) = \frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T$ and $\log\left(\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right)$ does not involve an exponential term so it will not explode. Therefore it suffices to simplify $$\log\left(\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) \eta_T^b \, d\mu(b)\right).$$

% We notice that $\log\left(\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) \eta_T^b \, d\mu(b)\right)$ is indeed a random variable where the randomness is from the $B$ and $W_T$, and the integral can be seen as taken over another random variable $A$ (since $b$ is dummy) which is independent of $B$ and $W_T$, but $A$ has the same distribution as $B$ under $P$. In other words, 
