   &= E^P\left[\Phi_{\lambda, \beta}' \left( E^{Q^A} \left[ u(X_T) \right] \right)\exp\left(-\frac{b_0-A}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)-\frac{(b_0-A)^2}{2\sigma^2}T\right) \,\middle\vert\, \mathcal{G}\right]\\
   &= E^Q\left[\Phi_{\lambda, \beta}' \left( E^{Q^A} \left[ u(X_T) \right] \right)\,\middle\vert\, \mathcal{G} \right]
   E^P\left[\exp\left(-\frac{b_0-A}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)-\frac{(b_0-A)^2}{2\sigma^2}T\right) \,\middle\vert\, \mathcal{G} \right],
\end{align*}
where the last equality is from abstract Bayes' rule \citep{absBayes} with the Radon-Nikodym derivative 
$$\frac{dQ}{dP} = \frac{\exp\left(-\frac{b_0-A}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)-\frac{(b_0-A)^2}{2\sigma^2}T\right)}{E^P\left[\exp\left(-\frac{b_0-A}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)-\frac{(b_0-A)^2}{2\sigma^2}T\right) \,\middle\vert\, \mathcal{G} \right]}.$$
% For the second term, since $A \sim \mu \sim \mathcal{N}\left(\mu_0, \sigma_0^2\right)$ and $A$, $B$, $W_T$ are mutually independent under $P$, we denote $D = W_T + \frac{B - b_0}{\sigma} T$ for convenience of notations, then 
