    &+ \log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right)\\ &- \log\left(\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) \eta_T^b \, d\mu(b)\right)\\
    &=\log(\kappa) + \frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)- \frac{(b_0-r)^2}{2\sigma^2}T \\
    &+ \log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right)\\&-\log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}'\left(E^{Q^a}[u(X_T)]\right)d\mu_A(a)\right) -C - \log\left(\sigma_Q\right) +\log\left(\sigma_0\right),
\end{align*}then $X_T$ is the optimal terminal wealth corresponding to Problem (\ref{inner}). If we define \begin{align*}
L_{\kappa}(X_T) &=
\kappa - \log\left(u'(X_T)\right) +\log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(X_T) \right] \right) d\mu(b)\right)\\
&-\log\left(\int_{\mathbb{R}}\Phi_{\lambda, \beta}'\left(E^{Q^a}[u(X_T)]\right)d\mu_A(a)\right)\notag\\
&\quad + K_3 - \frac{K_2^2}{4K_1} - \log\left(\sigma_Q\right) +\log\left(\sigma_0\right)+ \frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T,\notag
\end{align*}then $L_{\kappa}(X_T) = 0$.
\end{proof}

