\textbf{repeat}
\begin{itemize}
\item Draw $n$ i.i.d. samples $\{b_i\}_{1 \leq i \leq n}$ from $\mu$. For each $i = 1,2,\ldots, n$, sample $\tilde{N}^{b_i} \sim \text{Geo}(R)$ independently, and compute $N^{b_i} = \tilde{N}^{b_i} + n_0$, then give $b_i$ to $\mathcal{S}$ and generate $2^{N^{b_i}+1}$ i.i.d. samples of $\hat{Z}_i^b$.
\item Compute $\nabla F$
and $H(F)
$ by Theorem \ref{Hessian}. Update $(\lambda, \beta)^T = (\lambda, \beta)^T- H(F)^{-1}\nabla F$.
\end{itemize}
\textbf{until} $(\lambda, \beta)^T$ converges.\\
\textbf{Return }$\hat{Q}_{\text{DRBC}}(\pi) = \beta - \lambda \delta + \mathcal
E_{\pi, \delta, \lambda, \beta}$ (Equation (\ref{rMLMC})).
\end{algorithm}
\subsection{Deferred Algorithm for Finite Prior Example}\label{defer2}
\begin{algorithm}\label{DROKLA}
\caption{DRBC KL Problem Solver}\label{DROKLA}
\textbf{Input:} A simulator $\mathcal{S}$, simulation observations $S = \{S_t\}_{t \in [0,T]}$, real observations $\tilde{S} = \{\tilde{S}_t\}_{t \in [0,T]}$ rMLMC parameter $R \in (\frac{1}{2},\frac{3}{4})$ and $n_0$, prior $\boldsymbol{p}$, initializations of $\lambda$, $\pi$, and $k = 0$, step-size sequence $\{\alpha_k : k \in \mathbb{Z}_{\geq 0}\}$. \\
\textbf{Output:} DRBC optimal policy $\hat{\pi}_{\text{DRBCKL}}$.\\
\textbf{repeat}
\begin{itemize}
\item Draw $n$ i.i.d. samples $\{b_i\}_{1 \leq i \leq n}$ from $\mu$. For each $i = 1,2,\ldots, n$, sample $\tilde{N}^{b_i} \sim \text{Geo}(R)$ independently, and compute $N^{b_i} = \tilde{N}^{b_i} + n_0$, then give $b_i$ to $\mathcal{S}$ and generate $2^{N^{b_i}+1}$ i.i.d. samples of $\hat{Z}_i^b$.
\item Compute $\text{GF} :=\frac{\partial}{\partial \lambda}\mathcal{E}_{\text{KL}}$ (Theorem \ref{KLderivatives}). Update $\lambda = \lambda + \alpha_k \text{GF}$ and update $k = k+1$.
\item Update $\pi$ by Algorithm \ref{DROpo} with $\lambda$ and $S$.
\end{itemize}
\textbf{until} $\lambda$ converges.\\
\textbf{Return }$\hat{\pi}_{\text{DRBCKL}} = $ output of Algorithm \ref{DROpo} with $\lambda$ and $\tilde{S}$.
\end{algorithm}
\subsection{Learning the Optimal Alternative Measure for the Finite Prior Example}
Recall that the problem that we want to solve is \begin{align*}
\inf_{\substack{\boldsymbol{q} = (q_1, \ldots, q_d)\\\sum_{i=1}^d q_i = 1,\text{and }q_i \geq 0}}V(\boldsymbol{q}) =
    \inf_{\substack{\boldsymbol{q} = (q_1, \ldots, q_d)\\\sum_{i=1}^d q_i = 1,\text{and }q_i \geq 0}}\tilde{V}(\boldsymbol{q}) + \lambda\sum_{i=1}^d q_i \log \frac{q_i}{p_i},
\end{align*}
where $\tilde{V}(\boldsymbol{p}) := \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(\tilde{F}_{\boldsymbol{p}}(T,z)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha}$
and $\tilde{F}_{\boldsymbol{p}}(t,z) = \sum_{i=1}^dp_iL_t(b_i,z)$. Note that the value function can be seen as an expectation with respect to the Gaussian distribution $\mathcal{N}(0,T)$, thus it can be computed via simulation methods (plain Monte Carlo).

% Note that the value function is indeed a nested expectation even though $B$ (which has finite support) and $W_T \sim \mathcal{N}(0,T)$ are independent, so we cannot use the plain Monte Carlo method for the loss evaluation. More precisely, if we define $Z = L_T(B,W_T)$, then
% \begin{align*}
%   \tilde{V}(\boldsymbol{p}) &= \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(\tilde{F}_{\boldsymbol{p}}(T,z)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha}\\&= \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(\int_{\mathbb{R}}L_T\left(b,z\right)d\mu(b)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha}\\
%   &=\frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}E^P\left[\left( E^P\left[L_T(B,W_T)|W_T\right]\right)^{\frac{1}{1-\alpha}}\right]\\
%   &=\frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}E^P\left[U\left( E^P\left[Z|W_T\right]\right)\right],
% \end{align*}
% where $U(x) = x^{\frac{1}{1-\alpha}}$. Note that $U$ does not satisfy the linear growth condition thus we cannot apply the rMLMC method from \citet{Y_b} here directly (unless we have integrability with higher order moments, which is much stronger). However, since $\tilde{V}(\boldsymbol{p})$ is the optimal value function of Problem \ref{OriginalKaratzas} and we know the optimal control (Theorem \ref{Karatzassolution}), thus we can simulate $X_T$ and then plug in to approximate $\tilde{V}(\boldsymbol{p})$ in each iteration of $\boldsymbol{p}$.

On the other hand, the gradient information of $\tilde{V}(\boldsymbol{p})$ is hard to compute. Thus, we will focus on the zero-order methods \citep{nesterov2017random, shamir2017optimal, duchi2015optimal}. We will mimic first-order optimization strategies by replacing the
gradient of the objective function with an approximation built through finite differences \citep{leveque2007finite}: for a fixed $i = 1, 2, \ldots, d,$ let $h >0$ small, then $$\frac{\partial \tilde{V}(\boldsymbol{p})}{\partial p_i} \approx \frac{1}{2h}\left[\tilde{V}(\boldsymbol{p}+h\boldsymbol{e}_i) - \tilde{V}(\boldsymbol{p}-h\boldsymbol{e}_i)\right],$$
where $\boldsymbol{e}_i$ is the unit vector in the $i$th coordinate direction. Note that here we use the central difference method, which has the $\mathcal{O}(h^2)$ rate of convergence, instead of the backward or forward difference method, which both have the $\mathcal{O}(h)$ rate of convergence. The exact steps to solve Problem (\ref{toyopti}) are summarized in Algorithm \ref{DROpo}.

% Then we can use the empirical risk minimization technique \citep{Bach} to find the optimal $\boldsymbol{q}^*$ (Algorithm \ref{DROpo}).
\begin{algorithm}\label{DROpo}
\caption{rMLMC DRBC KL Policy Learning Step}\label{DROpo}
\textbf{Input:} Prior distribution $\boldsymbol{p}$, step-size sequence $\{\alpha_k\}_{k \in \mathbb{Z}_{\geq 0}}$, parameter $h >0$ and $\lambda >0$, observations $\{S_t\}_{t \in [0,T]}$ (see remark in Section \ref{toy} for which process to plug in),   initializations of $\boldsymbol{q}$ and $k = 0$. \\
\textbf{Output:} DRBC optimal policy $\{\pi^*_{\lambda,t}\}_{t \in [0,T]}$.\\ 
\textbf{repeat}
\begin{itemize}
\item For each $i = 1,2,\ldots, d$, approximate $\tilde{V}(\boldsymbol{q}+h\boldsymbol{e}_i)$ and $\tilde{V}(\boldsymbol{q}-h\boldsymbol{e}_i))$ by simulations. 
\item For each $i = 1,2,\ldots, d$, compute $\text{GF}_i = \frac{1}{2h}\left[\tilde{V}(\boldsymbol{q}+h\boldsymbol{e}_i) - \tilde{V}(\boldsymbol{q}-h\boldsymbol{e}_i)\right] + \lambda \left(\log\left(\frac{q_i}{p_i}\right)+1\right)$. 
\item Update $\boldsymbol{q} = \boldsymbol{q} - \alpha_k \text{GF}$, update $\boldsymbol{q} = \text{softmax}(\boldsymbol{q})$, and update $k = k+1$.
\end{itemize}
\textbf{until} $\boldsymbol{q}$ converges to $\boldsymbol{q}^*$.\\
\textbf{Return }$\pi^*_{\lambda,t} = \frac{\int_{\mathbb{R}}\nabla F_{\boldsymbol{q}^*}\left(T,z+Y_t\right)\left(F_{\boldsymbol{q}^*}\left(T,z+Y_t\right)\right)^{\frac{\alpha}{1-\alpha}}\varphi_{T-t}(z)dz}{(1-\alpha)\sigma \int_{\mathbb{R}}\left(F_{\boldsymbol{q}^*}\left(T,z+Y_t\right)\right)^{\frac{1}{1-\alpha}}\varphi_{T-t}(z)dz}$, for each $t \in [0,T]$, where $Y_t $ is given by Equation (\ref{YS}).
\end{algorithm}

\subsection{Implementation Details for the KL divergence Case (Algorithm \ref{DROKLA})}
Here we elaborate on the details of simulating a sample of the optimal terminal wealth $X_T$. Recall that the controlled SDE is given by
\begin{equation}\label{SDE1}
d X_t = (X_t - \pi_t) r \, d t + \pi_t \left(B d t + \sigma d W_t\right),    
\end{equation}
where $\pi_t$ is the amount of money invested in the stock at time $t \in [0,T]$. Theorem \ref{Karatzassolution} provides the optimal fraction of total wealth invested in stock at time $t$. If we model $\pi_t$ as the fraction of total wealth invested in stock at time $t$, then the controlled SDE becomes 
\begin{equation}\label{SDE2}
  d X_t = X_t \left(rdt + \pi_t\left(B-r\right)dt + \sigma dW_t\right).  
\end{equation}These two formulations are equivalent since they give the same optimal value function (thus the same optimal terminal wealth) and the optimal fraction for the formulation (\ref{SDE1}) indeed gives the optimal control for the formulation (\ref{SDE2}). Thus, in Algorithm \ref{DROKLA}, when we sample $X_T$ for the KL divergence case, we plug in the optimal fraction for Equation (\ref{SDE2}) and use either Euler's method or rMLMC method \citep{RheeGlynn2015}.

\subsection{Deep Learning Method to Learn Optimal Terminal Wealth for the General Case}\label{algo3}
In this section, we discuss and give the Algorithm \ref{first} to compute the loss function $\mathcal{L}(\boldsymbol{\theta})$ with fixed neural network parameter (get high quality estimates (e.g. unbiased, low variance, and fast computing speed)), and then auto-differentiation (back propagation neural network \citep{rumelhart1986learning, lecun2015deep}) can be used to do the optimizations (Algorithm \ref{BPG}). 

Before discussing the loss function (\ref{loss}), we remark that Equation (\ref{explode}) also motivates a loss function for $b_1 \in \mathbb{R}$,
\begin{align}\label{badloss}
&\mathcal{\tilde{L}}(\boldsymbol{\theta}) =E^{Q^{b_1}} \bigg[\bigg\|
u'(h_{\theta}(W_T,B))\int_{\mathbb{R}} \Phi_{\lambda, \beta}' \left( E^{Q^a} \left[ u(X_T) \right] \right)* \\
&\exp\left(-\frac{b_0-a}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T \right)-\frac{(b_0-a)^2}{2\sigma^2}T\right) \, d\mu(a) \notag\\ 
&- \kappa \exp\left(\frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T\right)\int_{\mathbb{R}}\Phi_{\lambda, \beta}' \left( E^{Q^b} \left[ u(h_{\theta}(W_T,B)) \right] \right) d\mu(b)
\bigg\|_2^2\bigg] \notag\\
&\quad + \Bigg( E^{Q^{r}}[h_{\theta}(W_T,B)] - x_0 e^{rT} \Bigg)^2. \notag
\end{align}
In theory, loss (\ref{loss}) and (\ref{badloss}) are equivalent. However, in terms of numerical computation, (\ref{badloss}) is bad since when we initializing neural network parameters and do the optimization steps, we cannot control the flow and with high probability, the terms in (\ref{badloss}) becomes $\infty$ since $\frac{1}{\sigma^2}$ is small. Moreover, the scalar learnable parameter in (\ref{badloss}) is restricted to be positive so we need to do projected gradient descent, while in (\ref{loss}) the scalar learnable parameter can be any real number. Therefore, in order to achieve the numerical stability and convenience for implementation, we choose loss (\ref{loss}).

% The main challenges in this computation are to compute $\int_{\mathbb{R}} \phi\left(E^{Q^b}\left[u(h_{\theta}(W_T, B))\right]\right) d\mu(b)$ and $\int_{\mathbb{R}} \phi\left(E^{Q^a}\left[u(h_{\theta}(W_T, B))\right]\right) d\mu_A(a)$ (with realizations of $W_T$ and $B$), which motivates Algorithm \ref{first}.

Recall that from Theorem \ref{system}, if we replace $\Phi_{\lambda, \beta}$ by $\phi$, then the conditions that the parametrized optimal terminal wealth $h_{\theta}(W_T,B)$ needs to satisfy are
$$E^{Q^{r}}[h_{\theta}(W_T,B)] = x_0 e^{rT}$$ and
\begin{align}
\log\left(u'(h_{\theta}(W_T,B))\right)  &=  \log\left(\int_{\mathbb{R}}\phi' \left( E^{Q^b} \left[ u(h_{\theta}(W_T,B)) \right] \right) d\mu(b)\right) \text{        (constant log term)}\label{1}\\ &-\log\left(\int_{\mathbb{R}}\phi'\left(E^{Q^a}[u(h_{\theta}(W_T,B))]\right)d\mu_A(a)\right)\text{ (random log term)}\label{2}\\
&\quad+ \kappa + K_3 - \frac{K_2^2}{4K_1} - \log\left(\sigma_Q\right) +\log\left(\sigma_0\right) \\
&+\frac{r-b_0}{\sigma}\left(W_T + \frac{B-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T,\label{3}
\end{align}where the second condition is an equation of random variables, thus for each $b_1$ in the support of $\mu$, we need to sample $W_T$ and $B$ under the probability measure $Q^{b_1}$. From Appendix \ref{transformderive}, under $Q^{b_1}$, the distribution of $B$ is unchanged. Moreover, since under $Q^{b_1}$, $W^{b_1}$ is a standard Brownian motion and $W^{b_1}_t = W_t + \frac{B-b_1}{\sigma}t$, then we get samples of $W_T$ by first sampling $N \sim \mathcal{N}(0,T)$, $B \sim \mu$, and then compute $W_T = N - \frac{B-b_1}{\sigma}T$. The reason to do this can be found in Section \ref{algo4}.

% We choose the probability measure $Q^r$ with the following intuitions and reasons. To begin with, since the other part of the loss function requires samples under $Q^r$, using the same probability space reduces the cost of simulation. On the other hand, the probability measure $Q^r$ represents the risk-neutral measure in financial mathematics \citep{KaratzasShreve1998}, thus is a natural choice. Finally, choosing $Q^r$ is beneficial for potential downstream tasks. For example, $\{e^{-rt} \hat{X}_t \}_{0 \leq t \leq T}$ is a martingale under $Q^{r}$, then we can numerically compute the optimal wealth process with the learned optimal terminal wealth and the conditional expectations. Therefore, the loss function is defined by Equation (\ref{loss}).

Once we sample from $W_T$ and $B$ under $Q^{b_1}$, we need to compute the nested expectations  (\ref{1}) and (\ref{2}) since (\ref{3}) is easy to compute. Essentially, computations of (\ref{1}) and (\ref{2}) are the same, except the outermost distribution in (\ref{1}) is deterministic, where the outermost distribution in (\ref{2}) depends on the sampling of $W_T$ and $B$ under $Q^{b_1}$. We can view the whole loss function as a nested expectation with layers in $x \mapsto x^2$ and $x \mapsto \log(x)$ and then apply the method in \cite{YG23}, but then the regularity conditions are hard to check. Thus, we only consider the rMLMC method for the nonlinear transform $\phi'$. For the rest of the estimator, we use the plug-in method.



\begin{algorithm}
\caption{Loss Estimator with rMLMC}\label{first}
\textbf{Input:} Functions $\phi$ and $u$, scalar parameters $(x_0, b_0, T, \mu_0, \sigma_0, r,\sigma)$, fixed parameters $\kappa$ and $\theta$, data sets $\{W_k^{(1)}\}_{1 \leq k \leq n^{(1)}}$, $\{B_k^{(1)}\}_{1 \leq k \leq n^{(1)}}$, $\{W_{i,j}^{(3)}\}_{1 \leq j \leq n^{(2)}, 1 \leq i \leq 2^{N+1}, }$, $\{B_{i,j}^{(3)}\}_{1 \leq j \leq n^{(2)}, 1 \leq i \leq 2^{N+1}}$, $\{W_{i,j,k}^{(3)}\}_{1 \leq j \leq n^{(2)}, 1 \leq i \leq 2^{N+1}, 1 \leq k \leq n^{(1)}}$, and $\{B_{i,j,k}^{(3)}\}_{1 \leq j \leq n^{(2)}, 1 \leq i \leq 2^{N+1}, 1 \leq k \leq n^{(1)}}$, sample $N$.\\
\textbf{Output:} Estimate of $\mathcal{L}(\boldsymbol{\theta}) = \mathcal{L}\left(\theta, \kappa\right)$.
\begin{itemize}
    \item \textbf{Compute the constant log term:}
 \textbf{For each $j = 1, \ldots, n^{(2)}$}
\begin{itemize}
    % \item Initialize $Z_j = 0$.
    \item For each $i = 1, \ldots, 2^{N + 1}$, define $Y_{i,j} = \left(W^{(3)}_{i,j}, B^{(3)}_{i,j}\right)^T$ and compute $X_{i,j} = u\left(h_{\theta}\left(Y_{i,j}\right)\right)$.
    \item Split the sequence of $X_{i,j}$ into odd and even indices for $i$. Compute
    $S_{j,l} = \sum_{i=1}^l X_{i,j}$, $S^O_{j,l} = \sum_{i=1}^k X^O_{i,j}$, and $S^E_{j,l} = \sum_{i=1}^l X^E_{i,j}$.
    \item Compute
    $
    \Delta_N = \phi'\left(\frac{S_{j,2^{N+1}}}{2^{N+1}}\right) - \frac{1}{2}\left(\phi'\left(\frac{S^O_{j,2^N}}{2^N}\right) + \phi'\left(\frac{S^E_{j,2^N}}{2^N}\right)\right).
    $
    \item Compute $Z_j = \frac{\Delta_N}{p(N)} + \phi'\left(\frac{S_{j, 2^{n_0}}}{2^{n_0}}\right),$
    where $p(N)$ is the probability mass function of $N$.
\end{itemize}\textbf{end for }Compute $\hat{I}_c = \log\left(\frac{1}{n^{(2)}} \sum_{j=1}^{n^{(2)}}Z_j\right).$

\item Compute $D = W^{(1)}_k + \frac{B^{(1)}_k-b_0}{\sigma}T$, $K_1 = \dfrac{T}{2 \sigma^2} + \dfrac{1}{2 \sigma_0^2},$, $K_2 = \dfrac{T b_0}{\sigma^2} + \dfrac{D}{\sigma} + \dfrac{\mu_0}{\sigma_0^2}$, and $K_3 = \dfrac{T b_0^2}{2 \sigma^2} + \dfrac{b_0 D}{\sigma} + \dfrac{\mu_0^2}{2 \sigma_0^2}$.

\item Compute $\hat{I}_{r_1} = \frac{r-b_0}{\sigma}\left(W^{(1)}_k + \frac{B^{(1)}_k-b_0}{\sigma}T\right) - \frac{(b_0-r)^2}{2\sigma^2}T + K_3 - \frac{K_2^2}{4K_1} - \log\left(\sigma_Q\right) +\log\left(\sigma_0\right).$
\item \textbf{Compute the random log term: }\textbf{For each $k = 1, \ldots, n^{(1)}$}\begin{itemize}
    \item 
 \textbf{For each $j = 1, \ldots, n^{(2)}$}
\begin{itemize}
    % \item Initialize $Z_j = 0$.
    \item For each $i = 1, \ldots, 2^{N + 1}$, define $Y_{i,j,k} = \left(W^{(3)}_{i,j,k}, B^{(3)}_{i,j,k}\right)^T$ and compute $X_{i,j,k} = u\left(h_{\theta}\left(Y_{i,j,k}\right)\right)$.
    \item Split the sequence of $X_{i,j,k}$ into odd and even indices for $i$. Compute
    $S_{j,l,k} = \sum_{i=1}^l X_{i,j,k}$, $S^O_{j,l,k} = \sum_{i=1}^k X^O_{i,j,k}$, and $S^E_{j,l,k} = \sum_{i=1}^l X^E_{i,j,k}$.
    \item Compute
    $
    \Delta_{N,k} = \phi'\left(\frac{S_{j,2^{N+1},k}}{2^{N+1}}\right) - \frac{1}{2}\left(\phi'\left(\frac{S^O_{j,2^N,k}}{2^N}\right) + \phi'\left(\frac{S^E_{j,2^N,k}}{2^N}\right)\right)
    $ and $Z_{j,k} = \frac{\Delta_{N,k}}{p(N)} + \phi'\left(\frac{S_{j,2^{n_0},k}}{2^{n_0}}\right).$
\end{itemize}\textbf{end for }Compute $\hat{I}_{r_2} = \log\left(\frac{1}{n^{(2)}} \sum_{j=1}^{n^{(2)}}Z_{j,k}\right)$. \textbf{end for }
\end{itemize}
\item Compute $\mathcal{L}_2 = \left(\frac{1}{n^{(1)}}\sum_{k=1}^{n^{(1)}}h_{\theta}\left(W^{(1)}_k, B^{(1)}_k\right) - x_0e^{rT}\right)^2$.
\end{itemize}
\textbf{Return:} 
% \begin{align*}
%     &\mathcal{L}\left(\boldsymbol{\theta}\right) =\\
%     & = \frac{1}{n^{(1)}}\sum_{k=1}^{n^{(1)}}\left(\kappa - \log\left(u'\left(h_{\theta}\left(W^{(1)}_k, B^{(1)}_k\right)\right)\right) + \hat{I}_{r_1} - \hat{I}_{r_2} + \hat{I}_{c}\right)^2 + .
% \end{align*}
$\mathcal{L}\left(\boldsymbol{\theta}\right) = \frac{1}{n^{(1)}}\sum_{k=1}^{n^{(1)}}\left(\kappa - \log\left(u'\left(h_{\theta}\left(W^{(1)}_k, B^{(1)}_k\right)\right)\right) + \hat{I}_{r_1} - \hat{I}_{r_2} + \hat{I}_{c}\right)^2 + \mathcal{L}_2.$ 
