\begin{algorithm}\label{BPG}
\caption{rMLMC DR Policy Learning Step for the General Case}\label{BPG}
\textbf{Input:} Functions $\phi$ and $u$, scalar parameters $(x_0, b_0, T, \mu_0, \sigma_0, r,\sigma)$, step-size sequence $\{\alpha_k\}_{k \in \mathbb{Z}_{\geq 0}}$, initilizations $\boldsymbol{\theta} = (\theta, \kappa)^T$ and $k = 0$.\\
\textbf{Output:} DR optimal terminal wealth $X_T$.\\ 
\textbf{Samples for constant log term:} sample $\tilde{N} \sim \text{Geo}(R)$ and compute $N = \tilde{N} + n_0$; sample $n^{(2)}$ i.i.d. values $\{B^{(2)}_j\}_{1 \leq j \leq n^{(2)}}$ from $\mathcal{N}(\mu_0, \sigma_0^2)$.  \textbf{For each $j = 1, \ldots, n^{(2)}$}\begin{itemize}
    % \item Initialize $Z_j = 0$.
    \item Sample $2^{N + 1}$ i.i.d. samples $\{B^{(3)}_{i,j}\}_{1 \leq i \leq 2^{N + 1}}$ from $\mathcal{N}(\mu_0, \sigma_0^2)$. 
    \item Sample $2^{N + 1}$ i.i.d. samples $\{N^{(3)}_{i,j}\}_{1 \leq i \leq 2^{N + 1}}$ from $\mathcal{N}(0,T)$. 
     \item For each $i = 1, \ldots, 2^{N + 1}$, compute $W^{(3)}_{i,j} = N^{(3)}_{i,j} - \frac{B^{(3)}_{i,j}-B^{(2)}_j}{\sigma}T$.
    \end{itemize}
Sample $n^{(1)}$ i.i.d. values $\{B^{(1)}_k\}_{1 \leq k \leq n^{(1)}}$ from $\mathcal{N}(\mu_0, \sigma_0^2)$ and $n^{(1)}$ i.i.d. values $\{N^{(1)}_k\}_{1 \leq k \leq n^{(1)}}$ from $\mathcal{N}(0, T)$. For each $k = 1, \ldots, n^{(1)}$, compute $W^{(1)}_k = N^{(1)}_k - \frac{B^{(1)}_k-r}{\sigma}T$. Compute $\sigma_Q^2 = \left( \dfrac{T}{\sigma^2} + \dfrac{1}{\sigma_0^2} \right )^{-1}$.\\
\textbf{Samples for random log term:}\textbf{ For each $k = 1, \ldots, n^{(1)}$}\begin{itemize}
    \item Compute $\mu_{Q} = \sigma_Q^2 \left( \dfrac{W^{(1)}_k}{\sigma} + \dfrac{B^{(1)}_k T}{\sigma^2} + \dfrac{\mu_0}{\sigma_0^2} \right )$. Sample $n^{(2)}$ i.i.d. values $\{B^{(2)}_{j,k}\}_{1 \leq j \leq n^{(2)}}$ from $\mathcal{N}(\mu_Q, \sigma_Q^2)$.
 \textbf{For each $j = 1, \ldots, n^{(2)}$}
\begin{itemize}
    % \item Initialize $Z_j = 0$.
    \item Sample $2^{N + 1}$ i.i.d. samples $\{B^{(3)}_{i,j,k}\}_{1 \leq i \leq 2^{N + 1}}$ from $\mathcal{N}(\mu_0, \sigma_0^2)$. 
    \item Sample $2^{N + 1}$ i.i.d. samples $\{N^{(3)}_{i,j,k}\}_{1 \leq i \leq 2^{N + 1}}$ from $\mathcal{N}(0,T)$. 
    \item For each $i = 1, \ldots, 2^{N + 1}$, compute $W^{(3)}_{i,j,k} = N^{(3)}_{i,j,k} - \frac{B^{(3)}_{i,j,k}-B^{(2)}_{j,k}}{\sigma}T$.
    \end{itemize}
    \end{itemize}
\textbf{repeat}
\begin{itemize}
\item Compute $\mathcal{L}\left(\boldsymbol{\theta}\right)$ by Algorithm \ref{first} and the above samples.
\item Update $\boldsymbol{\theta} = \boldsymbol{\theta} - \alpha_k \nabla_{\boldsymbol{\theta}} \mathcal{L}\left(\boldsymbol{\theta}\right)$, where the gradient is computed by back propagation; update $k = k+1$.
\end{itemize}
\textbf{until} $\boldsymbol{\theta} = (\theta,\kappa)^T$ converges to $\boldsymbol{\theta}^* = (\theta^*,\kappa^*)^T$.\\
\textbf{Return }$X_T = h_{\theta^*}(W_T,B)$.
\end{algorithm}

\subsection{Deep Learning Method to Learn Optimal Policy for the General Case}\label{algo4}
Suppose we have numerically computed the approximation of the optimal terminal wealth $X^*_T \approx h_{\theta^*}(W_T,B)$, then for the policy evaluation step (Section \ref{outeroptimization}), the simulation is simpler than the KL case (since we can directly sample unbiased terminal wealth directly without simulating an SDE).
However, in order to use the rMLMC estimator for $Q_{\text{DRBC}}$, we still need to draw $\{b_1, b_2, \ldots, b_n\}$ from the distribution of $\mu$ and generate unbiased estimator of $$E^{P^{b_i}}\left[u(X_T)\right] = E^{Q^{b_i}}\left[u(X_T)\right] = E^{Q^{b_i}}\left[u(h_{\theta^*}(W_T,B))\right].$$
Thus, it is better to design a loss function for each $b_i$ rather than choose a "uniformly" best $Q^{b^*}$ for the loss function.

    Suppose the multipliers of the alternative optimization algorithm converge finally, then we get realizations of $\hat{V}(x_0)$ in the worst case. Since the optimal value function of the distributionally robust problem is just plugging the worst case probability $\mu^*$ into the original form of the solution (Theorem \ref{Karatzassolution}), thus we can solve the optimization problem $\inf_{\theta}\mathcal{L}(\theta)$ to derive $\mu^*$ if we parametrize the density by a neural network: 
    \begin{align*}
        \mathcal{L}(\theta)
      &= E^P\left[\left\Vert \hat{V}(x_0) - V(x_0, f_{\theta}) \right\Vert_2^2\right],
    \end{align*}
    where $\theta$ represents the parameter of the neural network $f_{\theta}$ for the approximation of $\rho_{\mu^{*}}$ and $V(x_0, \mu) = \frac{\left(x_0e^{rT}\right)^{\alpha}}{\alpha}\left(\int_{\mathbb{R}}\left(F_{\mu}(T,z)\right)^{\frac{1}{1-\alpha}}\varphi_T(z)dz\right)^{1-\alpha}$ for a fixed distribution $\mu \in \mathcal{P}(\mathbb{R})$. To simplify the trackability issue, we may parametrize $\rho_{\mu^{*}}$ as exponential family or Gaussian mixtures \citep{goodfellow2016deep}.  Finally, to get the DRBC optimal control with real observations of stock prices, we plug in Theorem \ref{Karatzassolution} with the learned worst-case probability and the observations.

