\subsection{Details of Experiments in Section \ref{smps}}\label{KMM}
\subsubsection{Choice of Performance Measures}
From \cite{GLS22}, if \[
\Phi(x) =
\begin{cases}
\frac{x^{\gamma}}{\gamma}, & \text{if } x \geq 0, \\
\frac{-(-x)^{\gamma}}{\gamma}, & \text{if } x < 0,
\end{cases}
\quad \text{where } \gamma \in (0,1) \text{ is a fixed constant,}
\] then the optimal terminal wealth has the closed-form
\begin{align}\label{closedform}
  X^*_T
  &= \exp \Bigg( \frac{1}{\alpha} \Bigg( \frac{p}{2T} 
  \left(W_T + \frac{B-b_0}{\sigma}\right)^2 + q \left(W_T + \frac{B-b_0}{\sigma}\right) + c \Bigg) \Bigg),
\end{align}where
$$
\left\{
\begin{aligned}
    p &=  \frac{\frac{1}{1 - \alpha} + \sigma_0^2 -\sqrt{\sigma_0^4 + \frac{2 - 4\alpha}{1 - \alpha} \sigma_0^2 + \frac{1}{(1 - \alpha)^2} - \frac{4\alpha}{1 - \alpha} \gamma}}{2(\sigma_0^2 + \gamma)}, \\
    q &= \frac{\alpha(1 - p)}{(1 - \alpha)(1 - \gamma p)} \nu, \\
    c &= \alpha \left[ \log(x_0) + rT + \left( \nu^2 - \frac{\left( \nu - \frac{q}{\alpha} \right)^2}{1 - \frac{p}{\alpha}} \right) \frac{T}{2} \right].
\end{aligned}
\right.
$$
From \cite{GLS22}, for a fixed $b \in \mathbb{R}$ (more precisely in the support of the prior)
\[
E^{Q^b}[u(X^*_T)] = \frac{1}{\alpha \sqrt{1-p}} \exp \Bigg(
\frac{pT}{2(1-p)} \nu^2_b - \frac{qT}{1-p} \nu_b + \frac{q^2T}{2(1-p)} + c
\Bigg)
\]
\[
= \frac{1}{\alpha \sqrt{1-p}} \exp \Bigg(
\frac{pT}{2(1-p)} \frac{(b - b_0)^2}{\sigma^2} + \frac{qT}{1-p} \frac{b - b_0}{\sigma}
+ \frac{q^2T}{2(1-p)} + c
\Bigg).
\]
% thus 
% \begin{align*}
%     V(x_0) &= \sup_{\alpha \in \mathcal{A}(x_0)} \int_{\mathbb{R}}\Phi\left(E^{Q^b}\left[u(X_T)\right]\right)d\mu(b)\\
%     &= \int_{\mathbb{R}} \frac{1}{\alpha \sqrt{1-p}} \exp \Bigg(
% \frac{pT}{2(1-p)} \frac{(b - b_0)^2}{\sigma^2} + \frac{qT}{1-p} \frac{b - b_0}{\sigma}
% + \frac{q^2T}{2(1-p)} + c
% \Bigg) d\mu(b)\\
% &= 
